// Nuvemath — 11-sinf, II qism (Geometriya 11, B.Q. Xaydarov, 2018) nazariyasi, t1–t7. Format: js/theory/GUIDE.md
(function (root) {
  'use strict';
  var L = root.NMCurriculum.H.L, T = root.NMTheory, P = '11-2';

  // ---------- t1. Fazoda dekart koordinatalari sistemasi ----------
  T.add(P, 't1', { sections: [
    { kind: 'intro', h: L('Uchinchi o‘lchamni qo‘shamiz', 'Добавляем третье измерение', 'Adding the third dimension'), p: [
      L('Tekislikda nuqtaning o‘rnini ikki son — (x; y) aniqlaydi: shahar xaritasida «sharqqa 3 km, shimolga 2 km» deyish yetarli. Ammo samolyot dispetcheri uchun bu kam: u samolyot qaysi <b>balandlikda</b> uchayotganini ham bilishi shart. Xuddi shunday, ko‘p qavatli binoda kvartirani topish uchun ko‘cha, uy raqami va qavat kerak. Demak, fazoda nuqtaning o‘rnini <b>uchta son</b> belgilaydi.', 'На плоскости положение точки задают два числа — (x; y): на карте города достаточно сказать «3 км на восток, 2 км на север». Но авиадиспетчеру этого мало: ему нужно знать и <b>высоту</b> полёта самолёта. Так же, чтобы найти квартиру в многоэтажном доме, нужны улица, номер дома и этаж. Значит, в пространстве положение точки задают <b>три числа</b>.', 'On a plane, two numbers (x; y) fix the position of a point: on a city map it is enough to say “3 km east, 2 km north”. An air traffic controller needs more: the <b>altitude</b> of the plane as well. Likewise, to find a flat in a tall building you need the street, the house number and the floor. So in space a point is fixed by <b>three numbers</b>.'),
      L('Bu mavzuda biz fazoviy dekart koordinatalar sistemasini quramiz, nuqtalar orasidagi masofani va kesma o‘rtasini hisoblashni o‘rganamiz. Bu usul stereometriya masalalarini chizmasiz, faqat algebra yordamida yechish imkonini beradi — 10-sinfda murakkab yasashlar talab qilgan masalalar bir necha qator hisobga aylanadi.', 'В этой теме мы построим пространственную декартову систему координат и научимся вычислять расстояние между точками и середину отрезка. Этот метод позволяет решать стереометрические задачи без чертежа, одной алгеброй — задачи, требовавшие в 10-м классе сложных построений, превращаются в несколько строк вычислений.', 'In this topic we build the Cartesian coordinate system in space and learn to compute the distance between points and the midpoint of a segment. The method lets us solve solid-geometry problems without drawings, by algebra alone — problems that needed tricky constructions in grade 10 become a few lines of computation.')
    ] },
    { kind: 'def', h: L('Koordinatalar sistemasi qanday quriladi', 'Как строится система координат', 'How the coordinate system is built'), p: [
      L('Fazoda O nuqta orqali o‘zaro perpendikulyar uchta to‘g‘ri chiziq o‘tkazamiz va har biriga yo‘nalish hamda bir xil uzunlik birligini tanlaymiz. Ular <b>koordinata o‘qlari</b> deyiladi: <b>Ox</b> — abssissalar o‘qi, <b>Oy</b> — ordinatalar o‘qi, <b>Oz</b> — applikatalar o‘qi. O nuqta — <b>koordinatalar boshi</b>.', 'В пространстве через точку O проведём три попарно перпендикулярные прямые и выберем на каждой направление и одну и ту же единицу длины. Они называются <b>осями координат</b>: <b>Ox</b> — ось абсцисс, <b>Oy</b> — ось ординат, <b>Oz</b> — ось аппликат. Точка O — <b>начало координат</b>.', 'Through a point O in space draw three mutually perpendicular lines, and on each choose a direction and the same unit of length. They are the <b>coordinate axes</b>: <b>Ox</b> — the x-axis (abscissa), <b>Oy</b> — the y-axis (ordinate), <b>Oz</b> — the z-axis (applicate). O is the <b>origin</b>.'),
      L('Har ikki o‘q bitta <b>koordinata tekisligini</b> belgilaydi: Oxy, Oyz va Oxz. Bu uch tekislik fazoni <b>sakkizta oktantga</b> bo‘ladi (tekislikdagi to‘rtta chorak o‘rniga). Odatda <b>o‘ng sistema</b> olinadi: o‘ng qo‘lning bosh barmog‘i Ox, ko‘rsatkich barmog‘i Oy bo‘ylab yo‘nalsa, o‘rta barmoq Oz yo‘nalishini ko‘rsatadi.', 'Каждые две оси задают <b>координатную плоскость</b>: Oxy, Oyz и Oxz. Эти три плоскости делят пространство на <b>восемь октантов</b> (вместо четырёх четвертей на плоскости). Обычно берут <b>правую систему</b>: если большой палец правой руки направлен по Ox, указательный — по Oy, то средний покажет направление Oz.', 'Each pair of axes determines a <b>coordinate plane</b>: Oxy, Oyz and Oxz. These three planes cut space into <b>eight octants</b> (instead of the four quadrants of the plane). One usually takes a <b>right-handed system</b>: if the thumb of the right hand points along Ox and the index finger along Oy, the middle finger shows the direction of Oz.'),
      L('M nuqtadan har bir koordinata tekisligiga parallel tekislik o‘tkazamiz; ular o‘qlarni M<sub>x</sub>, M<sub>y</sub>, M<sub>z</sub> nuqtalarda kesadi. Bu nuqtalarning o‘qlardagi koordinatalari x, y, z — M nuqtaning <b>koordinatalari</b>: M(x; y; z). Har bir nuqtaga yagona uchlik mos keladi va aksincha.', 'Через точку M проведём плоскости, параллельные координатным плоскостям; они пересекут оси в точках M<sub>x</sub>, M<sub>y</sub>, M<sub>z</sub>. Координаты этих точек на осях x, y, z — <b>координаты</b> точки M: M(x; y; z). Каждой точке соответствует единственная тройка чисел и наоборот.', 'Through M draw planes parallel to the coordinate planes; they cut the axes at M<sub>x</sub>, M<sub>y</sub>, M<sub>z</sub>. The coordinates of these points on the axes, x, y, z, are the <b>coordinates</b> of M: M(x; y; z). Every point has exactly one such triple, and every triple gives exactly one point.')
    ] },
    { kind: 'history', h: L('Dekart, Ferma va uchinchi o‘q', 'Декарт, Ферма и третья ось', 'Descartes, Fermat and the third axis'), p: [
      L('Koordinatalar usuli 1637-yilda fransuz faylasufi va matematigi <b>Rene Dekart</b>ning «Metod haqida mulohaza» asariga ilova qilingan «Geometriya» kitobida e’lon qilindi. Deyarli bir vaqtda <b>Pyer Ferma</b> ham xuddi shu g‘oyaga kelgan: uning «Tekis va fazoviy o‘rinlarga kirish» qo‘lyozmasi 1636–1637-yillarda olimlar orasida tarqalgan, lekin faqat 1679-yilda bosilgan. Shu sababli bu sohani ikkisining nomi bilan bog‘lash adolatli.', 'Метод координат был опубликован в 1637 году в «Геометрии» французского философа и математика <b>Рене Декарта</b> — приложении к «Рассуждению о методе». Почти одновременно к той же идее пришёл <b>Пьер Ферма</b>: его рукопись «Введение в изучение плоских и телесных мест» ходила среди учёных в 1636–1637 годах, но была напечатана лишь в 1679 году. Поэтому справедливо связывать этот метод с обоими именами.', 'The coordinate method was published in 1637 in <i>La Géométrie</i> by the French philosopher and mathematician <b>René Descartes</b>, an appendix to his <i>Discourse on Method</i>. At almost the same time <b>Pierre de Fermat</b> reached the same idea: his manuscript <i>Introduction to Plane and Solid Loci</i> circulated among scholars in 1636–1637 but was printed only in 1679. So it is fair to link the method with both names.'),
      L('Dekart va Ferma asosan tekislik bilan ishlagan. Uchinchi koordinatani muntazam qo‘llash XVIII asrda boshlandi: 1731-yilda yosh fransuz <b>Aleksi Klero</b> fazoviy egri chiziqlarni uchta koordinata bilan o‘rgandi, keyin <b>Leonard Eyler</b> va <b>Jozef Lagranj</b> fazoviy analitik geometriyani to‘liq nazariyaga aylantirdi. «Applikata» so‘zi lotincha <i>applicare</i> — «qo‘shib qo‘ymoq» so‘zidan olingan.', 'Декарт и Ферма работали в основном с плоскостью. Систематическое использование третьей координаты началось в XVIII веке: в 1731 году молодой француз <b>Алексис Клеро</b> изучил пространственные кривые с помощью трёх координат, затем <b>Леонард Эйлер</b> и <b>Жозеф Лагранж</b> превратили пространственную аналитическую геометрию в стройную теорию. Слово «аппликата» происходит от латинского <i>applicare</i> — «прикладывать».', 'Descartes and Fermat worked mainly in the plane. Systematic use of a third coordinate began in the 18th century: in 1731 the young Frenchman <b>Alexis Clairaut</b> studied space curves with three coordinates, and later <b>Leonhard Euler</b> and <b>Joseph-Louis Lagrange</b> turned solid analytic geometry into a complete theory. The word “applicate” comes from the Latin <i>applicare</i>, “to put against”.')
    ] },
    { kind: 'rule', h: L('Maxsus nuqtalar: o‘qlar va tekisliklar', 'Особые точки: оси и плоскости', 'Special points: axes and planes'), p: [
      L('Koordinatalarning qaysi biri nolga tengligiga qarab nuqtaning joylashuvi darhol aniq bo‘ladi. Masalan, A(0; 0; 5) nuqta Oz o‘qida yotadi, B(3; −2; 0) esa Oxy tekisligida. Nuqtaning tekislikka <b>proyeksiyasini</b> topish ham oson: M(x; y; z) ning Oxy tekisligiga proyeksiyasi (x; y; 0), Oz o‘qiga proyeksiyasi (0; 0; z).', 'По тому, какие координаты равны нулю, сразу видно расположение точки. Например, точка A(0; 0; 5) лежит на оси Oz, а B(3; −2; 0) — в плоскости Oxy. Легко найти и <b>проекцию</b> точки: проекция M(x; y; z) на плоскость Oxy — (x; y; 0), на ось Oz — (0; 0; z).', 'Which coordinates vanish tells us at once where a point lies. For example, A(0; 0; 5) lies on the Oz axis and B(3; −2; 0) in the Oxy plane. <b>Projections</b> are easy too: the projection of M(x; y; z) onto the Oxy plane is (x; y; 0), onto the Oz axis it is (0; 0; z).'),
      L('Shuningdek, |z| — nuqtadan Oxy tekisligigacha masofa, |x| — Oyz tekisligigacha, |y| — Oxz tekisligigacha masofa. Nuqtadan Oz o‘qigacha masofa esa √(x² + y²).', 'Кроме того, |z| — расстояние от точки до плоскости Oxy, |x| — до плоскости Oyz, |y| — до Oxz. А расстояние от точки до оси Oz равно √(x² + y²).', 'Also, |z| is the distance from the point to the Oxy plane, |x| to the Oyz plane and |y| to the Oxz plane. The distance from the point to the Oz axis is √(x² + y²).')
    ], table: { head: [L('Joy', 'Место', 'Location'), L('Shart', 'Условие', 'Condition'), L('Misol', 'Пример', 'Example')], rows: [
      [L('Koordinatalar boshi', 'Начало координат', 'Origin'), L('x = y = z = 0', 'x = y = z = 0', 'x = y = z = 0'), L('O(0; 0; 0)', 'O(0; 0; 0)', 'O(0; 0; 0)')],
      [L('Ox o‘qi', 'Ось Ox', 'Ox axis'), L('y = z = 0', 'y = z = 0', 'y = z = 0'), L('(4; 0; 0)', '(4; 0; 0)', '(4; 0; 0)')],
      [L('Oz o‘qi', 'Ось Oz', 'Oz axis'), L('x = y = 0', 'x = y = 0', 'x = y = 0'), L('(0; 0; −2)', '(0; 0; −2)', '(0; 0; −2)')],
      [L('Oxy tekisligi', 'Плоскость Oxy', 'Oxy plane'), L('z = 0', 'z = 0', 'z = 0'), L('(1; 5; 0)', '(1; 5; 0)', '(1; 5; 0)')],
      [L('Oyz tekisligi', 'Плоскость Oyz', 'Oyz plane'), L('x = 0', 'x = 0', 'x = 0'), L('(0; 3; 7)', '(0; 3; 7)', '(0; 3; 7)')]
    ] } },
    { kind: 'rule', h: L('Ikki nuqta orasidagi masofa', 'Расстояние между двумя точками', 'Distance between two points'), p: [
      L('<b>Teorema.</b> A(x₁; y₁; z₁) va B(x₂; y₂; z₂) nuqtalar orasidagi masofa: <b>AB = √((x₂ − x₁)² + (y₂ − y₁)² + (z₂ − z₁)²)</b>.', '<b>Теорема.</b> Расстояние между точками A(x₁; y₁; z₁) и B(x₂; y₂; z₂): <b>AB = √((x₂ − x₁)² + (y₂ − y₁)² + (z₂ − z₁)²)</b>.', '<b>Theorem.</b> The distance between A(x₁; y₁; z₁) and B(x₂; y₂; z₂) is <b>AB = √((x₂ − x₁)² + (y₂ − y₁)² + (z₂ − z₁)²)</b>.'),
      L('<b>Isbot g‘oyasi.</b> A va B orqali koordinata tekisliklariga parallel tekisliklar o‘tkazsak, qirralari |Δx|, |Δy|, |Δz| bo‘lgan to‘g‘ri burchakli parallelepiped hosil bo‘ladi, AB esa uning diagonali. Asosning diagonali Pifagor teoremasiga ko‘ra d₁² = Δx² + Δy². Keyin d₁ va |Δz| katetli to‘g‘ri burchakli uchburchakdan AB² = d₁² + Δz² = Δx² + Δy² + Δz². Shunday qilib, fazoviy formula — Pifagor teoremasining ikki marta qo‘llanishi.', '<b>Идея доказательства.</b> Проведя через A и B плоскости, параллельные координатным, получим прямоугольный параллелепипед с рёбрами |Δx|, |Δy|, |Δz|, а AB — его диагональ. Диагональ основания по теореме Пифагора: d₁² = Δx² + Δy². Затем из прямоугольного треугольника с катетами d₁ и |Δz|: AB² = d₁² + Δz² = Δx² + Δy² + Δz². Итак, пространственная формула — это теорема Пифагора, применённая дважды.', '<b>Proof idea.</b> Planes through A and B parallel to the coordinate planes form a rectangular box with edges |Δx|, |Δy|, |Δz|, and AB is its diagonal. By Pythagoras the base diagonal satisfies d₁² = Δx² + Δy². Then the right triangle with legs d₁ and |Δz| gives AB² = d₁² + Δz² = Δx² + Δy² + Δz². So the space formula is just Pythagoras used twice.'),
      L('Xususan, nuqtadan koordinatalar boshigacha masofa OM = √(x² + y² + z²). Agar z₁ = z₂ = 0 bo‘lsa, formula tekislikdagi tanish formulaga aylanadi.', 'В частности, расстояние от точки до начала координат OM = √(x² + y² + z²). При z₁ = z₂ = 0 формула превращается в знакомую плоскую.', 'In particular, the distance to the origin is OM = √(x² + y² + z²). When z₁ = z₂ = 0 the formula becomes the familiar planar one.')
    ] },
    { kind: 'rule', h: L('Kesma o‘rtasi va kesmani nisbatda bo‘lish', 'Середина отрезка и деление в отношении', 'Midpoint and division in a ratio'), p: [
      L('AB kesma o‘rtasi M ning koordinatalari uchlari koordinatalarining o‘rta arifmetigiga teng: <b>M((x₁ + x₂)/2; (y₁ + y₂)/2; (z₁ + z₂)/2)</b>. Isbot: A, M, B ni Ox o‘qiga proyeksiyalasak, parallel proyeksiyalashda kesma o‘rtasi o‘rtaga o‘tadi (Fales teoremasi), demak x = (x₁ + x₂)/2; qolgan o‘qlar uchun ham xuddi shunday.', 'Координаты середины M отрезка AB равны средним арифметическим координат концов: <b>M((x₁ + x₂)/2; (y₁ + y₂)/2; (z₁ + z₂)/2)</b>. Доказательство: спроецируем A, M, B на ось Ox; при параллельном проецировании середина переходит в середину (теорема Фалеса), значит x = (x₁ + x₂)/2; для остальных осей так же.', 'The midpoint M of AB has coordinates equal to the averages of the endpoints: <b>M((x₁ + x₂)/2; (y₁ + y₂)/2; (z₁ + z₂)/2)</b>. Proof: project A, M, B onto Ox; parallel projection sends a midpoint to a midpoint (Thales), so x = (x₁ + x₂)/2; the same holds on the other axes.'),
      L('Umumiyroq: C nuqta AB ni AC : CB = m : n nisbatda bo‘lsa, x = (n·x₁ + m·x₂)/(m + n), y va z uchun ham shunday. Uchburchak og‘irlik markazi (medianalar kesishgan nuqta) esa uchlar koordinatalarining o‘rtachasi: G((x₁ + x₂ + x₃)/3; (y₁ + y₂ + y₃)/3; (z₁ + z₂ + z₃)/3).', 'Более общо: если точка C делит AB в отношении AC : CB = m : n, то x = (n·x₁ + m·x₂)/(m + n), и так же для y и z. Центр тяжести треугольника (точка пересечения медиан) — среднее координат вершин: G((x₁ + x₂ + x₃)/3; (y₁ + y₂ + y₃)/3; (z₁ + z₂ + z₃)/3).', 'More generally, if C divides AB so that AC : CB = m : n, then x = (n·x₁ + m·x₂)/(m + n), and similarly for y and z. The centroid of a triangle (where the medians meet) is the average of the vertices: G((x₁ + x₂ + x₃)/3; (y₁ + y₂ + y₃)/3; (z₁ + z₂ + z₃)/3).'),
      L('Masofa formulasidan <b>sfera tenglamasi</b> ham kelib chiqadi: markazi C(a; b; c), radiusi R bo‘lgan sfera nuqtalari uchun (x − a)² + (y − b)² + (z − c)² = R².', 'Из формулы расстояния следует и <b>уравнение сферы</b>: для точек сферы с центром C(a; b; c) и радиусом R выполняется (x − a)² + (y − b)² + (z − c)² = R².', 'The distance formula also gives the <b>equation of a sphere</b>: points of the sphere with centre C(a; b; c) and radius R satisfy (x − a)² + (y − b)² + (z − c)² = R².')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Решённые примеры', 'Worked examples'), ex: [
      { q: L('A(1; 2; 3) va B(3; −4; 6) nuqtalar orasidagi masofani va AB kesma o‘rtasini toping.', 'Найдите расстояние между точками A(1; 2; 3) и B(3; −4; 6) и середину отрезка AB.', 'Find the distance between A(1; 2; 3) and B(3; −4; 6) and the midpoint of AB.'),
        s: L('Ayirmalar: Δx = 3 − 1 = 2, Δy = −4 − 2 = −6, Δz = 6 − 3 = 3. AB = √(4 + 36 + 9) = √49 = <b>7</b>. O‘rtasi: ((1 + 3)/2; (2 − 4)/2; (3 + 6)/2) = <b>(2; −1; 4,5)</b>.', 'Разности: Δx = 3 − 1 = 2, Δy = −4 − 2 = −6, Δz = 6 − 3 = 3. AB = √(4 + 36 + 9) = √49 = <b>7</b>. Середина: ((1 + 3)/2; (2 − 4)/2; (3 + 6)/2) = <b>(2; −1; 4,5)</b>.', 'Differences: Δx = 3 − 1 = 2, Δy = −4 − 2 = −6, Δz = 6 − 3 = 3. AB = √(4 + 36 + 9) = √49 = <b>7</b>. Midpoint: ((1 + 3)/2; (2 − 4)/2; (3 + 6)/2) = <b>(2; −1; 4.5)</b>.') },
      { q: L('Oz o‘qida A(1; 2; 3) va B(−2; 1; 0) nuqtalardan teng uzoqlikdagi nuqtani toping.', 'Найдите на оси Oz точку, равноудалённую от A(1; 2; 3) и B(−2; 1; 0).', 'Find the point on the Oz axis equidistant from A(1; 2; 3) and B(−2; 1; 0).'),
        s: L('Izlanayotgan nuqta M(0; 0; z). MA² = 1 + 4 + (z − 3)², MB² = 4 + 1 + z². Tenglaymiz: 5 + z² − 6z + 9 = 5 + z², bundan −6z + 9 = 0, z = 1,5. Javob: <b>M(0; 0; 1,5)</b>. Tekshirish: MA² = 5 + 2,25 = 7,25 va MB² = 5 + 2,25 = 7,25.', 'Искомая точка M(0; 0; z). MA² = 1 + 4 + (z − 3)², MB² = 4 + 1 + z². Приравниваем: 5 + z² − 6z + 9 = 5 + z², откуда −6z + 9 = 0, z = 1,5. Ответ: <b>M(0; 0; 1,5)</b>. Проверка: MA² = 5 + 2,25 = 7,25 и MB² = 5 + 2,25 = 7,25.', 'The point is M(0; 0; z). MA² = 1 + 4 + (z − 3)², MB² = 4 + 1 + z². Equate: 5 + z² − 6z + 9 = 5 + z², so −6z + 9 = 0, z = 1.5. Answer: <b>M(0; 0; 1.5)</b>. Check: MA² = 5 + 2.25 = 7.25 and MB² = 5 + 2.25 = 7.25.') },
      { q: L('M(2; −1; 4) — AB kesma o‘rtasi, A(5; 1; 0). B nuqtani toping.', 'M(2; −1; 4) — середина отрезка AB, A(5; 1; 0). Найдите точку B.', 'M(2; −1; 4) is the midpoint of AB and A(5; 1; 0). Find B.'),
        s: L('x<sub>M</sub> = (x<sub>A</sub> + x<sub>B</sub>)/2 dan x<sub>B</sub> = 2x<sub>M</sub> − x<sub>A</sub>. Shunday qilib, B(2·2 − 5; 2·(−1) − 1; 2·4 − 0) = <b>B(−1; −3; 8)</b>.', 'Из x<sub>M</sub> = (x<sub>A</sub> + x<sub>B</sub>)/2 получаем x<sub>B</sub> = 2x<sub>M</sub> − x<sub>A</sub>. Значит, B(2·2 − 5; 2·(−1) − 1; 2·4 − 0) = <b>B(−1; −3; 8)</b>.', 'From x<sub>M</sub> = (x<sub>A</sub> + x<sub>B</sub>)/2 we get x<sub>B</sub> = 2x<sub>M</sub> − x<sub>A</sub>. Hence B(2·2 − 5; 2·(−1) − 1; 2·4 − 0) = <b>B(−1; −3; 8)</b>.') },
      { q: L('A(0; 0; 0), B(3; 4; 0), C(0; 4; 3) uchburchakning turini aniqlang.', 'Определите вид треугольника A(0; 0; 0), B(3; 4; 0), C(0; 4; 3).', 'Determine the type of triangle A(0; 0; 0), B(3; 4; 0), C(0; 4; 3).'),
        s: L('AB = √(9 + 16 + 0) = 5, AC = √(0 + 16 + 9) = 5, BC = √(9 + 0 + 9) = √18 = 3√2. AB = AC, demak uchburchak <b>teng yonli</b>. To‘g‘ri burchakli emas: 25 + 18 ≠ 25 va 25 + 25 ≠ 18.', 'AB = √(9 + 16 + 0) = 5, AC = √(0 + 16 + 9) = 5, BC = √(9 + 0 + 9) = √18 = 3√2. AB = AC, значит треугольник <b>равнобедренный</b>. Прямоугольным он не является: 25 + 18 ≠ 25 и 25 + 25 ≠ 18.', 'AB = √(9 + 16 + 0) = 5, AC = √(0 + 16 + 9) = 5, BC = √(9 + 0 + 9) = √18 = 3√2. AB = AC, so the triangle is <b>isosceles</b>. It is not right-angled: 25 + 18 ≠ 25 and 25 + 25 ≠ 18.') },
      { q: L('Markazi C(1; −2; 3), radiusi 5 bo‘lgan sferada D(4; 2; 3) nuqta yotadimi?', 'Лежит ли точка D(4; 2; 3) на сфере с центром C(1; −2; 3) и радиусом 5?', 'Does D(4; 2; 3) lie on the sphere with centre C(1; −2; 3) and radius 5?'),
        s: L('CD² = (4 − 1)² + (2 + 2)² + (3 − 3)² = 9 + 16 + 0 = 25 = 5². Demak, CD = 5 va <b>D sferada yotadi</b>.', 'CD² = (4 − 1)² + (2 + 2)² + (3 − 3)² = 9 + 16 + 0 = 25 = 5². Значит, CD = 5, и <b>D лежит на сфере</b>.', 'CD² = (4 − 1)² + (2 + 2)² + (3 − 3)² = 9 + 16 + 0 = 25 = 5². So CD = 5 and <b>D lies on the sphere</b>.') }
    ] },
    { kind: 'steps', h: L('Koordinatalar usuli bilan masala yechish', 'Решение задач методом координат', 'Solving problems by coordinates'), list: [
      L('Koordinatalar sistemasini qulay joylashtiring: boshni jismning uchiga, o‘qlarni qirralar bo‘ylab yo‘naltiring (kub, parallelepiped uchun ideal).', 'Удобно расположите систему координат: начало — в вершине тела, оси — вдоль рёбер (идеально для куба и параллелепипеда).', 'Place the coordinate system conveniently: origin at a vertex of the solid, axes along its edges (ideal for a cube or a box).'),
      L('Kerakli nuqtalarning koordinatalarini yozing; o‘rtalar uchun o‘rta arifmetik formulasidan foydalaning.', 'Запишите координаты нужных точек; для середин используйте формулу среднего арифметического.', 'Write down the coordinates of the points you need; use the averaging formula for midpoints.'),
      L('Masofa, o‘rta nuqta yoki sfera formulasini qo‘llang.', 'Примените формулу расстояния, середины или сферы.', 'Apply the distance, midpoint or sphere formula.'),
      L('Natijani geometrik ma’no bilan tekshiring: masofa manfiy bo‘lolmaydi, kub ichidagi kesma diagonaldan uzun bo‘lolmaydi.', 'Проверьте результат по смыслу: расстояние не бывает отрицательным, отрезок внутри куба не длиннее диагонали.', 'Check the answer geometrically: a distance is never negative, and a segment inside a cube is never longer than its diagonal.')
    ], after: [
      L('Misol: qirrasi 2 bo‘lgan kubda A(0; 0; 0) uchdan qarama-qarshi yoqning markazi (1; 1; 2) gacha masofa √(1 + 1 + 4) = √6 ≈ 2,45 — bu diagonaldan (2√3 ≈ 3,46) kichik, natija mantiqiy.', 'Пример: в кубе с ребром 2 расстояние от вершины A(0; 0; 0) до центра противоположной грани (1; 1; 2) равно √(1 + 1 + 4) = √6 ≈ 2,45 — меньше диагонали (2√3 ≈ 3,46), результат разумный.', 'Example: in a cube of edge 2, the distance from vertex A(0; 0; 0) to the centre of the opposite face (1; 1; 2) is √(1 + 1 + 4) = √6 ≈ 2.45 — less than the diagonal (2√3 ≈ 3.46), so the result makes sense.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>Uchinchi qo‘shiluvchini unutish:</b> masofani √(Δx² + Δy²) deb hisoblash. Fazoda har doim uchta kvadrat bor.', '<b>Забывают третье слагаемое:</b> считают расстояние как √(Δx² + Δy²). В пространстве всегда три квадрата.', '<b>Forgetting the third term:</b> computing the distance as √(Δx² + Δy²). In space there are always three squares.'),
      L('<b>Ishorada adashish:</b> (−4 − 2)² o‘rniga (−4 + 2)² yozish. Avval ayirmani qavs ichida to‘liq hisoblang, keyin kvadratga oshiring.', '<b>Ошибка в знаках:</b> вместо (−4 − 2)² пишут (−4 + 2)². Сначала полностью вычислите разность в скобках, потом возводите в квадрат.', '<b>Sign slips:</b> writing (−4 + 2)² instead of (−4 − 2)². Compute the difference in brackets fully first, then square it.'),
      L('<b>Ildizdan bo‘laklab chiqarish:</b> √(a² + b²) ≠ a + b. Masalan, √(9 + 16) = 5, 7 emas.', '<b>Извлечение корня по частям:</b> √(a² + b²) ≠ a + b. Например, √(9 + 16) = 5, а не 7.', '<b>Splitting the root:</b> √(a² + b²) ≠ a + b. For example, √(9 + 16) = 5, not 7.'),
      L('<b>O‘qda yotgan nuqtani noto‘g‘ri yozish:</b> Oz o‘qidagi nuqta (0; 0; z), (z; 0; 0) emas. Oxy tekisligida z = 0, x = 0 emas.', '<b>Неверная запись точки на оси:</b> точка на Oz — это (0; 0; z), а не (z; 0; 0). В плоскости Oxy равен нулю z, а не x.', '<b>Writing a point on an axis wrongly:</b> a point on Oz is (0; 0; z), not (z; 0; 0). In the Oxy plane it is z that is zero, not x.'),
      L('<b>O‘rta nuqtadan uchni topishda</b> o‘rtachani olish: B = 2M − A, (M + A)/2 emas.', '<b>При поиске конца по середине</b> берут среднее: правильно B = 2M − A, а не (M + A)/2.', '<b>Finding an endpoint from the midpoint</b> by averaging: correct is B = 2M − A, not (M + A)/2.')
    ] },
    { kind: 'life', h: L('Hayotda uch koordinata', 'Три координаты в жизни', 'Three coordinates in real life'), p: [
      L('<b>GPS</b> navigatori sun’iy yo‘ldoshlargacha masofalarni o‘lchaydi va har bir yo‘ldosh atrofida sfera tenglamasini tuzadi. Bir nechta sferaning kesishgan nuqtasi — sizning (x; y; z) koordinatalaringiz. Aslida bu, masofa formulasidan tuzilgan tenglamalar sistemasini yechish demakdir.', 'Навигатор <b>GPS</b> измеряет расстояния до спутников и для каждого спутника составляет уравнение сферы. Точка пересечения нескольких сфер — ваши координаты (x; y; z). По сути, это решение системы уравнений, составленных по формуле расстояния.', 'A <b>GPS</b> receiver measures distances to satellites and writes the equation of a sphere around each one. The common point of several spheres gives your coordinates (x; y; z). In essence it solves a system of equations built from the distance formula.'),
      L('<b>3D-printer</b> va <b>CNC</b> dastgohi soplo yoki frezani (x; y; z) buyruqlari bo‘yicha harakatlantiradi. Kompyuter o‘yinlari va animatsiya filmlarida har bir personaj millionlab uchburchaklardan iborat bo‘lib, ularning har bir uchi uchta koordinata bilan saqlanadi. Shifokorlar KT va MRT tasvirlarida o‘simtaning aniq o‘rnini ham koordinatalar orqali belgilaydi.', '<b>3D-принтер</b> и станок с <b>ЧПУ</b> двигают сопло или фрезу по командам (x; y; z). В компьютерных играх и анимационных фильмах каждый персонаж состоит из миллионов треугольников, и каждая их вершина хранится тремя координатами. Врачи на снимках КТ и МРТ тоже указывают точное положение опухоли координатами.', 'A <b>3D printer</b> or a <b>CNC</b> machine moves its nozzle or cutter by (x; y; z) commands. In video games and animated films every character is made of millions of triangles, each vertex stored as three coordinates. Doctors locate a tumour precisely on CT and MRI scans with coordinates as well.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Fun facts'), list: [
      L('Rivoyatga ko‘ra, Dekart karavotda yotib, shift burchagida o‘rmalab yurgan pashshani kuzatgan va uning o‘rnini uchta devorgacha masofa bilan ifodalash mumkinligini tushungan. Bu go‘zal afsona, lekin hujjatlar bilan tasdiqlanmagan.', 'По легенде, Декарт, лёжа в постели, наблюдал за мухой в углу потолка и понял, что её положение можно задать расстояниями до трёх стен. Это красивая легенда, но документами она не подтверждена.', 'Legend says Descartes, lying in bed, watched a fly in a corner of the ceiling and realised its position could be given by its distances to three walls. A lovely story, but not confirmed by any document.'),
      L('Fizika va muhandislikda koordinatalar to‘rtinchi o‘lcham — vaqt bilan to‘ldiriladi: hodisa (x; y; z; t) bilan beriladi.', 'В физике и технике к координатам добавляют четвёртое измерение — время: событие задаётся четвёркой (x; y; z; t).', 'In physics and engineering a fourth dimension — time — is added: an event is given by (x; y; z; t).'),
      L('n o‘lchovli fazoda masofa formulasi xuddi shunday: √(Δx₁² + Δx₂² + … + Δxₙ²). Sun’iy intellekt matnlar va rasmlarni yuzlab o‘lchovli fazodagi nuqtalar sifatida taqqoslaydi.', 'В n-мерном пространстве формула расстояния такая же: √(Δx₁² + Δx₂² + … + Δxₙ²). Искусственный интеллект сравнивает тексты и изображения как точки в пространстве из сотен измерений.', 'In n-dimensional space the distance formula looks the same: √(Δx₁² + Δx₂² + … + Δxₙ²). Artificial intelligence compares texts and images as points in spaces of hundreds of dimensions.')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверьте себя', 'Check yourself'), ex: [
      { q: L('M(3; −4; 12) nuqtadan koordinatalar boshigacha va Oz o‘qigacha masofani toping.', 'Найдите расстояние от точки M(3; −4; 12) до начала координат и до оси Oz.', 'Find the distance from M(3; −4; 12) to the origin and to the Oz axis.'),
        s: L('OM = √(9 + 16 + 144) = √169 = 13. Oz o‘qigacha: √(9 + 16) = 5.', 'OM = √(9 + 16 + 144) = √169 = 13. До оси Oz: √(9 + 16) = 5.', 'OM = √(9 + 16 + 144) = √169 = 13. To the Oz axis: √(9 + 16) = 5.') },
      { q: L('A(2; 0; −1), B(0; 4; 3), C(1; −1; 4) uchburchak og‘irlik markazini toping.', 'Найдите центр тяжести треугольника A(2; 0; −1), B(0; 4; 3), C(1; −1; 4).', 'Find the centroid of triangle A(2; 0; −1), B(0; 4; 3), C(1; −1; 4).'),
        s: L('G((2 + 0 + 1)/3; (0 + 4 − 1)/3; (−1 + 3 + 4)/3) = G(1; 1; 2).', 'G((2 + 0 + 1)/3; (0 + 4 − 1)/3; (−1 + 3 + 4)/3) = G(1; 1; 2).', 'G((2 + 0 + 1)/3; (0 + 4 − 1)/3; (−1 + 3 + 4)/3) = G(1; 1; 2).') }
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Fazoda nuqta uchta koordinata bilan beriladi: M(x; y; z) — abssissa, ordinata, applikata.', 'В пространстве точка задаётся тремя координатами: M(x; y; z) — абсцисса, ордината, аппликата.', 'In space a point is given by three coordinates: M(x; y; z) — abscissa, ordinate, applicate.'),
      L('Uch koordinata tekisligi fazoni sakkiz oktantga bo‘ladi; Oz o‘qida x = y = 0, Oxy tekisligida z = 0.', 'Три координатные плоскости делят пространство на восемь октантов; на оси Oz x = y = 0, в плоскости Oxy z = 0.', 'The three coordinate planes split space into eight octants; on Oz x = y = 0, in the Oxy plane z = 0.'),
      L('Masofa: d = √(Δx² + Δy² + Δz²) — ikki marta qo‘llangan Pifagor teoremasi.', 'Расстояние: d = √(Δx² + Δy² + Δz²) — дважды применённая теорема Пифагора.', 'Distance: d = √(Δx² + Δy² + Δz²) — Pythagoras applied twice.'),
      L('Kesma o‘rtasi — uchlar koordinatalarining o‘rta arifmetigi; uchburchak og‘irlik markazi — uch uchning o‘rtachasi.', 'Середина отрезка — среднее арифметическое координат концов; центр тяжести треугольника — среднее трёх вершин.', 'A midpoint is the average of the endpoints; the centroid of a triangle is the average of its three vertices.'),
      L('Sfera tenglamasi: (x − a)² + (y − b)² + (z − c)² = R².', 'Уравнение сферы: (x − a)² + (y − b)² + (z − c)² = R².', 'Sphere: (x − a)² + (y − b)² + (z − c)² = R².'),
      L('Koordinatalar usuli (Dekart, Ferma, 1637) geometriya masalalarini algebra tiliga o‘giradi.', 'Метод координат (Декарт, Ферма, 1637) переводит задачи геометрии на язык алгебры.', 'The coordinate method (Descartes, Fermat, 1637) translates geometry problems into algebra.')
    ] }
  ] });

  // ---------- t2. Fazoda vektorlar va ular ustida amallar ----------
  T.add(P, 't2', { sections: [
    { kind: 'intro', h: L('Kattalik va yo‘nalish', 'Величина и направление', 'Magnitude and direction'), p: [
      L('Uchuvchiga «shamol 15 m/s tezlikda esmoqda» deyish yetarli emas — qaysi tomonga esayotgani ham muhim. Kuch, tezlik, ko‘chish kabi kattaliklar son bilan birga yo‘nalishga ham ega; ular <b>vektorlar</b> bilan tasvirlanadi. 9-sinfda tekislikdagi vektorlarni o‘rgangan edik. Endi ularni fazoga o‘tkazamiz: har bir vektor <b>uchta koordinata</b> bilan beriladi, amallar esa xuddi tekislikdagidek bajariladi.', 'Пилоту мало сказать «ветер дует со скоростью 15 м/с» — важно и то, куда он дует. Сила, скорость, перемещение имеют не только численное значение, но и направление; их изображают <b>векторами</b>. В 9-м классе мы изучали векторы на плоскости. Теперь перенесём их в пространство: каждый вектор задаётся <b>тремя координатами</b>, а действия выполняются так же, как на плоскости.', 'Telling a pilot “the wind blows at 15 m/s” is not enough — where it blows matters too. Force, velocity and displacement have a size and a direction; they are represented by <b>vectors</b>. In grade 9 we studied vectors in the plane. Now we carry them into space: every vector is given by <b>three coordinates</b>, and operations work just as in the plane.'),
      L('Bu mavzuning eng kuchli quroli — <b>skalyar ko‘paytma</b>. U yordamida fazodagi har qanday ikki to‘g‘ri chiziq orasidagi burchakni hisoblash va perpendikulyarlikni bir qator hisob bilan tekshirish mumkin.', 'Самый сильный инструмент этой темы — <b>скалярное произведение</b>. С его помощью можно вычислить угол между любыми двумя прямыми в пространстве и проверить перпендикулярность одной строкой вычислений.', 'The strongest tool of this topic is the <b>dot product</b>. With it you can compute the angle between any two lines in space and test perpendicularity in a single line of computation.')
    ] },
    { kind: 'def', h: L('Vektor va uning koordinatalari', 'Вектор и его координаты', 'A vector and its coordinates'), p: [
      L('<b>Vektor</b> — yo‘nalgan kesma, ya’ni boshi va oxiri ko‘rsatilgan kesma: AB⃗. Uzunligi bir xil va yo‘nalishi bir xil bo‘lgan vektorlar <b>teng</b> hisoblanadi, shuning uchun vektorni fazoning istalgan nuqtasidan qo‘yish mumkin. Uzunligi nolga teng vektor — <b>nol vektor</b> 0⃗.', '<b>Вектор</b> — направленный отрезок, то есть отрезок с указанными началом и концом: AB⃗. Векторы одинаковой длины и одинакового направления считаются <b>равными</b>, поэтому вектор можно откладывать от любой точки пространства. Вектор нулевой длины — <b>нулевой вектор</b> 0⃗.', 'A <b>vector</b> is a directed segment, that is, a segment with a marked start and end: AB⃗. Vectors with the same length and the same direction are <b>equal</b>, so a vector may be drawn from any point of space. The vector of zero length is the <b>zero vector</b> 0⃗.'),
      L('Ox, Oy, Oz o‘qlari bo‘ylab yo‘nalgan uzunligi 1 ga teng vektorlar — <b>koordinata vektorlari</b> (ortlar) i⃗, j⃗, k⃗. Har qanday vektor ular orqali yagona usulda yoyiladi: a⃗ = x·i⃗ + y·j⃗ + z·k⃗. Sonlar x, y, z — vektorning <b>koordinatalari</b>: a⃗(x; y; z).', 'Векторы единичной длины, направленные по осям Ox, Oy, Oz, — <b>координатные векторы</b> (орты) i⃗, j⃗, k⃗. Любой вектор единственным образом раскладывается по ним: a⃗ = x·i⃗ + y·j⃗ + z·k⃗. Числа x, y, z — <b>координаты</b> вектора: a⃗(x; y; z).', 'Unit vectors along Ox, Oy, Oz are the <b>coordinate vectors</b> (basis vectors) i⃗, j⃗, k⃗. Every vector can be written in exactly one way as a⃗ = x·i⃗ + y·j⃗ + z·k⃗. The numbers x, y, z are the <b>coordinates</b> of the vector: a⃗(x; y; z).'),
      L('Agar A(x₁; y₁; z₁), B(x₂; y₂; z₂) bo‘lsa, <b>AB⃗ = (x₂ − x₁; y₂ − y₁; z₂ − z₁)</b> — «oxiridan boshini ayiramiz». Vektor uzunligi (moduli): <b>|a⃗| = √(x² + y² + z²)</b>, bu masofa formulasining o‘zi.', 'Если A(x₁; y₁; z₁), B(x₂; y₂; z₂), то <b>AB⃗ = (x₂ − x₁; y₂ − y₁; z₂ − z₁)</b> — «из конца вычитаем начало». Длина (модуль) вектора: <b>|a⃗| = √(x² + y² + z²)</b> — это та же формула расстояния.', 'If A(x₁; y₁; z₁) and B(x₂; y₂; z₂), then <b>AB⃗ = (x₂ − x₁; y₂ − y₁; z₂ − z₁)</b> — “end minus start”. The length (magnitude) is <b>|a⃗| = √(x² + y² + z²)</b>, which is just the distance formula.')
    ] },
    { kind: 'history', h: L('Gamilton ko‘prigi va vektorlarning tug‘ilishi', 'Мост Гамильтона и рождение векторов', 'Hamilton’s bridge and the birth of vectors'), p: [
      L('Irlandiyalik matematik <b>Uilyam Rouan Gamilton</b> uzoq yillar fazodagi burilishlarni sonlar bilan ifodalashga urindi. 1843-yil 16-oktabrda Dublindagi Brum ko‘prigi yonidan o‘tayotib, u yechimni topdi — <b>kvaternionlar</b> va hayajondan formulani ko‘prik toshiga o‘yib yozdi. Bugun u yerda yodgorlik lavhasi bor. Aynan Gamilton «vektor» (lotincha <i>vector</i> — «tashuvchi») va «skalyar» atamalarini kiritgan.', 'Ирландский математик <b>Уильям Роуэн Гамильтон</b> много лет пытался описать повороты в пространстве числами. 16 октября 1843 года, проходя у моста Брум в Дублине, он нашёл решение — <b>кватернионы</b> — и от волнения вырезал формулу на камне моста. Сегодня там висит памятная табличка. Именно Гамильтон ввёл термины «вектор» (лат. <i>vector</i> — «несущий») и «скаляр».', 'The Irish mathematician <b>William Rowan Hamilton</b> spent years trying to describe rotations in space with numbers. On 16 October 1843, walking by Broom Bridge in Dublin, he found the answer — <b>quaternions</b> — and in excitement carved the formula into the stone of the bridge. A plaque marks the spot today. Hamilton also coined the words “vector” (Latin <i>vector</i>, “carrier”) and “scalar”.'),
      L('1844-yilda nemis o‘qituvchisi <b>German Grassman</b> ko‘p o‘lchovli fazolar nazariyasini e’lon qildi, ammo uni zamondoshlari tushunmadi. 1880-yillarda amerikalik <b>Jozaya Gibbs</b> va ingliz <b>Oliver Xevisayd</b> kvaternionlardan bugungi soddaroq vektor hisobini ajratib oldi — skalyar va vektor ko‘paytmalar bilan. Fiziklar uni darhol qabul qildi, chunki Maksvellning elektromagnetizm tenglamalari shu tilda juda ixcham yozildi.', 'В 1844 году немецкий учитель <b>Герман Грассман</b> опубликовал теорию многомерных пространств, но современники её не поняли. В 1880-х американец <b>Джозайя Гиббс</b> и англичанин <b>Оливер Хевисайд</b> выделили из кватернионов более простое векторное исчисление — со скалярным и векторным произведениями. Физики сразу приняли его, потому что уравнения электромагнетизма Максвелла записывались на этом языке очень компактно.', 'In 1844 the German schoolteacher <b>Hermann Grassmann</b> published a theory of many-dimensional spaces, but his contemporaries did not understand it. In the 1880s the American <b>Josiah Willard Gibbs</b> and the Englishman <b>Oliver Heaviside</b> extracted from quaternions the simpler vector calculus we use today, with the dot and cross products. Physicists adopted it at once, because Maxwell’s equations of electromagnetism became very compact in that language.')
    ] },
    { kind: 'rule', h: L('Vektorlar ustida amallar', 'Действия над векторами', 'Operations on vectors'), p: [
      L('a⃗(x₁; y₁; z₁) va b⃗(x₂; y₂; z₂) uchun amallar koordinatalar bo‘yicha bajariladi: <b>a⃗ + b⃗ = (x₁ + x₂; y₁ + y₂; z₁ + z₂)</b>, <b>a⃗ − b⃗ = (x₁ − x₂; y₁ − y₂; z₁ − z₂)</b>, <b>λa⃗ = (λx₁; λy₁; λz₁)</b>. Geometrik ma’no o‘zgarmaydi: yig‘indi uchburchak yoki parallelogramm qoidasi bilan yasaladi, λ &gt; 0 da songa ko‘paytirish vektorni cho‘zadi yoki qisqartiradi, λ &lt; 0 da esa yo‘nalishini teskarisiga o‘zgartiradi.', 'Для a⃗(x₁; y₁; z₁) и b⃗(x₂; y₂; z₂) действия выполняются покоординатно: <b>a⃗ + b⃗ = (x₁ + x₂; y₁ + y₂; z₁ + z₂)</b>, <b>a⃗ − b⃗ = (x₁ − x₂; y₁ − y₂; z₁ − z₂)</b>, <b>λa⃗ = (λx₁; λy₁; λz₁)</b>. Геометрический смысл прежний: сумма строится по правилу треугольника или параллелограмма, умножение на λ &gt; 0 растягивает или сжимает вектор, а при λ &lt; 0 меняет направление на противоположное.', 'For a⃗(x₁; y₁; z₁) and b⃗(x₂; y₂; z₂) the operations are done coordinate by coordinate: <b>a⃗ + b⃗ = (x₁ + x₂; y₁ + y₂; z₁ + z₂)</b>, <b>a⃗ − b⃗ = (x₁ − x₂; y₁ − y₂; z₁ − z₂)</b>, <b>λa⃗ = (λx₁; λy₁; λz₁)</b>. The geometric meaning is unchanged: a sum is built by the triangle or parallelogram rule; multiplying by λ &gt; 0 stretches or shrinks a vector, and λ &lt; 0 also reverses it.'),
      L('<b>Kollinear vektorlar</b> bitta to‘g‘ri chiziqqa parallel bo‘ladi; nol bo‘lmagan b⃗ uchun a⃗ ∥ b⃗ ⇔ a⃗ = λb⃗, ya’ni koordinatalar proporsional: x₁/x₂ = y₁/y₂ = z₁/z₂. Fazoda yangi tushuncha ham bor — <b>komplanar vektorlar</b>, ya’ni bitta tekislikka parallel vektorlar. Uchta komplanar bo‘lmagan vektor orqali istalgan vektorni yagona usulda yoyish mumkin; i⃗, j⃗, k⃗ — shunday uchlikning eng qulayi.', '<b>Коллинеарные векторы</b> параллельны одной прямой; для ненулевого b⃗ a⃗ ∥ b⃗ ⇔ a⃗ = λb⃗, то есть координаты пропорциональны: x₁/x₂ = y₁/y₂ = z₁/z₂. В пространстве есть и новое понятие — <b>компланарные векторы</b>, параллельные одной плоскости. По трём некомпланарным векторам любой вектор раскладывается единственным образом; i⃗, j⃗, k⃗ — самая удобная такая тройка.', '<b>Collinear vectors</b> are parallel to one line; for a nonzero b⃗, a⃗ ∥ b⃗ ⇔ a⃗ = λb⃗, i.e. the coordinates are proportional: x₁/x₂ = y₁/y₂ = z₁/z₂. Space brings a new notion — <b>coplanar vectors</b>, parallel to one plane. Any vector can be expressed uniquely through three non-coplanar vectors; i⃗, j⃗, k⃗ is the most convenient such triple.')
    ] },
    { kind: 'rule', h: L('Skalyar ko‘paytma', 'Скалярное произведение', 'The dot product'), p: [
      L('<b>Ta’rif.</b> Ikki vektorning skalyar ko‘paytmasi — ularning uzunliklari va orasidagi burchak kosinusining ko‘paytmasi: <b>a⃗·b⃗ = |a⃗|·|b⃗|·cos φ</b>. Natija — vektor emas, <b>son</b> (skalyar).', '<b>Определение.</b> Скалярное произведение двух векторов — произведение их длин на косинус угла между ними: <b>a⃗·b⃗ = |a⃗|·|b⃗|·cos φ</b>. Результат — не вектор, а <b>число</b> (скаляр).', '<b>Definition.</b> The dot product of two vectors is the product of their lengths and the cosine of the angle between them: <b>a⃗·b⃗ = |a⃗|·|b⃗|·cos φ</b>. The result is not a vector but a <b>number</b> (a scalar).'),
      L('<b>Teorema.</b> Koordinatalarda: <b>a⃗·b⃗ = x₁x₂ + y₁y₂ + z₁z₂</b>. <b>Isbot.</b> a⃗ va b⃗ ni bir nuqtadan qo‘yib, uchlarini tutashtiramiz; uchinchi tomon a⃗ − b⃗ vektoridir. Kosinuslar teoremasi: |a⃗ − b⃗|² = |a⃗|² + |b⃗|² − 2|a⃗||b⃗|cos φ. Chap tomonni koordinatalarda yozamiz: (x₁ − x₂)² + (y₁ − y₂)² + (z₁ − z₂)² = (x₁² + y₁² + z₁²) + (x₂² + y₂² + z₂²) − 2(x₁x₂ + y₁y₂ + z₁z₂). Taqqoslasak, |a⃗||b⃗|cos φ = x₁x₂ + y₁y₂ + z₁z₂.', '<b>Теорема.</b> В координатах: <b>a⃗·b⃗ = x₁x₂ + y₁y₂ + z₁z₂</b>. <b>Доказательство.</b> Отложим a⃗ и b⃗ от одной точки и соединим их концы; третья сторона — вектор a⃗ − b⃗. По теореме косинусов |a⃗ − b⃗|² = |a⃗|² + |b⃗|² − 2|a⃗||b⃗|cos φ. Левую часть запишем в координатах: (x₁ − x₂)² + (y₁ − y₂)² + (z₁ − z₂)² = (x₁² + y₁² + z₁²) + (x₂² + y₂² + z₂²) − 2(x₁x₂ + y₁y₂ + z₁z₂). Сравнивая, получаем |a⃗||b⃗|cos φ = x₁x₂ + y₁y₂ + z₁z₂.', '<b>Theorem.</b> In coordinates, <b>a⃗·b⃗ = x₁x₂ + y₁y₂ + z₁z₂</b>. <b>Proof.</b> Draw a⃗ and b⃗ from one point and join their ends; the third side is a⃗ − b⃗. By the law of cosines |a⃗ − b⃗|² = |a⃗|² + |b⃗|² − 2|a⃗||b⃗|cos φ. Writing the left side in coordinates: (x₁ − x₂)² + (y₁ − y₂)² + (z₁ − z₂)² = (x₁² + y₁² + z₁²) + (x₂² + y₂² + z₂²) − 2(x₁x₂ + y₁y₂ + z₁z₂). Comparing gives |a⃗||b⃗|cos φ = x₁x₂ + y₁y₂ + z₁z₂.'),
      L('<b>Natijalar:</b> cos φ = (x₁x₂ + y₁y₂ + z₁z₂) / (|a⃗|·|b⃗|); <b>a⃗ ⊥ b⃗ ⇔ a⃗·b⃗ = 0</b>; a⃗·a⃗ = |a⃗|². Ko‘paytma musbat bo‘lsa burchak o‘tkir, manfiy bo‘lsa o‘tmas. Xossalari: a⃗·b⃗ = b⃗·a⃗, (λa⃗)·b⃗ = λ(a⃗·b⃗), a⃗·(b⃗ + c⃗) = a⃗·b⃗ + a⃗·c⃗.', '<b>Следствия:</b> cos φ = (x₁x₂ + y₁y₂ + z₁z₂) / (|a⃗|·|b⃗|); <b>a⃗ ⊥ b⃗ ⇔ a⃗·b⃗ = 0</b>; a⃗·a⃗ = |a⃗|². Если произведение положительно — угол острый, если отрицательно — тупой. Свойства: a⃗·b⃗ = b⃗·a⃗, (λa⃗)·b⃗ = λ(a⃗·b⃗), a⃗·(b⃗ + c⃗) = a⃗·b⃗ + a⃗·c⃗.', '<b>Consequences:</b> cos φ = (x₁x₂ + y₁y₂ + z₁z₂) / (|a⃗|·|b⃗|); <b>a⃗ ⊥ b⃗ ⇔ a⃗·b⃗ = 0</b>; a⃗·a⃗ = |a⃗|². A positive product means an acute angle, a negative one an obtuse angle. Properties: a⃗·b⃗ = b⃗·a⃗, (λa⃗)·b⃗ = λ(a⃗·b⃗), a⃗·(b⃗ + c⃗) = a⃗·b⃗ + a⃗·c⃗.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Решённые примеры', 'Worked examples'), ex: [
      { q: L('a⃗(2; −1; 3), b⃗(1; 4; −2). a⃗ + b⃗, 2a⃗ − b⃗, |a⃗| va a⃗·b⃗ ni toping.', 'a⃗(2; −1; 3), b⃗(1; 4; −2). Найдите a⃗ + b⃗, 2a⃗ − b⃗, |a⃗| и a⃗·b⃗.', 'a⃗(2; −1; 3), b⃗(1; 4; −2). Find a⃗ + b⃗, 2a⃗ − b⃗, |a⃗| and a⃗·b⃗.'),
        s: L('a⃗ + b⃗ = (3; 3; 1). 2a⃗ = (4; −2; 6), 2a⃗ − b⃗ = (3; −6; 8). |a⃗| = √(4 + 1 + 9) = √14 ≈ 3,74. a⃗·b⃗ = 2·1 + (−1)·4 + 3·(−2) = 2 − 4 − 6 = <b>−8</b> &lt; 0, demak burchak o‘tmas.', 'a⃗ + b⃗ = (3; 3; 1). 2a⃗ = (4; −2; 6), 2a⃗ − b⃗ = (3; −6; 8). |a⃗| = √(4 + 1 + 9) = √14 ≈ 3,74. a⃗·b⃗ = 2·1 + (−1)·4 + 3·(−2) = 2 − 4 − 6 = <b>−8</b> &lt; 0, значит угол тупой.', 'a⃗ + b⃗ = (3; 3; 1). 2a⃗ = (4; −2; 6), 2a⃗ − b⃗ = (3; −6; 8). |a⃗| = √(4 + 1 + 9) = √14 ≈ 3.74. a⃗·b⃗ = 2·1 + (−1)·4 + 3·(−2) = 2 − 4 − 6 = <b>−8</b> &lt; 0, so the angle is obtuse.') },
      { q: L('a⃗(1; 1; 0) va b⃗(1; 0; 1) vektorlar orasidagi burchakni toping.', 'Найдите угол между векторами a⃗(1; 1; 0) и b⃗(1; 0; 1).', 'Find the angle between a⃗(1; 1; 0) and b⃗(1; 0; 1).'),
        s: L('a⃗·b⃗ = 1 + 0 + 0 = 1; |a⃗| = |b⃗| = √2. cos φ = 1/(√2·√2) = 1/2, demak <b>φ = 60°</b>. (Bu kubning ikki qo‘shni yog‘idagi diagonallar: ular teng tomonli uchburchak hosil qiladi.)', 'a⃗·b⃗ = 1 + 0 + 0 = 1; |a⃗| = |b⃗| = √2. cos φ = 1/(√2·√2) = 1/2, значит <b>φ = 60°</b>. (Это диагонали двух соседних граней куба: они образуют равносторонний треугольник.)', 'a⃗·b⃗ = 1 + 0 + 0 = 1; |a⃗| = |b⃗| = √2. cos φ = 1/(√2·√2) = 1/2, so <b>φ = 60°</b>. (These are diagonals of two adjacent faces of a cube: they form an equilateral triangle.)') },
      { q: L('m ning qanday qiymatida a⃗(m; 2; −1) va b⃗(3; m; 4) perpendikulyar?', 'При каком m векторы a⃗(m; 2; −1) и b⃗(3; m; 4) перпендикулярны?', 'For which m are a⃗(m; 2; −1) and b⃗(3; m; 4) perpendicular?'),
        s: L('Shart: a⃗·b⃗ = 0. 3m + 2m − 4 = 0, 5m = 4, <b>m = 0,8</b>. Tekshirish: 2,4 + 1,6 − 4 = 0.', 'Условие: a⃗·b⃗ = 0. 3m + 2m − 4 = 0, 5m = 4, <b>m = 0,8</b>. Проверка: 2,4 + 1,6 − 4 = 0.', 'Condition: a⃗·b⃗ = 0. 3m + 2m − 4 = 0, 5m = 4, <b>m = 0.8</b>. Check: 2.4 + 1.6 − 4 = 0.') },
      { q: L('Kubning diagonali va qirrasi orasidagi burchakni toping.', 'Найдите угол между диагональю куба и его ребром.', 'Find the angle between a diagonal of a cube and an edge.'),
        s: L('Qirrasi 1 bo‘lgan kubni o‘qlar bo‘ylab joylashtiramiz: diagonal d⃗(1; 1; 1), qirra e⃗(1; 0; 0). cos φ = 1/(√3·1) = 1/√3 ≈ 0,577, <b>φ ≈ 54,7°</b>. Javob kub o‘lchamiga bog‘liq emas.', 'Поместим куб с ребром 1 вдоль осей: диагональ d⃗(1; 1; 1), ребро e⃗(1; 0; 0). cos φ = 1/(√3·1) = 1/√3 ≈ 0,577, <b>φ ≈ 54,7°</b>. Ответ не зависит от размера куба.', 'Place a unit cube along the axes: diagonal d⃗(1; 1; 1), edge e⃗(1; 0; 0). cos φ = 1/(√3·1) = 1/√3 ≈ 0.577, <b>φ ≈ 54.7°</b>. The answer does not depend on the size of the cube.') },
      { q: L('a⃗(2; −4; 6) va b⃗(−1; 2; −3) kollinearmi? Bir xil yo‘nalganmi?', 'Коллинеарны ли a⃗(2; −4; 6) и b⃗(−1; 2; −3)? Сонаправлены ли они?', 'Are a⃗(2; −4; 6) and b⃗(−1; 2; −3) collinear? Do they point the same way?'),
        s: L('2/(−1) = −4/2 = 6/(−3) = −2, demak a⃗ = −2b⃗: vektorlar <b>kollinear</b>, lekin λ = −2 &lt; 0 bo‘lgani uchun <b>qarama-qarshi yo‘nalgan</b>.', '2/(−1) = −4/2 = 6/(−3) = −2, значит a⃗ = −2b⃗: векторы <b>коллинеарны</b>, но так как λ = −2 &lt; 0, они <b>противоположно направлены</b>.', '2/(−1) = −4/2 = 6/(−3) = −2, so a⃗ = −2b⃗: the vectors are <b>collinear</b>, but since λ = −2 &lt; 0 they point in <b>opposite directions</b>.') }
    ] },
    { kind: 'steps', h: L('Ikki to‘g‘ri chiziq orasidagi burchak', 'Угол между двумя прямыми', 'Angle between two lines'), list: [
      L('Har bir to‘g‘ri chiziqda ikkita nuqtani tanlab, yo‘naltiruvchi vektorlarni toping (oxiridan boshini ayiring).', 'На каждой прямой выберите две точки и найдите направляющие векторы (из конца вычтите начало).', 'Pick two points on each line and find the direction vectors (end minus start).'),
      L('Skalyar ko‘paytmani va uzunliklarni hisoblang.', 'Вычислите скалярное произведение и длины.', 'Compute the dot product and the lengths.'),
      L('To‘g‘ri chiziqlar orasidagi burchak 90° dan oshmaydi, shuning uchun modul oling: cos φ = |a⃗·b⃗| / (|a⃗|·|b⃗|).', 'Угол между прямыми не больше 90°, поэтому берите модуль: cos φ = |a⃗·b⃗| / (|a⃗|·|b⃗|).', 'The angle between lines never exceeds 90°, so take the absolute value: cos φ = |a⃗·b⃗| / (|a⃗|·|b⃗|).'),
      L('Burchakni jadval yoki kalkulyator yordamida toping; ayqash to‘g‘ri chiziqlar uchun ham usul aynan shunday ishlaydi.', 'Найдите угол по таблице или калькулятору; для скрещивающихся прямых метод работает точно так же.', 'Find the angle with a table or calculator; the method works the same way for skew lines.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>Vektor koordinatalarini teskari ayirish:</b> AB⃗ = A − B deb yozish. To‘g‘risi: AB⃗ = B − A (oxiridan boshini).', '<b>Вычитание наоборот:</b> пишут AB⃗ = A − B. Правильно: AB⃗ = B − A (из конца — начало).', '<b>Subtracting the wrong way:</b> writing AB⃗ = A − B. Correct: AB⃗ = B − A (end minus start).'),
      L('<b>Skalyar ko‘paytmani vektor deb hisoblash:</b> (x₁x₂; y₁y₂; z₁z₂) yozish. Skalyar ko‘paytma — bitta son, ko‘paytmalar <b>qo‘shiladi</b>.', '<b>Считают скалярное произведение вектором:</b> пишут (x₁x₂; y₁y₂; z₁z₂). Скалярное произведение — одно число, произведения <b>складываются</b>.', '<b>Treating the dot product as a vector:</b> writing (x₁x₂; y₁y₂; z₁z₂). The dot product is a single number — the products are <b>added</b>.'),
      L('<b>Kosinusni bo‘lishni unutish:</b> burchak uchun a⃗·b⃗ ni |a⃗|·|b⃗| ga bo‘lish shart; aks holda «kosinus» 1 dan katta chiqishi mumkin.', '<b>Забывают делить:</b> для угла a⃗·b⃗ надо разделить на |a⃗|·|b⃗|; иначе «косинус» может оказаться больше 1.', '<b>Forgetting to divide:</b> to get the angle, a⃗·b⃗ must be divided by |a⃗|·|b⃗|; otherwise the “cosine” may exceed 1.'),
      L('<b>To‘g‘ri chiziqlar burchagini o‘tmas deb olish:</b> vektorlar burchagi 120° bo‘lsa, to‘g‘ri chiziqlar burchagi 60°.', '<b>Тупой угол между прямыми:</b> если угол между векторами 120°, то угол между прямыми 60°.', '<b>Giving an obtuse angle between lines:</b> if the vectors make 120°, the lines make 60°.'),
      L('<b>Uzunlikda manfiy ishorani saqlash:</b> |(−3; 0; 4)| = √(9 + 16) = 5; kvadratdan keyin minus yo‘qoladi.', '<b>Минус под корнем:</b> |(−3; 0; 4)| = √(9 + 16) = 5; после возведения в квадрат минус исчезает.', '<b>Keeping a minus in the length:</b> |(−3; 0; 4)| = √(9 + 16) = 5; squaring removes the sign.')
    ] },
    { kind: 'life', h: L('Vektorlar qayerda ishlaydi', 'Где работают векторы', 'Where vectors are at work'), p: [
      L('<b>Fizikada</b> kuchning bajargan ishi skalyar ko‘paytmaning o‘zi: A = F⃗·s⃗ = F·s·cos φ. Chana arqonini 30° burchak ostida 100 N kuch bilan 50 m tortsangiz, ish 100·50·cos 30° ≈ 4330 J bo‘ladi — kuchning faqat harakat yo‘nalishidagi qismi ish bajaradi.', 'В <b>физике</b> работа силы — это и есть скалярное произведение: A = F⃗·s⃗ = F·s·cos φ. Если тянуть санки за верёвку под углом 30° силой 100 Н на 50 м, работа составит 100·50·cos 30° ≈ 4330 Дж — работу совершает лишь часть силы вдоль движения.', 'In <b>physics</b> the work done by a force is exactly a dot product: A = F⃗·s⃗ = F·s·cos φ. Pull a sledge by a rope at 30° with 100 N over 50 m, and the work is 100·50·cos 30° ≈ 4330 J — only the part of the force along the motion does work.'),
      L('<b>Kompyuter grafikasida</b> sirtning yorug‘ligi normal vektor va yorug‘lik yo‘nalishi orasidagi skalyar ko‘paytma bilan hisoblanadi (Lambert qonuni): yorug‘lik tik tushsa sirt yorqin, qiya tushsa xira. <b>Qidiruv tizimlari</b> va sun’iy intellekt matnlarni vektorlarga aylantirib, ularning o‘xshashligini burchak kosinusi bilan o‘lchaydi. Dronlar va raketalar esa tezlik va shamol vektorlarini qo‘shib, yo‘nalishini tuzatadi.', 'В <b>компьютерной графике</b> яркость поверхности вычисляется скалярным произведением нормали и направления света (закон Ламберта): при отвесном свете поверхность яркая, при косом — тусклая. <b>Поисковые системы</b> и искусственный интеллект превращают тексты в векторы и измеряют их сходство косинусом угла. Дроны и ракеты складывают векторы скорости и ветра, корректируя курс.', 'In <b>computer graphics</b> the brightness of a surface is the dot product of its normal and the light direction (Lambert’s law): head-on light makes it bright, grazing light makes it dim. <b>Search engines</b> and AI turn texts into vectors and measure similarity by the cosine of the angle. Drones and rockets add velocity and wind vectors to correct their course.')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверьте себя', 'Check yourself'), ex: [
      { q: L('A(1; 0; 2), B(3; 2; 1), C(1; 4; 4). ABC uchburchakda B burchak to‘g‘rimi?', 'A(1; 0; 2), B(3; 2; 1), C(1; 4; 4). Прямой ли угол B треугольника ABC?', 'A(1; 0; 2), B(3; 2; 1), C(1; 4; 4). Is angle B of triangle ABC a right angle?'),
        s: L('BA⃗ = (−2; −2; 1), BC⃗ = (−2; 2; 3). BA⃗·BC⃗ = 4 − 4 + 3 = 3 ≠ 0 — to‘g‘ri emas (o‘tkir, chunki 3 &gt; 0).', 'BA⃗ = (−2; −2; 1), BC⃗ = (−2; 2; 3). BA⃗·BC⃗ = 4 − 4 + 3 = 3 ≠ 0 — не прямой (острый, так как 3 &gt; 0).', 'BA⃗ = (−2; −2; 1), BC⃗ = (−2; 2; 3). BA⃗·BC⃗ = 4 − 4 + 3 = 3 ≠ 0 — not right (acute, since 3 &gt; 0).') },
      { q: L('|a⃗| = 3, |b⃗| = 4, a⃗ va b⃗ orasidagi burchak 60°. |a⃗ + b⃗| ni toping.', '|a⃗| = 3, |b⃗| = 4, угол между a⃗ и b⃗ равен 60°. Найдите |a⃗ + b⃗|.', '|a⃗| = 3, |b⃗| = 4, the angle between a⃗ and b⃗ is 60°. Find |a⃗ + b⃗|.'),
        s: L('|a⃗ + b⃗|² = 9 + 16 + 2·3·4·0,5 = 37, demak |a⃗ + b⃗| = √37 ≈ 6,08.', '|a⃗ + b⃗|² = 9 + 16 + 2·3·4·0,5 = 37, значит |a⃗ + b⃗| = √37 ≈ 6,08.', '|a⃗ + b⃗|² = 9 + 16 + 2·3·4·0.5 = 37, so |a⃗ + b⃗| = √37 ≈ 6.08.') }
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Fazoda vektor uchta koordinata bilan beriladi: a⃗ = x·i⃗ + y·j⃗ + z·k⃗; AB⃗ = B − A.', 'В пространстве вектор задаётся тремя координатами: a⃗ = x·i⃗ + y·j⃗ + z·k⃗; AB⃗ = B − A.', 'In space a vector has three coordinates: a⃗ = x·i⃗ + y·j⃗ + z·k⃗; AB⃗ = B − A.'),
      L('Qo‘shish, ayirish va songa ko‘paytirish koordinatalar bo‘yicha bajariladi; |a⃗| = √(x² + y² + z²).', 'Сложение, вычитание и умножение на число выполняются покоординатно; |a⃗| = √(x² + y² + z²).', 'Addition, subtraction and scaling are done coordinate-wise; |a⃗| = √(x² + y² + z²).'),
      L('Kollinearlik — koordinatalar proporsionalligi; uchta komplanar bo‘lmagan vektor fazoda bazis bo‘ladi.', 'Коллинеарность — пропорциональность координат; три некомпланарных вектора образуют базис пространства.', 'Collinear means proportional coordinates; three non-coplanar vectors form a basis of space.'),
      L('Skalyar ko‘paytma: a⃗·b⃗ = |a⃗||b⃗|cos φ = x₁x₂ + y₁y₂ + z₁z₂ (kosinuslar teoremasidan).', 'Скалярное произведение: a⃗·b⃗ = |a⃗||b⃗|cos φ = x₁x₂ + y₁y₂ + z₁z₂ (из теоремы косинусов).', 'Dot product: a⃗·b⃗ = |a⃗||b⃗|cos φ = x₁x₂ + y₁y₂ + z₁z₂ (from the law of cosines).'),
      L('a⃗ ⊥ b⃗ ⇔ a⃗·b⃗ = 0; ishora burchak o‘tkir yoki o‘tmasligini ko‘rsatadi.', 'a⃗ ⊥ b⃗ ⇔ a⃗·b⃗ = 0; знак показывает, острый угол или тупой.', 'a⃗ ⊥ b⃗ ⇔ a⃗·b⃗ = 0; the sign tells whether the angle is acute or obtuse.'),
      L('Vektor hisobi Gamilton (1843), Grassman (1844), Gibbs va Xevisayd (1880-yillar) ishlaridan kelib chiqqan.', 'Векторное исчисление выросло из работ Гамильтона (1843), Грассмана (1844), Гиббса и Хевисайда (1880-е).', 'Vector calculus grew from the work of Hamilton (1843), Grassmann (1844), Gibbs and Heaviside (1880s).')
    ] }
  ] });

  // ---------- t3. Fazoda almashtirishlar va o‘xshashlik ----------
  T.add(P, 't3', { sections: [
    { kind: 'intro', h: L('Shaklni siljitamiz, aylantiramiz, kattalashtiramiz', 'Сдвигаем, поворачиваем, увеличиваем', 'Move it, turn it, enlarge it'), p: [
      L('Ko‘zguga qarang: aksingiz sizning aniq nusxangiz, faqat o‘ng qo‘l chap qo‘lga aylangan. Liftda yuqoriga ko‘tarilganda butun tanangiz bir xil masofaga siljiydi. Karusel esa sizni o‘q atrofida aylantiradi. Bularning barchasi — fazodagi <b>almashtirishlar</b>: har bir nuqta yangi nuqtaga o‘tadi. Ba’zi almashtirishlar masofalarni saqlaydi (harakatlar), ba’zilari esa shaklni o‘xshash ravishda kattalashtiradi yoki kichraytiradi.', 'Посмотрите в зеркало: отражение — ваша точная копия, только правая рука стала левой. Когда лифт поднимается, всё ваше тело сдвигается на одно и то же расстояние. Карусель поворачивает вас вокруг оси. Всё это — <b>преобразования</b> пространства: каждая точка переходит в новую точку. Одни преобразования сохраняют расстояния (движения), другие подобно увеличивают или уменьшают фигуру.', 'Look in a mirror: the reflection is an exact copy of you, except the right hand has become the left. When a lift goes up, your whole body shifts by the same distance. A carousel turns you about an axis. All of these are <b>transformations</b> of space: each point goes to a new point. Some transformations keep distances (motions), others enlarge or shrink a figure similarly.'),
      L('Bu mavzuda fazodagi asosiy almashtirishlarni koordinatalarda yozishni va o‘xshash jismlarning yuzlari hamda hajmlari qanday bog‘langanini o‘rganamiz. Oxirgi qoida — «hajm k³ marta o‘zgaradi» — nima uchun fil ingichka oyoqli bo‘lolmasligini ham tushuntiradi.', 'В этой теме мы научимся записывать основные преобразования пространства в координатах и узнаем, как связаны площади и объёмы подобных тел. Последнее правило — «объём меняется в k³ раз» — объясняет даже то, почему у слона не может быть тонких ног.', 'In this topic we learn to write the main transformations of space in coordinates and see how the areas and volumes of similar solids are related. The last rule — “volume changes by a factor of k³” — even explains why an elephant cannot have thin legs.')
    ] },
    { kind: 'def', h: L('Harakat nima', 'Что такое движение', 'What a motion is'), p: [
      L('Fazoning har bir nuqtasini qandaydir nuqtaga o‘tkazuvchi moslik <b>almashtirish</b> deyiladi. Agar almashtirish istalgan ikki nuqta orasidagi masofani saqlasa (A′B′ = AB), u <b>harakat</b> (izometriya) deyiladi. Harakatda to‘g‘ri chiziq to‘g‘ri chiziqqa, tekislik tekislikka, kesma unga teng kesmaga o‘tadi, burchaklar saqlanadi. Bir-biriga harakat bilan o‘tadigan ikki shakl <b>teng</b> deyiladi.', 'Соответствие, переводящее каждую точку пространства в некоторую точку, называется <b>преобразованием</b>. Если преобразование сохраняет расстояние между любыми двумя точками (A′B′ = AB), оно называется <b>движением</b> (изометрией). При движении прямая переходит в прямую, плоскость — в плоскость, отрезок — в равный отрезок, углы сохраняются. Две фигуры, переводимые друг в друга движением, называются <b>равными</b>.', 'A rule that sends every point of space to some point is a <b>transformation</b>. If it keeps the distance between any two points (A′B′ = AB), it is a <b>motion</b> (isometry). A motion sends lines to lines, planes to planes and segments to equal segments, and it preserves angles. Two figures related by a motion are called <b>congruent</b>.'),
      L('Fazodagi asosiy harakatlar: <b>markaziy simmetriya</b> (nuqtaga nisbatan), <b>o‘q simmetriyasi</b> (to‘g‘ri chiziqqa nisbatan), <b>ko‘zgu simmetriyasi</b> (tekislikka nisbatan), <b>parallel ko‘chirish</b> va to‘g‘ri chiziq atrofida <b>burish</b>. Tekislikda «ko‘zgu» to‘g‘ri chiziq edi, fazoda esa u tekislik — haqiqiy oyna kabi.', 'Основные движения пространства: <b>центральная симметрия</b> (относительно точки), <b>осевая симметрия</b> (относительно прямой), <b>зеркальная симметрия</b> (относительно плоскости), <b>параллельный перенос</b> и <b>поворот</b> вокруг прямой. На плоскости «зеркалом» была прямая, в пространстве же это плоскость — как настоящее зеркало.', 'The main motions of space are <b>central symmetry</b> (about a point), <b>axial symmetry</b> (about a line), <b>mirror symmetry</b> (about a plane), <b>translation</b> and <b>rotation</b> about a line. In the plane the “mirror” was a line; in space it is a plane — just like a real mirror.')
    ] },
    { kind: 'table', h: L('Harakatlar koordinatalarda', 'Движения в координатах', 'Motions in coordinates'), p: [
      L('M(x; y; z) nuqtaning obrazi quyidagicha topiladi. Formulalarni yodlash shart emas: qaysi koordinata «ko‘zgu»ga perpendikulyar bo‘lsa, o‘sha ishorasini o‘zgartiradi.', 'Образ точки M(x; y; z) находится так. Формулы не обязательно заучивать: меняет знак та координата, которая перпендикулярна «зеркалу».', 'The image of M(x; y; z) is found as follows. No need to memorise: the coordinate perpendicular to the “mirror” changes sign.')
    ], table: { head: [L('Almashtirish', 'Преобразование', 'Transformation'), L('Obraz', 'Образ', 'Image')], rows: [
      [L('O nuqtaga nisbatan simmetriya', 'Симметрия относительно точки O', 'Symmetry about the origin O'), L('(−x; −y; −z)', '(−x; −y; −z)', '(−x; −y; −z)')],
      [L('C(a; b; c) nuqtaga nisbatan simmetriya', 'Симметрия относительно точки C(a; b; c)', 'Symmetry about C(a; b; c)'), L('(2a − x; 2b − y; 2c − z)', '(2a − x; 2b − y; 2c − z)', '(2a − x; 2b − y; 2c − z)')],
      [L('Oxy tekisligiga nisbatan', 'Относительно плоскости Oxy', 'About the Oxy plane'), L('(x; y; −z)', '(x; y; −z)', '(x; y; −z)')],
      [L('Oyz tekisligiga nisbatan', 'Относительно плоскости Oyz', 'About the Oyz plane'), L('(−x; y; z)', '(−x; y; z)', '(−x; y; z)')],
      [L('Oz o‘qiga nisbatan', 'Относительно оси Oz', 'About the Oz axis'), L('(−x; −y; z)', '(−x; −y; z)', '(−x; −y; z)')],
      [L('p⃗(a; b; c) vektorga parallel ko‘chirish', 'Перенос на вектор p⃗(a; b; c)', 'Translation by p⃗(a; b; c)'), L('(x + a; y + b; z + c)', '(x + a; y + b; z + c)', '(x + a; y + b; z + c)')],
      [L('O markazli, k koeffitsiyentli gomotetiya', 'Гомотетия с центром O и коэффициентом k', 'Homothety, centre O, ratio k'), L('(kx; ky; kz)', '(kx; ky; kz)', '(kx; ky; kz)')]
    ] } },
    { kind: 'history', h: L('Simmetriyadan kristallargacha', 'От симметрии к кристаллам', 'From symmetry to crystals'), p: [
      L('Shakllarni ustma-ust qo‘yib tenglikni isbotlash g‘oyasi <b>Yevklid</b>ning «Negizlar»idayoq bor (miloddan avvalgi III asr). Ammo almashtirishlarni geometriyaning markaziga qo‘ygan olim nemis <b>Feliks Klyayn</b> bo‘ldi: 1872-yilgi «Erlangen dasturi»da u har bir geometriyani ma’lum almashtirishlar to‘plami saqlaydigan xossalarni o‘rganuvchi fan sifatida ta’rifladi. Masalan, Yevklid geometriyasi — harakatlarda o‘zgarmaydigan xossalar haqidagi fan.', 'Идея доказывать равенство наложением фигур есть ещё в «Началах» <b>Евклида</b> (III век до н. э.). Но в центр геометрии преобразования поставил немец <b>Феликс Клейн</b>: в «Эрлангенской программе» 1872 года он определил каждую геометрию как науку о свойствах, сохраняющихся при некоторой группе преобразований. Например, евклидова геометрия — наука о свойствах, не меняющихся при движениях.', 'The idea of proving congruence by laying one figure on another already appears in <b>Euclid</b>’s <i>Elements</i> (3rd century BC). But it was the German <b>Felix Klein</b> who put transformations at the heart of geometry: in his 1872 “Erlangen programme” he defined each geometry as the study of properties preserved by a certain group of transformations. Euclidean geometry, for instance, studies properties unchanged by motions.'),
      L('Fazoviy simmetriyalar kristallografiyada hal qiluvchi rol o‘ynadi. 1891-yilda rus kristallografi <b>Yevgraf Fyodorov</b> va nemis matematigi <b>Artur Shyonflis</b> bir-biridan mustaqil ravishda kristall panjaralar simmetriyasining roppa-rosa <b>230 turi</b> borligini isbotladi. <b>Galiley</b> esa 1638-yilda «Ikki yangi fan haqida suhbatlar» kitobida o‘xshash jismlarda hajm o‘lchamning kubiga, mustahkamlik esa kvadratiga mos o‘sishini birinchi bo‘lib tahlil qilgan.', 'Пространственные симметрии сыграли решающую роль в кристаллографии. В 1891 году русский кристаллограф <b>Евграф Фёдоров</b> и немецкий математик <b>Артур Шёнфлис</b> независимо доказали, что существует ровно <b>230 типов</b> симметрии кристаллических решёток. А <b>Галилей</b> в книге «Беседы о двух новых науках» (1638) первым проанализировал, что у подобных тел объём растёт как куб размера, а прочность — как квадрат.', 'Spatial symmetries proved decisive in crystallography. In 1891 the Russian crystallographer <b>Evgraf Fedorov</b> and the German mathematician <b>Arthur Schoenflies</b> independently proved that there are exactly <b>230 types</b> of symmetry of crystal lattices. And <b>Galileo</b>, in his <i>Two New Sciences</i> (1638), was the first to analyse how, for similar bodies, volume grows like the cube of size while strength grows like the square.')
    ] },
    { kind: 'def', h: L('Gomotetiya va o‘xshashlik', 'Гомотетия и подобие', 'Homothety and similarity'), p: [
      L('<b>Gomotetiya</b> — O markaz va k ≠ 0 koeffitsiyent bilan berilgan almashtirish: har bir M nuqta OM′⃗ = k·OM⃗ shartini qanoatlantiruvchi M′ nuqtaga o‘tadi. k &gt; 1 da shakl kattalashadi, 0 &lt; k &lt; 1 da kichrayadi, k &lt; 0 da esa markazning narigi tomoniga «ag‘dariladi». Gomotetiyada barcha masofalar |k| marta o‘zgaradi: A′B′ = |k|·AB.', '<b>Гомотетия</b> — преобразование с центром O и коэффициентом k ≠ 0: каждая точка M переходит в точку M′ с OM′⃗ = k·OM⃗. При k &gt; 1 фигура увеличивается, при 0 &lt; k &lt; 1 уменьшается, при k &lt; 0 «переворачивается» на другую сторону от центра. При гомотетии все расстояния меняются в |k| раз: A′B′ = |k|·AB.', 'A <b>homothety</b> with centre O and ratio k ≠ 0 sends each point M to the point M′ with OM′⃗ = k·OM⃗. For k &gt; 1 the figure grows, for 0 &lt; k &lt; 1 it shrinks, and for k &lt; 0 it is also flipped to the other side of the centre. A homothety multiplies all distances by |k|: A′B′ = |k|·AB.'),
      L('<b>O‘xshashlik</b> — barcha masofalarni bir xil k &gt; 0 marta o‘zgartiruvchi almashtirish; har qanday o‘xshashlik gomotetiya va harakatning ketma-ket bajarilishidir. O‘xshash shakllarda burchaklar teng, mos uzunliklar nisbati k ga teng. Barcha kublar, barcha sferalar o‘zaro o‘xshash; ammo ikki to‘g‘ri burchakli parallelepiped faqat uchala qirra nisbati teng bo‘lsagina o‘xshash.', '<b>Подобие</b> — преобразование, меняющее все расстояния в одно и то же число k &gt; 0 раз; любое подобие есть композиция гомотетии и движения. У подобных фигур углы равны, а отношение соответственных длин равно k. Все кубы и все сферы подобны друг другу; а два прямоугольных параллелепипеда подобны, лишь если отношения всех трёх рёбер одинаковы.', 'A <b>similarity</b> multiplies all distances by the same k &gt; 0; every similarity is a homothety followed by a motion. Similar figures have equal angles, and corresponding lengths are in ratio k. All cubes and all spheres are similar to one another, but two rectangular boxes are similar only if all three edge ratios agree.')
    ] },
    { kind: 'rule', h: L('Yuz k², hajm k³', 'Площадь k², объём k³', 'Area k², volume k³'), p: [
      L('<b>Teorema.</b> O‘xshashlik koeffitsiyenti k bo‘lsa: uzunliklar k marta, sirt yuzlari <b>k² marta</b>, hajmlar <b>k³ marta</b> o‘zgaradi: S₂/S₁ = k², V₂/V₁ = k³.', '<b>Теорема.</b> При коэффициенте подобия k длины меняются в k раз, площади поверхностей — в <b>k² раз</b>, объёмы — в <b>k³ раз</b>: S₂/S₁ = k², V₂/V₁ = k³.', '<b>Theorem.</b> With similarity ratio k, lengths change by a factor k, surface areas by <b>k²</b> and volumes by <b>k³</b>: S₂/S₁ = k², V₂/V₁ = k³.'),
      L('<b>Isbot g‘oyasi.</b> Kubdan boshlaymiz: qirrasi a bo‘lgan kub qirrasi ka bo‘lgan kubga o‘tadi; yoq yuzi a² dan k²a² ga, hajm a³ dan k³a³ ga o‘zgaradi. Har qanday jismni juda mayda kubchalar bilan to‘ldirish (yaqinlashtirish) mumkin; o‘xshashlikda har bir kubcha hajmi k³ marta oshadi, demak butun jism hajmi ham k³ marta oshadi. Sirt uchun xuddi shunday mayda kvadratchalar bilan mulohaza yuritiladi.', '<b>Идея доказательства.</b> Начнём с куба: куб с ребром a переходит в куб с ребром ka; площадь грани меняется с a² на k²a², объём — с a³ на k³a³. Любое тело можно заполнить (приблизить) очень мелкими кубиками; при подобии объём каждого кубика растёт в k³ раз, значит и объём всего тела растёт в k³ раз. Для поверхности рассуждают так же с мелкими квадратиками.', '<b>Proof idea.</b> Start with a cube: a cube of edge a becomes a cube of edge ka; a face area changes from a² to k²a², the volume from a³ to k³a³. Any solid can be filled (approximated) by tiny cubes; under the similarity each tiny cube’s volume grows by k³, so the whole volume grows by k³. For surfaces one argues the same way with tiny squares.'),
      L('Teskari masala ham muhim: hajmlar nisbati ma’lum bo‘lsa, k = ∛(V₂/V₁). Masalan, hajmlari 8 va 27 bo‘lgan o‘xshash jismlarda k = 3/2, sirtlar nisbati esa k² = 9/4.', 'Важна и обратная задача: если известно отношение объёмов, то k = ∛(V₂/V₁). Например, у подобных тел с объёмами 8 и 27 k = 3/2, а отношение поверхностей k² = 9/4.', 'The reverse is important too: if the volume ratio is known, k = ∛(V₂/V₁). For similar solids with volumes 8 and 27, k = 3/2 and the surface ratio is k² = 9/4.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Решённые примеры', 'Worked examples'), ex: [
      { q: L('A(2; −3; 5) nuqtaga koordinatalar boshiga, Oxy tekisligiga, Oz o‘qiga va Oyz tekisligiga nisbatan simmetrik nuqtalarni toping.', 'Найдите точки, симметричные A(2; −3; 5) относительно начала координат, плоскости Oxy, оси Oz и плоскости Oyz.', 'Find the points symmetric to A(2; −3; 5) about the origin, the Oxy plane, the Oz axis and the Oyz plane.'),
        s: L('O ga nisbatan: (−2; 3; −5). Oxy ga: (2; −3; −5). Oz o‘qiga: (−2; 3; 5). Oyz ga: (−2; −3; 5).', 'Относительно O: (−2; 3; −5). Относительно Oxy: (2; −3; −5). Относительно оси Oz: (−2; 3; 5). Относительно Oyz: (−2; −3; 5).', 'About O: (−2; 3; −5). About Oxy: (2; −3; −5). About the Oz axis: (−2; 3; 5). About Oyz: (−2; −3; 5).') },
      { q: L('A(1; 2; 3) nuqtaga C(2; 0; −1) nuqtaga nisbatan simmetrik nuqtani toping.', 'Найдите точку, симметричную A(1; 2; 3) относительно точки C(2; 0; −1).', 'Find the point symmetric to A(1; 2; 3) about C(2; 0; −1).'),
        s: L('C — AA′ kesma o‘rtasi, shuning uchun A′ = 2C − A = (4 − 1; 0 − 2; −2 − 3) = <b>(3; −2; −5)</b>.', 'C — середина AA′, поэтому A′ = 2C − A = (4 − 1; 0 − 2; −2 − 3) = <b>(3; −2; −5)</b>.', 'C is the midpoint of AA′, so A′ = 2C − A = (4 − 1; 0 − 2; −2 − 3) = <b>(3; −2; −5)</b>.') },
      { q: L('Parallel ko‘chirish A(1; 0; 2) ni B(4; −1; 5) ga o‘tkazadi. C(0; 2; −1) qayerga o‘tadi?', 'Параллельный перенос переводит A(1; 0; 2) в B(4; −1; 5). Куда перейдёт C(0; 2; −1)?', 'A translation sends A(1; 0; 2) to B(4; −1; 5). Where does C(0; 2; −1) go?'),
        s: L('Ko‘chirish vektori p⃗ = AB⃗ = (3; −1; 3). C′ = (0 + 3; 2 − 1; −1 + 3) = <b>(3; 1; 2)</b>.', 'Вектор переноса p⃗ = AB⃗ = (3; −1; 3). C′ = (0 + 3; 2 − 1; −1 + 3) = <b>(3; 1; 2)</b>.', 'The translation vector is p⃗ = AB⃗ = (3; −1; 3). C′ = (0 + 3; 2 − 1; −1 + 3) = <b>(3; 1; 2)</b>.') },
      { q: L('Bino maketi 1 : 50 masshtabda. Maket bo‘yalgan sirti 2 m², hajmi 0,1 m³. Binoning sirti va hajmi qancha?', 'Макет здания в масштабе 1 : 50. Окрашенная поверхность макета 2 м², объём 0,1 м³. Каковы поверхность и объём здания?', 'A model of a building is at scale 1 : 50. Its painted surface is 2 m² and its volume 0.1 m³. Find the building’s surface and volume.'),
        s: L('k = 50. Sirt: 2·50² = 2·2500 = <b>5000 m²</b>. Hajm: 0,1·50³ = 0,1·125 000 = <b>12 500 m³</b>.', 'k = 50. Поверхность: 2·50² = 2·2500 = <b>5000 м²</b>. Объём: 0,1·50³ = 0,1·125 000 = <b>12 500 м³</b>.', 'k = 50. Surface: 2·50² = 2·2500 = <b>5000 m²</b>. Volume: 0.1·50³ = 0.1·125,000 = <b>12,500 m³</b>.') },
      { q: L('Ikki o‘xshash piramidaning hajmlari 8 va 27. Kichigining sirti 40 bo‘lsa, kattasiniki qancha?', 'Объёмы двух подобных пирамид 8 и 27. Поверхность меньшей 40. Какова поверхность большей?', 'Two similar pyramids have volumes 8 and 27. The smaller has surface area 40. Find the surface area of the larger.'),
        s: L('k³ = 27/8, k = 3/2. Sirtlar nisbati k² = 9/4. S = 40·9/4 = <b>90</b>.', 'k³ = 27/8, k = 3/2. Отношение поверхностей k² = 9/4. S = 40·9/4 = <b>90</b>.', 'k³ = 27/8, so k = 3/2. The surface ratio is k² = 9/4. S = 40·9/4 = <b>90</b>.') }
    ] },
    { kind: 'fact', h: L('Kubning simmetriyalari', 'Симметрии куба', 'The symmetries of a cube'), p: [
      L('Kub — juda simmetrik jism. Uning <b>simmetriya markazi</b> bor (diagonallar kesishgan nuqta). <b>Simmetriya tekisliklari</b> 9 ta: 3 tasi kub markazi orqali yoqlarga parallel, 6 tasi qarama-qarshi qirralar juftligi orqali o‘tadi. <b>Burish o‘qlari</b> 13 ta: qarama-qarshi yoqlar markazlari orqali 3 ta (90° ga burilganda kub o‘ziga o‘tadi), diagonallar bo‘ylab 4 ta (120°), qarama-qarshi qirralar o‘rtalari orqali 6 ta (180°).', 'Куб — очень симметричное тело. У него есть <b>центр симметрии</b> (точка пересечения диагоналей). <b>Плоскостей симметрии</b> 9: 3 проходят через центр куба параллельно граням, 6 — через пары противоположных рёбер. <b>Осей поворота</b> 13: 3 через центры противоположных граней (поворот на 90° совмещает куб с собой), 4 вдоль диагоналей (120°), 6 через середины противоположных рёбер (180°).', 'A cube is highly symmetric. It has a <b>centre of symmetry</b> (where the diagonals meet). It has 9 <b>planes of symmetry</b>: 3 through the centre parallel to the faces, and 6 through pairs of opposite edges. It has 13 <b>rotation axes</b>: 3 through centres of opposite faces (a 90° turn maps the cube to itself), 4 along the diagonals (120°), and 6 through midpoints of opposite edges (180°).'),
      L('Hammasi bo‘lib kubni o‘ziga o‘tkazuvchi 48 ta harakat bor; ularning 24 tasi — burishlar. Aynan shuning uchun Rubik kubigi kabi jumboqlar matematiklar uchun guruhlar nazariyasining jonli namunasi hisoblanadi.', 'Всего существует 48 движений, совмещающих куб с собой; 24 из них — повороты. Поэтому головоломки вроде кубика Рубика служат для математиков живым примером теории групп.', 'Altogether 48 motions map the cube onto itself; 24 of them are rotations. That is why puzzles like the Rubik’s cube are a living example of group theory for mathematicians.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>Hajmni ham k marta oshirish:</b> qirrasi 2 marta katta kubning hajmi 2 marta emas, 8 marta katta.', '<b>Объём увеличивают в k раз:</b> у куба с вдвое большим ребром объём больше не в 2, а в 8 раз.', '<b>Scaling the volume by k:</b> a cube with twice the edge has 8 times, not 2 times, the volume.'),
      L('<b>Tekislikka va o‘qqa nisbatan simmetriyani adashtirish:</b> Oz o‘qiga nisbatan ikkita koordinata (x, y) ishorasini o‘zgartiradi, Oxy tekisligiga nisbatan esa faqat bittasi (z).', '<b>Путают симметрию относительно плоскости и оси:</b> относительно оси Oz меняют знак две координаты (x, y), относительно плоскости Oxy — одна (z).', '<b>Confusing plane and axis symmetry:</b> about the Oz axis two coordinates (x, y) change sign, about the Oxy plane only one (z).'),
      L('<b>Nuqtaga nisbatan simmetriyada faqat ishorani o‘zgartirish:</b> C(a; b; c) ga nisbatan obraz (2a − x; …), (−x; …) emas — bu faqat C = O bo‘lganda to‘g‘ri.', '<b>При симметрии относительно точки меняют только знак:</b> относительно C(a; b; c) образ равен (2a − x; …), а не (−x; …) — это верно только при C = O.', '<b>Only flipping signs for symmetry about a point:</b> about C(a; b; c) the image is (2a − x; …), not (−x; …) — that holds only when C = O.'),
      L('<b>Har qanday ikki parallelepipedni o‘xshash deb hisoblash:</b> o‘xshashlik uchun barcha mos qirralar nisbati bir xil bo‘lishi shart.', '<b>Считают любые два параллелепипеда подобными:</b> для подобия отношения всех соответственных рёбер должны совпадать.', '<b>Assuming any two boxes are similar:</b> similarity needs all corresponding edges in the same ratio.')
    ] },
    { kind: 'life', h: L('Kvadrat-kub qonuni hayotda', 'Закон квадрата–куба в жизни', 'The square–cube law in real life'), p: [
      L('Hayvonni 2 marta kattalashtirsak, uning massasi (hajmga proporsional) 8 marta, suyaklar kesimining yuzi (mustahkamlik) esa faqat 4 marta oshadi. Shuning uchun fil oyoqlari ustunga o‘xshash yo‘g‘on, chumoli esa o‘z vaznidan o‘nlab marta og‘ir yukni ko‘tara oladi. Ulkan hasharotlar haqidagi filmlar biologik jihatdan mumkin emas — ular o‘z og‘irligi ostida ezilib qolar edi.', 'Если увеличить животное в 2 раза, его масса (пропорциональная объёму) вырастет в 8 раз, а площадь сечения костей (прочность) — лишь в 4 раза. Поэтому ноги слона толстые, как колонны, а муравей поднимает груз в десятки раз тяжелее себя. Фильмы о гигантских насекомых биологически невозможны — те раздавили бы себя собственным весом.', 'Make an animal twice as large and its mass (proportional to volume) grows 8 times, while the cross-section of its bones (its strength) grows only 4 times. That is why an elephant’s legs are thick like columns, while an ant lifts loads dozens of times its own weight. Films about giant insects are biologically impossible — they would be crushed by their own weight.'),
      L('Muhandislar kemalar va samolyotlarni avval kichik maketlarda sinaydi, keyin natijalarni k², k³ qoidalari bilan qayta hisoblaydi. Arxitektorlar maket bo‘yicha bo‘yoq (sirt) va beton (hajm) miqdorini baholaydi. Kichik bolalar tez soviydi, chunki ularda sirtning hajmga nisbati kattalarnikidan ko‘p — issiqlik sirt orqali chiqadi.', 'Инженеры сначала испытывают корабли и самолёты на маленьких моделях, а затем пересчитывают результаты по правилам k², k³. Архитекторы по макету оценивают количество краски (поверхность) и бетона (объём). Маленькие дети быстрее мёрзнут: у них отношение поверхности к объёму больше, чем у взрослых, а тепло уходит через поверхность.', 'Engineers first test ships and aircraft on small models, then rescale the results with the k² and k³ rules. Architects estimate paint (surface) and concrete (volume) from a model. Small children get cold faster because their surface-to-volume ratio is larger than an adult’s, and heat escapes through the surface.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Harakat — masofani saqlovchi almashtirish: markaziy, o‘q va ko‘zgu simmetriyalari, parallel ko‘chirish, burish.', 'Движение — преобразование, сохраняющее расстояния: центральная, осевая и зеркальная симметрии, параллельный перенос, поворот.', 'A motion keeps distances: central, axial and mirror symmetries, translations, rotations.'),
      L('Koordinatalarda: O ga nisbatan (−x; −y; −z), Oxy ga nisbatan (x; y; −z), Oz ga nisbatan (−x; −y; z), ko‘chirish (x + a; y + b; z + c).', 'В координатах: относительно O (−x; −y; −z), относительно Oxy (x; y; −z), относительно Oz (−x; −y; z), перенос (x + a; y + b; z + c).', 'In coordinates: about O (−x; −y; −z), about Oxy (x; y; −z), about Oz (−x; −y; z), translation (x + a; y + b; z + c).'),
      L('Gomotetiya (kx; ky; kz) masofalarni |k| marta o‘zgartiradi; o‘xshashlik = gomotetiya + harakat.', 'Гомотетия (kx; ky; kz) меняет расстояния в |k| раз; подобие = гомотетия + движение.', 'A homothety (kx; ky; kz) scales distances by |k|; similarity = homothety + motion.'),
      L('O‘xshash jismlarda: uzunlik k, yuz k², hajm k³ marta o‘zgaradi.', 'У подобных тел длины меняются в k, площади — в k², объёмы — в k³ раз.', 'For similar solids: lengths scale by k, areas by k², volumes by k³.'),
      L('Klyayn (1872): geometriya — almashtirishlarda saqlanadigan xossalar haqidagi fan.', 'Клейн (1872): геометрия — наука о свойствах, сохраняющихся при преобразованиях.', 'Klein (1872): geometry studies properties preserved by transformations.'),
      L('Kvadrat-kub qonuni (Galiley, 1638) hayvonlar, binolar va mashinalar o‘lchamlarini cheklaydi.', 'Закон квадрата–куба (Галилей, 1638) ограничивает размеры животных, зданий и машин.', 'The square–cube law (Galileo, 1638) limits the size of animals, buildings and machines.')
    ] }
  ] });

  // ---------- t4. Ko‘pyoqli burchaklar va ko‘pyoqlar ----------
  T.add(P, 't4', { sections: [
    { kind: 'intro', h: L('Nega faqat beshta?', 'Почему только пять?', 'Why only five?'), p: [
      L('Tekislikda muntazam ko‘pburchaklar cheksiz ko‘p: uchburchak, kvadrat, beshburchak, oltiburchak va hokazo. Fazoda esa barcha yoqlari bir xil muntazam ko‘pburchak bo‘lgan qavariq ko‘pyoqlar atigi <b>beshta</b>. Bu ajablanarli fakt qadimgi yunonlarni hayratga solgan va 2000 yildan ko‘proq vaqt davomida falsafa, san’at va astronomiyaga ilhom bergan.', 'На плоскости правильных многоугольников бесконечно много: треугольник, квадрат, пятиугольник, шестиугольник и так далее. А в пространстве выпуклых многогранников, у которых все грани — одинаковые правильные многоугольники, всего <b>пять</b>. Этот удивительный факт поразил древних греков и более 2000 лет вдохновлял философию, искусство и астрономию.', 'In the plane there are infinitely many regular polygons: triangle, square, pentagon, hexagon and so on. But in space there are only <b>five</b> convex polyhedra whose faces are all the same regular polygon. This striking fact amazed the ancient Greeks and inspired philosophy, art and astronomy for more than 2000 years.'),
      L('Sababini tushunish uchun ko‘pyoqning bitta uchiga «yaqindan» qarash kerak: u yerda bir nechta yoq uchrashib, <b>ko‘pyoqli burchak</b> hosil qiladi. Bu burchaklarning xossalari ko‘pyoqlar dunyosini qat’iy cheklaydi. Mavzuda shuningdek ko‘pyoq tushunchasini va Eylerning mashhur V − E + F = 2 formulasini o‘rganamiz.', 'Чтобы понять причину, надо «вблизи» рассмотреть одну вершину многогранника: там сходятся несколько граней, образуя <b>многогранный угол</b>. Свойства таких углов жёстко ограничивают мир многогранников. В теме мы также изучим понятие многогранника и знаменитую формулу Эйлера В − Р + Г = 2.', 'To see why, look “up close” at one vertex of a polyhedron: several faces meet there and form a <b>polyhedral angle</b>. The properties of such angles strictly limit the world of polyhedra. We also study the notion of a polyhedron and Euler’s famous formula V − E + F = 2.')
    ] },
    { kind: 'def', h: L('Ko‘pyoqli burchak', 'Многогранный угол', 'Polyhedral angle'), p: [
      L('Bir S nuqtadan chiquvchi, hech qaysi uchtasi bitta tekislikda yotmaydigan SA₁, SA₂, …, SAₙ nurlarni olaylik. Ketma-ket nurlar orasidagi tekis burchaklar (A₁SA₂, A₂SA₃, …, AₙSA₁) bilan chegaralangan fazo qismi <b>ko‘pyoqli burchak</b> deyiladi. S — uning <b>uchi</b>, nurlar — <b>qirralari</b>, A₁SA₂ kabi burchaklar — <b>yassi burchaklari</b> (yoqlari), qo‘shni yoqlar orasidagi burchaklar — <b>ikki yoqli burchaklari</b>.', 'Возьмём лучи SA₁, SA₂, …, SAₙ с общим началом S, никакие три из которых не лежат в одной плоскости. Часть пространства, ограниченная плоскими углами между соседними лучами (A₁SA₂, A₂SA₃, …, AₙSA₁), называется <b>многогранным углом</b>. S — его <b>вершина</b>, лучи — <b>рёбра</b>, углы вида A₁SA₂ — <b>плоские углы</b> (грани), углы между соседними гранями — <b>двугранные углы</b>.', 'Take rays SA₁, SA₂, …, SAₙ from a common point S, no three of them in one plane. The part of space bounded by the plane angles between neighbouring rays (A₁SA₂, A₂SA₃, …, AₙSA₁) is a <b>polyhedral angle</b>. S is its <b>vertex</b>, the rays are its <b>edges</b>, angles like A₁SA₂ are its <b>face angles</b>, and the angles between neighbouring faces are its <b>dihedral angles</b>.'),
      L('Eng soddasi — <b>uchyoqli burchak</b> (n = 3): xonaning burchagi, kubning uchi. Agar ko‘pyoqli burchak har bir yog‘i tekisligining bir tomonida yotsa, u <b>qavariq</b> deyiladi. Qavariq ko‘pyoqli burchakni uchidan o‘tmaydigan tekislik bilan kesganda qavariq ko‘pburchak hosil bo‘ladi.', 'Простейший — <b>трёхгранный угол</b> (n = 3): угол комнаты, вершина куба. Если многогранный угол лежит по одну сторону от плоскости каждой своей грани, он называется <b>выпуклым</b>. Сечение выпуклого многогранного угла плоскостью, не проходящей через вершину, — выпуклый многоугольник.', 'The simplest is the <b>trihedral angle</b> (n = 3): the corner of a room, a vertex of a cube. A polyhedral angle lying on one side of the plane of each of its faces is <b>convex</b>. A plane not through the vertex cuts a convex polyhedral angle in a convex polygon.')
    ] },
    { kind: 'rule', h: L('Ikki asosiy teorema', 'Две основные теоремы', 'Two main theorems'), p: [
      L('<b>1-teorema.</b> Uchyoqli burchakning har bir yassi burchagi qolgan ikkitasining yig‘indisidan kichik. <b>Isbot g‘oyasi.</b> α — eng katta yassi burchak, u SA va SC orasida bo‘lsin. Uning tekisligida SD nurini ∠ASD = ∠ASB bo‘ladigan qilib o‘tkazamiz va SD = SB olamiz. Uchburchaklar ASB va ASD teng, demak AB = AD. ABC uchburchakda AC &lt; AB + BC, bundan DC &lt; BC. SDC va SBC uchburchaklarda ikki tomon teng (SD = SB, SC umumiy), uchinchi tomon DC kichik — demak ∠DSC &lt; ∠BSC. Shunday qilib α = ∠ASD + ∠DSC &lt; ∠ASB + ∠BSC.', '<b>Теорема 1.</b> Каждый плоский угол трёхгранного угла меньше суммы двух других. <b>Идея доказательства.</b> Пусть α — наибольший плоский угол, между SA и SC. В его плоскости проведём луч SD так, что ∠ASD = ∠ASB, и возьмём SD = SB. Треугольники ASB и ASD равны, значит AB = AD. В треугольнике ABC AC &lt; AB + BC, откуда DC &lt; BC. В треугольниках SDC и SBC две стороны равны (SD = SB, SC общая), а третья DC меньше — значит ∠DSC &lt; ∠BSC. Итак, α = ∠ASD + ∠DSC &lt; ∠ASB + ∠BSC.', '<b>Theorem 1.</b> Each face angle of a trihedral angle is less than the sum of the other two. <b>Proof idea.</b> Let α, between SA and SC, be the largest face angle. In its plane draw ray SD with ∠ASD = ∠ASB and take SD = SB. Triangles ASB and ASD are congruent, so AB = AD. In triangle ABC, AC &lt; AB + BC, hence DC &lt; BC. Triangles SDC and SBC have two equal sides (SD = SB, SC shared) and the third side DC is smaller, so ∠DSC &lt; ∠BSC. Thus α = ∠ASD + ∠DSC &lt; ∠ASB + ∠BSC.'),
      L('<b>2-teorema.</b> Qavariq ko‘pyoqli burchak yassi burchaklarining yig‘indisi <b>360° dan kichik</b>. <b>Isbot g‘oyasi.</b> Burchakni tekislik bilan kesib, A₁A₂…Aₙ ko‘pburchakni va n ta SAᵢAᵢ₊₁ uchburchakni olamiz. Har bir Aᵢ uchdagi uchyoqli burchakka 1-teoremani qo‘llasak, ko‘pburchak burchagi ikki yon uchburchakning Aᵢ dagi burchaklari yig‘indisidan kichik. Qo‘shib chiqamiz: (n − 2)·180° &lt; n·180° − Σ (S dagi yassi burchaklar). Bundan Σ &lt; 360°.', '<b>Теорема 2.</b> Сумма плоских углов выпуклого многогранного угла <b>меньше 360°</b>. <b>Идея доказательства.</b> Рассечём угол плоскостью и получим многоугольник A₁A₂…Aₙ и n треугольников SAᵢAᵢ₊₁. Применяя теорему 1 к трёхгранному углу при каждой вершине Aᵢ, получаем: угол многоугольника меньше суммы углов двух боковых треугольников при Aᵢ. Складывая: (n − 2)·180° &lt; n·180° − Σ (плоских углов при S). Отсюда Σ &lt; 360°.', '<b>Theorem 2.</b> The face angles of a convex polyhedral angle add up to <b>less than 360°</b>. <b>Proof idea.</b> Cut the angle by a plane to get the polygon A₁A₂…Aₙ and n triangles SAᵢAᵢ₊₁. Applying Theorem 1 to the trihedral angle at each Aᵢ, the polygon’s angle is less than the sum of the two side-triangle angles at Aᵢ. Adding up: (n − 2)·180° &lt; n·180° − Σ (face angles at S). Hence Σ &lt; 360°.'),
      L('Buni qog‘ozda tekshirish mumkin: bir nuqta atrofida yig‘indisi 360° bo‘lgan burchaklar tekis yotadi; ko‘pyoqli burchak «bukilishi» uchun bir qismini qirqib tashlash kerak.', 'Это можно проверить на бумаге: углы с суммой 360° вокруг точки лежат плоско; чтобы многогранный угол «сложился», часть надо вырезать.', 'You can check this with paper: angles totalling 360° around a point lie flat; to fold a polyhedral angle you must cut a piece out.')
    ] },
    { kind: 'def', h: L('Ko‘pyoq va Eyler formulasi', 'Многогранник и формула Эйлера', 'Polyhedra and Euler’s formula'), p: [
      L('<b>Ko‘pyoq</b> — sirti chekli sondagi ko‘pburchaklardan iborat jism. Bu ko‘pburchaklar — <b>yoqlar</b> (F), ularning tomonlari — <b>qirralar</b> (E), uchlari — <b>uchlar</b> (V). Har bir qirra roppa-rosa ikki yoqqa tegishli. Ko‘pyoq har bir yog‘i tekisligining bir tomonida yotsa, u <b>qavariq</b> deyiladi; prizma, piramida, kub — qavariq ko‘pyoqlar.', '<b>Многогранник</b> — тело, поверхность которого состоит из конечного числа многоугольников. Эти многоугольники — <b>грани</b> (Г), их стороны — <b>рёбра</b> (Р), вершины — <b>вершины</b> (В). Каждое ребро принадлежит ровно двум граням. Если многогранник лежит по одну сторону от плоскости каждой своей грани, он <b>выпуклый</b>; призма, пирамида, куб — выпуклые многогранники.', 'A <b>polyhedron</b> is a solid whose surface consists of finitely many polygons. These polygons are the <b>faces</b> (F), their sides are the <b>edges</b> (E), and their corners are the <b>vertices</b> (V). Each edge belongs to exactly two faces. A polyhedron lying on one side of the plane of each face is <b>convex</b>; prisms, pyramids and cubes are convex.'),
      L('<b>Eyler teoremasi.</b> Har qanday qavariq ko‘pyoq uchun <b>V − E + F = 2</b>. Tekshiramiz: kubda 8 − 12 + 6 = 2, tetraedrda 4 − 6 + 4 = 2. n burchakli prizmada V = 2n, E = 3n, F = n + 2: 2n − 3n + n + 2 = 2. Isbot g‘oyasi: bitta yoqni olib tashlab, qolgan sirtni tekislikka «yoyamiz» va qirralarni birma-bir o‘chirib boramiz; har qadamda V − E + F o‘zgarmaydi, oxirida bitta uchburchak qoladi.', '<b>Теорема Эйлера.</b> Для любого выпуклого многогранника <b>В − Р + Г = 2</b>. Проверим: у куба 8 − 12 + 6 = 2, у тетраэдра 4 − 6 + 4 = 2. У n-угольной призмы В = 2n, Р = 3n, Г = n + 2: 2n − 3n + n + 2 = 2. Идея доказательства: удалим одну грань, «растянем» остальную поверхность на плоскость и будем стирать рёбра по одному; на каждом шаге В − Р + Г не меняется, в конце остаётся один треугольник.', '<b>Euler’s theorem.</b> For every convex polyhedron <b>V − E + F = 2</b>. Check: a cube has 8 − 12 + 6 = 2, a tetrahedron 4 − 6 + 4 = 2. An n-gonal prism has V = 2n, E = 3n, F = n + 2: 2n − 3n + n + 2 = 2. Proof idea: remove one face, stretch the rest of the surface flat onto a plane and erase edges one by one; each step leaves V − E + F unchanged, and at the end one triangle remains.')
    ] },
    { kind: 'table', h: L('Beshta muntazam ko‘pyoq', 'Пять правильных многогранников', 'The five regular polyhedra'), p: [
      L('<b>Muntazam ko‘pyoq</b> — barcha yoqlari teng muntazam ko‘pburchaklar va har bir uchida bir xil sondagi yoq uchrashadigan qavariq ko‘pyoq.', '<b>Правильный многогранник</b> — выпуклый многогранник, все грани которого — равные правильные многоугольники и в каждой вершине сходится одинаковое число граней.', 'A <b>regular polyhedron</b> is a convex polyhedron whose faces are all equal regular polygons, with the same number of faces meeting at every vertex.')
    ], table: { head: [L('Nomi', 'Название', 'Name'), L('Yoq', 'Грань', 'Face'), L('V', 'В', 'V'), L('E', 'Р', 'E'), L('F', 'Г', 'F'), L('Uchdagi Σ', 'Σ при вершине', 'Σ at vertex')], rows: [
      [L('Tetraedr', 'Тетраэдр', 'Tetrahedron'), L('3 × uchburchak', '3 × треугольник', '3 × triangle'), L('4', '4', '4'), L('6', '6', '6'), L('4', '4', '4'), L('180°', '180°', '180°')],
      [L('Oktaedr', 'Октаэдр', 'Octahedron'), L('4 × uchburchak', '4 × треугольник', '4 × triangle'), L('6', '6', '6'), L('12', '12', '12'), L('8', '8', '8'), L('240°', '240°', '240°')],
      [L('Ikosaedr', 'Икосаэдр', 'Icosahedron'), L('5 × uchburchak', '5 × треугольник', '5 × triangle'), L('12', '12', '12'), L('30', '30', '30'), L('20', '20', '20'), L('300°', '300°', '300°')],
      [L('Kub (geksaedr)', 'Куб (гексаэдр)', 'Cube (hexahedron)'), L('3 × kvadrat', '3 × квадрат', '3 × square'), L('8', '8', '8'), L('12', '12', '12'), L('6', '6', '6'), L('270°', '270°', '270°')],
      [L('Dodekaedr', 'Додекаэдр', 'Dodecahedron'), L('3 × beshburchak', '3 × пятиугольник', '3 × pentagon'), L('20', '20', '20'), L('30', '30', '30'), L('12', '12', '12'), L('324°', '324°', '324°')]
    ] }, after: [
      L('<b>Nega boshqasi yo‘q?</b> Uchda kamida 3 ta yoq uchrashadi va yassi burchaklar yig‘indisi 360° dan kichik. Muntazam uchburchak burchagi 60°: 3, 4 yoki 5 tasi sig‘adi (6·60° = 360° — tekis). Kvadrat 90°: faqat 3 ta. Beshburchak 108°: faqat 3 ta (324°). Oltiburchak 120°: 3·120° = 360° — endi bukilmaydi. Jami 3 + 1 + 1 = 5 imkoniyat.', '<b>Почему других нет?</b> В вершине сходится не меньше 3 граней, а сумма плоских углов меньше 360°. Угол правильного треугольника 60°: помещается 3, 4 или 5 (6·60° = 360° — плоско). Квадрат 90°: только 3. Пятиугольник 108°: только 3 (324°). Шестиугольник 120°: 3·120° = 360° — уже не сгибается. Всего 3 + 1 + 1 = 5 возможностей.', '<b>Why no others?</b> At least 3 faces meet at a vertex, and the face angles sum to less than 360°. An equilateral triangle has 60°: 3, 4 or 5 fit (6·60° = 360° is flat). A square has 90°: only 3. A pentagon has 108°: only 3 (324°). A hexagon has 120°: 3·120° = 360° — it can no longer fold. In all, 3 + 1 + 1 = 5 possibilities.')
    ] },
    { kind: 'history', h: L('Platon jismlari', 'Тела Платона', 'The Platonic solids'), p: [
      L('Muntazam ko‘pyoqlar <b>Platon jismlari</b> deb ataladi: faylasuf Platon «Timey» dialogida (miloddan avvalgi taxminan 360-yil) to‘rt unsurni ular bilan bog‘lagan — olov tetraedr, yer kub, havo oktaedr, suv ikosaedr; dodekaedr esa butun olamni ifodalagan. Oktaedr va ikosaedrni chuqur o‘rgangan <b>Teetet</b> edi, <b>Yevklid</b> esa «Negizlar»ning so‘nggi, XIII kitobida muntazam ko‘pyoqlar faqat beshta ekanini isbotlagan — bu butun asarning yakuniy cho‘qqisi.', 'Правильные многогранники называют <b>телами Платона</b>: философ Платон в диалоге «Тимей» (около 360 г. до н. э.) связал с ними четыре стихии — огонь с тетраэдром, землю с кубом, воздух с октаэдром, воду с икосаэдром; додекаэдр символизировал всю Вселенную. Октаэдр и икосаэдр глубоко изучил <b>Теэтет</b>, а <b>Евклид</b> в последней, XIII книге «Начал» доказал, что правильных многогранников только пять, — это итоговая вершина всего труда.', 'Regular polyhedra are called the <b>Platonic solids</b>: in the dialogue <i>Timaeus</i> (about 360 BC) the philosopher Plato linked them with the four elements — fire with the tetrahedron, earth with the cube, air with the octahedron, water with the icosahedron — while the dodecahedron stood for the whole cosmos. <b>Theaetetus</b> studied the octahedron and icosahedron in depth, and <b>Euclid</b> proved in the last book (XIII) of the <i>Elements</i> that there are only five — the crowning result of the whole work.'),
      L('1596-yilda <b>Iogann Kepler</b> «Kosmografik sir» kitobida oltita sayyoraning orbitalarini bir-birining ichiga joylashtirilgan beshta Platon jismi bilan tushuntirishga urindi. Model noto‘g‘ri chiqdi, lekin aniq o‘lchovlarga intilish Keplerni sayyoralar harakatining haqiqiy qonunlarigacha olib keldi. V − E + F = 2 formulasini <b>Leonard Eyler</b> 1750-yilda maktubda bayon qilgan; Dekartning shunga yaqin natijasi saqlanib qolgan qo‘lyozmasida ham uchraydi.', 'В 1596 году <b>Иоганн Кеплер</b> в книге «Тайна мироздания» пытался объяснить орбиты шести планет пятью платоновыми телами, вложенными друг в друга. Модель оказалась неверной, но стремление к точным измерениям привело Кеплера к настоящим законам движения планет. Формулу В − Р + Г = 2 <b>Леонард Эйлер</b> изложил в письме 1750 года; близкий результат встречается и в сохранившейся рукописи Декарта.', 'In 1596 <b>Johannes Kepler</b>, in his <i>Mysterium Cosmographicum</i>, tried to explain the orbits of the six known planets by the five Platonic solids nested inside one another. The model was wrong, but the quest for precise measurements led Kepler to the true laws of planetary motion. <b>Leonhard Euler</b> stated V − E + F = 2 in a letter of 1750; a closely related result also appears in a surviving manuscript of Descartes.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Решённые примеры', 'Worked examples'), ex: [
      { q: L('Yassi burchaklari 50°, 60° va 120° bo‘lgan uchyoqli burchak mavjudmi?', 'Существует ли трёхгранный угол с плоскими углами 50°, 60° и 120°?', 'Is there a trihedral angle with face angles 50°, 60° and 120°?'),
        s: L('Eng katta burchak qolgan ikkitasining yig‘indisidan kichik bo‘lishi kerak: 120° &lt; 50° + 60° = 110°? Yo‘q. Demak, bunday uchyoqli burchak <b>mavjud emas</b>.', 'Наибольший угол должен быть меньше суммы двух других: 120° &lt; 50° + 60° = 110°? Нет. Значит, такого трёхгранного угла <b>не существует</b>.', 'The largest angle must be less than the sum of the other two: is 120° &lt; 50° + 60° = 110°? No. So such a trihedral angle <b>does not exist</b>.') },
      { q: L('Qavariq ko‘pyoqning 12 ta uchi va 30 ta qirrasi bor. Nechta yog‘i bor?', 'У выпуклого многогранника 12 вершин и 30 рёбер. Сколько у него граней?', 'A convex polyhedron has 12 vertices and 30 edges. How many faces does it have?'),
        s: L('Eyler formulasi: F = 2 − V + E = 2 − 12 + 30 = <b>20</b>. (Masalan, ikosaedr.)', 'Формула Эйлера: Г = 2 − В + Р = 2 − 12 + 30 = <b>20</b>. (Например, икосаэдр.)', 'Euler’s formula: F = 2 − V + E = 2 − 12 + 30 = <b>20</b>. (For example, the icosahedron.)') },
      { q: L('Futbol to‘pi 12 ta beshburchak va 20 ta oltiburchakdan tikilgan. Uning nechta qirrasi va uchi bor?', 'Футбольный мяч сшит из 12 пятиугольников и 20 шестиугольников. Сколько у него рёбер и вершин?', 'A football is sewn from 12 pentagons and 20 hexagons. How many edges and vertices does it have?'),
        s: L('Tomonlar soni: 12·5 + 20·6 = 180; har bir qirra ikki yoqqa tegishli, E = 180/2 = <b>90</b>. F = 32. V = 2 + E − F = 2 + 90 − 32 = <b>60</b>. Tekshirish: har uchda 3 yoq uchrashadi, 180/3 = 60.', 'Число сторон: 12·5 + 20·6 = 180; каждое ребро принадлежит двум граням, Р = 180/2 = <b>90</b>. Г = 32. В = 2 + Р − Г = 2 + 90 − 32 = <b>60</b>. Проверка: в каждой вершине сходятся 3 грани, 180/3 = 60.', 'Number of sides: 12·5 + 20·6 = 180; each edge belongs to two faces, so E = 180/2 = <b>90</b>. F = 32. V = 2 + E − F = 2 + 90 − 32 = <b>60</b>. Check: 3 faces meet at each vertex, 180/3 = 60.') },
      { q: L('To‘rtta yassi burchagi 100° dan bo‘lgan qavariq to‘rtyoqli burchak bormi? 80° dan bo‘lgani-chi?', 'Есть ли выпуклый четырёхгранный угол с четырьмя плоскими углами по 100°? А по 80°?', 'Is there a convex four-faced angle with four face angles of 100° each? And of 80° each?'),
        s: L('4·100° = 400° &gt; 360° — <b>mavjud emas</b>. 4·80° = 320° &lt; 360° — bunday burchak <b>mavjud</b> (masalan, muntazam to‘rtburchakli piramidaning uchi).', '4·100° = 400° &gt; 360° — <b>не существует</b>. 4·80° = 320° &lt; 360° — такой угол <b>существует</b> (например, вершина правильной четырёхугольной пирамиды).', '4·100° = 400° &gt; 360° — <b>impossible</b>. 4·80° = 320° &lt; 360° — such an angle <b>exists</b> (for instance, the apex of a regular square pyramid).') },
      { q: L('Dodekaedrning har bir uchidagi «yetishmovchilik» 360° dan yassi burchaklar yig‘indisini ayirganga teng. Barcha uchlardagi yetishmovchiliklar yig‘indisini toping.', 'Дефект каждой вершины додекаэдра равен 360° минус сумма плоских углов. Найдите сумму дефектов всех вершин.', 'The defect at a vertex of a dodecahedron is 360° minus the sum of its face angles. Find the total defect over all vertices.'),
        s: L('Uchda 3·108° = 324°, yetishmovchilik 36°. Uchlar 20 ta: 20·36° = <b>720°</b>. Dekart teoremasiga ko‘ra har qanday qavariq ko‘pyoq uchun bu yig‘indi doim 720° (kub: 8·90° = 720°).', 'При вершине 3·108° = 324°, дефект 36°. Вершин 20: 20·36° = <b>720°</b>. По теореме Декарта для любого выпуклого многогранника эта сумма всегда 720° (куб: 8·90° = 720°).', 'At a vertex 3·108° = 324°, so the defect is 36°. There are 20 vertices: 20·36° = <b>720°</b>. By Descartes’ theorem this total is always 720° for any convex polyhedron (cube: 8·90° = 720°).') }
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>Yassi va ikki yoqli burchaklarni adashtirish:</b> 360° dan kichik bo‘lishi kerak bo‘lgan — yassi burchaklar yig‘indisi; ikki yoqli burchaklar uchun bunday qoida yo‘q.', '<b>Путают плоские и двугранные углы:</b> меньше 360° должна быть сумма плоских углов; для двугранных такого правила нет.', '<b>Confusing face angles with dihedral angles:</b> it is the face angles that sum to less than 360°; there is no such rule for dihedral angles.'),
      L('<b>Qirralarni ikki marta sanash:</b> yoqlar tomonlarini qo‘shganda natijani 2 ga bo‘lish kerak, chunki har bir qirra ikki yoqda.', '<b>Двойной счёт рёбер:</b> сложив стороны граней, надо разделить на 2 — каждое ребро принадлежит двум граням.', '<b>Counting edges twice:</b> after adding up the sides of all faces, divide by 2 — each edge lies on two faces.'),
      L('<b>Eyler formulasini qavariq bo‘lmagan, «teshikli» jismga qo‘llash:</b> masalan, teshikli ramka uchun V − E + F = 0 bo‘ladi.', '<b>Применяют формулу Эйлера к телу «с дыркой»:</b> например, для рамки с отверстием В − Р + Г = 0.', '<b>Applying Euler’s formula to a solid with a hole:</b> for a picture-frame shape V − E + F = 0.'),
      L('<b>«Muntazam» uchun faqat teng yoqlarni tekshirish:</b> har uchda bir xil sonli yoq ham shart. Ikki tetraedrni yopishtirib, 6 ta teng uchburchakli, lekin muntazam bo‘lmagan jism olinadi.', '<b>Для «правильного» проверяют только равенство граней:</b> нужно ещё одинаковое число граней в каждой вершине. Склеив два тетраэдра, получим тело с 6 равными треугольниками, но не правильное.', '<b>Checking only equal faces for “regular”:</b> the same number of faces at each vertex is also required. Gluing two tetrahedra gives a solid with 6 equal triangles that is not regular.')
    ] },
    { kind: 'life', h: L('Ko‘pyoqlar atrofimizda', 'Многогранники вокруг нас', 'Polyhedra around us'), p: [
      L('Osh tuzi kristallari kub shaklida, olmos ko‘pincha oktaedr shaklida o‘sadi, pirit esa dodekaedrga o‘xshash kristallar hosil qiladi. Ko‘plab viruslarning (masalan, adenovirus) qobig‘i ikosaedr shaklida: bu bir xil oqsil bo‘laklaridan eng tejamkor yopiq «quti» yasash usuli. Stol o‘yinlaridagi zarlar ham beshta Platon jismi shaklida yasaladi — 4, 6, 8, 12 va 20 yoqli.', 'Кристаллы поваренной соли имеют форму куба, алмаз часто растёт октаэдрами, а пирит образует кристаллы, похожие на додекаэдр. Оболочка многих вирусов (например, аденовируса) — икосаэдр: это самый экономный способ собрать замкнутую «коробку» из одинаковых белковых блоков. Игральные кости в настольных играх делают в форме всех пяти платоновых тел — с 4, 6, 8, 12 и 20 гранями.', 'Table salt crystallises in cubes, diamond often grows as octahedra, and pyrite forms crystals that look like dodecahedra. The shell of many viruses (adenovirus, for example) is an icosahedron: the most economical way to build a closed “box” from identical protein blocks. Dice for board games come in the shapes of all five Platonic solids — with 4, 6, 8, 12 and 20 faces.'),
      L('Arxitektor <b>Bakminster Fuller</b> ikosaedrni bo‘lib, yengil va mustahkam <b>geodezik gumbazlar</b> yaratgan. Uglerodning C₆₀ molekulasi — «fulleren» — futbol to‘pi kabi 60 uchli ko‘pyoq; uni kashf etgan olimlar 1996-yilda Nobel mukofotini olgan. Kompyuter grafikasida esa har qanday 3D model — minglab uchburchakli ko‘pyoq.', 'Архитектор <b>Бакминстер Фуллер</b>, разбивая икосаэдр, создавал лёгкие и прочные <b>геодезические купола</b>. Молекула углерода C₆₀ — «фуллерен» — многогранник с 60 вершинами, как футбольный мяч; её открыватели получили Нобелевскую премию 1996 года. А в компьютерной графике любая 3D-модель — многогранник из тысяч треугольников.', 'The architect <b>Buckminster Fuller</b> subdivided the icosahedron to build light, strong <b>geodesic domes</b>. The carbon molecule C₆₀ — “fullerene” — is a 60-vertex polyhedron shaped like a football; its discoverers won the 1996 Nobel Prize. And in computer graphics every 3D model is a polyhedron made of thousands of triangles.')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверьте себя', 'Check yourself'), ex: [
      { q: L('n burchakli piramida uchun V − E + F ni tekshiring.', 'Проверьте В − Р + Г для n-угольной пирамиды.', 'Check V − E + F for an n-gonal pyramid.'),
        s: L('V = n + 1, E = 2n, F = n + 1: (n + 1) − 2n + (n + 1) = 2.', 'В = n + 1, Р = 2n, Г = n + 1: (n + 1) − 2n + (n + 1) = 2.', 'V = n + 1, E = 2n, F = n + 1: (n + 1) − 2n + (n + 1) = 2.') },
      { q: L('Har bir uchida 3 ta yoq uchrashadigan qavariq ko‘pyoqning 8 ta yog‘i bor. Uchlari va qirralari nechta?', 'У выпуклого многогранника 8 граней, в каждой вершине сходятся 3 грани. Сколько вершин и рёбер?', 'A convex polyhedron has 8 faces with 3 faces at every vertex. How many vertices and edges?'),
        s: L('Har bir uchdan 3 qirra chiqadi va har qirra 2 uchni tutashtiradi: E = 3V/2. Eyler: V − 3V/2 + 8 = 2, V/2 = 6, V = 12, E = 18 (masalan, oltiburchakli prizma).', 'Из каждой вершины выходят 3 ребра, каждое ребро соединяет 2 вершины: Р = 3В/2. Эйлер: В − 3В/2 + 8 = 2, В/2 = 6, В = 12, Р = 18 (например, шестиугольная призма).', 'Three edges leave each vertex and each edge joins 2 vertices: E = 3V/2. Euler: V − 3V/2 + 8 = 2, V/2 = 6, V = 12, E = 18 (e.g. a hexagonal prism).') }
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Ko‘pyoqli burchak — bir uchdan chiquvchi nurlar va ular orasidagi yassi burchaklardan tuzilgan shakl; eng soddasi uchyoqli.', 'Многогранный угол образован лучами из одной вершины и плоскими углами между ними; простейший — трёхгранный.', 'A polyhedral angle is formed by rays from one vertex and the face angles between them; the simplest is trihedral.'),
      L('Uchyoqli burchakda har bir yassi burchak qolgan ikkitasining yig‘indisidan kichik.', 'В трёхгранном угле каждый плоский угол меньше суммы двух других.', 'In a trihedral angle each face angle is less than the sum of the other two.'),
      L('Qavariq ko‘pyoqli burchak yassi burchaklari yig‘indisi 360° dan kichik.', 'Сумма плоских углов выпуклого многогранного угла меньше 360°.', 'The face angles of a convex polyhedral angle sum to less than 360°.'),
      L('Qavariq ko‘pyoq uchun Eyler formulasi: V − E + F = 2.', 'Для выпуклого многогранника формула Эйлера: В − Р + Г = 2.', 'For a convex polyhedron, Euler’s formula: V − E + F = 2.'),
      L('Muntazam ko‘pyoqlar beshta: tetraedr, oktaedr, ikosaedr, kub, dodekaedr (Yevklid, XIII kitob).', 'Правильных многогранников пять: тетраэдр, октаэдр, икосаэдр, куб, додекаэдр (Евклид, XIII книга).', 'There are five regular polyhedra: tetrahedron, octahedron, icosahedron, cube, dodecahedron (Euclid, Book XIII).'),
      L('Ko‘pyoqlar kristallar, viruslar, molekulalar va gumbazlarda uchraydi.', 'Многогранники встречаются в кристаллах, вирусах, молекулах и куполах.', 'Polyhedra appear in crystals, viruses, molecules and domes.')
    ] }
  ] });

  // ---------- t5. Prizma va uning sirti ----------
  T.add(P, 't5', { sections: [
    { kind: 'intro', h: L('Qutidan binogacha', 'От коробки до здания', 'From a box to a building'), p: [
      L('Gugurt qutisi, g‘isht, kitob, akvarium, ko‘p qavatli uy, qalam (oltiburchakli!), shokolad «Toblerone» qutisi (uchburchakli!) — bularning hammasi <b>prizmalar</b>. Prizma — kundalik hayotdagi eng ko‘p uchraydigan jism, chunki uni yasash, taxlash va qadoqlash qulay. Uni bo‘yash, qoplash yoki o‘rash uchun qancha material ketishini bilish esa — <b>sirt yuzini</b> hisoblash demakdir.', 'Спичечный коробок, кирпич, книга, аквариум, многоэтажный дом, карандаш (шестигранный!), коробка шоколада «Toblerone» (треугольная!) — всё это <b>призмы</b>. Призма — самое распространённое тело в быту: её легко изготовить, сложить штабелем и упаковать. А узнать, сколько материала нужно, чтобы её покрасить, обшить или обернуть, — значит вычислить <b>площадь поверхности</b>.', 'A matchbox, a brick, a book, an aquarium, a tower block, a (hexagonal!) pencil, a (triangular!) Toblerone box — all of these are <b>prisms</b>. The prism is the most common solid in everyday life because it is easy to make, stack and pack. Finding how much material is needed to paint, clad or wrap one means computing its <b>surface area</b>.'),
      L('Bu mavzuda prizmaning ta’rifi, turlari, parallelepiped xossalari va yon hamda to‘la sirtni hisoblash formulalarini o‘rganamiz.', 'В этой теме мы изучим определение и виды призм, свойства параллелепипеда и формулы боковой и полной поверхности.', 'In this topic we study the definition and types of prisms, the properties of the parallelepiped, and formulas for the lateral and total surface area.')
    ] },
    { kind: 'def', h: L('Prizma va uning elementlari', 'Призма и её элементы', 'The prism and its parts'), p: [
      L('<b>Prizma</b> — ikki yog‘i parallel tekisliklarda yotuvchi teng n burchakli ko‘pburchaklar, qolgan n ta yog‘i esa parallelogrammlar bo‘lgan ko‘pyoq. Teng ko‘pburchaklar — <b>asoslar</b>, parallelogrammlar — <b>yon yoqlar</b>, ularning asoslarga tegishli bo‘lmagan tomonlari — <b>yon qirralar</b>. Barcha yon qirralar o‘zaro teng va parallel.', '<b>Призма</b> — многогранник, у которого две грани — равные n-угольники, лежащие в параллельных плоскостях, а остальные n граней — параллелограммы. Равные многоугольники — <b>основания</b>, параллелограммы — <b>боковые грани</b>, их стороны, не принадлежащие основаниям, — <b>боковые рёбра</b>. Все боковые рёбра равны и параллельны.', 'A <b>prism</b> is a polyhedron with two faces that are equal n-gons in parallel planes, while its other n faces are parallelograms. The equal polygons are the <b>bases</b>, the parallelograms are the <b>lateral faces</b>, and their sides not on the bases are the <b>lateral edges</b>. All lateral edges are equal and parallel.'),
      L('Asos tekisliklari orasidagi masofa — prizmaning <b>balandligi</b> h. Bitta yon yoqqa tegishli bo‘lmagan ikki uchni tutashtiruvchi kesma — <b>diagonal</b>; ikki qo‘shni bo‘lmagan yon qirra orqali o‘tgan kesim — <b>diagonal kesim</b> (u parallelogramm). Asosi uchburchak bo‘lsa — uchburchakli prizma, to‘rtburchak bo‘lsa — to‘rtburchakli prizma va hokazo.', 'Расстояние между плоскостями оснований — <b>высота</b> призмы h. Отрезок, соединяющий две вершины, не лежащие в одной грани, — <b>диагональ</b>; сечение через два несоседних боковых ребра — <b>диагональное сечение</b> (это параллелограмм). Если основание — треугольник, призма треугольная, если четырёхугольник — четырёхугольная и т. д.', 'The distance between the base planes is the <b>height</b> h. A segment joining two vertices not on the same face is a <b>diagonal</b>; a section through two non-adjacent lateral edges is a <b>diagonal section</b> (a parallelogram). A prism with a triangular base is triangular, with a quadrilateral base quadrilateral, and so on.')
    ] },
    { kind: 'table', h: L('Prizma turlari', 'Виды призм', 'Types of prisms'), table: { head: [L('Turi', 'Вид', 'Type'), L('Ta’rif', 'Определение', 'Definition'), L('Yon yoqlar', 'Боковые грани', 'Lateral faces')], rows: [
      [L('Og‘ma', 'Наклонная', 'Oblique'), L('yon qirralar asosga perpendikulyar emas', 'боковые рёбра не перпендикулярны основанию', 'lateral edges not perpendicular to the base'), L('parallelogrammlar; h &lt; yon qirra', 'параллелограммы; h &lt; бокового ребра', 'parallelograms; h &lt; lateral edge')],
      [L('To‘g‘ri', 'Прямая', 'Right'), L('yon qirralar asosga perpendikulyar', 'боковые рёбра перпендикулярны основанию', 'lateral edges perpendicular to the base'), L('to‘g‘ri to‘rtburchaklar; h = yon qirra', 'прямоугольники; h = боковому ребру', 'rectangles; h = lateral edge')],
      [L('Muntazam', 'Правильная', 'Regular'), L('to‘g‘ri, asosi muntazam ko‘pburchak', 'прямая, основание — правильный многоугольник', 'right, with a regular polygon base'), L('teng to‘g‘ri to‘rtburchaklar', 'равные прямоугольники', 'equal rectangles')],
      [L('Parallelepiped', 'Параллелепипед', 'Parallelepiped'), L('asosi parallelogramm', 'основание — параллелограмм', 'base is a parallelogram'), L('barcha 6 yoq parallelogramm', 'все 6 граней — параллелограммы', 'all 6 faces parallelograms')],
      [L('To‘g‘ri burchakli parallelepiped', 'Прямоугольный параллелепипед', 'Rectangular box'), L('to‘g‘ri, asosi to‘g‘ri to‘rtburchak', 'прямой, основание — прямоугольник', 'right, rectangular base'), L('barcha yoqlar to‘g‘ri to‘rtburchak', 'все грани — прямоугольники', 'all faces rectangles')],
      [L('Kub', 'Куб', 'Cube'), L('barcha qirralari teng to‘g‘ri burchakli parallelepiped', 'прямоугольный параллелепипед с равными рёбрами', 'rectangular box with all edges equal'), L('6 ta teng kvadrat', '6 равных квадратов', '6 equal squares')]
    ] } },
    { kind: 'rule', h: L('Parallelepiped xossalari', 'Свойства параллелепипеда', 'Properties of the parallelepiped'), p: [
      L('<b>1.</b> Parallelepipedning qarama-qarshi yoqlari teng va parallel. <b>2.</b> Uning to‘rtta diagonali bir nuqtada kesishadi va shu nuqtada teng ikkiga bo‘linadi. Isbot g‘oyasi: har qanday ikki diagonal, masalan AC₁ va BD₁, ABC₁D₁ to‘rtburchakning diagonallari; bu to‘rtburchakning AB va D₁C₁ tomonlari teng va parallel, demak u parallelogramm va diagonallari o‘rtada kesishadi. Kesishish nuqtasi — parallelepipedning <b>simmetriya markazi</b>.', '<b>1.</b> Противоположные грани параллелепипеда равны и параллельны. <b>2.</b> Его четыре диагонали пересекаются в одной точке и делятся ею пополам. Идея доказательства: любые две диагонали, например AC₁ и BD₁, — диагонали четырёхугольника ABC₁D₁; его стороны AB и D₁C₁ равны и параллельны, значит это параллелограмм, и диагонали пересекаются посередине. Точка пересечения — <b>центр симметрии</b> параллелепипеда.', '<b>1.</b> Opposite faces of a parallelepiped are equal and parallel. <b>2.</b> Its four diagonals meet at one point, which bisects each of them. Proof idea: any two diagonals, say AC₁ and BD₁, are the diagonals of quadrilateral ABC₁D₁; its sides AB and D₁C₁ are equal and parallel, so it is a parallelogram and its diagonals bisect each other. The common point is the parallelepiped’s <b>centre of symmetry</b>.'),
      L('<b>3.</b> To‘g‘ri burchakli parallelepipedda diagonal kvadrati uchta o‘lchov kvadratlari yig‘indisiga teng: <b>d² = a² + b² + c²</b> (Pifagor teoremasi ikki marta). Barcha to‘rt diagonal teng. Kubda d = a√3, yog‘ining diagonali a√2.', '<b>3.</b> В прямоугольном параллелепипеде квадрат диагонали равен сумме квадратов трёх измерений: <b>d² = a² + b² + c²</b> (теорема Пифагора дважды). Все четыре диагонали равны. У куба d = a√3, диагональ грани a√2.', '<b>3.</b> In a rectangular box the square of a diagonal equals the sum of the squares of its three dimensions: <b>d² = a² + b² + c²</b> (Pythagoras twice). All four diagonals are equal. For a cube d = a√3, and a face diagonal is a√2.')
    ] },
    { kind: 'rule', h: L('Yon va to‘la sirt', 'Боковая и полная поверхность', 'Lateral and total surface'), p: [
      L('Yon yoqlar yuzlarining yig‘indisi — <b>yon sirt</b> S<sub>yon</sub>, unga ikki asos yuzi qo‘shilsa — <b>to‘la sirt</b>: <b>S = S<sub>yon</sub> + 2S<sub>asos</sub></b>.', 'Сумма площадей боковых граней — <b>боковая поверхность</b> S<sub>бок</sub>, вместе с двумя основаниями — <b>полная поверхность</b>: <b>S = S<sub>бок</sub> + 2S<sub>осн</sub></b>.', 'The sum of the lateral face areas is the <b>lateral surface</b> S<sub>lat</sub>; adding the two bases gives the <b>total surface</b>: <b>S = S<sub>lat</sub> + 2S<sub>base</sub></b>.'),
      L('<b>Teorema.</b> To‘g‘ri prizmaning yon sirti asos perimetri bilan balandlik ko‘paytmasiga teng: <b>S<sub>yon</sub> = P·h</b>. <b>Isbot.</b> Yon yoqlar — to‘g‘ri to‘rtburchaklar, ularning asoslari a₁, a₂, …, aₙ (asos tomonlari), balandligi h. Yig‘indi: a₁h + a₂h + … + aₙh = (a₁ + … + aₙ)h = P·h. Ko‘rgazmali: yon sirtni qirqib yoysak, tomonlari P va h bo‘lgan bitta to‘g‘ri to‘rtburchak hosil bo‘ladi.', '<b>Теорема.</b> Боковая поверхность прямой призмы равна произведению периметра основания на высоту: <b>S<sub>бок</sub> = P·h</b>. <b>Доказательство.</b> Боковые грани — прямоугольники со сторонами a₁, a₂, …, aₙ (стороны основания) и высотой h. Сумма: a₁h + a₂h + … + aₙh = (a₁ + … + aₙ)h = P·h. Наглядно: разрезав и развернув боковую поверхность, получим один прямоугольник со сторонами P и h.', '<b>Theorem.</b> The lateral surface of a right prism equals the base perimeter times the height: <b>S<sub>lat</sub> = P·h</b>. <b>Proof.</b> The lateral faces are rectangles with bases a₁, a₂, …, aₙ (the sides of the base) and height h. Sum: a₁h + a₂h + … + aₙh = (a₁ + … + aₙ)h = P·h. Visually: cutting and unrolling the lateral surface gives a single rectangle with sides P and h.'),
      L('<b>Og‘ma prizma</b> uchun: S<sub>yon</sub> = P<sub>⊥</sub>·l, bu yerda l — yon qirra, P<sub>⊥</sub> — yon qirralarga perpendikulyar kesim perimetri. Har bir yon yoq — asosi l, balandligi esa perpendikulyar kesim tomoni bo‘lgan parallelogramm. To‘g‘ri burchakli parallelepiped uchun: <b>S = 2(ab + bc + ca)</b>, kub uchun S = 6a².', 'Для <b>наклонной призмы</b>: S<sub>бок</sub> = P<sub>⊥</sub>·l, где l — боковое ребро, P<sub>⊥</sub> — периметр перпендикулярного сечения. Каждая боковая грань — параллелограмм с основанием l и высотой, равной стороне перпендикулярного сечения. Для прямоугольного параллелепипеда: <b>S = 2(ab + bc + ca)</b>, для куба S = 6a².', 'For an <b>oblique prism</b>: S<sub>lat</sub> = P<sub>⊥</sub>·l, where l is a lateral edge and P<sub>⊥</sub> the perimeter of a section perpendicular to the lateral edges. Each lateral face is a parallelogram with base l and height equal to a side of that section. For a rectangular box: <b>S = 2(ab + bc + ca)</b>; for a cube S = 6a².')
    ] },
    { kind: 'history', h: L('«Arralangan» jism', '«Отпиленное» тело', 'The “sawn-off” solid'), p: [
      L('«Prizma» so‘zi yunoncha <i>prisma</i> — «arralangan narsa» so‘zidan olingan: haqiqatan ham, uzun to‘sinni ko‘ndalangiga arralasangiz, prizma hosil bo‘ladi. Prizmaning qat’iy ta’rifi <b>Yevklid</b> «Negizlar»ining XI kitobida berilgan, uning hajmi bilan bog‘liq teoremalar esa XII kitobda isbotlangan. Qadimgi Misr va Bobil quruvchilari to‘g‘ri burchakli tosh bloklar va kanallarning sirti va hajmini amaliy hisoblay olgan.', 'Слово «призма» происходит от греческого <i>prisma</i> — «отпиленное»: действительно, если распилить длинный брус поперёк, получится призма. Строгое определение призмы дано в XI книге «Начал» <b>Евклида</b>, а теоремы об её объёме доказаны в XII книге. Строители Древнего Египта и Вавилона умели практически рассчитывать поверхности и объёмы прямоугольных каменных блоков и каналов.', 'The word “prism” comes from the Greek <i>prisma</i>, “something sawn”: indeed, sawing a long beam crosswise produces a prism. A strict definition appears in Book XI of <b>Euclid</b>’s <i>Elements</i>, and theorems on its volume are proved in Book XII. Builders in ancient Egypt and Babylon could already compute surfaces and volumes of rectangular stone blocks and canals in practice.'),
      L('1666-yilda <b>Isaak Nyuton</b> shisha uchburchakli prizma orqali quyosh nurini o‘tkazib, oq yorug‘lik kamalak ranglariga ajralishini ko‘rsatdi. Shundan beri optikada «prizma» so‘zi alohida ma’noga ega bo‘ldi: durbinlar, fotoapparatlar va spektrometrlarda shisha prizmalar nurni burish va ranglarga ajratish uchun ishlatiladi.', 'В 1666 году <b>Исаак Ньютон</b>, пропуская солнечный луч через стеклянную треугольную призму, показал, что белый свет разлагается на цвета радуги. С тех пор слово «призма» получило особое значение в оптике: в биноклях, фотоаппаратах и спектрометрах стеклянные призмы поворачивают лучи и разлагают их на цвета.', 'In 1666 <b>Isaac Newton</b> passed a sunbeam through a glass triangular prism and showed that white light splits into the colours of the rainbow. Since then “prism” has had a special meaning in optics: in binoculars, cameras and spectrometers glass prisms turn light and split it into colours.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Решённые примеры', 'Worked examples'), ex: [
      { q: L('Muntazam uchburchakli prizmaning asos tomoni 6, balandligi 10. Yon va to‘la sirtini toping.', 'Сторона основания правильной треугольной призмы 6, высота 10. Найдите боковую и полную поверхность.', 'A regular triangular prism has base side 6 and height 10. Find its lateral and total surface.'),
        s: L('P = 18, S<sub>yon</sub> = 18·10 = <b>180</b>. S<sub>asos</sub> = (√3/4)·36 = 9√3. S = 180 + 2·9√3 = <b>180 + 18√3 ≈ 211,2</b>.', 'P = 18, S<sub>бок</sub> = 18·10 = <b>180</b>. S<sub>осн</sub> = (√3/4)·36 = 9√3. S = 180 + 2·9√3 = <b>180 + 18√3 ≈ 211,2</b>.', 'P = 18, S<sub>lat</sub> = 18·10 = <b>180</b>. S<sub>base</sub> = (√3/4)·36 = 9√3. S = 180 + 2·9√3 = <b>180 + 18√3 ≈ 211.2</b>.') },
      { q: L('To‘g‘ri burchakli parallelepipedning o‘lchamlari 3, 4, 12. Diagonali va to‘la sirtini toping.', 'Измерения прямоугольного параллелепипеда 3, 4, 12. Найдите диагональ и полную поверхность.', 'A rectangular box measures 3 × 4 × 12. Find its diagonal and total surface.'),
        s: L('d = √(9 + 16 + 144) = √169 = <b>13</b>. S = 2(3·4 + 4·12 + 12·3) = 2(12 + 48 + 36) = 2·96 = <b>192</b>.', 'd = √(9 + 16 + 144) = √169 = <b>13</b>. S = 2(3·4 + 4·12 + 12·3) = 2(12 + 48 + 36) = 2·96 = <b>192</b>.', 'd = √(9 + 16 + 144) = √169 = <b>13</b>. S = 2(3·4 + 4·12 + 12·3) = 2(12 + 48 + 36) = 2·96 = <b>192</b>.') },
      { q: L('To‘g‘ri prizmaning asosi diagonallari 6 va 8 bo‘lgan romb, balandligi 10. To‘la sirtini toping.', 'Основание прямой призмы — ромб с диагоналями 6 и 8, высота 10. Найдите полную поверхность.', 'A right prism has a rhombus base with diagonals 6 and 8 and height 10. Find its total surface.'),
        s: L('Romb diagonallari to‘g‘ri burchak ostida teng ikkiga bo‘linadi: tomon = √(3² + 4²) = 5, P = 20. S<sub>yon</sub> = 20·10 = 200. S<sub>asos</sub> = 6·8/2 = 24. S = 200 + 48 = <b>248</b>.', 'Диагонали ромба делятся пополам под прямым углом: сторона = √(3² + 4²) = 5, P = 20. S<sub>бок</sub> = 20·10 = 200. S<sub>осн</sub> = 6·8/2 = 24. S = 200 + 48 = <b>248</b>.', 'The diagonals of a rhombus bisect each other at right angles: side = √(3² + 4²) = 5, P = 20. S<sub>lat</sub> = 20·10 = 200. S<sub>base</sub> = 6·8/2 = 24. S = 200 + 48 = <b>248</b>.') },
      { q: L('Muntazam to‘rtburchakli prizmaning asos tomoni 4, diagonali 9. Uning to‘la sirtini toping.', 'Сторона основания правильной четырёхугольной призмы 4, диагональ 9. Найдите полную поверхность.', 'A regular square prism has base side 4 and diagonal 9. Find its total surface.'),
        s: L('d² = a² + a² + h²: 81 = 16 + 16 + h², h² = 49, h = 7. S<sub>yon</sub> = 16·7 = 112, 2S<sub>asos</sub> = 2·16 = 32. S = <b>144</b>.', 'd² = a² + a² + h²: 81 = 16 + 16 + h², h² = 49, h = 7. S<sub>бок</sub> = 16·7 = 112, 2S<sub>осн</sub> = 2·16 = 32. S = <b>144</b>.', 'd² = a² + a² + h²: 81 = 16 + 16 + h², h² = 49, h = 7. S<sub>lat</sub> = 16·7 = 112, 2S<sub>base</sub> = 2·16 = 32. S = <b>144</b>.') },
      { q: L('Muntazam oltiburchakli prizmaning asos tomoni 2, balandligi 5. To‘la sirtini toping.', 'Сторона основания правильной шестиугольной призмы 2, высота 5. Найдите полную поверхность.', 'A regular hexagonal prism has base side 2 and height 5. Find its total surface.'),
        s: L('S<sub>yon</sub> = 6·2·5 = 60. Muntazam oltiburchak 6 ta teng tomonli uchburchakdan iborat: S<sub>asos</sub> = 6·(√3/4)·4 = 6√3. S = 60 + 12√3 ≈ 60 + 20,78 = <b>80,78</b>.', 'S<sub>бок</sub> = 6·2·5 = 60. Правильный шестиугольник состоит из 6 равносторонних треугольников: S<sub>осн</sub> = 6·(√3/4)·4 = 6√3. S = 60 + 12√3 ≈ 60 + 20,78 = <b>80,78</b>.', 'S<sub>lat</sub> = 6·2·5 = 60. A regular hexagon consists of 6 equilateral triangles: S<sub>base</sub> = 6·(√3/4)·4 = 6√3. S = 60 + 12√3 ≈ 60 + 20.78 = <b>80.78</b>.') }
    ] },
    { kind: 'steps', h: L('Sirtni hisoblash rejasi', 'План вычисления поверхности', 'Plan for computing a surface'), list: [
      L('Prizma turini aniqlang: to‘g‘rimi yoki og‘mami, asosi qanday ko‘pburchak.', 'Определите вид призмы: прямая или наклонная, какой многоугольник в основании.', 'Identify the prism: right or oblique, and what polygon the base is.'),
      L('Asos perimetrini va yuzini toping (uchburchak, romb, muntazam oltiburchak formulalari).', 'Найдите периметр и площадь основания (формулы треугольника, ромба, правильного шестиугольника).', 'Find the base perimeter and area (formulas for triangles, rhombi, regular hexagons).'),
      L('Balandlik noma’lum bo‘lsa — diagonal yoki burchak orqali to‘g‘ri burchakli uchburchakdan toping.', 'Если высота неизвестна — найдите её из прямоугольного треугольника через диагональ или угол.', 'If the height is unknown, find it from a right triangle using a diagonal or an angle.'),
      L('S<sub>yon</sub> = P·h (og‘ma prizmada P<sub>⊥</sub>·l), so‘ng S = S<sub>yon</sub> + 2S<sub>asos</sub>.', 'S<sub>бок</sub> = P·h (для наклонной P<sub>⊥</sub>·l), затем S = S<sub>бок</sub> + 2S<sub>осн</sub>.', 'S<sub>lat</sub> = P·h (oblique: P<sub>⊥</sub>·l), then S = S<sub>lat</sub> + 2S<sub>base</sub>.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>Asosni bir marta qo‘shish:</b> to‘la sirtda asos <b>ikki</b> marta qatnashadi — pastki va ustki.', '<b>Добавляют основание один раз:</b> в полной поверхности основание участвует <b>дважды</b> — нижнее и верхнее.', '<b>Adding the base once:</b> the total surface contains the base <b>twice</b> — bottom and top.'),
      L('<b>Og‘ma prizmada S<sub>yon</sub> = P·h deb olish:</b> bu faqat to‘g‘ri prizma uchun; og‘ma prizmada P<sub>⊥</sub>·l.', '<b>Для наклонной призмы берут S<sub>бок</sub> = P·h:</b> это верно только для прямой; для наклонной — P<sub>⊥</sub>·l.', '<b>Using S<sub>lat</sub> = P·h for an oblique prism:</b> it holds only for right prisms; for oblique ones use P<sub>⊥</sub>·l.'),
      L('<b>Yon qirrani balandlik deb olish</b> og‘ma prizmada: balandlik yon qirradan kichik, h = l·sin φ.', '<b>Принимают боковое ребро за высоту</b> в наклонной призме: высота меньше ребра, h = l·sin φ.', '<b>Taking the lateral edge as the height</b> in an oblique prism: the height is shorter, h = l·sin φ.'),
      L('<b>Yog‘ diagonali bilan prizma diagonalini adashtirish:</b> kubda yog‘ diagonali a√2, prizma diagonali a√3.', '<b>Путают диагональ грани и диагональ призмы:</b> у куба диагональ грани a√2, а диагональ куба a√3.', '<b>Confusing a face diagonal with a space diagonal:</b> in a cube the face diagonal is a√2, the space diagonal a√3.'),
      L('<b>Muntazam prizmani «barcha qirralari teng» deb tushunish:</b> muntazam prizmada faqat asos muntazam; balandlik asos tomoniga teng bo‘lishi shart emas.', '<b>Понимают правильную призму как «все рёбра равны»:</b> у правильной призмы правильным является основание; высота не обязана равняться стороне основания.', '<b>Thinking a regular prism has all edges equal:</b> only the base is regular; the height need not equal the base side.')
    ] },
    { kind: 'life', h: L('Prizma sirti amalda', 'Поверхность призмы на практике', 'Prism surfaces in practice'), p: [
      L('Xonani ta’mirlashda devorlarga qancha gulqog‘oz kerakligini hisoblash — to‘g‘ri burchakli parallelepipedning yon sirtini topish demakdir: o‘lchamlari 5 × 4 m, balandligi 2,7 m bo‘lgan xona uchun S<sub>yon</sub> = 18·2,7 = 48,6 m², eshik va derazalar yuzi esa ayiriladi. Shiftni bo‘yash uchun yana 20 m² qo‘shiladi.', 'При ремонте расчёт обоев для стен — это боковая поверхность прямоугольного параллелепипеда: для комнаты 5 × 4 м высотой 2,7 м S<sub>бок</sub> = 18·2,7 = 48,6 м², а площадь дверей и окон вычитается. Для покраски потолка добавляют ещё 20 м².', 'Working out wallpaper for a room is finding the lateral surface of a rectangular box: for a 5 × 4 m room 2.7 m high, S<sub>lat</sub> = 18·2.7 = 48.6 m², minus the area of doors and windows. Painting the ceiling adds another 20 m².'),
      L('Qadoqlash sanoatida karton qutilar yoyilmasi (to‘la sirt + yopishtirish uchun «quloqchalar») bo‘yicha qirqiladi; sirtni kamaytirish — karton va pulni tejash. Asalarilarning mumli kataklari muntazam oltiburchakli prizmalar shaklida: bu shakl berilgan hajm uchun eng kam mum sarflaydi. Issiqxona, angar va choyshablar o‘lchami ham prizma sirti orqali hisoblanadi.', 'В упаковочной промышленности картонные коробки вырезают по развёртке (полная поверхность + «клапаны» для склейки); уменьшить поверхность — значит сэкономить картон и деньги. Восковые ячейки пчёл имеют форму правильных шестиугольных призм: такая форма требует меньше всего воска для заданного объёма. Размеры теплиц, ангаров и тентов тоже рассчитывают через поверхность призмы.', 'In packaging, cardboard boxes are cut from a net (total surface + flaps for gluing); reducing the surface saves cardboard and money. Honeybee wax cells are regular hexagonal prisms: that shape uses the least wax for a given volume. Greenhouses, hangars and tarpaulins are also sized via prism surfaces.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Prizma: ikki teng parallel asos va parallelogramm shaklidagi yon yoqlar; yon qirralar teng va parallel.', 'Призма: два равных параллельных основания и боковые грани-параллелограммы; боковые рёбра равны и параллельны.', 'A prism has two equal parallel bases and parallelogram lateral faces; the lateral edges are equal and parallel.'),
      L('To‘g‘ri prizmada yon qirra = balandlik; muntazam prizma — asosi muntazam ko‘pburchak bo‘lgan to‘g‘ri prizma.', 'В прямой призме боковое ребро = высота; правильная призма — прямая призма с правильным многоугольником в основании.', 'In a right prism the lateral edge equals the height; a regular prism is a right prism with a regular base.'),
      L('Parallelepiped diagonallari bir nuqtada kesishib, teng ikkiga bo‘linadi; to‘g‘ri burchaklisida d² = a² + b² + c².', 'Диагонали параллелепипеда пересекаются в одной точке и делятся пополам; в прямоугольном d² = a² + b² + c².', 'The diagonals of a parallelepiped meet and bisect each other; in a rectangular box d² = a² + b² + c².'),
      L('To‘g‘ri prizma: S<sub>yon</sub> = P·h; og‘ma prizma: S<sub>yon</sub> = P<sub>⊥</sub>·l.', 'Прямая призма: S<sub>бок</sub> = P·h; наклонная: S<sub>бок</sub> = P<sub>⊥</sub>·l.', 'Right prism: S<sub>lat</sub> = P·h; oblique prism: S<sub>lat</sub> = P<sub>⊥</sub>·l.'),
      L('To‘la sirt: S = S<sub>yon</sub> + 2S<sub>asos</sub>; to‘g‘ri burchakli parallelepiped: S = 2(ab + bc + ca), kub: 6a².', 'Полная поверхность: S = S<sub>бок</sub> + 2S<sub>осн</sub>; прямоугольный параллелепипед: S = 2(ab + bc + ca), куб: 6a².', 'Total surface: S = S<sub>lat</sub> + 2S<sub>base</sub>; rectangular box: S = 2(ab + bc + ca), cube: 6a².')
    ] }
  ] });

  // ---------- t6. Prizmaning hajmi ----------
  T.add(P, 't6', { sections: [
    { kind: 'intro', h: L('Qancha suv sig‘adi?', 'Сколько воды поместится?', 'How much water fits?'), p: [
      L('Hovuzni to‘ldirish uchun qancha suv kerak? Yuk mashinasiga qancha qum sig‘adi? Xonani isitish uchun qanday quvvatli konditsioner olish kerak? Bu savollarning barchasi jism egallagan fazo miqdori — <b>hajm</b> haqida. Sirt jismni «o‘rash» uchun qancha material ketishini aytsa, hajm uning ichiga qancha narsa sig‘ishini aytadi.', 'Сколько воды нужно, чтобы наполнить бассейн? Сколько песка поместится в грузовик? Какой мощности кондиционер купить для комнаты? Все эти вопросы — о количестве пространства, занимаемого телом, то есть об <b>объёме</b>. Если поверхность говорит, сколько материала нужно, чтобы тело «обернуть», то объём — сколько в него поместится.', 'How much water does it take to fill a pool? How much sand fits in a lorry? What air conditioner does a room need? All these questions are about the amount of space a body occupies — its <b>volume</b>. The surface tells how much material wraps a solid; the volume tells how much fits inside it.'),
      L('Bu mavzuda hajm tushunchasining xossalarini, to‘g‘ri burchakli parallelepiped va istalgan prizma hajmi formulalarini hamda og‘ma jismlar hajmini topishga yordam beruvchi ajoyib vosita — <b>Kavalyeri prinsipini</b> o‘rganamiz.', 'В этой теме мы изучим свойства объёма, формулы объёма прямоугольного параллелепипеда и любой призмы, а также замечательный инструмент для наклонных тел — <b>принцип Кавальери</b>.', 'In this topic we study the properties of volume, the volume formulas for a rectangular box and any prism, and a wonderful tool for slanted solids — <b>Cavalieri’s principle</b>.')
    ] },
    { kind: 'def', h: L('Hajm va uning xossalari', 'Объём и его свойства', 'Volume and its properties'), p: [
      L('Har bir jismga musbat son — uning <b>hajmi</b> V mos qo‘yiladi va u quyidagi xossalarga ega: <b>1)</b> teng jismlarning hajmlari teng; <b>2)</b> jism bir necha bo‘lakka bo‘linsa, uning hajmi bo‘laklar hajmlari yig‘indisiga teng; <b>3)</b> qirrasi uzunlik birligiga teng kubning hajmi 1 ga teng (1 sm³, 1 m³ va hokazo).', 'Каждому телу ставится в соответствие положительное число — его <b>объём</b> V, обладающий свойствами: <b>1)</b> равные тела имеют равные объёмы; <b>2)</b> если тело разбито на части, его объём равен сумме объёмов частей; <b>3)</b> объём куба с ребром, равным единице длины, равен 1 (1 см³, 1 м³ и т. д.).', 'Each solid is assigned a positive number, its <b>volume</b> V, with these properties: <b>1)</b> congruent solids have equal volumes; <b>2)</b> if a solid is cut into pieces, its volume is the sum of the pieces’ volumes; <b>3)</b> a cube whose edge is the unit of length has volume 1 (1 cm³, 1 m³ and so on).'),
      L('Birliklar: 1 m³ = 1000 dm³ = 1 000 000 sm³. Suyuqliklar uchun <b>litr</b>: 1 l = 1 dm³, demak 1 m³ = 1000 l. Hajmlari teng jismlar <b>tengdosh</b> deyiladi; ular teng bo‘lishi shart emas (masalan, 1 × 1 × 8 parallelepiped va qirrasi 2 bo‘lgan kub).', 'Единицы: 1 м³ = 1000 дм³ = 1 000 000 см³. Для жидкостей — <b>литр</b>: 1 л = 1 дм³, значит 1 м³ = 1000 л. Тела с равными объёмами называются <b>равновеликими</b>; они не обязаны быть равными (например, параллелепипед 1 × 1 × 8 и куб с ребром 2).', 'Units: 1 m³ = 1000 dm³ = 1,000,000 cm³. For liquids, the <b>litre</b>: 1 L = 1 dm³, so 1 m³ = 1000 L. Solids with equal volumes are called <b>equivalent</b>; they need not be congruent (for example, a 1 × 1 × 8 box and a cube of edge 2).')
    ] },
    { kind: 'rule', h: L('To‘g‘ri burchakli parallelepiped hajmi', 'Объём прямоугольного параллелепипеда', 'Volume of a rectangular box'), p: [
      L('<b>Teorema.</b> O‘lchamlari a, b, c bo‘lgan to‘g‘ri burchakli parallelepiped hajmi <b>V = abc</b>; kub uchun V = a³.', '<b>Теорема.</b> Объём прямоугольного параллелепипеда с измерениями a, b, c равен <b>V = abc</b>; для куба V = a³.', '<b>Theorem.</b> A rectangular box with dimensions a, b, c has volume <b>V = abc</b>; for a cube V = a³.'),
      L('<b>Isbot g‘oyasi.</b> Agar a, b, c butun sonlar bo‘lsa, parallelepipedni a·b·c ta birlik kubga bo‘lish mumkin: pastki qatlamda a·b ta kub, qatlamlar c ta. Agar o‘lchamlar kasr bo‘lsa (masalan, umumiy maxraj n bilan), birlik kubni qirrasi 1/n bo‘lgan n³ ta kichik kubga bo‘lamiz; har birining hajmi 1/n³, va yana sanash bilan V = abc chiqadi. Irratsional o‘lchamlar uchun a, b, c ni kami va ortig‘i bilan olingan o‘nli kasrlar bilan yaqinlashtirib, limitga o‘tamiz.', '<b>Идея доказательства.</b> Если a, b, c — целые, параллелепипед делится на a·b·c единичных кубов: в нижнем слое a·b кубов, слоёв c. Если измерения дробные (скажем, с общим знаменателем n), разобьём единичный куб на n³ кубиков с ребром 1/n; объём каждого 1/n³, и подсчёт снова даёт V = abc. Для иррациональных измерений приближаем a, b, c десятичными дробями с недостатком и избытком и переходим к пределу.', '<b>Proof idea.</b> If a, b, c are whole numbers, the box splits into a·b·c unit cubes: a·b cubes in the bottom layer, c layers. If the dimensions are fractions (say with common denominator n), split the unit cube into n³ small cubes of edge 1/n, each of volume 1/n³; counting again gives V = abc. For irrational dimensions approximate a, b, c by decimals from below and above and pass to the limit.'),
      L('Formulani V = (ab)·c = S<sub>asos</sub>·h ko‘rinishida yozsak, u barcha prizmalar uchun umumlashadi.', 'Записав формулу как V = (ab)·c = S<sub>осн</sub>·h, мы обобщим её на все призмы.', 'Written as V = (ab)·c = S<sub>base</sub>·h, the formula generalises to every prism.')
    ] },
    { kind: 'rule', h: L('Har qanday prizma hajmi', 'Объём любой призмы', 'Volume of any prism'), p: [
      L('<b>Teorema.</b> Prizmaning hajmi asos yuzi bilan balandlik ko‘paytmasiga teng: <b>V = S<sub>asos</sub>·h</b>.', '<b>Теорема.</b> Объём призмы равен произведению площади основания на высоту: <b>V = S<sub>осн</sub>·h</b>.', '<b>Theorem.</b> The volume of a prism equals its base area times its height: <b>V = S<sub>base</sub>·h</b>.'),
      L('<b>To‘g‘ri prizma uchun isbot bosqichlari.</b> 1) Asosi to‘g‘ri burchakli uchburchak bo‘lgan to‘g‘ri prizma — to‘g‘ri burchakli parallelepipedning diagonal kesim bo‘yicha yarmi: V = abh/2 = S·h. 2) Har qanday uchburchakni balandlik bilan ikki to‘g‘ri burchakli uchburchakka bo‘lsak, prizma ham ikkiga bo‘linadi va hajmlar qo‘shiladi. 3) Har qanday ko‘pburchakni uchburchaklarga bo‘lish mumkin, demak V = (S₁ + S₂ + …)·h = S·h.', '<b>Шаги доказательства для прямой призмы.</b> 1) Прямая призма с основанием — прямоугольным треугольником — это половина прямоугольного параллелепипеда по диагональному сечению: V = abh/2 = S·h. 2) Любой треугольник высотой делится на два прямоугольных, призма тоже делится на две, и объёмы складываются. 3) Любой многоугольник можно разбить на треугольники, значит V = (S₁ + S₂ + …)·h = S·h.', '<b>Proof steps for a right prism.</b> 1) A right prism on a right-triangle base is half of a rectangular box, cut along a diagonal section: V = abh/2 = S·h. 2) An altitude splits any triangle into two right triangles, splitting the prism in two, and the volumes add. 3) Any polygon can be cut into triangles, so V = (S₁ + S₂ + …)·h = S·h.'),
      L('Og‘ma prizma uchun ikkinchi formula ham bor: <b>V = S<sub>⊥</sub>·l</b>, bu yerda S<sub>⊥</sub> — yon qirralarga perpendikulyar kesim yuzi, l — yon qirra. Uni og‘ma prizmani perpendikulyar kesim bo‘yicha qirqib, bo‘lakni narigi uchiga ko‘chirish orqali isbotlash mumkin: hosil bo‘lgan to‘g‘ri prizmaning asosi S<sub>⊥</sub>, balandligi l.', 'Для наклонной призмы есть и вторая формула: <b>V = S<sub>⊥</sub>·l</b>, где S<sub>⊥</sub> — площадь перпендикулярного сечения, l — боковое ребро. Её доказывают, разрезав призму по перпендикулярному сечению и переставив кусок на другой конец: получается прямая призма с основанием S<sub>⊥</sub> и высотой l.', 'For an oblique prism there is a second formula: <b>V = S<sub>⊥</sub>·l</b>, where S<sub>⊥</sub> is the area of a section perpendicular to the lateral edges and l is a lateral edge. Prove it by cutting along the perpendicular section and moving the piece to the other end: you get a right prism with base S<sub>⊥</sub> and height l.')
    ] },
    { kind: 'rule', h: L('Kavalyeri prinsipi', 'Принцип Кавальери', 'Cavalieri’s principle'), p: [
      L('<b>Prinsip.</b> Agar ikki jism bitta tekislikka parallel istalgan tekislik bilan kesilganda teng yuzli kesimlar hosil bo‘lsa, bu jismlarning hajmlari teng.', '<b>Принцип.</b> Если при сечении двух тел любой плоскостью, параллельной данной, получаются сечения равной площади, то объёмы этих тел равны.', '<b>Principle.</b> If every plane parallel to a given plane cuts two solids in sections of equal area, then the solids have equal volumes.'),
      L('Tasavvur qiling: tangalar ustuni tik turibdi. Uni qiyshaytirsak, shakl o‘zgaradi, lekin har bir tanga (kesim) o‘sha-o‘sha, tangalar soni ham o‘zgarmaydi — demak hajm ham o‘zgarmaydi. Xuddi shunday, asosi S, balandligi h bo‘lgan og‘ma prizmaning asosga parallel har bir kesimi asosga teng ko‘pburchak (yuzi S). Asosi va balandligi xuddi shunday to‘g‘ri prizmada ham kesimlar yuzi S. Kavalyeri prinsipiga ko‘ra hajmlar teng: <b>og‘ma prizma uchun ham V = S·h</b>.', 'Представьте стопку монет, стоящую прямо. Если её наклонить, форма изменится, но каждая монета (сечение) та же, и число монет прежнее — значит, объём не изменился. Точно так же каждое сечение наклонной призмы с основанием S и высотой h, параллельное основанию, — многоугольник, равный основанию (площадь S). У прямой призмы с тем же основанием и высотой сечения тоже площади S. По принципу Кавальери объёмы равны: <b>и для наклонной призмы V = S·h</b>.', 'Picture a stack of coins standing straight. Tilt it and the shape changes, but every coin (section) is the same and so is the number of coins — so the volume is unchanged. Likewise every section of an oblique prism with base S and height h parallel to the base is a polygon equal to the base (area S). A right prism with the same base and height also has sections of area S. By Cavalieri’s principle the volumes are equal: <b>V = S·h for an oblique prism too</b>.'),
      L('Kavalyeri prinsipi qat’iy isbotlanadigan teorema (integral hisobidan kelib chiqadi), ammo maktabda u tayanch tasdiq sifatida qabul qilinadi. Keyingi mavzularda u piramida, konus va shar hajmlarini topishda ham asosiy vosita bo‘ladi.', 'Принцип Кавальери — строго доказуемая теорема (следует из интегрального исчисления), но в школе его принимают как опорное утверждение. В следующих темах он станет главным инструментом и для объёмов пирамиды, конуса и шара.', 'Cavalieri’s principle is a rigorously provable theorem (it follows from integral calculus), but at school it is accepted as a basic statement. In later topics it is also the main tool for the volumes of pyramids, cones and balls.')
    ] },
    { kind: 'history', h: L('Bo‘linmaslar usuli', 'Метод неделимых', 'The method of indivisibles'), p: [
      L('Italiyalik rohib va matematik <b>Bonaventura Kavalyeri</b> (1598–1647), Galileyning shogirdi, 1635-yilda «Bo‘linmaslar geometriyasi» kitobini nashr etdi. U yassi shaklni cheksiz ko‘p parallel kesmalardan, jismni esa cheksiz ko‘p parallel tekis kesimlardan — «bo‘linmaslardan» iborat deb qaradi. Bu g‘oya Nyuton va Leybnitsning integral hisobiga yo‘l ochdi.', 'Итальянский монах и математик <b>Бонавентура Кавальери</b> (1598–1647), ученик Галилея, в 1635 году издал «Геометрию неделимых». Он рассматривал плоскую фигуру как состоящую из бесконечного числа параллельных отрезков, а тело — из бесконечного числа параллельных плоских сечений, «неделимых». Эта идея открыла путь к интегральному исчислению Ньютона и Лейбница.', 'The Italian friar and mathematician <b>Bonaventura Cavalieri</b> (1598–1647), a pupil of Galileo, published <i>Geometry of Indivisibles</i> in 1635. He treated a plane figure as made of infinitely many parallel segments, and a solid as made of infinitely many parallel plane sections — “indivisibles”. This idea paved the way for the integral calculus of Newton and Leibniz.'),
      L('Qizig‘i shundaki, xuddi shu prinsipni Xitoyda V–VI asrlarda <b>Zu Geng</b> (mashhur astronom Zu Chongjining o‘g‘li) aniq ifodalagan: «balandliklar teng va kesimlar yuzlari teng bo‘lsa, hajmlar teng bo‘lmasligi mumkin emas» — va u bilan shar hajmini topgan. Qadimgi Yunonistonda esa <b>Demokrit</b> va <b>Yevdoks</b> jismlarni yupqa qatlamlarga bo‘lish g‘oyasidan foydalangan, <b>Arximed</b> esa «Usul» asarida shunga o‘xshash mulohazalar bilan shar hajmini kashf etgan.', 'Интересно, что тот же принцип чётко сформулировал в Китае в V–VI веках <b>Цзу Гэн</b> (сын знаменитого астронома Цзу Чунчжи): «если высоты равны и площади сечений равны, объёмы не могут быть неравными» — и с его помощью нашёл объём шара. В Древней Греции идеей разбиения тел на тонкие слои пользовались <b>Демокрит</b> и <b>Евдокс</b>, а <b>Архимед</b> в сочинении «Метод» похожими рассуждениями открыл объём шара.', 'Remarkably, the same principle was stated clearly in China in the 5th–6th centuries by <b>Zu Geng</b> (son of the famous astronomer Zu Chongzhi): “if the heights are equal and the section areas are equal, the volumes cannot be unequal” — and he used it to find the volume of a ball. In ancient Greece <b>Democritus</b> and <b>Eudoxus</b> used the idea of slicing solids into thin layers, and <b>Archimedes</b>, in <i>The Method</i>, discovered the volume of a ball by similar reasoning.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Решённые примеры', 'Worked examples'), ex: [
      { q: L('Yuk mashinasi kuzovining ichki o‘lchamlari 4 m × 2,5 m × 1,2 m. Unga necha kub metr va necha litr qum sig‘adi?', 'Внутренние размеры кузова грузовика 4 м × 2,5 м × 1,2 м. Сколько кубометров и литров песка в него поместится?', 'A lorry body measures 4 m × 2.5 m × 1.2 m inside. How many cubic metres and litres of sand fit in it?'),
        s: L('V = 4·2,5·1,2 = 10·1,2 = <b>12 m³</b> = 12·1000 = <b>12 000 l</b>.', 'V = 4·2,5·1,2 = 10·1,2 = <b>12 м³</b> = 12·1000 = <b>12 000 л</b>.', 'V = 4·2.5·1.2 = 10·1.2 = <b>12 m³</b> = 12·1000 = <b>12,000 L</b>.') },
      { q: L('Muntazam uchburchakli prizmaning asos tomoni 4, balandligi 9. Hajmini toping.', 'Сторона основания правильной треугольной призмы 4, высота 9. Найдите объём.', 'A regular triangular prism has base side 4 and height 9. Find its volume.'),
        s: L('S<sub>asos</sub> = (√3/4)·16 = 4√3. V = 4√3·9 = <b>36√3 ≈ 62,35</b>.', 'S<sub>осн</sub> = (√3/4)·16 = 4√3. V = 4√3·9 = <b>36√3 ≈ 62,35</b>.', 'S<sub>base</sub> = (√3/4)·16 = 4√3. V = 4√3·9 = <b>36√3 ≈ 62.35</b>.') },
      { q: L('Og‘ma prizmaning asos yuzi 12, yon qirrasi 10 va u asos tekisligi bilan 60° burchak tashkil qiladi. Hajmini toping.', 'Площадь основания наклонной призмы 12, боковое ребро 10 образует с плоскостью основания угол 60°. Найдите объём.', 'An oblique prism has base area 12; its lateral edge is 10 and makes 60° with the base plane. Find its volume.'),
        s: L('Balandlik — yon qirraning asosga perpendikulyar tashkil etuvchisi: h = 10·sin 60° = 5√3. V = 12·5√3 = <b>60√3 ≈ 103,9</b>. (h o‘rniga 10 olinsa, noto‘g‘ri 120 chiqadi.)', 'Высота — перпендикулярная к основанию составляющая ребра: h = 10·sin 60° = 5√3. V = 12·5√3 = <b>60√3 ≈ 103,9</b>. (Если взять 10 вместо h, получится неверное 120.)', 'The height is the component of the edge perpendicular to the base: h = 10·sin 60° = 5√3. V = 12·5√3 = <b>60√3 ≈ 103.9</b>. (Using 10 instead of h gives the wrong answer 120.)') },
      { q: L('Kubning diagonali 6√3. Kub hajmini toping.', 'Диагональ куба 6√3. Найдите объём куба.', 'A cube has diagonal 6√3. Find its volume.'),
        s: L('d = a√3 = 6√3, demak a = 6. V = 6³ = <b>216</b>.', 'd = a√3 = 6√3, значит a = 6. V = 6³ = <b>216</b>.', 'd = a√3 = 6√3, so a = 6. V = 6³ = <b>216</b>.') },
      { q: L('Hovuz 25 m × 10 m, chuqurligi 2 m. Nasos soatiga 50 m³ suv quysa, hovuz necha soatda to‘ladi?', 'Бассейн 25 м × 10 м глубиной 2 м. Насос подаёт 50 м³ воды в час. За сколько часов наполнится бассейн?', 'A pool is 25 m × 10 m and 2 m deep. A pump delivers 50 m³ of water per hour. How many hours to fill it?'),
        s: L('V = 25·10·2 = 500 m³. Vaqt: 500 : 50 = <b>10 soat</b>.', 'V = 25·10·2 = 500 м³. Время: 500 : 50 = <b>10 часов</b>.', 'V = 25·10·2 = 500 m³. Time: 500 ÷ 50 = <b>10 hours</b>.') }
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>Og‘ma prizmada yon qirrani balandlik deb olish:</b> V = S·h formulasida h — asoslar orasidagi masofa, l emas.', '<b>Берут боковое ребро наклонной призмы за высоту:</b> в V = S·h h — расстояние между основаниями, а не l.', '<b>Using the lateral edge of an oblique prism as the height:</b> in V = S·h, h is the distance between the bases, not l.'),
      L('<b>Birliklarni aralashtirish:</b> 1 m³ = 1000 dm³, 100 emas; 1 m³ = 10⁶ sm³. Hisobdan oldin barcha o‘lchamlarni bir birlikka keltiring.', '<b>Путают единицы:</b> 1 м³ = 1000 дм³, а не 100; 1 м³ = 10⁶ см³. Перед вычислением приведите все размеры к одной единице.', '<b>Mixing units:</b> 1 m³ = 1000 dm³, not 100; 1 m³ = 10⁶ cm³. Convert all dimensions to one unit before computing.'),
      L('<b>Hajmni sirt bilan adashtirish:</b> 2(ab + bc + ca) — sirt (m²), abc — hajm (m³).', '<b>Путают объём с поверхностью:</b> 2(ab + bc + ca) — поверхность (м²), abc — объём (м³).', '<b>Confusing volume with surface:</b> 2(ab + bc + ca) is surface (m²), abc is volume (m³).'),
      L('<b>Tengdosh jismlarni teng deb hisoblash:</b> hajmlari teng jismlar shakli turlicha bo‘lishi mumkin.', '<b>Считают равновеликие тела равными:</b> тела с равными объёмами могут иметь разную форму.', '<b>Treating equivalent solids as congruent:</b> solids of equal volume can have different shapes.'),
      L('<b>Kavalyeri prinsipini faqat bitta kesim bilan qo‘llash:</b> kesimlar <b>barcha</b> balandliklarda teng bo‘lishi shart.', '<b>Применяют принцип Кавальери по одному сечению:</b> сечения должны быть равны на <b>всех</b> высотах.', '<b>Applying Cavalieri with one section only:</b> the sections must be equal at <b>every</b> height.')
    ] },
    { kind: 'life', h: L('Hajm hayotda', 'Объём в жизни', 'Volume in everyday life'), p: [
      L('Quruvchi poydevor uchun beton buyurtma qiladi: uzunligi 40 m, eni 0,5 m, chuqurligi 1 m bo‘lgan lenta poydevorga 20 m³ beton kerak — bu taxminan 3 ta beton aralashtirgich mashinasi. Konditsioner va isitish tizimi xona hajmiga qarab tanlanadi. Yuk tashuvchi kompaniyalar to‘lovni ko‘pincha og‘irlik bo‘yicha emas, qutining «hajmiy og‘irligi» — uzunlik × eni × balandlik bo‘yicha hisoblaydi.', 'Строитель заказывает бетон для фундамента: на ленточный фундамент длиной 40 м, шириной 0,5 м и глубиной 1 м нужно 20 м³ бетона — это примерно 3 бетономешалки. Кондиционер и отопление подбирают по объёму комнаты. Транспортные компании часто берут плату не по весу, а по «объёмному весу» коробки — длина × ширина × высота.', 'A builder orders concrete for a foundation: a strip footing 40 m long, 0.5 m wide and 1 m deep needs 20 m³ of concrete — about three mixer trucks. Air conditioning and heating are chosen by room volume. Delivery companies often charge not by weight but by the “volumetric weight” of a box — length × width × height.'),
      L('Arximed qonuniga ko‘ra suvga botirilgan jism o‘z hajmicha suvni siqib chiqaradi; shunday qilib, noto‘g‘ri shakldagi jism (masalan, tosh) hajmini o‘lchov idishi bilan topish mumkin. Kemalar suv sig‘imi, neft barrellari (≈ 159 l) va daryolarning suv sarfi (m³/s) ham hajm tushunchasiga tayanadi.', 'По закону Архимеда погружённое в воду тело вытесняет объём воды, равный своему; так можно найти объём тела неправильной формы (например, камня) с помощью мерного сосуда. Водоизмещение кораблей, нефтяные баррели (≈ 159 л) и расход воды рек (м³/с) тоже опираются на понятие объёма.', 'By Archimedes’ law a body submerged in water displaces its own volume of water, so the volume of an irregular object (a stone, say) can be found with a measuring jug. Ship displacement, oil barrels (≈ 159 L) and river discharge (m³/s) all rest on the idea of volume.')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверьте себя', 'Check yourself'), ex: [
      { q: L('To‘g‘ri prizmaning asosi katetlari 6 va 8 bo‘lgan to‘g‘ri burchakli uchburchak, katta yon yog‘i kvadrat. Hajmini toping.', 'Основание прямой призмы — прямоугольный треугольник с катетами 6 и 8, наибольшая боковая грань — квадрат. Найдите объём.', 'A right prism has a right-triangle base with legs 6 and 8, and its largest lateral face is a square. Find its volume.'),
        s: L('Gipotenuza 10, demak h = 10. S<sub>asos</sub> = 6·8/2 = 24. V = 24·10 = 240.', 'Гипотенуза 10, значит h = 10. S<sub>осн</sub> = 6·8/2 = 24. V = 24·10 = 240.', 'The hypotenuse is 10, so h = 10. S<sub>base</sub> = 6·8/2 = 24. V = 24·10 = 240.') },
      { q: L('Kubning har bir qirrasi 3 marta oshirildi. Hajmi necha marta oshdi?', 'Каждое ребро куба увеличили в 3 раза. Во сколько раз увеличился объём?', 'Each edge of a cube is tripled. By what factor does the volume grow?'),
        s: L('3³ = 27 marta.', 'В 3³ = 27 раз.', 'By 3³ = 27.') }
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Hajm xossalari: teng jismlar hajmi teng, bo‘laklar hajmi qo‘shiladi, birlik kub hajmi 1.', 'Свойства объёма: равные тела имеют равные объёмы, объёмы частей складываются, объём единичного куба равен 1.', 'Volume properties: congruent solids have equal volume, volumes of parts add, the unit cube has volume 1.'),
      L('To‘g‘ri burchakli parallelepiped: V = abc; kub: V = a³.', 'Прямоугольный параллелепипед: V = abc; куб: V = a³.', 'Rectangular box: V = abc; cube: V = a³.'),
      L('Har qanday prizma: V = S<sub>asos</sub>·h; og‘ma prizma: shuningdek V = S<sub>⊥</sub>·l.', 'Любая призма: V = S<sub>осн</sub>·h; наклонная также: V = S<sub>⊥</sub>·l.', 'Any prism: V = S<sub>base</sub>·h; an oblique prism also: V = S<sub>⊥</sub>·l.'),
      L('Kavalyeri prinsipi: barcha parallel kesimlari teng yuzli jismlar tengdosh.', 'Принцип Кавальери: тела, у которых все параллельные сечения равновелики, имеют равные объёмы.', 'Cavalieri’s principle: solids with equal-area parallel sections at every level have equal volumes.'),
      L('1 l = 1 dm³, 1 m³ = 1000 l.', '1 л = 1 дм³, 1 м³ = 1000 л.', '1 L = 1 dm³, 1 m³ = 1000 L.'),
      L('Bo‘linmaslar g‘oyasi — Kavalyeri (1635) va Zu Geng (V–VI asr) — integral hisobining ildizi.', 'Идея неделимых — Кавальери (1635) и Цзу Гэн (V–VI века) — корень интегрального исчисления.', 'The idea of indivisibles — Cavalieri (1635) and Zu Geng (5th–6th centuries) — is a root of integral calculus.')
    ] }
  ] });

  // ---------- t7. Silindrning sirti va hajmi ----------
  T.add(P, 't7', { sections: [
    { kind: 'intro', h: L('Dumaloq prizma', 'Круглая призма', 'A round prism'), p: [
      L('Konserva bankasi, stakan, quvur, gaz ballon, qalam ichidagi grafit, neft sisternasi, minora — bularning hammasi <b>silindr</b> shaklida. Silindrni «asosi doira bo‘lgan prizma» deb tasavvur qilish mumkin: agar muntazam prizma asosidagi ko‘pburchak tomonlari sonini cheksiz oshirsak, u silindrga tobora yaqinlashadi. Shu sababli silindr formulalari prizma formulalariga juda o‘xshaydi, faqat ularda π soni paydo bo‘ladi.', 'Консервная банка, стакан, труба, газовый баллон, грифель карандаша, нефтяная цистерна, башня — всё это <b>цилиндры</b>. Цилиндр можно представить как «призму с круглым основанием»: если неограниченно увеличивать число сторон правильного многоугольника в основании призмы, она всё ближе к цилиндру. Поэтому формулы цилиндра очень похожи на формулы призмы, только в них появляется число π.', 'A tin can, a glass, a pipe, a gas cylinder, a pencil lead, an oil tank, a tower — all of these are <b>cylinders</b>. A cylinder can be pictured as a “prism with a round base”: if we keep increasing the number of sides of the regular polygon at the base of a prism, it gets ever closer to a cylinder. So the cylinder formulas look much like the prism formulas, except that π appears.'),
      L('Bu mavzuda silindrning ta’rifi va elementlarini, uning kesimlarini, yon va to‘la sirtini hamda hajmini o‘rganamiz.', 'В этой теме мы изучим определение и элементы цилиндра, его сечения, боковую и полную поверхность и объём.', 'In this topic we study the definition and parts of a cylinder, its sections, its lateral and total surface, and its volume.')
    ] },
    { kind: 'def', h: L('Silindr va uning elementlari', 'Цилиндр и его элементы', 'The cylinder and its parts'), p: [
      L('<b>Silindr</b> (to‘g‘ri doiraviy silindr) — to‘g‘ri to‘rtburchakni bir tomoni atrofida aylantirishdan hosil bo‘lgan jism. Aylanish o‘qi bo‘lgan tomon — silindrning <b>o‘qi</b>; unga qo‘shni tomonlar aylanib, ikki teng doira — <b>asoslarni</b> chizadi; qarama-qarshi tomon esa <b>yon sirtni</b> hosil qiladi.', '<b>Цилиндр</b> (прямой круговой цилиндр) — тело, полученное вращением прямоугольника вокруг одной из его сторон. Сторона, служащая осью вращения, — <b>ось</b> цилиндра; соседние с ней стороны при вращении описывают два равных круга — <b>основания</b>; противоположная сторона образует <b>боковую поверхность</b>.', 'A <b>cylinder</b> (right circular cylinder) is the solid obtained by rotating a rectangle about one of its sides. The side that serves as the axis is the <b>axis</b> of the cylinder; the adjacent sides sweep out two equal discs — the <b>bases</b>; the opposite side sweeps out the <b>lateral surface</b>.'),
      L('Asos doirasining radiusi — silindr <b>radiusi</b> r. Yon sirtdagi o‘qqa parallel kesmalar — <b>yasovchilar</b>; ular teng va asoslarga perpendikulyar. Asoslar orasidagi masofa — <b>balandlik</b> h; to‘g‘ri silindrda u yasovchiga teng. Balandligi diametrga teng (h = 2r) silindr <b>teng tomonli silindr</b> deyiladi.', 'Радиус круга основания — <b>радиус</b> цилиндра r. Отрезки боковой поверхности, параллельные оси, — <b>образующие</b>; они равны и перпендикулярны основаниям. Расстояние между основаниями — <b>высота</b> h; у прямого цилиндра она равна образующей. Цилиндр, у которого высота равна диаметру (h = 2r), называется <b>равносторонним</b>.', 'The radius of a base disc is the cylinder’s <b>radius</b> r. Segments on the lateral surface parallel to the axis are the <b>generators</b> (elements); they are equal and perpendicular to the bases. The distance between the bases is the <b>height</b> h; in a right cylinder it equals a generator. A cylinder whose height equals its diameter (h = 2r) is called <b>equilateral</b>.')
    ] },
    { kind: 'rule', h: L('Silindr kesimlari', 'Сечения цилиндра', 'Sections of a cylinder'), p: [
      L('<b>Asosga parallel</b> tekislik silindrni asosga teng doira bo‘yicha kesadi. <b>O‘q orqali</b> o‘tgan tekislik bilan kesim — <b>o‘q kesim</b>: tomonlari 2r va h bo‘lgan to‘g‘ri to‘rtburchak. Teng tomonli silindrning o‘q kesimi kvadrat. <b>O‘qqa parallel</b>, o‘qdan d masofadagi tekislik (d &lt; r) bilan kesim ham to‘g‘ri to‘rtburchak, uning bir tomoni h, ikkinchisi asosdagi vatar 2√(r² − d²).', 'Плоскость, <b>параллельная основанию</b>, пересекает цилиндр по кругу, равному основанию. Сечение плоскостью <b>через ось</b> — <b>осевое сечение</b>: прямоугольник со сторонами 2r и h. Осевое сечение равностороннего цилиндра — квадрат. Сечение плоскостью, <b>параллельной оси</b>, на расстоянии d от неё (d &lt; r) — тоже прямоугольник: одна сторона h, другая — хорда основания 2√(r² − d²).', 'A plane <b>parallel to the base</b> cuts the cylinder in a disc equal to the base. A plane <b>through the axis</b> gives the <b>axial section</b>: a rectangle with sides 2r and h. The axial section of an equilateral cylinder is a square. A plane <b>parallel to the axis</b> at distance d from it (d &lt; r) also gives a rectangle: one side h, the other the base chord 2√(r² − d²).'),
      L('Asosga og‘ma tekislik yon sirtni <b>ellips</b> bo‘yicha kesadi — buni stakandagi suvni qiyshaytirib ko‘rish mumkin. Yasovchi orqali o‘tib, o‘q kesimiga perpendikulyar bo‘lgan tekislik silindrga <b>urinma tekislik</b> deyiladi: u silindr bilan faqat shu yasovchi bo‘ylab umumiy nuqtalarga ega.', 'Плоскость, наклонная к основанию, пересекает боковую поверхность по <b>эллипсу</b> — это видно, если наклонить стакан с водой. Плоскость, проходящая через образующую перпендикулярно осевому сечению через неё, называется <b>касательной плоскостью</b> к цилиндру: у неё с цилиндром общие точки только на этой образующей.', 'A plane tilted to the base cuts the lateral surface in an <b>ellipse</b> — you can see it by tilting a glass of water. A plane through a generator, perpendicular to the axial section containing it, is a <b>tangent plane</b> to the cylinder: it meets the cylinder only along that generator.')
    ] },
    { kind: 'rule', h: L('Yon va to‘la sirt', 'Боковая и полная поверхность', 'Lateral and total surface'), p: [
      L('Yon sirtni bitta yasovchi bo‘ylab qirqib, tekislikka yoysak, <b>to‘g‘ri to‘rtburchak</b> hosil bo‘ladi: bir tomoni h, ikkinchisi asos aylanasi uzunligi 2πr. Shuning uchun <b>S<sub>yon</sub> = 2πrh</b>. (Qog‘oz yorliqni bankadan ajratib ko‘ring — u to‘g‘ri to‘rtburchak!) Qat’iy ta’rifda silindr yon sirti — unga ichki chizilgan muntazam prizmalar yon sirtlarining limiti: P·h → 2πr·h.', 'Разрезав боковую поверхность по образующей и развернув на плоскость, получим <b>прямоугольник</b>: одна сторона h, другая — длина окружности основания 2πr. Поэтому <b>S<sub>бок</sub> = 2πrh</b>. (Снимите бумажную этикетку с банки — это прямоугольник!) При строгом определении боковая поверхность цилиндра — предел боковых поверхностей вписанных правильных призм: P·h → 2πr·h.', 'Cut the lateral surface along a generator and unroll it flat: you get a <b>rectangle</b> with sides h and the base circumference 2πr. Hence <b>S<sub>lat</sub> = 2πrh</b>. (Peel the paper label off a can — it is a rectangle!) Strictly, the lateral surface is the limit of the lateral surfaces of inscribed regular prisms: P·h → 2πr·h.'),
      L('To‘la sirt — yon sirt va ikki doira: <b>S = 2πrh + 2πr² = 2πr(r + h)</b>. Teng tomonli silindr uchun (h = 2r): S = 6πr².', 'Полная поверхность — боковая плюс два круга: <b>S = 2πrh + 2πr² = 2πr(r + h)</b>. Для равностороннего цилиндра (h = 2r): S = 6πr².', 'Total surface = lateral surface plus two discs: <b>S = 2πrh + 2πr² = 2πr(r + h)</b>. For an equilateral cylinder (h = 2r): S = 6πr².')
    ] },
    { kind: 'rule', h: L('Silindr hajmi', 'Объём цилиндра', 'Volume of a cylinder'), p: [
      L('<b>Teorema.</b> Silindr hajmi asos yuzi bilan balandlik ko‘paytmasiga teng: <b>V = πr²h</b>.', '<b>Теорема.</b> Объём цилиндра равен произведению площади основания на высоту: <b>V = πr²h</b>.', '<b>Theorem.</b> The volume of a cylinder equals base area times height: <b>V = πr²h</b>.'),
      L('<b>Isbot g‘oyasi.</b> Silindrga ichki va tashqi muntazam n burchakli prizmalar chizamiz. Ularning hajmlari S<sub>n</sub>·h va S′<sub>n</sub>·h, bunda S<sub>n</sub> &lt; πr² &lt; S′<sub>n</sub>. n o‘sgan sari ko‘pburchaklar yuzi doira yuzi πr² ga intiladi, silindr hajmi esa doim ikki prizma hajmi orasida — demak V = πr²h. Boshqa yo‘l: Kavalyeri prinsipi. Asos yuzi πr², balandligi h bo‘lgan istalgan prizmani silindr yoniga qo‘ysak, har bir balandlikda kesimlar yuzi teng (πr²), demak hajmlar ham teng.', '<b>Идея доказательства.</b> Впишем в цилиндр и опишем около него правильные n-угольные призмы. Их объёмы S<sub>n</sub>·h и S′<sub>n</sub>·h, где S<sub>n</sub> &lt; πr² &lt; S′<sub>n</sub>. С ростом n площади многоугольников стремятся к площади круга πr², а объём цилиндра всегда заключён между объёмами призм — значит V = πr²h. Другой путь — принцип Кавальери: поставим рядом с цилиндром призму с площадью основания πr² и высотой h; на каждой высоте площади сечений равны (πr²), значит равны и объёмы.', '<b>Proof idea.</b> Inscribe and circumscribe regular n-gonal prisms. Their volumes are S<sub>n</sub>·h and S′<sub>n</sub>·h with S<sub>n</sub> &lt; πr² &lt; S′<sub>n</sub>. As n grows the polygon areas tend to the disc area πr², and the cylinder’s volume is always squeezed between the two prisms — so V = πr²h. Another route is Cavalieri’s principle: stand a prism with base area πr² and height h next to the cylinder; at every height the section areas are equal (πr²), so the volumes are equal.'),
      L('Ichi bo‘sh quvur (tashqi radius R, ichki r) devorining hajmi: V = π(R² − r²)h.', 'Объём стенки полой трубы (внешний радиус R, внутренний r): V = π(R² − r²)h.', 'The wall of a hollow pipe (outer radius R, inner r) has volume V = π(R² − r²)h.')
    ] },
    { kind: 'history', h: L('Arximedning qabri', 'Могила Архимеда', 'Archimedes’ tomb'), p: [
      L('Buyuk yunon olimi <b>Arximed</b> (miloddan avvalgi taxminan 287–212-yillar) «Shar va silindr haqida» asarida ajoyib natijani isbotladi: silindrga ichki chizilgan sharning hajmi silindr hajmining <b>2/3</b> qismiga teng, shar sirti ham silindr to‘la sirtining 2/3 qismi. Arximed bu kashfiyotini eng yuqori yutug‘i deb bilgan va qabr toshiga silindr ichidagi shar tasvirini o‘yib qo‘yishni vasiyat qilgan.', 'Великий греческий учёный <b>Архимед</b> (около 287–212 гг. до н. э.) в сочинении «О шаре и цилиндре» доказал замечательный результат: объём шара, вписанного в цилиндр, равен <b>2/3</b> объёма цилиндра, и поверхность шара тоже равна 2/3 полной поверхности цилиндра. Архимед считал это открытие своим высшим достижением и завещал высечь на надгробии шар, вписанный в цилиндр.', 'The great Greek scientist <b>Archimedes</b> (c. 287–212 BC) proved a wonderful result in <i>On the Sphere and Cylinder</i>: a ball inscribed in a cylinder has <b>2/3</b> of the cylinder’s volume, and the sphere’s surface is also 2/3 of the cylinder’s total surface. Archimedes considered this his greatest discovery and asked for a sphere inside a cylinder to be carved on his tombstone.'),
      L('Arximed Sirakuzani Rim qo‘shinlari egallaganda halok bo‘ldi. Taxminan 137 yil o‘tib, miloddan avvalgi 75-yilda Sitsiliyada xizmat qilgan Rim notig‘i <b>Sitseron</b> butalar orasidan shar va silindr tasvirlangan, yarim unutilgan qabrni topdi va uni tozalatdi. Silindr hajmini aniq hisoblash uchun π ning yaxshi qiymati kerak: Arximedning o‘zi 3 10/71 &lt; π &lt; 3 1/7 ekanini, xitoylik <b>Zu Chongji</b> esa V asrda π ≈ 355/113 (6 ta to‘g‘ri o‘nli xona) ekanini topgan.', 'Архимед погиб, когда Сиракузы взяли римские войска. Примерно через 137 лет, в 75 году до н. э., римский оратор <b>Цицерон</b>, служивший на Сицилии, нашёл среди кустов полузабытую могилу с изображением шара и цилиндра и велел её расчистить. Чтобы точно считать объём цилиндра, нужно хорошее значение π: сам Архимед доказал, что 3 10/71 &lt; π &lt; 3 1/7, а китаец <b>Цзу Чунчжи</b> в V веке нашёл π ≈ 355/113 (6 верных десятичных знаков).', 'Archimedes died when Roman troops took Syracuse. About 137 years later, in 75 BC, the Roman orator <b>Cicero</b>, then serving in Sicily, found the half-forgotten tomb with its sphere and cylinder among the bushes and had it cleared. Computing a cylinder’s volume accurately needs a good value of π: Archimedes himself proved 3 10/71 &lt; π &lt; 3 1/7, and in the 5th century the Chinese mathematician <b>Zu Chongzhi</b> found π ≈ 355/113 (six correct decimals).')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Решённые примеры', 'Worked examples'), ex: [
      { q: L('Silindr radiusi 3, balandligi 5. Yon sirti, to‘la sirti va hajmini toping.', 'Радиус цилиндра 3, высота 5. Найдите боковую, полную поверхность и объём.', 'A cylinder has radius 3 and height 5. Find its lateral surface, total surface and volume.'),
        s: L('S<sub>yon</sub> = 2π·3·5 = <b>30π ≈ 94,2</b>. S = 2π·3·(3 + 5) = <b>48π ≈ 150,8</b>. V = π·9·5 = <b>45π ≈ 141,4</b>.', 'S<sub>бок</sub> = 2π·3·5 = <b>30π ≈ 94,2</b>. S = 2π·3·(3 + 5) = <b>48π ≈ 150,8</b>. V = π·9·5 = <b>45π ≈ 141,4</b>.', 'S<sub>lat</sub> = 2π·3·5 = <b>30π ≈ 94.2</b>. S = 2π·3·(3 + 5) = <b>48π ≈ 150.8</b>. V = π·9·5 = <b>45π ≈ 141.4</b>.') },
      { q: L('Silindrning o‘q kesimi diagonali 8√2 bo‘lgan kvadrat. Silindr hajmi va to‘la sirtini toping.', 'Осевое сечение цилиндра — квадрат с диагональю 8√2. Найдите объём и полную поверхность цилиндра.', 'The axial section of a cylinder is a square with diagonal 8√2. Find the volume and total surface.'),
        s: L('Kvadrat tomoni 8√2/√2 = 8, demak 2r = 8, r = 4, h = 8. V = π·16·8 = <b>128π ≈ 402,1</b>. S = 2π·4·(4 + 8) = <b>96π ≈ 301,6</b>.', 'Сторона квадрата 8√2/√2 = 8, значит 2r = 8, r = 4, h = 8. V = π·16·8 = <b>128π ≈ 402,1</b>. S = 2π·4·(4 + 8) = <b>96π ≈ 301,6</b>.', 'The side of the square is 8√2/√2 = 8, so 2r = 8, r = 4, h = 8. V = π·16·8 = <b>128π ≈ 402.1</b>. S = 2π·4·(4 + 8) = <b>96π ≈ 301.6</b>.') },
      { q: L('Tomonlari 4 va 6 bo‘lgan to‘g‘ri to‘rtburchak avval 6 ga teng tomoni, keyin 4 ga teng tomoni atrofida aylantirildi. Hajmlarni taqqoslang.', 'Прямоугольник со сторонами 4 и 6 вращают сначала вокруг стороны 6, затем вокруг стороны 4. Сравните объёмы.', 'A 4 × 6 rectangle is rotated first about its side of length 6, then about its side of length 4. Compare the volumes.'),
        s: L('6 atrofida: r = 4, h = 6, V₁ = π·16·6 = 96π. 4 atrofida: r = 6, h = 4, V₂ = π·36·4 = 144π. V₂ : V₁ = 3 : 2 — radius kvadratda qatnashgani uchun u hajmga kuchliroq ta’sir qiladi.', 'Вокруг 6: r = 4, h = 6, V₁ = π·16·6 = 96π. Вокруг 4: r = 6, h = 4, V₂ = π·36·4 = 144π. V₂ : V₁ = 3 : 2 — радиус входит в квадрате, поэтому сильнее влияет на объём.', 'About 6: r = 4, h = 6, V₁ = π·16·6 = 96π. About 4: r = 6, h = 4, V₂ = π·36·4 = 144π. V₂ : V₁ = 3 : 2 — the radius is squared, so it affects the volume more.') },
      { q: L('Diametri 2 m, balandligi 3 m bo‘lgan silindrsimon suv baki necha litr suv sig‘diradi?', 'Сколько литров воды вмещает цилиндрический бак диаметром 2 м и высотой 3 м?', 'How many litres does a cylindrical tank 2 m in diameter and 3 m high hold?'),
        s: L('r = 1 m. V = π·1²·3 = 3π ≈ 9,42 m³ ≈ <b>9420 l</b>.', 'r = 1 м. V = π·1²·3 = 3π ≈ 9,42 м³ ≈ <b>9420 л</b>.', 'r = 1 m. V = π·1²·3 = 3π ≈ 9.42 m³ ≈ <b>9420 L</b>.') },
      { q: L('Po‘lat quvurning tashqi radiusi 5 sm, ichki radiusi 4 sm, uzunligi 1 m. Devor hajmini toping.', 'Внешний радиус стальной трубы 5 см, внутренний 4 см, длина 1 м. Найдите объём стенки.', 'A steel pipe has outer radius 5 cm, inner radius 4 cm and length 1 m. Find the volume of its wall.'),
        s: L('h = 100 sm. V = π(25 − 16)·100 = 900π ≈ <b>2827 sm³</b> (≈ 2,8 l). Po‘lat zichligi ≈ 7,8 g/sm³ bo‘lsa, quvur massasi ≈ 22 kg.', 'h = 100 см. V = π(25 − 16)·100 = 900π ≈ <b>2827 см³</b> (≈ 2,8 л). При плотности стали ≈ 7,8 г/см³ масса трубы ≈ 22 кг.', 'h = 100 cm. V = π(25 − 16)·100 = 900π ≈ <b>2827 cm³</b> (≈ 2.8 L). With steel density ≈ 7.8 g/cm³ the pipe weighs ≈ 22 kg.') }
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>Diametrni radius o‘rniga qo‘yish:</b> «diametri 2 m» bo‘lsa r = 1 m; aks holda hajm 4 marta katta chiqadi.', '<b>Подставляют диаметр вместо радиуса:</b> если «диаметр 2 м», то r = 1 м; иначе объём выйдет в 4 раза больше.', '<b>Using the diameter as the radius:</b> “diameter 2 m” means r = 1 m; otherwise the volume comes out 4 times too big.'),
      L('<b>Yon sirtga asoslarni qo‘shmaslik yoki ortiqcha qo‘shish:</b> yon sirt — 2πrh; to‘la sirt — 2πrh + 2πr². Ochiq idish (stakan) uchun faqat bitta asos qo‘shiladi.', '<b>Не добавляют или лишний раз добавляют основания:</b> боковая — 2πrh; полная — 2πrh + 2πr². Для открытого сосуда (стакана) добавляют одно основание.', '<b>Forgetting or overcounting the bases:</b> lateral is 2πrh; total is 2πrh + 2πr². An open container (a glass) has only one base.'),
      L('<b>πr² ni (πr)² deb hisoblash:</b> kvadratga faqat r oshiriladi.', '<b>Считают πr² как (πr)²:</b> в квадрат возводится только r.', '<b>Computing πr² as (πr)²:</b> only r is squared.'),
      L('<b>Aylanish o‘qini adashtirish:</b> to‘rtburchak qaysi tomon atrofida aylansa, o‘sha tomon — balandlik, ikkinchisi — radius.', '<b>Путают ось вращения:</b> сторона, вокруг которой вращают прямоугольник, — высота, другая — радиус.', '<b>Mixing up the axis:</b> the side the rectangle rotates about is the height; the other side is the radius.'),
      L('<b>Birliklar:</b> 1 m³ = 1000 l; sm³ dan l ga o‘tishda 1000 ga bo‘ling.', '<b>Единицы:</b> 1 м³ = 1000 л; при переходе от см³ к литрам делите на 1000.', '<b>Units:</b> 1 m³ = 1000 L; divide by 1000 when going from cm³ to litres.')
    ] },
    { kind: 'life', h: L('Nega bankalar silindr shaklida?', 'Почему банки цилиндрические?', 'Why are cans cylindrical?'), p: [
      L('Silindr ishlab chiqarishda juda qulay: yon sirti bitta to‘g‘ri to‘rtburchak listdan buklanadi, asoslari esa oddiy doiralar. Ichki bosimga ham yaxshi chidaydi — shuning uchun gaz ballonlari, bug‘ qozonlari va neft sisternalari silindr shaklida. Berilgan hajmda eng kam metall sarflaydigan silindr — <b>teng tomonli</b> (h = 2r): bu natija hosila yordamida isbotlanadi. Amalda ko‘p bankalar biroz balandroq yasaladi, chunki qo‘lda ushlash va javonga terish ham hisobga olinadi.', 'Цилиндр очень удобен в производстве: боковая поверхность сворачивается из одного прямоугольного листа, основания — простые круги. Он хорошо выдерживает внутреннее давление — поэтому газовые баллоны, паровые котлы и нефтяные цистерны цилиндрические. При заданном объёме меньше всего металла уходит на <b>равносторонний</b> цилиндр (h = 2r): это доказывается с помощью производной. На практике многие банки делают чуть выше, потому что учитывают удобство хвата и расстановки на полке.', 'A cylinder is very convenient to manufacture: its lateral surface rolls up from one rectangular sheet and its bases are plain discs. It withstands internal pressure well — which is why gas bottles, boilers and oil tanks are cylindrical. For a given volume the cylinder using the least metal is the <b>equilateral</b> one (h = 2r), a fact proved with derivatives. In practice many cans are made a little taller, since grip and shelf stacking also matter.'),
      L('Dvigatel «hajmi» (masalan, 1,5 litr) — barcha silindrlarda porshen yo‘li bo‘yicha hosil bo‘ladigan silindr hajmlari yig‘indisi: V = πr²·s·(silindrlar soni). Suv quvurlarining o‘tkazuvchanligi, quduqdagi suv zaxirasi, yog‘och g‘o‘lalarning kub metri ham πr²h formulasi bilan hisoblanadi.', '«Объём» двигателя (например, 1,5 литра) — сумма объёмов цилиндров, описываемых ходом поршня: V = πr²·s·(число цилиндров). Пропускная способность водопровода, запас воды в колодце, кубатура брёвен тоже вычисляются по формуле πr²h.', 'An engine’s “displacement” (say 1.5 litres) is the total of the cylinder volumes swept by the pistons: V = πr²·s·(number of cylinders). Water-pipe capacity, the water stored in a well and the cubic volume of logs are all computed with πr²h.')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверьте себя', 'Check yourself'), ex: [
      { q: L('Silindr hajmi 72π, balandligi 8. Radiusini va yon sirtini toping.', 'Объём цилиндра 72π, высота 8. Найдите радиус и боковую поверхность.', 'A cylinder has volume 72π and height 8. Find its radius and lateral surface.'),
        s: L('πr²·8 = 72π, r² = 9, r = 3. S<sub>yon</sub> = 2π·3·8 = 48π.', 'πr²·8 = 72π, r² = 9, r = 3. S<sub>бок</sub> = 2π·3·8 = 48π.', 'πr²·8 = 72π, r² = 9, r = 3. S<sub>lat</sub> = 2π·3·8 = 48π.') },
      { q: L('Silindr radiusi 2 marta oshirilib, balandligi 2 marta kamaytirildi. Hajmi qanday o‘zgaradi?', 'Радиус цилиндра увеличили в 2 раза, высоту уменьшили в 2 раза. Как изменится объём?', 'A cylinder’s radius is doubled and its height halved. How does the volume change?'),
        s: L('π(2r)²·(h/2) = 2πr²h — hajm 2 marta oshadi.', 'π(2r)²·(h/2) = 2πr²h — объём увеличится в 2 раза.', 'π(2r)²·(h/2) = 2πr²h — the volume doubles.') }
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Silindr — to‘g‘ri to‘rtburchakni tomoni atrofida aylantirishdan hosil bo‘lgan jism; asoslari teng doiralar, yasovchilar asosga perpendikulyar.', 'Цилиндр — тело вращения прямоугольника вокруг стороны; основания — равные круги, образующие перпендикулярны основаниям.', 'A cylinder is a rectangle rotated about a side; its bases are equal discs and its generators are perpendicular to them.'),
      L('O‘q kesim — tomonlari 2r va h bo‘lgan to‘g‘ri to‘rtburchak; asosga parallel kesim — doira.', 'Осевое сечение — прямоугольник со сторонами 2r и h; сечение, параллельное основанию, — круг.', 'The axial section is a 2r × h rectangle; a section parallel to the base is a disc.'),
      L('Yon sirt yoyilmasi — 2πr × h to‘g‘ri to‘rtburchak: S<sub>yon</sub> = 2πrh.', 'Развёртка боковой поверхности — прямоугольник 2πr × h: S<sub>бок</sub> = 2πrh.', 'The lateral net is a 2πr × h rectangle: S<sub>lat</sub> = 2πrh.'),
      L('To‘la sirt: S = 2πr(r + h).', 'Полная поверхность: S = 2πr(r + h).', 'Total surface: S = 2πr(r + h).'),
      L('Hajm: V = πr²h (prizmalar limiti yoki Kavalyeri prinsipi); quvur devori: π(R² − r²)h.', 'Объём: V = πr²h (предел призм или принцип Кавальери); стенка трубы: π(R² − r²)h.', 'Volume: V = πr²h (limit of prisms or Cavalieri’s principle); pipe wall: π(R² − r²)h.'),
      L('Arximed: silindrga ichki chizilgan shar hajmi va sirti silindrnikining 2/3 qismi.', 'Архимед: объём и поверхность вписанного в цилиндр шара составляют 2/3 от цилиндра.', 'Archimedes: a ball inscribed in a cylinder has 2/3 of its volume and surface.')
    ] }
  ] });
})(this);

// Nuvemath — 11-sinf, II qism (Geometriya 11) nazariyasi, t8–t14. Format: js/theory/GUIDE.md
(function (root) {
  'use strict';
  var L = root.NMCurriculum.H.L, T = root.NMTheory, P = '11-2';

  // ---------- t8. Piramida va kesik piramida ----------
  T.add(P, 't8', { sections: [
    { kind: 'intro', h: L('Eng qadimgi ko‘pyoq', 'Самый древний многогранник', 'The oldest polyhedron'), p: [
      L('To‘rt ming yildan ortiq vaqt davomida Gizadagi piramidalar sahrodan qad ko‘tarib turibdi. Ularni qurgan muhandislar hali «geometriya» degan so‘zni bilmagan, ammo har bir tosh blokning o‘rni, yon yoqlarning qiyaligi va asosning kvadratligi hayratlanarli aniqlikda hisoblangan. Bugun ham piramida shakli eng barqaror shakllardan biri hisoblanadi: og‘irlik markazi past, asosi keng, yuk pastga qarab taqsimlanadi.', 'Уже больше четырёх тысяч лет пирамиды Гизы возвышаются над пустыней. Строившие их инженеры ещё не знали слова «геометрия», но место каждого блока, наклон граней и квадратность основания рассчитаны с поразительной точностью. И сегодня пирамида считается одной из самых устойчивых форм: центр тяжести низко, основание широкое, нагрузка распределяется вниз.', 'For more than four thousand years the pyramids of Giza have risen above the desert. Their engineers did not yet know the word “geometry”, yet the place of every block, the slope of the faces and the squareness of the base were computed with amazing accuracy. Even today the pyramid is one of the most stable shapes: a low centre of mass, a wide base and loads spread downwards.'),
      L('10-sinfda biz prizmani o‘rgandik: uning yon yoqlari parallelogrammlar edi. Endi yon yoqlari bir nuqtada uchrashadigan uchburchaklar bo‘lgan jism — <b>piramida</b> bilan, so‘ng uning uchini kesib tashlashdan hosil bo‘ladigan <b>kesik piramida</b> bilan tanishamiz. Bu mavzuda asosiy savol: piramida sirtini qanday hisoblaymiz? Tom yopish uchun qancha tunuka kerak, chodir uchun qancha mato ketadi, shisha piramida uchun qancha oyna buyurtma qilish kerak — bularning barchasi yon sirt yuzi formulasiga borib taqaladi.', 'В 10 классе мы изучили призму: её боковые грани были параллелограммами. Теперь познакомимся с телом, боковые грани которого — треугольники с общей вершиной, — с <b>пирамидой</b>, а затем с <b>усечённой пирамидой</b>, которая получается, если отрезать её верхушку. Главный вопрос темы: как вычислить поверхность пирамиды? Сколько жести нужно на крышу, сколько ткани на шатёр, сколько стекла заказать для стеклянной пирамиды — всё это сводится к формуле площади боковой поверхности.', 'In grade 10 we studied the prism, whose lateral faces were parallelograms. Now we meet a solid whose lateral faces are triangles sharing one vertex — the <b>pyramid</b> — and then the <b>frustum</b>, obtained by cutting off its top. The main question of the topic: how do we compute the surface of a pyramid? How much metal is needed for a roof, how much fabric for a tent, how much glass for a glass pyramid — all of this comes down to the formula for the lateral area.'),
      L('Biz piramidaning elementlarini aniq ta’riflaymiz, muntazam piramida uchun yon sirt formulasini isbotlaymiz, piramida ichida yashiringan to‘g‘ri burchakli uchburchaklarni topishni o‘rganamiz va kesik piramidaga o‘tamiz.', 'Мы точно определим элементы пирамиды, докажем формулу боковой поверхности правильной пирамиды, научимся находить прямоугольные треугольники, спрятанные внутри пирамиды, и перейдём к усечённой пирамиде.', 'We will define the elements of a pyramid precisely, prove the lateral-area formula for a regular pyramid, learn to find the right triangles hidden inside a pyramid, and move on to the frustum.')
    ] },
    { kind: 'def', h: L('Piramida va uning elementlari', 'Пирамида и её элементы', 'The pyramid and its elements'), p: [
      L('Tekislikda A₁A₂…A<sub>n</sub> ko‘pburchak va bu tekislikda yotmaydigan S nuqta berilgan bo‘lsin. S nuqtani ko‘pburchakning barcha uchlari bilan tutashtiramiz. Hosil bo‘lgan n ta uchburchak SA₁A₂, SA₂A₃, …, SA<sub>n</sub>A₁ va ko‘pburchakning o‘zi bilan chegaralangan ko‘pyoq <b>piramida</b> deyiladi. Ko‘pburchak — piramidaning <b>asosi</b>, S — <b>uchi</b>, uchburchaklar — <b>yon yoqlari</b>, SA<sub>i</sub> kesmalar — <b>yon qirralari</b>.', 'Пусть в плоскости дан многоугольник A₁A₂…A<sub>n</sub> и точка S вне этой плоскости. Соединим S со всеми вершинами многоугольника. Многогранник, ограниченный n треугольниками SA₁A₂, SA₂A₃, …, SA<sub>n</sub>A₁ и самим многоугольником, называется <b>пирамидой</b>. Многоугольник — <b>основание</b>, S — <b>вершина</b>, треугольники — <b>боковые грани</b>, отрезки SA<sub>i</sub> — <b>боковые рёбра</b>.', 'Let a polygon A₁A₂…A<sub>n</sub> lie in a plane and let S be a point outside that plane. Join S to every vertex of the polygon. The polyhedron bounded by the n triangles SA₁A₂, SA₂A₃, …, SA<sub>n</sub>A₁ and the polygon itself is called a <b>pyramid</b>. The polygon is the <b>base</b>, S is the <b>apex</b>, the triangles are the <b>lateral faces</b> and the segments SA<sub>i</sub> are the <b>lateral edges</b>.'),
      L('Uchdan asos tekisligiga tushirilgan perpendikulyar SO — piramidaning <b>balandligi</b> h. Asosiga qarab piramida uchburchakli, to‘rtburchakli, …, n-burchakli bo‘ladi. n-burchakli piramidada n + 1 ta uch, 2n ta qirra va n + 1 ta yoq bor. Uchburchakli piramidani <b>tetraedr</b> ham deyishadi: uning har bir yog‘ini asos deb olish mumkin.', 'Перпендикуляр SO, опущенный из вершины на плоскость основания, — <b>высота</b> пирамиды h. По основанию пирамида бывает треугольной, четырёхугольной, …, n-угольной. У n-угольной пирамиды n + 1 вершина, 2n рёбер и n + 1 грань. Треугольную пирамиду называют также <b>тетраэдром</b>: любую её грань можно принять за основание.', 'The perpendicular SO dropped from the apex to the base plane is the <b>height</b> h. By its base a pyramid is triangular, quadrilateral, …, n-gonal. An n-gonal pyramid has n + 1 vertices, 2n edges and n + 1 faces. A triangular pyramid is also called a <b>tetrahedron</b>: any of its faces can serve as the base.'),
      L('Piramida <b>muntazam</b> deyiladi, agar uning asosi muntazam ko‘pburchak bo‘lsa va balandlik asosi shu ko‘pburchakning markaziga tushsa. Muntazam piramidada barcha yon qirralar teng, yon yoqlar esa o‘zaro teng teng yonli uchburchaklar. Yon yoqning uchidan tushirilgan balandligi <b>apofema</b> deyiladi va l bilan belgilanadi. Apofema faqat muntazam piramidada aniqlanadi — oddiy piramidada har bir yoqning balandligi har xil.', 'Пирамида называется <b>правильной</b>, если её основание — правильный многоугольник, а высота падает в его центр. В правильной пирамиде все боковые рёбра равны, а боковые грани — равные равнобедренные треугольники. Высота боковой грани, проведённая из вершины, называется <b>апофемой</b> и обозначается l. Апофема определена только для правильной пирамиды — в произвольной у каждой грани своя высота.', 'A pyramid is <b>regular</b> if its base is a regular polygon and the height lands at the centre of that polygon. In a regular pyramid all lateral edges are equal and the lateral faces are congruent isosceles triangles. The height of a lateral face drawn from the apex is called the <b>apothem</b> and denoted l. The apothem is defined only for a regular pyramid — in a general pyramid each face has its own height.')
    ] },
    { kind: 'def', h: L('Kesik piramida', 'Усечённая пирамида', 'The frustum'), p: [
      L('Piramidani asosiga parallel tekislik bilan kesaylik. Tekislik piramidani ikki bo‘lakka ajratadi: yuqorida berilgan piramidaga o‘xshash kichik piramida qoladi, pastda esa <b>kesik piramida</b> hosil bo‘ladi. Kesik piramidaning ikki asosi bor — <b>pastki</b> va <b>yuqori</b>; ular parallel tekisliklarda yotadi va o‘xshash ko‘pburchaklardir. Yon yoqlari — <b>trapetsiyalar</b>, chunki har bir yon yoqning yuqori va pastki tomonlari parallel.', 'Разрежем пирамиду плоскостью, параллельной основанию. Плоскость делит пирамиду на две части: сверху остаётся маленькая пирамида, подобная данной, снизу — <b>усечённая пирамида</b>. У усечённой пирамиды два основания — <b>нижнее</b> и <b>верхнее</b>; они лежат в параллельных плоскостях и являются подобными многоугольниками. Боковые грани — <b>трапеции</b>, так как верхняя и нижняя стороны каждой грани параллельны.', 'Cut a pyramid by a plane parallel to its base. The plane splits the pyramid into two parts: on top remains a small pyramid similar to the original, and below lies a <b>frustum</b>. A frustum has two bases — the <b>lower</b> and the <b>upper</b>; they lie in parallel planes and are similar polygons. The lateral faces are <b>trapezia</b>, since the top and bottom sides of each face are parallel.'),
      L('Asoslar tekisliklari orasidagi masofa — kesik piramidaning <b>balandligi</b> h. Muntazam piramidadan hosil bo‘lgan kesik piramida ham <b>muntazam</b> deyiladi: uning yon yoqlari teng teng yonli trapetsiyalar, ularning balandligi esa kesik piramidaning <b>apofemasi</b> l. Muhim kuzatish: kesuvchi tekislik uchdan qancha uzoqlikda bo‘lsa, kesim shuncha katta; agar u uchdan balandlikning k qismida yotsa, kesimdagi ko‘pburchak asosga k koeffitsiyent bilan o‘xshash, yuzi esa k²·S ga teng (S — asos yuzi).', 'Расстояние между плоскостями оснований — <b>высота</b> усечённой пирамиды h. Усечённая пирамида, полученная из правильной, тоже называется <b>правильной</b>: её боковые грани — равные равнобокие трапеции, а их высота — <b>апофема</b> усечённой пирамиды l. Важное наблюдение: чем дальше секущая плоскость от вершины, тем больше сечение; если она отстоит от вершины на долю k высоты, то сечение подобно основанию с коэффициентом k, а его площадь равна k²·S.', 'The distance between the base planes is the <b>height</b> h of the frustum. A frustum cut from a regular pyramid is also called <b>regular</b>: its lateral faces are congruent isosceles trapezia, and their height is the <b>apothem</b> l of the frustum. An important observation: the farther the cutting plane is from the apex, the larger the section; if it lies at the fraction k of the height from the apex, the section is similar to the base with ratio k and its area equals k²·S.')
    ] },
    { kind: 'history', h: L('Misr piramidalaridan Luvrgacha', 'От египетских пирамид до Лувра', 'From the Egyptian pyramids to the Louvre'), p: [
      L('Birinchi tosh piramida — fir’avn Josernning zinapoyali piramidasi — miloddan avvalgi XXVII asrda me’mor <b>Imxotep</b> tomonidan qurilgan. Taxminan yuz yildan so‘ng Xufu (Xeops) piramidasi barpo etildi: asos tomoni taxminan 230 m, dastlabki balandligi taxminan 146 m. Asosi kvadratining tomonlari bir-biridan bir necha santimetrgagina farq qiladi, tomonlari esa dunyo tomonlariga deyarli aniq yo‘naltirilgan. Yon yoqlarning asosga qiyaligi taxminan 51,8° — ya’ni apofema va asos tomonining yarmi nisbati taxminan 1,62 ga teng.', 'Первая каменная пирамида — ступенчатая пирамида фараона Джосера — построена в XXVII веке до н. э. зодчим <b>Имхотепом</b>. Примерно через сто лет возвели пирамиду Хуфу (Хеопса): сторона основания около 230 м, первоначальная высота около 146 м. Стороны квадрата основания отличаются друг от друга лишь на несколько сантиметров и почти точно ориентированы по сторонам света. Наклон граней к основанию около 51,8° — то есть отношение апофемы к половине стороны основания примерно 1,62.', 'The first stone pyramid — the step pyramid of pharaoh Djoser — was built in the 27th century BC by the architect <b>Imhotep</b>. About a century later the pyramid of Khufu (Cheops) was raised: a base side of about 230 m and an original height of about 146 m. The sides of its square base differ by only a few centimetres and point almost exactly to the cardinal directions. The faces slope at about 51.8° to the base, so the ratio of the apothem to half the base side is about 1.62.'),
      L('Misrliklar qiyalikni «seked» bilan o‘lchagan: balandlik bir tirsakka ko‘tarilganda gorizontal bo‘yicha necha kaft siljish kerakligi. Rind papirusida (mil. av. XVI asr) piramida sekedini topishga oid masalalar bor — bu aslida burchak kotangensining qadimiy shakli. Piramidalar Mesoamerikada ham qurilgan: Teotiuakandagi Quyosh piramidasi zinapoyali, kesik shaklga ega, ya’ni u aslida kesik piramidadir.', 'Египтяне измеряли наклон «секедом»: на сколько ладоней нужно сместиться по горизонтали при подъёме на один локоть. В папирусе Ринда (XVI в. до н. э.) есть задачи на нахождение секеда пирамиды — по сути древняя форма котангенса угла. Пирамиды строили и в Мезоамерике: пирамида Солнца в Теотиуакане ступенчатая, с плоской вершиной, то есть фактически это усечённая пирамида.', 'The Egyptians measured slope by the “seked”: how many palms one moves horizontally while rising one cubit. The Rhind Papyrus (16th century BC) contains problems on finding a pyramid’s seked — essentially an ancient form of the cotangent. Pyramids were also built in Mesoamerica: the Pyramid of the Sun at Teotihuacan is stepped with a flat top, so it is really a frustum.'),
      L('1989-yilda Parijdagi Luvr muzeyi hovlisida me’mor Yo Min Pey loyihasi bo‘yicha shisha piramida o‘rnatildi: balandligi 21,6 m, asos tomoni 35,4 m. Uning sirtini qoplash uchun yuzlab romb va uchburchak shaklidagi oynalar tayyorlangan — buyurtma aynan yon sirt yuzini hisoblashdan boshlangan.', 'В 1989 году во дворе Лувра в Париже установили стеклянную пирамиду по проекту архитектора Юй Мин Пэя: высота 21,6 м, сторона основания 35,4 м. Для её покрытия изготовили сотни ромбических и треугольных стёкол — заказ начинался именно с расчёта площади боковой поверхности.', 'In 1989 a glass pyramid designed by architect I. M. Pei was erected in the courtyard of the Louvre in Paris: height 21.6 m, base side 35.4 m. Hundreds of rhombic and triangular panes were made to cover it — and the order began precisely with computing the lateral area.')
    ] },
    { kind: 'rule', h: L('Muntazam piramidaning yon sirti', 'Боковая поверхность правильной пирамиды', 'Lateral area of a regular pyramid'), p: [
      L('<b>Teorema.</b> Muntazam piramidaning yon sirti yuzi asos perimetri bilan apofema ko‘paytmasining yarmiga teng: <b>S<sub>yon</sub> = ½ · P · l</b>.', '<b>Теорема.</b> Площадь боковой поверхности правильной пирамиды равна половине произведения периметра основания на апофему: <b>S<sub>бок</sub> = ½ · P · l</b>.', '<b>Theorem.</b> The lateral area of a regular pyramid equals half the product of the base perimeter and the apothem: <b>S<sub>lat</sub> = ½ · P · l</b>.'),
      L('<b>Isbot.</b> Asos — tomoni a bo‘lgan muntazam n-burchak. Har bir yon yoq — asosi a, balandligi l bo‘lgan uchburchak, uning yuzi ½·a·l. Yon yoqlar n ta va ular teng, demak S<sub>yon</sub> = n·½·a·l = ½·(n·a)·l = ½·P·l, chunki n·a = P. ∎ Bu formula «yoyilma» g‘oyasiga asoslangan: piramidaning yon sirtini qirralari bo‘yicha qirqib tekislikka yoysak, umumiy uchli n ta teng uchburchakdan iborat yelpig‘ich hosil bo‘ladi.', '<b>Доказательство.</b> Основание — правильный n-угольник со стороной a. Каждая боковая грань — треугольник с основанием a и высотой l, его площадь ½·a·l. Граней n, и они равны, значит S<sub>бок</sub> = n·½·a·l = ½·(n·a)·l = ½·P·l, так как n·a = P. ∎ Формула опирается на идею развёртки: разрезав боковую поверхность по рёбрам и развернув на плоскость, получим «веер» из n равных треугольников с общей вершиной.', '<b>Proof.</b> The base is a regular n-gon of side a. Each lateral face is a triangle with base a and height l, so its area is ½·a·l. There are n equal faces, hence S<sub>lat</sub> = n·½·a·l = ½·(n·a)·l = ½·P·l, because n·a = P. ∎ The formula rests on the idea of a net: cut the lateral surface along the edges and unfold it onto a plane, and you get a “fan” of n equal triangles sharing a vertex.'),
      L('<b>To‘la sirt</b> yon sirt va asos yuzining yig‘indisi: S<sub>to‘la</sub> = S<sub>yon</sub> + S<sub>asos</sub>. Ixtiyoriy (muntazam bo‘lmagan) piramida uchun umumiy formula yo‘q — har bir yon yoqning yuzini alohida hisoblab qo‘shamiz.', '<b>Полная поверхность</b> — сумма боковой поверхности и площади основания: S<sub>полн</sub> = S<sub>бок</sub> + S<sub>осн</sub>. Для произвольной (неправильной) пирамиды общей формулы нет — площади граней считают по отдельности и складывают.', 'The <b>total surface</b> is the lateral area plus the base area: S<sub>tot</sub> = S<sub>lat</sub> + S<sub>base</sub>. For an arbitrary (non-regular) pyramid there is no single formula — compute each face separately and add.'),
      L('<b>Teorema (proyeksiya orqali).</b> Agar piramidaning barcha yon yoqlari asos tekisligiga bir xil φ burchak ostida og‘ma bo‘lsa, S<sub>yon</sub> = S<sub>asos</sub> / cos φ. Sababi: har bir yon yoqning asosga ortogonal proyeksiyasi asosning bir bo‘lagi va S<sub>pr</sub> = S·cos φ; proyeksiyalar yig‘indisi butun asosni beradi.', '<b>Теорема (через проекцию).</b> Если все боковые грани пирамиды наклонены к основанию под одним углом φ, то S<sub>бок</sub> = S<sub>осн</sub> / cos φ. Причина: ортогональная проекция каждой грани на основание — часть основания, и S<sub>пр</sub> = S·cos φ; проекции вместе дают всё основание.', '<b>Theorem (via projection).</b> If all lateral faces are inclined to the base at the same angle φ, then S<sub>lat</sub> = S<sub>base</sub> / cos φ. Reason: the orthogonal projection of each face onto the base is a piece of the base and S<sub>pr</sub> = S·cos φ; together the projections fill the whole base.')
    ] },
    { kind: 'rule', h: L('Piramida ichidagi to‘g‘ri burchakli uchburchaklar', 'Прямоугольные треугольники внутри пирамиды', 'Right triangles inside a pyramid'), p: [
      L('Muntazam piramidaga oid deyarli har bir masala bir nechta to‘g‘ri burchakli uchburchakka keltiriladi. Belgilaymiz: h — balandlik, l — apofema, b — yon qirra, a — asos tomoni, r — asosga ichki chizilgan aylana radiusi (markazdan tomongacha masofa), R — tashqi chizilgan aylana radiusi (markazdan uchgacha masofa).', 'Почти любая задача о правильной пирамиде сводится к нескольким прямоугольным треугольникам. Обозначим: h — высота, l — апофема, b — боковое ребро, a — сторона основания, r — радиус вписанной в основание окружности (расстояние от центра до стороны), R — радиус описанной окружности (расстояние от центра до вершины).', 'Almost every problem on a regular pyramid reduces to a few right triangles. Notation: h is the height, l the apothem, b the lateral edge, a the base side, r the inradius of the base (centre to side), R the circumradius of the base (centre to vertex).'),
      L('1) Balandlik, r va apofema: <b>l² = h² + r²</b>; bu uchburchakdagi r ga qarshi burchak emas, balki l va r orasidagi burchak — yon yoq bilan asos orasidagi ikki yoqli burchak φ: cos φ = r / l. 2) Balandlik, R va yon qirra: <b>b² = h² + R²</b>; b va R orasidagi burchak — yon qirraning asosga og‘ish burchagi. 3) Yon yoqning yarmi: <b>b² = l² + (a/2)²</b>.', '1) Высота, r и апофема: <b>l² = h² + r²</b>; угол между l и r — двугранный угол φ между боковой гранью и основанием: cos φ = r / l. 2) Высота, R и боковое ребро: <b>b² = h² + R²</b>; угол между b и R — угол наклона бокового ребра к основанию. 3) Половина боковой грани: <b>b² = l² + (a/2)²</b>.', '1) Height, r and apothem: <b>l² = h² + r²</b>; the angle between l and r is the dihedral angle φ between a lateral face and the base: cos φ = r / l. 2) Height, R and lateral edge: <b>b² = h² + R²</b>; the angle between b and R is the inclination of the lateral edge to the base. 3) Half of a lateral face: <b>b² = l² + (a/2)²</b>.'),
      L('Muhim asoslar uchun r va R: kvadrat — r = a/2, R = a√2/2; muntazam uchburchak — r = a√3/6, R = a√3/3; muntazam oltiburchak — r = a√3/2, R = a. Bu qiymatlarni yod bilish masala yechishni ancha tezlashtiradi.', 'Значения r и R для важных оснований: квадрат — r = a/2, R = a√2/2; правильный треугольник — r = a√3/6, R = a√3/3; правильный шестиугольник — r = a√3/2, R = a. Знание этих значений сильно ускоряет решение.', 'Values of r and R for important bases: square — r = a/2, R = a√2/2; equilateral triangle — r = a√3/6, R = a√3/3; regular hexagon — r = a√3/2, R = a. Knowing these by heart speeds up problem solving a lot.')
    ] },
    { kind: 'rule', h: L('Kesik piramidaning yon sirti', 'Боковая поверхность усечённой пирамиды', 'Lateral area of a frustum'), p: [
      L('<b>Teorema.</b> Muntazam kesik piramidaning yon sirti asoslar perimetrlari yig‘indisining yarmi bilan apofema ko‘paytmasiga teng: <b>S<sub>yon</sub> = ½ · (P₁ + P₂) · l</b>.', '<b>Теорема.</b> Площадь боковой поверхности правильной усечённой пирамиды равна произведению полусуммы периметров оснований на апофему: <b>S<sub>бок</sub> = ½ · (P₁ + P₂) · l</b>.', '<b>Theorem.</b> The lateral area of a regular frustum equals half the sum of the base perimeters times the apothem: <b>S<sub>lat</sub> = ½ · (P₁ + P₂) · l</b>.'),
      L('<b>Isbot.</b> Har bir yon yoq — asoslari a₁ va a₂, balandligi l bo‘lgan teng yonli trapetsiya; uning yuzi ½(a₁ + a₂)·l. n ta yoqni qo‘shsak: S<sub>yon</sub> = n·½(a₁ + a₂)·l = ½(na₁ + na₂)·l = ½(P₁ + P₂)·l. ∎ Agar yuqori asos nuqtaga aylansa (P₂ = 0), oddiy piramida formulasi kelib chiqadi — bu formulaning to‘g‘riligini tekshirishning yaxshi usuli.', '<b>Доказательство.</b> Каждая боковая грань — равнобокая трапеция с основаниями a₁ и a₂ и высотой l; её площадь ½(a₁ + a₂)·l. Сложив n граней: S<sub>бок</sub> = n·½(a₁ + a₂)·l = ½(na₁ + na₂)·l = ½(P₁ + P₂)·l. ∎ Если верхнее основание стягивается в точку (P₂ = 0), получаем формулу обычной пирамиды — хороший способ проверить формулу.', '<b>Proof.</b> Each lateral face is an isosceles trapezium with bases a₁, a₂ and height l; its area is ½(a₁ + a₂)·l. Adding the n faces: S<sub>lat</sub> = n·½(a₁ + a₂)·l = ½(na₁ + na₂)·l = ½(P₁ + P₂)·l. ∎ If the upper base shrinks to a point (P₂ = 0), we recover the pyramid formula — a good way to check it.'),
      L('Kesik piramidada asosiy to‘g‘ri burchakli trapetsiya: asoslar markazlarini tutashtiruvchi balandlik h va apofema l. Undan <b>l² = h² + (r₁ − r₂)²</b> kelib chiqadi, bu yerda r₁, r₂ — asoslarga ichki chizilgan aylanalar radiuslari. Xuddi shunday yon qirra uchun b² = h² + (R₁ − R₂)².', 'Главная прямоугольная трапеция усечённой пирамиды образована высотой h, соединяющей центры оснований, и апофемой l. Из неё <b>l² = h² + (r₁ − r₂)²</b>, где r₁, r₂ — радиусы окружностей, вписанных в основания. Аналогично для бокового ребра b² = h² + (R₁ − R₂)².', 'The key right trapezium of a frustum is formed by the height h joining the centres of the bases and the apothem l. From it, <b>l² = h² + (r₁ − r₂)²</b>, where r₁, r₂ are the inradii of the bases. Likewise for a lateral edge, b² = h² + (R₁ − R₂)².')
    ] },
    { kind: 'steps', h: L('Sirtni hisoblash algoritmi', 'Алгоритм вычисления поверхности', 'Algorithm for the surface area'), list: [
      L('Chizma chizing: asos, balandlik va kamida bitta apofemani belgilang.', 'Сделайте чертёж: отметьте основание, высоту и хотя бы одну апофему.', 'Draw a figure: mark the base, the height and at least one apothem.'),
      L('Asos turini aniqlang va r, R ni a orqali ifodalang (kvadrat, uchburchak, oltiburchak).', 'Определите вид основания и выразите r, R через a (квадрат, треугольник, шестиугольник).', 'Identify the base and express r, R through a (square, triangle, hexagon).'),
      L('Kerakli to‘g‘ri burchakli uchburchakni tanlang: h–r–l, h–R–b yoki l–a/2–b.', 'Выберите нужный прямоугольный треугольник: h–r–l, h–R–b или l–a/2–b.', 'Choose the needed right triangle: h–r–l, h–R–b or l–a/2–b.'),
      L('Pifagor teoremasi yoki trigonometriya yordamida apofema l ni toping.', 'С помощью теоремы Пифагора или тригонометрии найдите апофему l.', 'Find the apothem l by Pythagoras or trigonometry.'),
      L('S<sub>yon</sub> = ½·P·l (kesik piramidada ½(P₁ + P₂)·l) ni hisoblang.', 'Вычислите S<sub>бок</sub> = ½·P·l (для усечённой ½(P₁ + P₂)·l).', 'Compute S<sub>lat</sub> = ½·P·l (for a frustum ½(P₁ + P₂)·l).'),
      L('To‘la sirt so‘ralgan bo‘lsa, asos(lar) yuzini qo‘shing va birliklarni (kvadrat birlik) yozing.', 'Если нужна полная поверхность, прибавьте площадь основания (оснований) и запишите единицы (квадратные).', 'If the total surface is asked, add the base area(s) and write square units.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Решённые примеры', 'Worked examples'), ex: [
      { q: L('Muntazam to‘rtburchakli piramidaning asos tomoni 6 sm, balandligi 4 sm. Yon va to‘la sirtni toping.', 'Сторона основания правильной четырёхугольной пирамиды 6 см, высота 4 см. Найдите боковую и полную поверхность.', 'A regular square pyramid has base side 6 cm and height 4 cm. Find its lateral and total surface areas.'),
        s: L('Asos — kvadrat, r = 6/2 = 3. Apofema: l = √(h² + r²) = √(16 + 9) = 5 sm. P = 4·6 = 24. S<sub>yon</sub> = ½·24·5 = 60 sm². S<sub>asos</sub> = 36, demak S<sub>to‘la</sub> = 60 + 36 = 96 sm².', 'Основание — квадрат, r = 6/2 = 3. Апофема: l = √(h² + r²) = √(16 + 9) = 5 см. P = 4·6 = 24. S<sub>бок</sub> = ½·24·5 = 60 см². S<sub>осн</sub> = 36, значит S<sub>полн</sub> = 60 + 36 = 96 см².', 'The base is a square, r = 6/2 = 3. Apothem: l = √(h² + r²) = √(16 + 9) = 5 cm. P = 4·6 = 24. S<sub>lat</sub> = ½·24·5 = 60 cm². S<sub>base</sub> = 36, so S<sub>tot</sub> = 60 + 36 = 96 cm².') },
      { q: L('Muntazam uchburchakli piramidaning asos tomoni 6, yon qirrasi 5. To‘la sirtni toping.', 'В правильной треугольной пирамиде сторона основания 6, боковое ребро 5. Найдите полную поверхность.', 'A regular triangular pyramid has base side 6 and lateral edge 5. Find its total surface area.'),
        s: L('Yon yoq — tomonlari 5, 5, 6 bo‘lgan teng yonli uchburchak. Apofema uni teng ikkiga bo‘ladi: l = √(5² − 3²) = 4. S<sub>yon</sub> = ½·18·4 = 36. Asos yuzi: (√3/4)·36 = 9√3. S<sub>to‘la</sub> = 36 + 9√3 ≈ 51,6.', 'Боковая грань — равнобедренный треугольник со сторонами 5, 5, 6. Апофема делит его пополам: l = √(5² − 3²) = 4. S<sub>бок</sub> = ½·18·4 = 36. Площадь основания: (√3/4)·36 = 9√3. S<sub>полн</sub> = 36 + 9√3 ≈ 51,6.', 'A lateral face is an isosceles triangle with sides 5, 5, 6. The apothem bisects it: l = √(5² − 3²) = 4. S<sub>lat</sub> = ½·18·4 = 36. Base area: (√3/4)·36 = 9√3. S<sub>tot</sub> = 36 + 9√3 ≈ 51.6.') },
      { q: L('Muntazam oltiburchakli piramidaning asos tomoni 4, balandligi 2. Yon sirtni toping.', 'В правильной шестиугольной пирамиде сторона основания 4, высота 2. Найдите боковую поверхность.', 'A regular hexagonal pyramid has base side 4 and height 2. Find its lateral area.'),
        s: L('Oltiburchak uchun r = a√3/2 = 2√3, r² = 12. l = √(4 + 12) = 4. P = 6·4 = 24. S<sub>yon</sub> = ½·24·4 = 48. (Asos yuzi 6·(√3/4)·16 = 24√3 — to‘la sirt kerak bo‘lsa qo‘shiladi.)', 'Для шестиугольника r = a√3/2 = 2√3, r² = 12. l = √(4 + 12) = 4. P = 6·4 = 24. S<sub>бок</sub> = ½·24·4 = 48. (Площадь основания 6·(√3/4)·16 = 24√3 — прибавляется, если нужна полная поверхность.)', 'For a hexagon r = a√3/2 = 2√3, r² = 12. l = √(4 + 12) = 4. P = 6·4 = 24. S<sub>lat</sub> = ½·24·4 = 48. (The base area 6·(√3/4)·16 = 24√3 is added if the total surface is needed.)') },
      { q: L('Muntazam to‘rtburchakli piramidada yon yoq asosga 60° burchak ostida og‘ma, asos tomoni 8. Yon sirtni ikki usulda toping.', 'В правильной четырёхугольной пирамиде боковая грань наклонена к основанию под углом 60°, сторона основания 8. Найдите боковую поверхность двумя способами.', 'In a regular square pyramid a lateral face makes 60° with the base and the base side is 8. Find the lateral area in two ways.'),
        s: L('1-usul: r = 4, cos 60° = r/l ⇒ l = 4 : ½ = 8; S<sub>yon</sub> = ½·32·8 = 128. 2-usul: S<sub>yon</sub> = S<sub>asos</sub>/cos φ = 64 : ½ = 128. Natijalar bir xil.', 'Способ 1: r = 4, cos 60° = r/l ⇒ l = 4 : ½ = 8; S<sub>бок</sub> = ½·32·8 = 128. Способ 2: S<sub>бок</sub> = S<sub>осн</sub>/cos φ = 64 : ½ = 128. Результаты совпадают.', 'Method 1: r = 4, cos 60° = r/l ⇒ l = 4 : ½ = 8; S<sub>lat</sub> = ½·32·8 = 128. Method 2: S<sub>lat</sub> = S<sub>base</sub>/cos φ = 64 : ½ = 128. The results agree.') },
      { q: L('Muntazam to‘rtburchakli kesik piramidaning asos tomonlari 8 va 2, balandligi 4. To‘la sirtni toping.', 'Стороны оснований правильной четырёхугольной усечённой пирамиды 8 и 2, высота 4. Найдите полную поверхность.', 'A regular square frustum has base sides 8 and 2 and height 4. Find its total surface area.'),
        s: L('r₁ = 4, r₂ = 1, r₁ − r₂ = 3. l = √(4² + 3²) = 5. P₁ = 32, P₂ = 8. S<sub>yon</sub> = ½·(32 + 8)·5 = 100. Asoslar: 64 + 4 = 68. S<sub>to‘la</sub> = 100 + 68 = 168.', 'r₁ = 4, r₂ = 1, r₁ − r₂ = 3. l = √(4² + 3²) = 5. P₁ = 32, P₂ = 8. S<sub>бок</sub> = ½·(32 + 8)·5 = 100. Основания: 64 + 4 = 68. S<sub>полн</sub> = 100 + 68 = 168.', 'r₁ = 4, r₂ = 1, r₁ − r₂ = 3. l = √(4² + 3²) = 5. P₁ = 32, P₂ = 8. S<sub>lat</sub> = ½·(32 + 8)·5 = 100. Bases: 64 + 4 = 68. S<sub>tot</sub> = 100 + 68 = 168.') }
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>Apofemani balandlik bilan chalkashtirish.</b> h — piramida ichida, asosga perpendikulyar; l — yon yoq tekisligida yotadi va har doim h dan katta (l² = h² + r²).', '<b>Путают апофему с высотой.</b> h — внутри пирамиды, перпендикулярна основанию; l — лежит в плоскости боковой грани и всегда больше h (l² = h² + r²).', '<b>Confusing the apothem with the height.</b> h is inside the pyramid, perpendicular to the base; l lies in a lateral face and is always longer than h (l² = h² + r²).'),
      L('<b>Apofemani yon qirra bilan chalkashtirish.</b> Yon qirra yon yoqning tomoni, apofema esa uning balandligi: b² = l² + (a/2)².', '<b>Путают апофему с боковым ребром.</b> Ребро — сторона боковой грани, апофема — её высота: b² = l² + (a/2)².', '<b>Confusing the apothem with a lateral edge.</b> The edge is a side of the face, the apothem is its height: b² = l² + (a/2)².'),
      L('<b>r va R ni almashtirish.</b> Apofema topishda markazdan <i>tomongacha</i> (r), yon qirra uchun markazdan <i>uchgacha</i> (R) masofa olinadi.', '<b>Путают r и R.</b> Для апофемы берут расстояние от центра <i>до стороны</i> (r), для бокового ребра — <i>до вершины</i> (R).', '<b>Swapping r and R.</b> For the apothem use the distance from the centre <i>to a side</i> (r); for a lateral edge, <i>to a vertex</i> (R).'),
      L('<b>To‘la sirtda asosni unutish</b> yoki kesik piramidada faqat bitta asosni qo‘shish.', '<b>Забывают основание в полной поверхности</b> или прибавляют только одно основание у усечённой пирамиды.', '<b>Forgetting the base in the total surface</b>, or adding only one base of a frustum.'),
      L('<b>½·P·l ni muntazam bo‘lmagan piramidaga qo‘llash.</b> Yon yoqlar turlicha bo‘lsa, ularning yuzlari alohida hisoblanadi.', '<b>Применяют ½·P·l к неправильной пирамиде.</b> Если грани разные, их площади считают по отдельности.', '<b>Using ½·P·l for a non-regular pyramid.</b> If the faces differ, compute their areas one by one.')
    ] },
    { kind: 'life', h: L('Hayotda piramida sirti', 'Поверхность пирамиды в жизни', 'Pyramid surfaces in real life'), p: [
      L('<b>Tomlar.</b> To‘rt nishabli «chodir» tom aslida muntazam to‘rtburchakli piramida. Usta tom tunukasi yoki cherepitsa miqdorini aynan ½·P·l formulasi bo‘yicha hisoblaydi va chiqindi uchun 10–15% qo‘shadi. Agar uyning tomoni 10 m, tom balandligi 3 m bo‘lsa, l = √(9 + 25) ≈ 5,83 m va yon sirt ≈ ½·40·5,83 ≈ 117 m².', '<b>Крыши.</b> Четырёхскатная «шатровая» крыша — это правильная четырёхугольная пирамида. Мастер считает количество жести или черепицы именно по формуле ½·P·l и добавляет 10–15% на отходы. Если сторона дома 10 м, а высота крыши 3 м, то l = √(9 + 25) ≈ 5,83 м и боковая поверхность ≈ ½·40·5,83 ≈ 117 м².', '<b>Roofs.</b> A four-sided “tent” roof is a regular square pyramid. A roofer orders metal sheets or tiles exactly by ½·P·l and adds 10–15% for waste. If the house side is 10 m and the roof height 3 m, then l = √(9 + 25) ≈ 5.83 m and the lateral area ≈ ½·40·5.83 ≈ 117 m².'),
      L('<b>Chodirlar va o‘tovlar.</b> Sayyohlik chodirlari ko‘pincha piramida shaklida tikiladi: matoning bichimi — yon sirt yoyilmasi. <b>Qadoqlash:</b> tetraedr shaklidagi sut paketlari (Tetra Pak, 1952) bir varaq kartondan minimal chiqindi bilan yasalgan. <b>Me’morchilik:</b> Luvr piramidasi, Las-Vegasdagi «Luxor» mehmonxonasi, ko‘plab masjid va maqbaralarning gumbaz ostidagi qirrali qismlari. <b>Akustika:</b> studiyalardagi ko‘pikli panellar mayda piramidalardan iborat — ular tovushni turli yo‘nalishlarga sochib yuboradi.', '<b>Палатки и шатры.</b> Туристические палатки часто шьют в форме пирамиды: выкройка ткани — развёртка боковой поверхности. <b>Упаковка:</b> молочные пакеты-тетраэдры (Tetra Pak, 1952) складывались из одного листа картона с минимумом отходов. <b>Архитектура:</b> пирамида Лувра, отель «Luxor» в Лас-Вегасе, гранёные части под куполами многих мечетей и мавзолеев. <b>Акустика:</b> поролоновые панели студий состоят из мелких пирамид — они рассеивают звук в разные стороны.', '<b>Tents.</b> Camping tents are often sewn as pyramids: the fabric pattern is the net of the lateral surface. <b>Packaging:</b> tetrahedral milk cartons (Tetra Pak, 1952) were folded from one sheet of card with minimal waste. <b>Architecture:</b> the Louvre pyramid, the Luxor hotel in Las Vegas, the faceted parts beneath the domes of many mosques and mausoleums. <b>Acoustics:</b> studio foam panels consist of tiny pyramids that scatter sound in different directions.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Interesting facts'), list: [
      L('Xufu piramidasi taxminan 3800 yil davomida dunyodagi eng baland inshoot bo‘lib qolgan — uni faqat XIV asrda Linkoln soborining shpili ortda qoldirgan.', 'Пирамида Хуфу около 3800 лет оставалась самым высоким сооружением мира — её превзошёл лишь шпиль Линкольнского собора в XIV веке.', 'The pyramid of Khufu remained the tallest structure in the world for about 3,800 years — only the spire of Lincoln Cathedral surpassed it in the 14th century.'),
      L('Piramida yon sirti dastlab silliq oq ohaktosh bilan qoplangan va quyoshda yaltirab turgan; yon sirt yuzi taxminan 85 000 m² — o‘ndan ortiq futbol maydoni.', 'Боковая поверхность пирамиды была облицована гладким белым известняком и сверкала на солнце; её площадь около 85 000 м² — больше десяти футбольных полей.', 'The pyramid’s lateral surface was once faced with smooth white limestone that shone in the sun; its area is about 85,000 m² — more than ten football pitches.'),
      L('Barcha qirralari teng bo‘lgan muntazam to‘rtburchakli piramidaning yon yoqlari teng tomonli uchburchaklar; ikkitasini asoslari bo‘yicha yopishtirsak, oktaedr hosil bo‘ladi.', 'У правильной четырёхугольной пирамиды со всеми равными рёбрами боковые грани — равносторонние треугольники; склеив две такие пирамиды основаниями, получим октаэдр.', 'A regular square pyramid with all edges equal has equilateral lateral faces; gluing two of them base to base gives an octahedron.'),
      L('Piramida uchun Eyler formulasi: (n + 1) − 2n + (n + 1) = 2 — har qanday n uchun bajariladi.', 'Формула Эйлера для пирамиды: (n + 1) − 2n + (n + 1) = 2 — верна при любом n.', 'Euler’s formula for a pyramid: (n + 1) − 2n + (n + 1) = 2 — true for every n.')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверьте себя', 'Test yourself'), p: [
      L('Javoblarni avval o‘zingiz toping, so‘ng pastdagi yechim bilan solishtiring.', 'Сначала найдите ответы сами, затем сравните с решением ниже.', 'Find the answers yourself first, then compare with the solutions below.')
    ], ex: [
      { q: L('Muntazam to‘rtburchakli piramidaning barcha qirralari 4 ga teng. To‘la sirtini toping.', 'Все рёбра правильной четырёхугольной пирамиды равны 4. Найдите полную поверхность.', 'All edges of a regular square pyramid equal 4. Find its total surface area.'),
        s: L('Yon yoqlar — tomoni 4 bo‘lgan teng tomonli uchburchaklar: har biri (√3/4)·16 = 4√3. S<sub>yon</sub> = 16√3, asos 16. S<sub>to‘la</sub> = 16 + 16√3 ≈ 43,7.', 'Боковые грани — равносторонние треугольники со стороной 4: каждая (√3/4)·16 = 4√3. S<sub>бок</sub> = 16√3, основание 16. S<sub>полн</sub> = 16 + 16√3 ≈ 43,7.', 'The lateral faces are equilateral triangles of side 4, each (√3/4)·16 = 4√3. S<sub>lat</sub> = 16√3, base 16. S<sub>tot</sub> = 16 + 16√3 ≈ 43.7.') },
      { q: L('Muntazam piramidaning yon sirti 60, asos perimetri 24. Apofemasi qancha?', 'Боковая поверхность правильной пирамиды 60, периметр основания 24. Чему равна апофема?', 'A regular pyramid has lateral area 60 and base perimeter 24. What is the apothem?'),
        s: L('60 = ½·24·l ⇒ l = 60 : 12 = 5.', '60 = ½·24·l ⇒ l = 60 : 12 = 5.', '60 = ½·24·l ⇒ l = 60 : 12 = 5.') }
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Piramida — asosi ko‘pburchak, yon yoqlari umumiy uchli uchburchaklar bo‘lgan ko‘pyoq; muntazam piramidada balandlik asos markaziga tushadi.', 'Пирамида — многогранник с многоугольником в основании и треугольными гранями с общей вершиной; в правильной пирамиде высота падает в центр основания.', 'A pyramid has a polygon base and triangular faces meeting at an apex; in a regular pyramid the height lands at the centre of the base.'),
      L('Apofema — muntazam piramida yon yog‘ining balandligi.', 'Апофема — высота боковой грани правильной пирамиды.', 'The apothem is the height of a lateral face of a regular pyramid.'),
      L('S<sub>yon</sub> = ½·P·l; S<sub>to‘la</sub> = S<sub>yon</sub> + S<sub>asos</sub>; teng og‘ma yoqlarda S<sub>yon</sub> = S<sub>asos</sub>/cos φ.', 'S<sub>бок</sub> = ½·P·l; S<sub>полн</sub> = S<sub>бок</sub> + S<sub>осн</sub>; при равнонаклонённых гранях S<sub>бок</sub> = S<sub>осн</sub>/cos φ.', 'S<sub>lat</sub> = ½·P·l; S<sub>tot</sub> = S<sub>lat</sub> + S<sub>base</sub>; with equally inclined faces S<sub>lat</sub> = S<sub>base</sub>/cos φ.'),
      L('Asosiy uchburchaklar: l² = h² + r², b² = h² + R², b² = l² + (a/2)².', 'Главные треугольники: l² = h² + r², b² = h² + R², b² = l² + (a/2)².', 'Key triangles: l² = h² + r², b² = h² + R², b² = l² + (a/2)².'),
      L('Kesik piramida: yon yoqlari trapetsiyalar, S<sub>yon</sub> = ½(P₁ + P₂)·l, l² = h² + (r₁ − r₂)².', 'Усечённая пирамида: грани — трапеции, S<sub>бок</sub> = ½(P₁ + P₂)·l, l² = h² + (r₁ − r₂)².', 'Frustum: the faces are trapezia, S<sub>lat</sub> = ½(P₁ + P₂)·l, l² = h² + (r₁ − r₂)².'),
      L('Misr piramidalari 4500 yil oldin qurilgan bo‘lsa-da, bu formulalar bugun ham tom, chodir va qadoqlash hisob-kitoblarida ishlatiladi.', 'Пирамиды Египта построены 4500 лет назад, но эти формулы и сегодня используются при расчёте крыш, палаток и упаковки.', 'The Egyptian pyramids were built 4,500 years ago, yet these formulas are still used today for roofs, tents and packaging.')
    ] }
  ] });

  // ---------- t9. Piramidaning hajmi ----------
  T.add(P, 't9', { sections: [
    { kind: 'intro', h: L('Nega aynan uchdan bir?', 'Почему именно треть?', 'Why exactly one third?'), p: [
      L('Shaffof idishda prizma va xuddi shunday asos va balandlikka ega piramida bor, deb tasavvur qiling. Piramidani suv bilan to‘ldirib, prizmaga quysak, uni to‘ldirish uchun roppa-rosa uch marta quyish kerak bo‘ladi. Bu tajribani istalgan maktab laboratoriyasida takrorlash mumkin. Ammo matematikada tajriba isbot emas: nega javob 2,9 yoki 3,1 emas, balki aniq 3? Bu savol qadimgi yunon matematiklarini yuz yillar davomida o‘ylantirgan.', 'Представьте прозрачные сосуды: призму и пирамиду с тем же основанием и высотой. Если наполнить пирамиду водой и переливать в призму, понадобится ровно три раза. Этот опыт можно повторить в любой школьной лаборатории. Но в математике опыт — не доказательство: почему ответ не 2,9 и не 3,1, а ровно 3? Этот вопрос веками занимал древнегреческих математиков.', 'Imagine transparent vessels: a prism and a pyramid with the same base and height. Fill the pyramid with water and pour it into the prism — you need exactly three pourings. Any school lab can repeat this. But in mathematics an experiment is not a proof: why is the answer not 2.9 or 3.1 but exactly 3? This question occupied the ancient Greek mathematicians for centuries.'),
      L('Bu mavzuda biz piramida hajmi formulasi <b>V = ⅓·S·h</b> ni isbotlaymiz, kesik piramida hajmini topamiz va piramidani asosga parallel kesganda hajm qanday o‘zgarishini o‘rganamiz. Shuningdek, 4000 yil oldin misrlik kotib yozib qoldirgan masalani yechib, uning javobini zamonaviy formula bilan tekshiramiz.', 'В этой теме мы докажем формулу объёма пирамиды <b>V = ⅓·S·h</b>, найдём объём усечённой пирамиды и изучим, как меняется объём при сечении, параллельном основанию. А ещё решим задачу, записанную египетским писцом 4000 лет назад, и проверим его ответ современной формулой.', 'In this topic we prove the pyramid volume formula <b>V = ⅓·S·h</b>, find the volume of a frustum and study how volume changes when we cut parallel to the base. We will also solve a problem written down by an Egyptian scribe 4,000 years ago and check his answer with the modern formula.')
    ] },
    { kind: 'def', h: L('Hajm xossalari va Kavalyeri prinsipi', 'Свойства объёма и принцип Кавальери', 'Properties of volume and Cavalieri’s principle'), p: [
      L('Eslatib o‘tamiz: har bir jismga musbat son — <b>hajm</b> mos qo‘yiladi va u quyidagi xossalarga ega: 1) teng jismlarning hajmlari teng; 2) jism bir necha bo‘lakka ajratilsa, uning hajmi bo‘laklar hajmlari yig‘indisiga teng; 3) qirrasi 1 bo‘lgan kubning hajmi 1 ga teng. Bu xossalardan to‘g‘ri burchakli parallelepiped hajmi V = abc va har qanday prizma hajmi V = S·h kelib chiqadi.', 'Напомним: каждому телу ставится в соответствие положительное число — <b>объём</b>, обладающий свойствами: 1) равные тела имеют равные объёмы; 2) если тело разбито на части, его объём равен сумме объёмов частей; 3) объём куба с ребром 1 равен 1. Из этих свойств следуют объём прямоугольного параллелепипеда V = abc и объём любой призмы V = S·h.', 'Recall: every solid is assigned a positive number, its <b>volume</b>, with the properties: 1) congruent solids have equal volumes; 2) if a solid is split into parts, its volume is the sum of their volumes; 3) the unit cube has volume 1. From these follow the volume V = abc of a rectangular box and V = S·h for every prism.'),
      L('<b>Kavalyeri prinsipi:</b> agar ikki jism bitta tekislikka parallel har qanday tekislik bilan kesilganda teng yuzli kesimlar hosil bo‘lsa, bu jismlarning hajmlari teng. Tasavvur qiling: tangalar ustuni to‘g‘ri yoki qiyshiq taxlanishidan qat’i nazar, uning hajmi bir xil — har bir «qatlam» o‘zgarmaydi. Natija: <b>asoslari teng yuzli va balandliklari teng piramidalarning hajmlari teng</b>, chunki uchdan bir xil masofadagi kesimlar asosga k koeffitsiyent bilan o‘xshash va ularning yuzlari k²·S ga teng.', '<b>Принцип Кавальери:</b> если при сечении двух тел любой плоскостью, параллельной данной, получаются сечения равной площади, то объёмы тел равны. Представьте стопку монет: прямо её сложить или наискось — объём один и тот же, ведь каждый «слой» не меняется. Следствие: <b>пирамиды с равновеликими основаниями и равными высотами имеют равные объёмы</b>, так как сечения на одинаковом расстоянии от вершины подобны основанию с коэффициентом k и имеют площадь k²·S.', '<b>Cavalieri’s principle:</b> if every plane parallel to a given one cuts two solids in sections of equal area, the solids have equal volumes. Think of a stack of coins: straight or slanted, its volume is the same, because each “layer” is unchanged. Consequence: <b>pyramids with bases of equal area and equal heights have equal volumes</b>, since sections at the same distance from the apex are similar to the base with ratio k and have area k²·S.')
    ] },
    { kind: 'history', h: L('Moskva papirusi, Demokrit va Evdoks', 'Московский папирус, Демокрит и Евдокс', 'The Moscow Papyrus, Democritus and Eudoxus'), p: [
      L('<b>Moskva matematik papirusi</b> (mil. av. taxminan 1850-yil) Moskvadagi Pushkin muzeyida saqlanadi. Uning 14-masalasida asoslari tomonlari 4 va 2 tirsak bo‘lgan kvadratlar, balandligi 6 tirsak bo‘lgan kesik piramida hajmini topish so‘raladi. Kotib shunday hisoblaydi: 4 ning kvadrati 16, 2 ning kvadrati 4, 4 bilan 2 ning ko‘paytmasi 8; ularni qo‘shsa 28; 6 ning uchdan biri 2; 28 ni 2 ga ko‘paytirsa 56. Bu aynan bugungi V = h/3·(a² + ab + b²) formulasi! Qadimgi misrliklar uni qanday topgani hamon sir.', '<b>Московский математический папирус</b> (около 1850 г. до н. э.) хранится в Пушкинском музее в Москве. В его 14-й задаче требуется найти объём усечённой пирамиды с квадратными основаниями со сторонами 4 и 2 локтя и высотой 6 локтей. Писец считает так: квадрат 4 — 16, квадрат 2 — 4, произведение 4 и 2 — 8; вместе 28; треть от 6 — 2; 28 умножить на 2 — 56. Это в точности современная формула V = h/3·(a² + ab + b²)! Как египтяне её нашли — до сих пор загадка.', 'The <b>Moscow Mathematical Papyrus</b> (about 1850 BC) is kept in the Pushkin Museum in Moscow. Its problem 14 asks for the volume of a frustum with square bases of sides 4 and 2 cubits and height 6 cubits. The scribe computes: the square of 4 is 16, the square of 2 is 4, 4 times 2 is 8; together 28; a third of 6 is 2; 28 times 2 is 56. This is exactly today’s formula V = h/3·(a² + ab + b²)! How the Egyptians found it is still a mystery.'),
      L('Arximedning yozishicha, piramida hajmi prizma hajmining uchdan biri ekanini birinchi bo‘lib <b>Demokrit</b> (mil. av. V asr) aytgan, ammo qat’iy isbotni <b>Knidlik Evdoks</b> (mil. av. IV asr) «tugatish usuli» bilan bergan. Bu usulda jism ichiga va tashqarisiga zinapoyasimon prizmalar chiziladi va ularning soni oshgan sari ikkala yig‘indi ham bitta songa yaqinlashishi ko‘rsatiladi — integralning qadimgi ajdodi. Yevklid «Negizlar»ining XII kitobida Evdoks isbotini keltirgan. 1900-yilda D. Hilbert o‘zining 3-muammosida so‘radi: bu formulani cheksiz jarayonsiz, faqat kesib-yopishtirish bilan isbotlash mumkinmi? 1901-yilda M. Den bunday qilib bo‘lmasligini isbotladi.', 'По словам Архимеда, первым утверждал, что объём пирамиды равен трети призмы, <b>Демокрит</b> (V в. до н. э.), а строгое доказательство «методом исчерпывания» дал <b>Евдокс Книдский</b> (IV в. до н. э.). В этом методе внутрь и снаружи тела вписывают ступенчатые призмы и показывают, что с ростом их числа обе суммы стремятся к одному числу — древний предок интеграла. Евклид привёл доказательство Евдокса в XII книге «Начал». В 1900 году Д. Гильберт в своей 3-й проблеме спросил: можно ли доказать эту формулу без бесконечного процесса, только разрезанием и перекладыванием? В 1901 году М. Ден доказал, что нельзя.', 'According to Archimedes, <b>Democritus</b> (5th century BC) first claimed that a pyramid is a third of a prism, while <b>Eudoxus of Cnidus</b> (4th century BC) gave a rigorous proof by the “method of exhaustion”. Stepped prisms are drawn inside and outside the solid, and as their number grows both sums approach a single number — an ancient ancestor of the integral. Euclid gave Eudoxus’ proof in Book XII of the Elements. In 1900 D. Hilbert asked in his third problem whether the formula can be proved without an infinite process, by cutting and reassembling only. In 1901 M. Dehn proved that it cannot.')
    ] },
    { kind: 'rule', h: L('Uchburchakli piramida hajmi', 'Объём треугольной пирамиды', 'Volume of a triangular pyramid'), p: [
      L('<b>Teorema.</b> Uchburchakli piramidaning hajmi asos yuzi bilan balandlik ko‘paytmasining uchdan biriga teng: <b>V = ⅓·S·h</b>.', '<b>Теорема.</b> Объём треугольной пирамиды равен трети произведения площади основания на высоту: <b>V = ⅓·S·h</b>.', '<b>Theorem.</b> The volume of a triangular pyramid equals one third of the base area times the height: <b>V = ⅓·S·h</b>.'),
      L('<b>Isbot g‘oyasi.</b> SABC piramidani uchburchakli ABCSB₁C₁ prizmagacha to‘ldiramiz (S — yuqori asosning bir uchi, AS, BB₁, CC₁ — yon qirralar). Prizmani uchta piramidaga bo‘lamiz: 1) SABC; 2) SBB₁C₁; 3) SBCC₁. Ikkinchi va uchinchi piramidalarni S uchli deb qarasak, ularning asoslari BB₁C₁ va BCC₁ — parallelogramm BB₁C₁C ning diagonal bo‘yicha teng yarmlari, balandligi esa bir xil (S dan shu tekislikkacha masofa). Demak, ularning hajmlari teng. Birinchi va ikkinchini taqqoslaymiz: SABC ning asosi ABC, SBB₁C₁ ni esa B uchli, asosi SB₁C₁ deb qaraymiz — ABC va SB₁C₁ prizmaning teng asoslari, balandligi ham prizma balandligi. Kavalyeri prinsipi bo‘yicha ular ham teng hajmli.', '<b>Идея доказательства.</b> Достроим пирамиду SABC до треугольной призмы ABCSB₁C₁ (S — вершина верхнего основания, AS, BB₁, CC₁ — боковые рёбра). Разобьём призму на три пирамиды: 1) SABC; 2) SBB₁C₁; 3) SBCC₁. Вторую и третью рассмотрим с вершиной S: их основания BB₁C₁ и BCC₁ — равные половины параллелограмма BB₁C₁C, а высота общая (расстояние от S до этой плоскости). Значит, их объёмы равны. Сравним первую и вторую: у SABC основание ABC, а SBB₁C₁ рассмотрим с вершиной B и основанием SB₁C₁ — ABC и SB₁C₁ равные основания призмы, высота — высота призмы. По принципу Кавальери объёмы тоже равны.', '<b>Proof idea.</b> Complete pyramid SABC to a triangular prism ABCSB₁C₁ (S is a vertex of the upper base, AS, BB₁, CC₁ are lateral edges). Split the prism into three pyramids: 1) SABC; 2) SBB₁C₁; 3) SBCC₁. View the second and third with apex S: their bases BB₁C₁ and BCC₁ are equal halves of parallelogram BB₁C₁C and the height is common (the distance from S to that plane), so their volumes are equal. Compare the first and second: SABC has base ABC, and view SBB₁C₁ with apex B and base SB₁C₁ — ABC and SB₁C₁ are the equal bases of the prism and the height is the prism’s height. By Cavalieri’s principle these volumes are equal too.'),
      L('Shunday qilib, prizma uchta teng hajmli piramidaga bo‘lindi: 3V = S·h, ya’ni V = ⅓·S·h. ∎', 'Итак, призма разбита на три равновеликие пирамиды: 3V = S·h, т. е. V = ⅓·S·h. ∎', 'Thus the prism splits into three pyramids of equal volume: 3V = S·h, i.e. V = ⅓·S·h. ∎')
    ] },
    { kind: 'rule', h: L('Ixtiyoriy piramida va kub misoli', 'Произвольная пирамида и пример с кубом', 'Any pyramid and the cube example'), p: [
      L('<b>Natija.</b> Har qanday piramida uchun <b>V = ⅓·S<sub>asos</sub>·h</b>. Haqiqatan, n-burchakli asosni bir uchidan chiqqan diagonallar bilan uchburchaklarga bo‘lsak, piramida umumiy balandlikli uchburchakli piramidalarga bo‘linadi: V = ⅓S₁h + ⅓S₂h + … = ⅓(S₁ + S₂ + …)h = ⅓Sh.', '<b>Следствие.</b> Для любой пирамиды <b>V = ⅓·S<sub>осн</sub>·h</b>. Действительно, разбив n-угольное основание диагоналями из одной вершины на треугольники, разобьём пирамиду на треугольные пирамиды с общей высотой: V = ⅓S₁h + ⅓S₂h + … = ⅓(S₁ + S₂ + …)h = ⅓Sh.', '<b>Corollary.</b> For every pyramid <b>V = ⅓·S<sub>base</sub>·h</b>. Indeed, splitting the n-gonal base into triangles by diagonals from one vertex splits the pyramid into triangular pyramids with a common height: V = ⅓S₁h + ⅓S₂h + … = ⅓(S₁ + S₂ + …)h = ⅓Sh.'),
      L('<b>Kub bilan tekshiruv.</b> Qirrasi a bo‘lgan kub markazini barcha 8 uchi bilan tutashtirsak, kub 6 ta teng piramidaga bo‘linadi: har birining asosi kub yog‘i (a²), balandligi a/2. Formula bo‘yicha bitta piramida hajmi ⅓·a²·a/2 = a³/6, oltitasi esa a³ — kub hajmi. Hammasi mos keladi! Yana bir foydali fakt: kubning bir uchidan chiqqan uchta qirra uchlarini tutashtiruvchi tekislik kesib tashlaydigan «burchak» piramidasining hajmi ⅓·(a²/2)·a = a³/6.', '<b>Проверка кубом.</b> Соединив центр куба с ребром a со всеми 8 вершинами, разобьём куб на 6 равных пирамид: основание каждой — грань куба (a²), высота a/2. По формуле объём одной пирамиды ⅓·a²·a/2 = a³/6, а шести — a³, объём куба. Всё сходится! Ещё полезный факт: «угловая» пирамида, отсекаемая плоскостью через концы трёх рёбер, выходящих из одной вершины куба, имеет объём ⅓·(a²/2)·a = a³/6.', '<b>Check with a cube.</b> Joining the centre of a cube of edge a to all 8 vertices splits it into 6 equal pyramids, each with a face (a²) as base and height a/2. By the formula one pyramid has volume ⅓·a²·a/2 = a³/6, and six of them a³ — the cube’s volume. It all fits! Another useful fact: the “corner” pyramid cut off by the plane through the ends of three edges from one vertex has volume ⅓·(a²/2)·a = a³/6.')
    ] },
    { kind: 'rule', h: L('Kesik piramida hajmi', 'Объём усечённой пирамиды', 'Volume of a frustum'), p: [
      L('<b>Teorema.</b> Asoslari yuzlari S₁, S₂ va balandligi h bo‘lgan kesik piramidaning hajmi <b>V = ⅓·h·(S₁ + S₂ + √(S₁S₂))</b>.', '<b>Теорема.</b> Объём усечённой пирамиды с площадями оснований S₁, S₂ и высотой h равен <b>V = ⅓·h·(S₁ + S₂ + √(S₁S₂))</b>.', '<b>Theorem.</b> A frustum with base areas S₁, S₂ and height h has volume <b>V = ⅓·h·(S₁ + S₂ + √(S₁S₂))</b>.'),
      L('<b>Isbot.</b> Kesik piramidani to‘liq piramidagacha to‘ldiramiz; kesib tashlangan kichik piramida balandligi x bo‘lsin. Kichik va katta piramidalar o‘xshash, koeffitsiyent x/(x + h), yuzlar nisbati esa uning kvadrati: √S₂/√S₁ = x/(x + h). Bundan x = h√S₂/(√S₁ − √S₂). Hajmlar ayirmasi: V = ⅓(x + h)S₁ − ⅓xS₂ = ⅓[hS₁ + x(S₁ − S₂)]. S₁ − S₂ = (√S₁ − √S₂)(√S₁ + √S₂) bo‘lgani uchun x(S₁ − S₂) = h√S₂(√S₁ + √S₂) = h(√(S₁S₂) + S₂). Demak V = ⅓h(S₁ + √(S₁S₂) + S₂). ∎', '<b>Доказательство.</b> Достроим усечённую пирамиду до полной; пусть высота отсечённой маленькой пирамиды x. Маленькая и большая пирамиды подобны с коэффициентом x/(x + h), а площади относятся как его квадрат: √S₂/√S₁ = x/(x + h). Отсюда x = h√S₂/(√S₁ − √S₂). Разность объёмов: V = ⅓(x + h)S₁ − ⅓xS₂ = ⅓[hS₁ + x(S₁ − S₂)]. Так как S₁ − S₂ = (√S₁ − √S₂)(√S₁ + √S₂), то x(S₁ − S₂) = h√S₂(√S₁ + √S₂) = h(√(S₁S₂) + S₂). Значит, V = ⅓h(S₁ + √(S₁S₂) + S₂). ∎', '<b>Proof.</b> Complete the frustum to a full pyramid; let the cut-off small pyramid have height x. The small and large pyramids are similar with ratio x/(x + h), and the areas are in the ratio of its square: √S₂/√S₁ = x/(x + h). Hence x = h√S₂/(√S₁ − √S₂). The difference of volumes: V = ⅓(x + h)S₁ − ⅓xS₂ = ⅓[hS₁ + x(S₁ − S₂)]. Since S₁ − S₂ = (√S₁ − √S₂)(√S₁ + √S₂), x(S₁ − S₂) = h√S₂(√S₁ + √S₂) = h(√(S₁S₂) + S₂). So V = ⅓h(S₁ + √(S₁S₂) + S₂). ∎'),
      L('<b>O‘xshashlik qonuni:</b> piramidani uchidan balandlikning k qismi masofada asosga parallel kessak, kichik piramida hajmi k³·V bo‘ladi. Masalan, balandlik o‘rtasidan kesilsa, kichik piramida butun hajmning 1/8 qismi, kesik piramida esa 7/8 qismi.', '<b>Закон подобия:</b> если разрезать пирамиду параллельно основанию на расстоянии доли k высоты от вершины, объём маленькой пирамиды равен k³·V. Например, при сечении через середину высоты маленькая пирамида составляет 1/8 объёма, а усечённая — 7/8.', '<b>Similarity law:</b> cutting a pyramid parallel to the base at the fraction k of the height from the apex gives a small pyramid of volume k³·V. For instance, cutting through the midpoint of the height leaves a small pyramid of 1/8 of the volume and a frustum of 7/8.')
    ] },
    { kind: 'steps', h: L('Hajmni topish bosqichlari', 'Этапы нахождения объёма', 'Steps for finding the volume'), list: [
      L('Asos shaklini aniqlang va uning yuzini toping (kvadrat a², muntazam uchburchak a²√3/4, oltiburchak 3a²√3/2).', 'Определите форму основания и найдите его площадь (квадрат a², правильный треугольник a²√3/4, шестиугольник 3a²√3/2).', 'Identify the base and find its area (square a², equilateral triangle a²√3/4, hexagon 3a²√3/2).'),
      L('Balandlik asosi qayerga tushishini aniqlang: muntazam piramidada — markazga, teng yon qirralarda — tashqi chizilgan aylana markaziga.', 'Определите, куда падает высота: в правильной пирамиде — в центр, при равных боковых рёбрах — в центр описанной окружности.', 'Decide where the height lands: at the centre in a regular pyramid, at the circumcentre when the lateral edges are equal.'),
      L('h ni to‘g‘ri burchakli uchburchakdan toping: h² = b² − R² yoki h² = l² − r².', 'Найдите h из прямоугольного треугольника: h² = b² − R² или h² = l² − r².', 'Find h from a right triangle: h² = b² − R² or h² = l² − r².'),
      L('V = ⅓·S·h ga qo‘ying; kesik piramidada V = ⅓h(S₁ + S₂ + √(S₁S₂)).', 'Подставьте в V = ⅓·S·h; для усечённой V = ⅓h(S₁ + S₂ + √(S₁S₂)).', 'Substitute into V = ⅓·S·h; for a frustum V = ⅓h(S₁ + S₂ + √(S₁S₂)).'),
      L('Javobni kub birliklarda yozing va mantiqan tekshiring: piramida hajmi shu asos va balandlikdagi prizmadan 3 marta kichik bo‘lishi kerak.', 'Запишите ответ в кубических единицах и проверьте по смыслу: пирамида в 3 раза меньше призмы с тем же основанием и высотой.', 'Write the answer in cubic units and sanity-check it: the pyramid is 3 times smaller than the prism with the same base and height.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Решённые примеры', 'Worked examples'), ex: [
      { q: L('Muntazam to‘rtburchakli piramida: asos tomoni 6, apofemasi 5. Hajmini toping.', 'Правильная четырёхугольная пирамида: сторона основания 6, апофема 5. Найдите объём.', 'Regular square pyramid: base side 6, apothem 5. Find its volume.'),
        s: L('r = 3, h = √(l² − r²) = √(25 − 9) = 4. S = 36. V = ⅓·36·4 = 48.', 'r = 3, h = √(l² − r²) = √(25 − 9) = 4. S = 36. V = ⅓·36·4 = 48.', 'r = 3, h = √(l² − r²) = √(25 − 9) = 4. S = 36. V = ⅓·36·4 = 48.') },
      { q: L('Muntazam uchburchakli piramidaning asos tomoni 6, yon qirrasi 4. Hajmini toping.', 'Сторона основания правильной треугольной пирамиды 6, боковое ребро 4. Найдите объём.', 'A regular triangular pyramid has base side 6 and lateral edge 4. Find its volume.'),
        s: L('R = a√3/3 = 2√3, R² = 12. h = √(16 − 12) = 2. S = 36√3/4 = 9√3. V = ⅓·9√3·2 = 6√3 ≈ 10,4.', 'R = a√3/3 = 2√3, R² = 12. h = √(16 − 12) = 2. S = 36√3/4 = 9√3. V = ⅓·9√3·2 = 6√3 ≈ 10,4.', 'R = a√3/3 = 2√3, R² = 12. h = √(16 − 12) = 2. S = 36√3/4 = 9√3. V = ⅓·9√3·2 = 6√3 ≈ 10.4.') },
      { q: L('Qirrasi a bo‘lgan muntazam tetraedr hajmini toping; a = 6 bo‘lgan holni hisoblang.', 'Найдите объём правильного тетраэдра с ребром a; вычислите при a = 6.', 'Find the volume of a regular tetrahedron of edge a; compute it for a = 6.'),
        s: L('R = a√3/3, h² = a² − a²/3 = 2a²/3, h = a√6/3. S = a²√3/4. V = ⅓·(a²√3/4)·(a√6/3) = a³√18/36 = a³√2/12. a = 6 da V = 216√2/12 = 18√2 ≈ 25,5.', 'R = a√3/3, h² = a² − a²/3 = 2a²/3, h = a√6/3. S = a²√3/4. V = ⅓·(a²√3/4)·(a√6/3) = a³√18/36 = a³√2/12. При a = 6: V = 216√2/12 = 18√2 ≈ 25,5.', 'R = a√3/3, h² = a² − a²/3 = 2a²/3, h = a√6/3. S = a²√3/4. V = ⅓·(a²√3/4)·(a√6/3) = a³√18/36 = a³√2/12. For a = 6: V = 216√2/12 = 18√2 ≈ 25.5.') },
      { q: L('Moskva papirusi masalasi: kesik piramida asoslari tomonlari 4 va 2 bo‘lgan kvadratlar, balandligi 6. Hajmini toping.', 'Задача Московского папируса: основания усечённой пирамиды — квадраты со сторонами 4 и 2, высота 6. Найдите объём.', 'The Moscow Papyrus problem: a frustum with square bases of sides 4 and 2 and height 6. Find its volume.'),
        s: L('S₁ = 16, S₂ = 4, √(S₁S₂) = 8. V = ⅓·6·(16 + 4 + 8) = 2·28 = 56 — misrlik kotib javobi bilan bir xil.', 'S₁ = 16, S₂ = 4, √(S₁S₂) = 8. V = ⅓·6·(16 + 4 + 8) = 2·28 = 56 — совпадает с ответом египетского писца.', 'S₁ = 16, S₂ = 4, √(S₁S₂) = 8. V = ⅓·6·(16 + 4 + 8) = 2·28 = 56 — the same as the Egyptian scribe’s answer.') },
      { q: L('Hajmi 81 bo‘lgan piramida uchidan hisoblaganda balandlikning ⅓ qismida asosga parallel tekislik bilan kesildi. Hosil bo‘lgan kesik piramida hajmini toping.', 'Пирамиду объёмом 81 рассекли плоскостью, параллельной основанию, на расстоянии ⅓ высоты от вершины. Найдите объём усечённой пирамиды.', 'A pyramid of volume 81 is cut by a plane parallel to the base at ⅓ of the height from the apex. Find the volume of the frustum.'),
        s: L('Kichik piramida o‘xshash, k = ⅓, hajmi k³·81 = 81/27 = 3. Kesik piramida: 81 − 3 = 78.', 'Малая пирамида подобна, k = ⅓, её объём k³·81 = 81/27 = 3. Усечённая: 81 − 3 = 78.', 'The small pyramid is similar with k = ⅓, its volume k³·81 = 81/27 = 3. Frustum: 81 − 3 = 78.') }
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>⅓ ni unutish.</b> V = S·h — prizma hajmi, piramidada albatta uchdan biri olinadi.', '<b>Забывают ⅓.</b> V = S·h — объём призмы; у пирамиды обязательно берётся треть.', '<b>Forgetting ⅓.</b> V = S·h is the prism; for a pyramid always take one third.'),
      L('<b>Balandlik o‘rniga apofema yoki yon qirrani qo‘yish.</b> Formulaga faqat asosga perpendikulyar h kiradi.', '<b>Подставляют апофему или боковое ребро вместо высоты.</b> В формулу входит только перпендикуляр к основанию h.', '<b>Using the apothem or a lateral edge instead of the height.</b> Only the perpendicular h to the base enters the formula.'),
      L('<b>Kesik piramida hajmini o‘rtacha asos bilan hisoblash:</b> V ≠ h·(S₁ + S₂)/2. Moskva masalasida bu 60 beradi, to‘g‘ri javob esa 56.', '<b>Считают объём усечённой пирамиды по среднему основанию:</b> V ≠ h·(S₁ + S₂)/2. В задаче папируса это дало бы 60 вместо верных 56.', '<b>Using the average base for a frustum:</b> V ≠ h·(S₁ + S₂)/2. In the papyrus problem this gives 60 instead of the correct 56.'),
      L('<b>O‘xshashlikda kvadrat va kubni chalkashtirish.</b> Chiziqli o‘lchamlar k marta o‘zgarsa, yuzlar k², hajmlar k³ marta o‘zgaradi.', '<b>Путают квадрат и куб при подобии.</b> Если линейные размеры меняются в k раз, площади — в k², объёмы — в k³ раз.', '<b>Mixing squares and cubes under similarity.</b> If lengths scale by k, areas scale by k² and volumes by k³.'),
      L('<b>√(S₁S₂) ni √S₁·S₂ deb yozish</b> — ildiz ikkala yuz ko‘paytmasidan olinadi.', '<b>Пишут √S₁·S₂ вместо √(S₁S₂)</b> — корень берётся из произведения обеих площадей.', '<b>Writing √S₁·S₂ instead of √(S₁S₂)</b> — the root is taken of the product of both areas.')
    ] },
    { kind: 'life', h: L('Hayotda piramida hajmi', 'Объём пирамиды в жизни', 'Pyramid volume in real life'), p: [
      L('<b>Xufu piramidasi.</b> Asos tomoni ≈ 230,4 m, balandligi ≈ 146,6 m: V ≈ ⅓·230,4²·146,6 ≈ 2,6 mln m³. Agar bir blok o‘rtacha 1,1 m³ bo‘lsa, taxminan 2,3 mln blok kerak bo‘lgan; 20 yillik qurilishda bu kuniga 300 dan ortiq blok demakdir. Tarixchilar ish kuchi va vaqtni aynan shunday hisob-kitoblar bilan baholaydi.', '<b>Пирамида Хуфу.</b> Сторона основания ≈ 230,4 м, высота ≈ 146,6 м: V ≈ ⅓·230,4²·146,6 ≈ 2,6 млн м³. Если средний блок 1,1 м³, понадобилось около 2,3 млн блоков; за 20 лет строительства это больше 300 блоков в день. Историки оценивают рабочую силу и сроки именно такими расчётами.', '<b>The pyramid of Khufu.</b> Base side ≈ 230.4 m, height ≈ 146.6 m: V ≈ ⅓·230.4²·146.6 ≈ 2.6 million m³. With an average block of 1.1 m³, about 2.3 million blocks were needed; over 20 years of building that is more than 300 blocks a day. Historians estimate labour and time with exactly such calculations.'),
      L('<b>Qurilish va qishloq xo‘jaligi.</b> Shag‘al, qum yoki don uyumi taxminan piramida yoki konus shaklida bo‘ladi; omborchi uning hajmini ⅓·S·h bilan baholaydi. <b>Bunker va voronkalar</b> — sement zavodlari va tegirmonlardagi to‘rtburchakli kesik piramida shaklidagi idishlar: sig‘imi kesik piramida formulasi bilan hisoblanadi. <b>Kimyo va mineralogiya:</b> olmos va ko‘plab kristallar oktaedr shaklida — u ikki piramidadan iborat. <b>Kompyuter grafikasi:</b> kamera ko‘rish sohasi — «frustum» deb ataladigan kesik piramida; ekranga faqat shu kesik piramida ichidagi narsalar chiziladi.', '<b>Строительство и сельское хозяйство.</b> Кучи щебня, песка или зерна имеют примерно форму пирамиды или конуса; кладовщик оценивает объём по ⅓·S·h. <b>Бункеры и воронки</b> на цементных заводах и мельницах — ёмкости в форме четырёхугольной усечённой пирамиды; их вместимость считают по формуле усечённой пирамиды. <b>Химия и минералогия:</b> алмаз и многие кристаллы имеют форму октаэдра — двух пирамид. <b>Компьютерная графика:</b> область видимости камеры — усечённая пирамида, «frustum»; на экран рисуется только то, что внутри неё.', '<b>Construction and farming.</b> Heaps of gravel, sand or grain are roughly pyramids or cones; a storekeeper estimates their volume by ⅓·S·h. <b>Hoppers</b> at cement plants and mills are square frustums, and their capacity is computed with the frustum formula. <b>Chemistry and mineralogy:</b> diamond and many crystals are octahedra — two pyramids. <b>Computer graphics:</b> a camera’s field of view is a frustum; only what lies inside it is drawn on the screen.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Interesting facts'), list: [
      L('Kubni uchta teng to‘rtburchakli piramidaga bo‘lish mumkin: har birining uchi kubning bitta umumiy uchida, asoslari esa shu uchga tegmaydigan uchta yoq. Har biri a³/3 = ⅓·a²·a.', 'Куб можно разбить на три равные четырёхугольные пирамиды с общей вершиной в одной вершине куба и основаниями — тремя не содержащими её гранями. Каждая a³/3 = ⅓·a²·a.', 'A cube can be cut into three equal square pyramids sharing one vertex of the cube, with bases the three faces not containing it. Each has a³/3 = ⅓·a²·a.'),
      L('Muhammad al-Xorazmiy «Al-jabr» kitobining o‘lchash bobida kesik piramida hajmini hisoblash usulini keltirgan.', 'Мухаммад аль-Хорезми в главе об измерениях своей «Книги об аль-джабре» привёл способ вычисления объёма усечённой пирамиды.', 'Muhammad al-Khwarizmi described how to compute the volume of a frustum in the mensuration chapter of his book on al-jabr.'),
      L('Piramida balandligini 2 marta oshirsak hajm 2 marta, asos tomonini 2 marta oshirsak — 4 marta, ikkalasini birga — 8 marta oshadi.', 'Если удвоить высоту пирамиды, объём удвоится; если удвоить сторону основания — вырастет в 4 раза; оба сразу — в 8 раз.', 'Doubling a pyramid’s height doubles the volume; doubling the base side multiplies it by 4; doing both multiplies it by 8.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Har qanday piramida: V = ⅓·S<sub>asos</sub>·h — xuddi shu asos va balandlikdagi prizmaning uchdan biri.', 'Любая пирамида: V = ⅓·S<sub>осн</sub>·h — треть призмы с тем же основанием и высотой.', 'Any pyramid: V = ⅓·S<sub>base</sub>·h — one third of the prism with the same base and height.'),
      L('Isbot: uchburchakli prizma uchta teng hajmli piramidaga bo‘linadi (Kavalyeri prinsipi).', 'Доказательство: треугольная призма делится на три равновеликие пирамиды (принцип Кавальери).', 'Proof: a triangular prism splits into three pyramids of equal volume (Cavalieri’s principle).'),
      L('Kesik piramida: V = ⅓h(S₁ + S₂ + √(S₁S₂)) — Moskva papirusida 4000 yil oldin qo‘llangan.', 'Усечённая пирамида: V = ⅓h(S₁ + S₂ + √(S₁S₂)) — применялась в Московском папирусе 4000 лет назад.', 'Frustum: V = ⅓h(S₁ + S₂ + √(S₁S₂)) — used in the Moscow Papyrus 4,000 years ago.'),
      L('Parallel kesishda kichik piramida hajmi k³·V.', 'При параллельном сечении объём малой пирамиды k³·V.', 'Under a parallel cut the small pyramid has volume k³·V.'),
      L('Demokrit formulani topgan, Evdoks tugatish usuli bilan isbotlagan, Yevklid XII kitobda bayon qilgan.', 'Демокрит нашёл формулу, Евдокс доказал методом исчерпывания, Евклид изложил в XII книге.', 'Democritus found the formula, Eudoxus proved it by exhaustion, Euclid set it out in Book XII.')
    ] }
  ] });


  // ---------- t10. Konus va kesik konus ----------
  T.add(P, 't10', { sections: [
    { kind: 'intro', h: L('Muzqaymoqdan vulqongacha', 'От мороженого до вулкана', 'From ice cream to volcanoes'), p: [
      L('Vafli muzqaymoq stakanchasi, yo‘l ishlari paytida qo‘yiladigan to‘q sariq belgilar, qumsoatning yuqori yarmi, Fudziyama tog‘i — bularning barchasini bitta jism birlashtiradi: <b>konus</b>. Tabiatda konus o‘z-o‘zidan paydo bo‘ladi: qum yoki don to‘kilganda u konus shaklidagi uyum hosil qiladi, vulqon otilganda lava va kul xuddi shunday tog‘ yasaydi.', 'Вафельный стаканчик мороженого, оранжевые дорожные конусы, верхняя половина песочных часов, гора Фудзияма — всё это объединяет одно тело: <b>конус</b>. В природе конус возникает сам собой: высыпанный песок или зерно образует коническую кучу, а при извержении вулкана лава и пепел строят такую же гору.', 'A wafer ice-cream cone, orange traffic cones, the upper half of an hourglass, Mount Fuji — one solid unites them all: the <b>cone</b>. Nature produces cones by itself: poured sand or grain forms a conical heap, and an erupting volcano builds the same kind of mountain from lava and ash.'),
      L('Konus piramidaning «yumaloq» qarindoshi: agar muntazam piramida asosidagi ko‘pburchak tomonlari sonini cheksiz oshirsak, u konusga aylanadi. Shuning uchun konus formulalari piramida formulalariga juda o‘xshaydi: perimetr o‘rniga aylana uzunligi 2πr, apofema o‘rniga yasovchi l keladi. Bu mavzuda konus va kesik konusning elementlari, kesimlari, yon sirti, to‘la sirti va hajmini o‘rganamiz.', 'Конус — «круглый» родственник пирамиды: если неограниченно увеличивать число сторон основания правильной пирамиды, она превратится в конус. Поэтому формулы конуса очень похожи на формулы пирамиды: вместо периметра — длина окружности 2πr, вместо апофемы — образующая l. В этой теме изучим элементы, сечения, боковую и полную поверхность и объём конуса и усечённого конуса.', 'The cone is the “round” relative of the pyramid: increase the number of sides of a regular pyramid’s base without limit and it becomes a cone. That is why cone formulas look so much like pyramid formulas: the perimeter is replaced by the circumference 2πr and the apothem by the slant height l. In this topic we study the elements, sections, lateral and total surface and volume of the cone and the truncated cone.')
    ] },
    { kind: 'def', h: L('Konus va uning elementlari', 'Конус и его элементы', 'The cone and its elements'), p: [
      L('To‘g‘ri burchakli uchburchakni katetlaridan biri atrofida aylantirganda hosil bo‘ladigan jism <b>konus</b> (aylanma konus) deyiladi. Aylanish o‘qi bo‘lgan katet — konusning <b>balandligi</b> h, ikkinchi katet chizgan doira — <b>asos</b>, uning radiusi r — <b>asos radiusi</b>. Gipotenuzaning aylanishidan <b>yon sirt</b> hosil bo‘ladi, gipotenuzaning o‘zi esa <b>yasovchi</b> l deyiladi. Konusning <b>uchi</b> S dan asos aylanasining istalgan nuqtasigacha bo‘lgan kesmalar — yasovchilar, ular hammasi teng.', 'Тело, получаемое вращением прямоугольного треугольника вокруг одного из катетов, называется <b>конусом</b> (конусом вращения). Катет-ось вращения — <b>высота</b> h, круг, описанный другим катетом, — <b>основание</b>, его радиус r — <b>радиус основания</b>. Вращение гипотенузы образует <b>боковую поверхность</b>, а сама гипотенуза называется <b>образующей</b> l. Отрезки от <b>вершины</b> S до любой точки окружности основания — образующие, все они равны.', 'The solid obtained by rotating a right triangle about one of its legs is called a <b>cone</b> (a cone of revolution). The leg on the axis is the <b>height</b> h, the disc swept by the other leg is the <b>base</b>, and its radius r is the <b>base radius</b>. Rotating the hypotenuse gives the <b>lateral surface</b>, and the hypotenuse itself is the <b>slant height</b> (generator) l. The segments from the <b>apex</b> S to any point of the base circle are generators; they are all equal.'),
      L('Asosiy bog‘lanish: <b>l² = r² + h²</b>. Yasovchi va asos tekisligi orasidagi burchak α uchun cos α = r/l, sin α = h/l, tg α = h/r. Uchning qarshisidagi burchak 2β (o‘q kesimdagi uchdagi burchak) uchun sin β = r/l.', 'Главная связь: <b>l² = r² + h²</b>. Для угла α между образующей и плоскостью основания cos α = r/l, sin α = h/l, tg α = h/r. Для угла 2β при вершине осевого сечения sin β = r/l.', 'The key relation: <b>l² = r² + h²</b>. For the angle α between a generator and the base plane, cos α = r/l, sin α = h/l, tan α = h/r. For the apex angle 2β of the axial section, sin β = r/l.')
    ] },
    { kind: 'def', h: L('Konus kesimlari va kesik konus', 'Сечения конуса и усечённый конус', 'Sections of a cone and the frustum'), p: [
      L('<b>O‘q kesim</b> — konus o‘qi orqali o‘tgan tekislik bilan kesim: asosi 2r, yon tomonlari l bo‘lgan teng yonli uchburchak. Agar o‘q kesim teng tomonli uchburchak bo‘lsa, konus <b>teng tomonli</b> deyiladi: l = 2r. Uch orqali o‘tib, asosni vatar bo‘yicha kesuvchi tekislik ham teng yonli uchburchak beradi. Asosga parallel tekislik konusni <b>doira</b> bo‘yicha kesadi; uchdan balandlikning k qismida yotsa, kesim radiusi k·r ga teng.', '<b>Осевое сечение</b> — сечение плоскостью через ось конуса: равнобедренный треугольник с основанием 2r и боковыми сторонами l. Если осевое сечение — равносторонний треугольник, конус называют <b>равносторонним</b>: l = 2r. Плоскость через вершину, пересекающая основание по хорде, тоже даёт равнобедренный треугольник. Плоскость, параллельная основанию, пересекает конус по <b>кругу</b>; на доле k высоты от вершины радиус сечения равен k·r.', 'The <b>axial section</b> is the section by a plane through the axis: an isosceles triangle with base 2r and sides l. If the axial section is equilateral, the cone is called <b>equilateral</b>: l = 2r. A plane through the apex cutting the base along a chord also gives an isosceles triangle. A plane parallel to the base cuts the cone in a <b>disc</b>; at the fraction k of the height from the apex its radius is k·r.'),
      L('Konusni asosiga parallel tekislik bilan kesganda pastki qism <b>kesik konus</b> deyiladi. Uni to‘g‘ri burchakli trapetsiyani asoslarga perpendikulyar yon tomoni atrofida aylantirish bilan ham olish mumkin. Kesik konusda ikkita asos (radiuslari r₁ &gt; r₂), balandlik h va yasovchi l bor; o‘q kesimi — teng yonli trapetsiya. Undan <b>l² = h² + (r₁ − r₂)²</b>.', 'Нижняя часть конуса, отсечённая плоскостью, параллельной основанию, называется <b>усечённым конусом</b>. Его можно получить и вращением прямоугольной трапеции вокруг боковой стороны, перпендикулярной основаниям. У усечённого конуса два основания (радиусы r₁ &gt; r₂), высота h и образующая l; осевое сечение — равнобокая трапеция. Отсюда <b>l² = h² + (r₁ − r₂)²</b>.', 'The lower part of a cone cut off by a plane parallel to the base is a <b>truncated cone</b> (conical frustum). It can also be obtained by rotating a right trapezium about its side perpendicular to the bases. It has two bases (radii r₁ &gt; r₂), height h and slant height l; its axial section is an isosceles trapezium. Hence <b>l² = h² + (r₁ − r₂)²</b>.'),
      L('Qiziq fakt: konusni uchidan o‘tmaydigan og‘ma tekisliklar bilan kessak, ellips, parabola va giperbola hosil bo‘ladi — ular <b>konus kesimlari</b> deyiladi.', 'Интересно: наклонные плоскости, не проходящие через вершину, высекают на конусе эллипс, параболу и гиперболу — <b>конические сечения</b>.', 'A curious fact: slanted planes not through the apex cut a cone in an ellipse, a parabola or a hyperbola — the <b>conic sections</b>.')
    ] },
    { kind: 'history', h: L('Demokritdan Apolloniygacha', 'От Демокрита до Аполлония', 'From Democritus to Apollonius'), p: [
      L('Konus hajmi silindr hajmining uchdan biri ekanini ham piramida singari <b>Demokrit</b> payqagan, <b>Evdoks</b> esa isbotlagan. <b>Arximed</b> (mil. av. III asr) «Sfera va silindr haqida» asarida konus yon sirti uchun «yon sirt radiusi √(rl) bo‘lgan doiraga teng» degan ta’rifni bergan — bu aynan πrl. Pergalik <b>Apolloniy</b> (mil. av. III–II asr) sakkiz kitobdan iborat «Konus kesimlari» asarini yozdi va «ellips», «parabola», «giperbola» nomlarini kiritdi.', 'То, что объём конуса — треть объёма цилиндра, как и для пирамиды, заметил <b>Демокрит</b>, а доказал <b>Евдокс</b>. <b>Архимед</b> (III в. до н. э.) в сочинении «О шаре и цилиндре» показал, что боковая поверхность конуса равна кругу с радиусом √(rl), — это и есть πrl. <b>Аполлоний Пергский</b> (III–II вв. до н. э.) написал восемь книг «Конических сечений» и ввёл названия «эллипс», «парабола», «гипербола».', 'Like the pyramid result, the fact that a cone is a third of a cylinder was noticed by <b>Democritus</b> and proved by <b>Eudoxus</b>. <b>Archimedes</b> (3rd century BC), in “On the Sphere and Cylinder”, showed that the lateral surface of a cone equals a disc of radius √(rl) — which is exactly πrl. <b>Apollonius of Perga</b> (3rd–2nd century BC) wrote the eight books of “Conics” and introduced the names “ellipse”, “parabola” and “hyperbola”.'),
      L('O‘rta asrlarda Sharq olimlari konus kesimlaridan amaliy maqsadlarda foydalangan: <b>Ibn al-Haysam</b> (X–XI asr) parabolik ko‘zgularni o‘rgangan, <b>Abu Rayhon Beruniy</b> esa astrolyabiya va quyosh soatlarini yasashda konus va uning kesimlariga tayangan — quyosh soatida tayoqcha uchining soyasi kun davomida aynan konus kesimini chizadi. 1609-yilda Kepler sayyoralar ellips bo‘ylab harakatlanishini aniqlab, qadimgi konus kesimlari nazariyasini osmonga «ko‘chirdi».', 'В средние века учёные Востока применяли конические сечения на практике: <b>Ибн аль-Хайсам</b> (X–XI вв.) изучал параболические зеркала, <b>Абу Райхан Беруни</b> опирался на конус и его сечения при построении астролябий и солнечных часов — тень конца стержня солнечных часов за день описывает именно коническое сечение. В 1609 году Кеплер установил, что планеты движутся по эллипсам, «перенеся» античную теорию конических сечений на небо.', 'In the Middle Ages scholars of the East put conic sections to practical use: <b>Ibn al-Haytham</b> (10th–11th c.) studied parabolic mirrors, and <b>Abu Rayhan al-Biruni</b> relied on the cone and its sections in building astrolabes and sundials — during a day the shadow of the tip of a sundial’s rod traces exactly a conic section. In 1609 Kepler found that planets move along ellipses, “moving” the ancient theory of conics into the sky.')
    ] },
    { kind: 'rule', h: L('Konusning yon va to‘la sirti', 'Боковая и полная поверхность конуса', 'Lateral and total surface of a cone'), p: [
      L('<b>Teorema.</b> Konusning yon sirti <b>S<sub>yon</sub> = π·r·l</b>, to‘la sirti <b>S<sub>to‘la</sub> = πr(r + l)</b>.', '<b>Теорема.</b> Боковая поверхность конуса <b>S<sub>бок</sub> = π·r·l</b>, полная <b>S<sub>полн</sub> = πr(r + l)</b>.', '<b>Theorem.</b> The lateral area of a cone is <b>S<sub>lat</sub> = π·r·l</b> and the total area is <b>S<sub>tot</sub> = πr(r + l)</b>.'),
      L('<b>Isbot (yoyilma orqali).</b> Konus yon sirtini bitta yasovchi bo‘yicha qirqib tekislikka yoyamiz. Radiusi l bo‘lgan doiraviy sektor hosil bo‘ladi, uning yoyi asos aylanasi uzunligiga teng: 2πr. Butun doira (radiusi l) aylanasi 2πl, yuzi πl². Sektor yuzi yoy uzunligiga proporsional: S = πl²·(2πr / 2πl) = πrl. ∎ Shu bilan birga sektor burchagi <b>φ = 360°·r/l</b>. Boshqa yo‘l: muntazam piramida formulasi ½·P·l da P → 2πr intiladi, natijada ½·2πr·l = πrl.', '<b>Доказательство (через развёртку).</b> Разрежем боковую поверхность конуса по образующей и развернём на плоскость. Получим круговой сектор радиуса l, длина дуги которого равна длине окружности основания 2πr. У всего круга радиуса l окружность 2πl и площадь πl². Площадь сектора пропорциональна длине дуги: S = πl²·(2πr / 2πl) = πrl. ∎ Попутно угол сектора <b>φ = 360°·r/l</b>. Другой путь: в формуле правильной пирамиды ½·P·l периметр P стремится к 2πr, и получаем ½·2πr·l = πrl.', '<b>Proof (via the net).</b> Cut the lateral surface along a generator and unroll it. We get a circular sector of radius l whose arc length equals the base circumference 2πr. The whole disc of radius l has circumference 2πl and area πl². The sector’s area is proportional to its arc: S = πl²·(2πr / 2πl) = πrl. ∎ Along the way, the sector angle is <b>φ = 360°·r/l</b>. Another route: in the regular-pyramid formula ½·P·l the perimeter P tends to 2πr, giving ½·2πr·l = πrl.'),
      L('Sektor burchagi har doim 360° dan kichik, chunki r &lt; l. Teng tomonli konusda r/l = ½ va yoyilma — roppa-rosa yarim doira (180°).', 'Угол сектора всегда меньше 360°, так как r &lt; l. У равностороннего конуса r/l = ½, и развёртка — ровно полукруг (180°).', 'The sector angle is always below 360° because r &lt; l. For an equilateral cone r/l = ½ and the net is exactly a half-disc (180°).')
    ] },
    { kind: 'rule', h: L('Konus hajmi', 'Объём конуса', 'Volume of a cone'), p: [
      L('<b>Teorema.</b> Konus hajmi <b>V = ⅓·π·r²·h</b>, ya’ni asos yuzi bilan balandlik ko‘paytmasining uchdan biri — xuddi piramidadagidek.', '<b>Теорема.</b> Объём конуса <b>V = ⅓·π·r²·h</b>, то есть треть произведения площади основания на высоту — как у пирамиды.', '<b>Theorem.</b> The volume of a cone is <b>V = ⅓·π·r²·h</b>, one third of the base area times the height — just like a pyramid.'),
      L('<b>Isbot g‘oyasi.</b> Konusga asosi muntazam n-burchak bo‘lgan piramidani ichki chizamiz. Uning hajmi ⅓·S<sub>n</sub>·h, bu yerda S<sub>n</sub> — n-burchak yuzi. n oshgan sari S<sub>n</sub> doira yuzi πr² ga intiladi, piramida esa konusni tobora to‘liqroq to‘ldiradi. Limitda V = ⅓·πr²·h. Kavalyeri prinsipi bilan ham isbotlash mumkin: asos yuzi πr² ga teng piramida bilan konus uchdan bir xil masofada teng yuzli kesimlarga ega (ikkalasida k²·πr²).', '<b>Идея доказательства.</b> Впишем в конус пирамиду с правильным n-угольником в основании. Её объём ⅓·S<sub>n</sub>·h, где S<sub>n</sub> — площадь n-угольника. С ростом n площадь S<sub>n</sub> стремится к площади круга πr², а пирамида всё полнее заполняет конус. В пределе V = ⅓·πr²·h. Можно доказать и принципом Кавальери: пирамида с площадью основания πr² и конус имеют на одинаковом расстоянии от вершины сечения равной площади (у обоих k²·πr²).', '<b>Proof idea.</b> Inscribe in the cone a pyramid whose base is a regular n-gon. Its volume is ⅓·S<sub>n</sub>·h, where S<sub>n</sub> is the area of the n-gon. As n grows, S<sub>n</sub> tends to the disc area πr² and the pyramid fills the cone ever more fully. In the limit V = ⅓·πr²·h. Cavalieri’s principle also works: a pyramid with base area πr² and the cone have equal-area sections at equal distances from the apex (k²·πr² for both).')
    ] },
    { kind: 'rule', h: L('Kesik konus formulalari', 'Формулы усечённого конуса', 'Formulas for the truncated cone'), p: [
      L('<b>Yon sirt:</b> <b>S<sub>yon</sub> = π(r₁ + r₂)·l</b> — kesik piramidadagi ½(P₁ + P₂)·l ning o‘xshashi, chunki ½(2πr₁ + 2πr₂) = π(r₁ + r₂). Isbot: katta konus yon sirtidan kichik konus yon sirtini ayiramiz va o‘xshashlikdan foydalanamiz. <b>To‘la sirt:</b> S = π(r₁ + r₂)l + πr₁² + πr₂².', '<b>Боковая поверхность:</b> <b>S<sub>бок</sub> = π(r₁ + r₂)·l</b> — аналог ½(P₁ + P₂)·l для усечённой пирамиды, ведь ½(2πr₁ + 2πr₂) = π(r₁ + r₂). Доказательство: из боковой поверхности большого конуса вычитаем боковую поверхность малого и пользуемся подобием. <b>Полная поверхность:</b> S = π(r₁ + r₂)l + πr₁² + πr₂².', '<b>Lateral area:</b> <b>S<sub>lat</sub> = π(r₁ + r₂)·l</b> — the analogue of ½(P₁ + P₂)·l for a frustum, since ½(2πr₁ + 2πr₂) = π(r₁ + r₂). Proof: subtract the small cone’s lateral area from the large one’s and use similarity. <b>Total area:</b> S = π(r₁ + r₂)l + πr₁² + πr₂².'),
      L('<b>Hajm:</b> <b>V = ⅓·π·h·(r₁² + r₁r₂ + r₂²)</b>. Bu kesik piramida formulasidan S₁ = πr₁², S₂ = πr₂², √(S₁S₂) = πr₁r₂ qo‘yish bilan olinadi. Tekshirish: r₂ = 0 bo‘lsa, oddiy konus hajmi ⅓πr₁²h; r₁ = r₂ = r bo‘lsa, silindr hajmi πr²h chiqadi.', '<b>Объём:</b> <b>V = ⅓·π·h·(r₁² + r₁r₂ + r₂²)</b>. Получается из формулы усечённой пирамиды подстановкой S₁ = πr₁², S₂ = πr₂², √(S₁S₂) = πr₁r₂. Проверка: при r₂ = 0 — объём конуса ⅓πr₁²h; при r₁ = r₂ = r — объём цилиндра πr²h.', '<b>Volume:</b> <b>V = ⅓·π·h·(r₁² + r₁r₂ + r₂²)</b>. It comes from the frustum formula with S₁ = πr₁², S₂ = πr₂², √(S₁S₂) = πr₁r₂. Check: r₂ = 0 gives the cone ⅓πr₁²h; r₁ = r₂ = r gives the cylinder πr²h.')
    ] },
    { kind: 'table', h: L('Formulalar jadvali', 'Таблица формул', 'Table of formulas'), table: {
      head: [L('Jism', 'Тело', 'Solid'), L('Yon sirt', 'Боковая поверхность', 'Lateral area'), L('Hajm', 'Объём', 'Volume')],
      rows: [
        [L('Muntazam piramida', 'Правильная пирамида', 'Regular pyramid'), L('½·P·l', '½·P·l', '½·P·l'), L('⅓·S·h', '⅓·S·h', '⅓·S·h')],
        [L('Konus', 'Конус', 'Cone'), L('πrl', 'πrl', 'πrl'), L('⅓πr²h', '⅓πr²h', '⅓πr²h')],
        [L('Kesik piramida', 'Усечённая пирамида', 'Frustum of a pyramid'), L('½(P₁ + P₂)·l', '½(P₁ + P₂)·l', '½(P₁ + P₂)·l'), L('⅓h(S₁ + S₂ + √(S₁S₂))', '⅓h(S₁ + S₂ + √(S₁S₂))', '⅓h(S₁ + S₂ + √(S₁S₂))')],
        [L('Kesik konus', 'Усечённый конус', 'Truncated cone'), L('π(r₁ + r₂)l', 'π(r₁ + r₂)l', 'π(r₁ + r₂)l'), L('⅓πh(r₁² + r₁r₂ + r₂²)', '⅓πh(r₁² + r₁r₂ + r₂²)', '⅓πh(r₁² + r₁r₂ + r₂²)')]
      ] }, after: [
      L('Jadvaldagi har bir «yumaloq» formula «qirrali» formuladan P → 2πr, S → πr² almashtirish bilan olinadi.', 'Каждая «круглая» формула таблицы получается из «гранёной» заменой P → 2πr, S → πr².', 'Every “round” formula in the table comes from the “faceted” one by replacing P → 2πr and S → πr².')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Решённые примеры', 'Worked examples'), ex: [
      { q: L('Konus asosining radiusi 3, balandligi 4. Yon sirti, to‘la sirti va hajmini toping.', 'Радиус основания конуса 3, высота 4. Найдите боковую, полную поверхность и объём.', 'A cone has base radius 3 and height 4. Find its lateral area, total area and volume.'),
        s: L('l = √(9 + 16) = 5. S<sub>yon</sub> = π·3·5 = 15π. S<sub>to‘la</sub> = π·3·(3 + 5) = 24π. V = ⅓·π·9·4 = 12π ≈ 37,7.', 'l = √(9 + 16) = 5. S<sub>бок</sub> = π·3·5 = 15π. S<sub>полн</sub> = π·3·(3 + 5) = 24π. V = ⅓·π·9·4 = 12π ≈ 37,7.', 'l = √(9 + 16) = 5. S<sub>lat</sub> = π·3·5 = 15π. S<sub>tot</sub> = π·3·(3 + 5) = 24π. V = ⅓·π·9·4 = 12π ≈ 37.7.') },
      { q: L('Konusning o‘q kesimi tomoni 6 bo‘lgan teng tomonli uchburchak. Yon sirt, hajm va yoyilma burchagini toping.', 'Осевое сечение конуса — равносторонний треугольник со стороной 6. Найдите боковую поверхность, объём и угол развёртки.', 'The axial section of a cone is an equilateral triangle of side 6. Find the lateral area, volume and net angle.'),
        s: L('r = 3, l = 6, h = 6·√3/2 = 3√3. S<sub>yon</sub> = π·3·6 = 18π. V = ⅓·π·9·3√3 = 9√3π ≈ 49. Yoyilma burchagi 360°·3/6 = 180° — yarim doira.', 'r = 3, l = 6, h = 6·√3/2 = 3√3. S<sub>бок</sub> = π·3·6 = 18π. V = ⅓·π·9·3√3 = 9√3π ≈ 49. Угол развёртки 360°·3/6 = 180° — полукруг.', 'r = 3, l = 6, h = 6·√3/2 = 3√3. S<sub>lat</sub> = π·3·6 = 18π. V = ⅓·π·9·3√3 = 9√3π ≈ 49. Net angle 360°·3/6 = 180° — a half-disc.') },
      { q: L('Radiusi 10, markaziy burchagi 216° bo‘lgan sektordan konus yasaldi. Konus hajmini toping.', 'Из сектора радиуса 10 с центральным углом 216° свернули конус. Найдите его объём.', 'A cone is rolled from a sector of radius 10 and central angle 216°. Find its volume.'),
        s: L('Yasovchi l = 10. 216° = 360°·r/10 ⇒ r = 6. h = √(100 − 36) = 8. V = ⅓·π·36·8 = 96π ≈ 301,6.', 'Образующая l = 10. 216° = 360°·r/10 ⇒ r = 6. h = √(100 − 36) = 8. V = ⅓·π·36·8 = 96π ≈ 301,6.', 'Slant height l = 10. 216° = 360°·r/10 ⇒ r = 6. h = √(100 − 36) = 8. V = ⅓·π·36·8 = 96π ≈ 301.6.') },
      { q: L('Kesik konus: r₁ = 6, r₂ = 3, h = 4. To‘la sirt va hajmni toping.', 'Усечённый конус: r₁ = 6, r₂ = 3, h = 4. Найдите полную поверхность и объём.', 'Truncated cone: r₁ = 6, r₂ = 3, h = 4. Find the total surface area and volume.'),
        s: L('l = √(16 + 9) = 5. S<sub>yon</sub> = π·9·5 = 45π; asoslar 36π + 9π = 45π; S = 90π. V = ⅓·π·4·(36 + 18 + 9) = ⅓·π·4·63 = 84π.', 'l = √(16 + 9) = 5. S<sub>бок</sub> = π·9·5 = 45π; основания 36π + 9π = 45π; S = 90π. V = ⅓·π·4·(36 + 18 + 9) = ⅓·π·4·63 = 84π.', 'l = √(16 + 9) = 5. S<sub>lat</sub> = π·9·5 = 45π; bases 36π + 9π = 45π; S = 90π. V = ⅓·π·4·(36 + 18 + 9) = ⅓·π·4·63 = 84π.') },
      { q: L('Chelak kesik konus shaklida: tubi radiusi 10 sm, og‘zi radiusi 15 sm, balandligi 30 sm. Necha litr suv sig‘adi?', 'Ведро имеет форму усечённого конуса: радиус дна 10 см, радиус верха 15 см, высота 30 см. Сколько литров воды оно вмещает?', 'A bucket is a truncated cone: bottom radius 10 cm, top radius 15 cm, height 30 cm. How many litres does it hold?'),
        s: L('V = ⅓·π·30·(225 + 150 + 100) = 10π·475 = 4750π ≈ 14 923 sm³ ≈ 14,9 l (1 l = 1000 sm³).', 'V = ⅓·π·30·(225 + 150 + 100) = 10π·475 = 4750π ≈ 14 923 см³ ≈ 14,9 л (1 л = 1000 см³).', 'V = ⅓·π·30·(225 + 150 + 100) = 10π·475 = 4750π ≈ 14,923 cm³ ≈ 14.9 L (1 L = 1000 cm³).') }
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>Yon sirtda l o‘rniga h olish:</b> S<sub>yon</sub> = πrl, πrh emas! Yasovchi har doim balandlikdan uzun.', '<b>Берут h вместо l в боковой поверхности:</b> S<sub>бок</sub> = πrl, а не πrh! Образующая всегда длиннее высоты.', '<b>Using h instead of l in the lateral area:</b> S<sub>lat</sub> = πrl, not πrh! The slant height is always longer than the height.'),
      L('<b>Hajmda h o‘rniga l olish:</b> V = ⅓πr²h — bu yerda aynan balandlik kerak.', '<b>Берут l вместо h в объёме:</b> V = ⅓πr²h — здесь нужна именно высота.', '<b>Using l instead of h in the volume:</b> V = ⅓πr²h needs the true height.'),
      L('<b>Diametrni radius deb olish</b> — masalada «asos diametri 8» deyilsa, r = 4.', '<b>Принимают диаметр за радиус</b> — если в задаче «диаметр основания 8», то r = 4.', '<b>Taking the diameter for the radius</b> — if the problem says “base diameter 8”, then r = 4.'),
      L('<b>Yoyilma sektori radiusini r deb olish.</b> Sektor radiusi — yasovchi l, uning yoyi esa 2πr.', '<b>Считают радиус сектора развёртки равным r.</b> Радиус сектора — образующая l, а его дуга равна 2πr.', '<b>Taking r as the radius of the net sector.</b> The sector’s radius is the slant height l; its arc is 2πr.'),
      L('<b>Kesik konusda l² = h² + (r₁ + r₂)² deb yozish</b> — radiuslar ayirmasi olinadi: (r₁ − r₂)².', '<b>Пишут l² = h² + (r₁ + r₂)² для усечённого конуса</b> — берётся разность радиусов: (r₁ − r₂)².', '<b>Writing l² = h² + (r₁ + r₂)² for a truncated cone</b> — it is the difference of radii: (r₁ − r₂)².')
    ] },
    { kind: 'life', h: L('Hayotda konus', 'Конус в жизни', 'Cones in real life'), p: [
      L('<b>Sochiluvchan materiallar.</b> Qum, shag‘al, don yoki tuz to‘kilganda u ma’lum burchakdan tikroq bo‘lmagan konus hosil qiladi — bu <b>tabiiy qiyalik burchagi</b> (quruq qum uchun taxminan 30–35°). Uyum asosining diametri o‘lchansa, balandligi h = r·tg α bilan, hajmi esa ⅓πr²h bilan topiladi. Elevatorlar va qurilish maydonchalarida aynan shunday hisoblanadi.', '<b>Сыпучие материалы.</b> Высыпанный песок, щебень, зерно или соль образуют конус, не круче определённого угла — <b>угла естественного откоса</b> (для сухого песка около 30–35°). Измерив диаметр основания кучи, находят высоту h = r·tg α и объём ⅓πr²h. Так считают на элеваторах и стройках.', '<b>Bulk materials.</b> Poured sand, gravel, grain or salt forms a cone no steeper than a certain angle — the <b>angle of repose</b> (about 30–35° for dry sand). Measuring the heap’s base diameter gives the height h = r·tan α and the volume ⅓πr²h. This is how grain elevators and building sites estimate stock.'),
      L('<b>Buyumlar.</b> Chelaklar, gul tuvaklari, stakanlar kesik konus shaklida yasaladi: ular bir-birining ichiga joylashadi va qolipdan oson chiqadi. Voronka, abajur, karnay, raketa burni, minora va o‘tov tomi — konus yoki kesik konus. <b>Optika va yorug‘lik:</b> fonar yoki projektor nuri konus shaklida tarqaladi; yoritilgan doira radiusi masofaga proporsional o‘sadi. <b>Geologiya:</b> Fudziyama yoki Kilimanjaro kabi vulqonlarning hajmini geologlar kesik konus formulasi bilan baholaydi.', '<b>Предметы.</b> Вёдра, цветочные горшки, стаканы делают в форме усечённого конуса: они вкладываются друг в друга и легко выходят из формы. Воронка, абажур, рупор, нос ракеты, крыша башни и юрты — конус или усечённый конус. <b>Оптика:</b> луч фонаря или прожектора расходится конусом; радиус освещённого круга растёт пропорционально расстоянию. <b>Геология:</b> объёмы вулканов вроде Фудзиямы или Килиманджаро оценивают по формуле усечённого конуса.', '<b>Objects.</b> Buckets, flower pots and cups are made as truncated cones: they nest inside each other and leave the mould easily. Funnels, lampshades, megaphones, rocket nose cones and the roofs of towers and yurts are cones or truncated cones. <b>Optics:</b> a torch or searchlight beam spreads as a cone; the radius of the lit circle grows in proportion to the distance. <b>Geology:</b> geologists estimate the volume of volcanoes like Fuji or Kilimanjaro with the truncated-cone formula.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Konus — to‘g‘ri burchakli uchburchakni katet atrofida aylantirishdan hosil bo‘ladi; l² = r² + h².', 'Конус получается вращением прямоугольного треугольника вокруг катета; l² = r² + h².', 'A cone comes from rotating a right triangle about a leg; l² = r² + h².'),
      L('Yon sirt yoyilmasi — radiusi l, burchagi 360°·r/l bo‘lgan sektor; S<sub>yon</sub> = πrl, S<sub>to‘la</sub> = πr(r + l).', 'Развёртка боковой поверхности — сектор радиуса l с углом 360°·r/l; S<sub>бок</sub> = πrl, S<sub>полн</sub> = πr(r + l).', 'The lateral net is a sector of radius l and angle 360°·r/l; S<sub>lat</sub> = πrl, S<sub>tot</sub> = πr(r + l).'),
      L('Hajm V = ⅓πr²h — shu asos va balandlikdagi silindrning uchdan biri.', 'Объём V = ⅓πr²h — треть цилиндра с тем же основанием и высотой.', 'Volume V = ⅓πr²h — one third of the cylinder with the same base and height.'),
      L('Kesik konus: l² = h² + (r₁ − r₂)², S<sub>yon</sub> = π(r₁ + r₂)l, V = ⅓πh(r₁² + r₁r₂ + r₂²).', 'Усечённый конус: l² = h² + (r₁ − r₂)², S<sub>бок</sub> = π(r₁ + r₂)l, V = ⅓πh(r₁² + r₁r₂ + r₂²).', 'Truncated cone: l² = h² + (r₁ − r₂)², S<sub>lat</sub> = π(r₁ + r₂)l, V = ⅓πh(r₁² + r₁r₂ + r₂²).'),
      L('Konus formulalari piramida formulalaridan P → 2πr, S → πr² bilan olinadi.', 'Формулы конуса получаются из формул пирамиды заменой P → 2πr, S → πr².', 'Cone formulas come from pyramid formulas via P → 2πr, S → πr².'),
      L('Konus kesimlari — ellips, parabola, giperbola — Apolloniy tomonidan o‘rganilgan va bugun optika hamda astronomiyada ishlatiladi.', 'Конические сечения — эллипс, парабола, гипербола — изучены Аполлонием и сегодня применяются в оптике и астрономии.', 'Conic sections — ellipse, parabola, hyperbola — were studied by Apollonius and are used today in optics and astronomy.')
    ] }
  ] });


  // ---------- t11. Shar va uning elementlari ----------
  T.add(P, 't11', { sections: [
    { kind: 'intro', h: L('Eng mukammal shakl', 'Самая совершенная форма', 'The most perfect shape'), p: [
      L('Suv tomchisi, sovun pufagi, sayyoralar, yulduzlar, ko‘z olmasi, futbol to‘pi — tabiat va texnika sharsimon shakllarni juda yaxshi ko‘radi. Sababi oddiy: shar barcha yo‘nalishlarda bir xil, uning sirtidagi har bir nuqta markazdan bir xil uzoqlikda. Qadimgi yunonlar sharni «eng mukammal jism» deb atashgan va osmon jismlari aynan shar shaklida bo‘lishi kerak, deb hisoblashgan.', 'Капля воды, мыльный пузырь, планеты, звёзды, глазное яблоко, футбольный мяч — природа и техника очень любят шарообразные формы. Причина проста: шар одинаков во всех направлениях, каждая точка его поверхности одинаково удалена от центра. Древние греки называли шар «самым совершенным телом» и считали, что небесные тела должны иметь именно такую форму.', 'A drop of water, a soap bubble, planets, stars, the eyeball, a football — nature and technology love spherical shapes. The reason is simple: a ball is the same in every direction, and every point of its surface is equally far from the centre. The ancient Greeks called the ball “the most perfect solid” and believed that heavenly bodies must have exactly this shape.'),
      L('Bu mavzuda <b>sfera</b> va <b>shar</b>ni aniq ta’riflaymiz, ularning koordinatalardagi tenglamasini yozamiz, sharni tekislik bilan kesganda nima hosil bo‘lishini isbotlaymiz va urinma tekislik bilan tanishamiz. Geografiyadagi parallellar va meridianlar, GPS navigatsiyasi va hatto Yer radiusini o‘lchash — barchasi shu mavzuga tayanadi.', 'В этой теме мы точно определим <b>сферу</b> и <b>шар</b>, запишем их уравнение в координатах, докажем, что получается при сечении шара плоскостью, и познакомимся с касательной плоскостью. Параллели и меридианы в географии, GPS-навигация и даже измерение радиуса Земли — всё опирается на эту тему.', 'In this topic we define the <b>sphere</b> and the <b>ball</b> precisely, write their coordinate equation, prove what a plane cuts out of a ball and meet the tangent plane. Parallels and meridians in geography, GPS navigation and even measuring the Earth’s radius all rest on this topic.')
    ] },
    { kind: 'def', h: L('Sfera, shar va ularning elementlari', 'Сфера, шар и их элементы', 'Sphere, ball and their elements'), p: [
      L('Fazoda berilgan O nuqtadan berilgan R masofada yotgan barcha nuqtalar to‘plami <b>sfera</b> deyiladi. O — sferaning <b>markazi</b>, R — <b>radiusi</b>. Sfera bilan chegaralangan jism, ya’ni O dan R dan katta bo‘lmagan masofadagi barcha nuqtalar to‘plami <b>shar</b> deyiladi. Demak, sfera — sirt (qobiq), shar esa jism: futbol to‘pining terisi sferaga, tarvuz esa sharga o‘xshaydi.', 'Множество всех точек пространства, находящихся на данном расстоянии R от данной точки O, называется <b>сферой</b>. O — <b>центр</b> сферы, R — её <b>радиус</b>. Тело, ограниченное сферой, то есть множество всех точек на расстоянии не больше R от O, называется <b>шаром</b>. Итак, сфера — поверхность (оболочка), а шар — тело: покрышка футбольного мяча похожа на сферу, а арбуз — на шар.', 'The set of all points in space at a given distance R from a given point O is called a <b>sphere</b>. O is its <b>centre</b> and R its <b>radius</b>. The solid bounded by the sphere, i.e. all points at distance at most R from O, is called a <b>ball</b>. So a sphere is a surface (a shell) while a ball is a solid: the skin of a football resembles a sphere, a watermelon a ball.'),
      L('Sferaning ikki nuqtasini tutashtiruvchi kesma — <b>vatar</b>, markazdan o‘tuvchi vatar — <b>diametr</b> (d = 2R). Diametrning uchlari <b>diametral qarama-qarshi</b> nuqtalar deyiladi, masalan, Yerning Shimoliy va Janubiy qutblari. Sharni yarim doirani diametri atrofida aylantirish bilan ham hosil qilish mumkin — shuning uchun shar ham aylanma jism, xuddi silindr va konus kabi.', 'Отрезок, соединяющий две точки сферы, — <b>хорда</b>, хорда через центр — <b>диаметр</b> (d = 2R). Концы диаметра называются <b>диаметрально противоположными</b> точками, например Северный и Южный полюсы Земли. Шар можно получить и вращением полукруга вокруг диаметра — поэтому шар тоже тело вращения, как цилиндр и конус.', 'A segment joining two points of the sphere is a <b>chord</b>; a chord through the centre is a <b>diameter</b> (d = 2R). The ends of a diameter are <b>antipodal</b> points, such as the Earth’s North and South Poles. A ball can also be obtained by rotating a half-disc about its diameter — so the ball, like the cylinder and cone, is a solid of revolution.')
    ] },
    { kind: 'rule', h: L('Sfera tenglamasi', 'Уравнение сферы', 'Equation of a sphere'), p: [
      L('To‘g‘ri burchakli koordinatalar sistemasida markazi O(a; b; c), radiusi R bo‘lgan sfera tenglamasi: <b>(x − a)² + (y − b)² + (z − c)² = R²</b>. Isbot fazodagi ikki nuqta orasidagi masofa formulasidan kelib chiqadi: M(x; y; z) nuqta sferada yotadi ⇔ OM = R ⇔ OM² = R². Markaz koordinatalar boshida bo‘lsa, x² + y² + z² = R².', 'В прямоугольной системе координат сфера с центром O(a; b; c) и радиусом R имеет уравнение <b>(x − a)² + (y − b)² + (z − c)² = R²</b>. Это следует из формулы расстояния между точками: M(x; y; z) лежит на сфере ⇔ OM = R ⇔ OM² = R². Если центр в начале координат, x² + y² + z² = R².', 'In Cartesian coordinates the sphere with centre O(a; b; c) and radius R has equation <b>(x − a)² + (y − b)² + (z − c)² = R²</b>. This follows from the distance formula: M(x; y; z) lies on the sphere ⇔ OM = R ⇔ OM² = R². With the centre at the origin, x² + y² + z² = R².'),
      L('Shar tengsizlik bilan beriladi: (x − a)² + (y − b)² + (z − c)² ≤ R². Nuqtaning sferaga nisbatan holatini aniqlash uchun uning markazdan masofasini R bilan solishtiramiz: kichik bo‘lsa — ichkarida, teng bo‘lsa — sferada, katta bo‘lsa — tashqarida. Agar tenglama qavslar ochilgan holda berilsa (x² + y² + z² + Ax + By + Cz + D = 0), to‘la kvadrat ajratish usuli bilan markaz va radius topiladi.', 'Шар задаётся неравенством: (x − a)² + (y − b)² + (z − c)² ≤ R². Чтобы определить положение точки относительно сферы, сравниваем её расстояние до центра с R: меньше — внутри, равно — на сфере, больше — снаружи. Если уравнение дано с раскрытыми скобками (x² + y² + z² + Ax + By + Cz + D = 0), центр и радиус находят выделением полного квадрата.', 'A ball is given by an inequality: (x − a)² + (y − b)² + (z − c)² ≤ R². To locate a point relative to the sphere, compare its distance from the centre with R: smaller — inside, equal — on the sphere, larger — outside. If the equation is given expanded (x² + y² + z² + Ax + By + Cz + D = 0), complete the squares to find the centre and radius.')
    ] },
    { kind: 'history', h: L('Eratosfen va Beruniy Yerni o‘lchaydi', 'Эратосфен и Беруни измеряют Землю', 'Eratosthenes and al-Biruni measure the Earth'), p: [
      L('Yerning shar shaklida ekanini Pifagorchilar taxmin qilgan, <b>Aristotel</b> (mil. av. IV asr) esa dalil keltirgan: Oy tutilishida Yer soyasi doim yumaloq. Mil. av. III asrda <b>Eratosfen</b> Siyena va Iskandariyada quyosh nurlari tushish burchagidagi farqdan (taxminan 7,2° — aylananing 1/50 qismi) Yer aylanasi uzunligini hisobladi va zamonaviy qiymatga ancha yaqin natija oldi.', 'О шарообразности Земли догадывались пифагорейцы, а <b>Аристотель</b> (IV в. до н. э.) привёл доводы: при лунном затмении тень Земли всегда круглая. В III веке до н. э. <b>Эратосфен</b> по разнице углов падения солнечных лучей в Сиене и Александрии (около 7,2° — 1/50 окружности) вычислил длину окружности Земли и получил результат, довольно близкий к современному.', 'The Pythagoreans guessed that the Earth is round, and <b>Aristotle</b> (4th century BC) gave evidence: during a lunar eclipse the Earth’s shadow is always round. In the 3rd century BC <b>Eratosthenes</b> used the difference in the angle of sunlight at Syene and Alexandria (about 7.2°, 1/50 of a circle) to compute the Earth’s circumference, obtaining a result fairly close to the modern one.'),
      L('XI asrda xorazmlik buyuk olim <b>Abu Rayhon Beruniy</b> ancha qulay usulni o‘ylab topdi. Hozirgi Pokiston hududidagi Nandana qal’asi yonidagi tog‘ cho‘qqisiga chiqib, u avval tog‘ balandligini, so‘ng cho‘qqidan ufqning pastga og‘ish burchagini o‘lchadi. Ufqqa qarab o‘tgan nur sferaga urinma bo‘lgani uchun u Yer markazi bilan to‘g‘ri burchakli uchburchak hosil qiladi: cos α = R/(R + h). Bundan Beruniy Yer radiusini taxminan 6340 km deb topdi — zamonaviy 6371 km dan atigi 0,5% ga farq qiladi! Bu natija «Qonuni Mas’udiy» asarida bayon etilgan.', 'В XI веке великий учёный из Хорезма <b>Абу Райхан Беруни</b> придумал гораздо более удобный способ. Поднявшись на гору у крепости Нандана (на территории нынешнего Пакистана), он сначала измерил высоту горы, а затем угол понижения горизонта с вершины. Луч к горизонту касается сферы, поэтому образует с центром Земли прямоугольный треугольник: cos α = R/(R + h). Отсюда Беруни нашёл радиус Земли около 6340 км — лишь на 0,5% меньше современных 6371 км! Результат изложен в «Каноне Масуда».', 'In the 11th century the great Khwarazmian scholar <b>Abu Rayhan al-Biruni</b> invented a much handier method. Climbing a mountain near the fort of Nandana (in today’s Pakistan), he first measured the mountain’s height and then the dip angle of the horizon from the summit. The line of sight to the horizon is tangent to the sphere, so it forms a right triangle with the Earth’s centre: cos α = R/(R + h). From this al-Biruni found the Earth’s radius to be about 6,340 km — only 0.5% less than the modern 6,371 km! The result is described in his “Mas’udi Canon”.')
    ] },
    { kind: 'rule', h: L('Sharning tekislik bilan kesimi', 'Сечение шара плоскостью', 'Plane section of a ball'), p: [
      L('<b>Teorema.</b> Sharning tekislik bilan har qanday kesimi doiradir. Bu doiraning markazi — shar markazidan kesuvchi tekislikka tushirilgan perpendikulyar asosi, radiusi esa <b>r = √(R² − d²)</b>, bu yerda d — markazdan tekislikkacha masofa.', '<b>Теорема.</b> Любое сечение шара плоскостью есть круг. Его центр — основание перпендикуляра, опущенного из центра шара на секущую плоскость, а радиус <b>r = √(R² − d²)</b>, где d — расстояние от центра до плоскости.', '<b>Theorem.</b> Every plane section of a ball is a disc. Its centre is the foot of the perpendicular from the ball’s centre to the cutting plane, and its radius is <b>r = √(R² − d²)</b>, where d is the distance from the centre to the plane.'),
      L('<b>Isbot.</b> O — shar markazi, OK — tekislikka perpendikulyar, OK = d. Kesimning ixtiyoriy M nuqtasini olamiz. OKM uchburchak to‘g‘ri burchakli (OK tekislikdagi KM ga perpendikulyar), shuning uchun KM² = OM² − d². M sharga tegishli ⇔ OM ≤ R ⇔ KM ≤ √(R² − d²). Demak, kesim — markazi K, radiusi √(R² − d²) bo‘lgan doira. ∎', '<b>Доказательство.</b> O — центр шара, OK — перпендикуляр к плоскости, OK = d. Возьмём любую точку M сечения. Треугольник OKM прямоугольный (OK перпендикулярен KM, лежащей в плоскости), поэтому KM² = OM² − d². M принадлежит шару ⇔ OM ≤ R ⇔ KM ≤ √(R² − d²). Значит, сечение — круг с центром K и радиусом √(R² − d²). ∎', '<b>Proof.</b> Let O be the centre and OK the perpendicular to the plane, OK = d. Take any point M of the section. Triangle OKM is right-angled (OK is perpendicular to KM, which lies in the plane), so KM² = OM² − d². M belongs to the ball ⇔ OM ≤ R ⇔ KM ≤ √(R² − d²). Hence the section is the disc with centre K and radius √(R² − d²). ∎'),
      L('Markazdan uzoqlashgan sari kesim kichrayadi. Eng katta kesim d = 0 da — markazdan o‘tuvchi tekislik bilan: uning radiusi R ga teng va u <b>katta doira</b> deyiladi (sferada — <b>katta aylana</b>). Ekvator va barcha meridianlar — Yerning katta aylanalari, ekvatordan boshqa parallellar esa kichik aylanalar.', 'Чем дальше от центра, тем меньше сечение. Наибольшее сечение при d = 0 — плоскостью через центр: его радиус равен R, и оно называется <b>большим кругом</b> (на сфере — <b>большой окружностью</b>). Экватор и все меридианы — большие окружности Земли, а остальные параллели — малые.', 'The farther from the centre, the smaller the section. The largest one, at d = 0, is cut by a plane through the centre: its radius is R and it is called a <b>great circle</b>. The equator and all meridians are great circles of the Earth, while the other parallels are small circles.')
    ] },
    { kind: 'rule', h: L('Tekislik va sferaning o‘zaro joylashuvi. Urinma tekislik', 'Взаимное расположение плоскости и сферы. Касательная плоскость', 'Plane and sphere. The tangent plane'), p: [
      L('Markazdan tekislikkacha masofa d bo‘lsin. Uch hol bor: 1) <b>d &lt; R</b> — tekislik sferani aylana bo‘yicha kesadi; 2) <b>d = R</b> — tekislik va sfera yagona umumiy nuqtaga ega, tekislik <b>urinma</b> deyiladi; 3) <b>d &gt; R</b> — umumiy nuqta yo‘q. Bu tekislikdagi to‘g‘ri chiziq va aylananing o‘zaro joylashuviga to‘liq o‘xshash.', 'Пусть расстояние от центра до плоскости равно d. Возможны три случая: 1) <b>d &lt; R</b> — плоскость пересекает сферу по окружности; 2) <b>d = R</b> — у плоскости и сферы одна общая точка, плоскость называется <b>касательной</b>; 3) <b>d &gt; R</b> — общих точек нет. Это полностью аналогично взаимному расположению прямой и окружности на плоскости.', 'Let d be the distance from the centre to the plane. There are three cases: 1) <b>d &lt; R</b> — the plane cuts the sphere in a circle; 2) <b>d = R</b> — the plane and sphere share exactly one point, and the plane is called <b>tangent</b>; 3) <b>d &gt; R</b> — no common points. This is fully analogous to a line and a circle in the plane.'),
      L('<b>Teorema.</b> Sferaning urinma tekisligi urinish nuqtasiga o‘tkazilgan radiusga perpendikulyar. Aksincha, radius uchidan unga perpendikulyar o‘tkazilgan tekislik urinma bo‘ladi. <b>Isbot g‘oyasi:</b> agar OA radius α tekislikka perpendikulyar bo‘lmasa, O dan α gacha masofa OA = R dan kichik bo‘lar edi, ya’ni d &lt; R va tekislik sferani aylana bo‘yicha kesar edi — urinish emas. Sferaga urinma to‘g‘ri chiziq ham xuddi shunday: u urinish nuqtasidagi radiusga perpendikulyar va urinma tekislikda yotadi.', '<b>Теорема.</b> Касательная плоскость к сфере перпендикулярна радиусу, проведённому в точку касания. Обратно, плоскость, перпендикулярная радиусу в его конце, — касательная. <b>Идея доказательства:</b> если радиус OA не перпендикулярен плоскости α, то расстояние от O до α меньше OA = R, т. е. d &lt; R, и плоскость пересекает сферу по окружности — касания нет. С касательной прямой так же: она перпендикулярна радиусу в точке касания и лежит в касательной плоскости.', '<b>Theorem.</b> A tangent plane to a sphere is perpendicular to the radius drawn to the point of contact. Conversely, the plane perpendicular to a radius at its endpoint is tangent. <b>Proof idea:</b> if radius OA were not perpendicular to plane α, the distance from O to α would be less than OA = R, i.e. d &lt; R, and the plane would cut the sphere in a circle — not tangency. Likewise a tangent line is perpendicular to the radius at the point of contact and lies in the tangent plane.')
    ] },
    { kind: 'rule', h: L('Ko‘pyoqlarga ichki va tashqi chizilgan sferalar', 'Сферы, вписанные в многогранники и описанные около них', 'Spheres inscribed in and circumscribed about polyhedra'), p: [
      L('Agar ko‘pyoqning barcha uchlari sferada yotsa, sfera ko‘pyoqqa <b>tashqi chizilgan</b> deyiladi; agar sfera ko‘pyoqning barcha yoqlariga urinsa — <b>ichki chizilgan</b>. Qirrasi a bo‘lgan kub uchun: ichki chizilgan sfera radiusi <b>a/2</b> (markazdan yoqqacha), tashqi chizilgan sfera radiusi <b>a√3/2</b> (kub diagonalining yarmi), barcha qirralarga urinuvchi sfera radiusi esa <b>a√2/2</b> (yoq diagonalining yarmi).', 'Если все вершины многогранника лежат на сфере, сфера называется <b>описанной</b> около него; если сфера касается всех граней — <b>вписанной</b>. Для куба с ребром a: радиус вписанной сферы <b>a/2</b> (от центра до грани), описанной — <b>a√3/2</b> (половина диагонали куба), а сферы, касающейся всех рёбер, — <b>a√2/2</b> (половина диагонали грани).', 'If all vertices of a polyhedron lie on a sphere, the sphere is <b>circumscribed</b> about it; if the sphere touches all faces, it is <b>inscribed</b>. For a cube of edge a: the inscribed sphere has radius <b>a/2</b> (centre to face), the circumscribed one <b>a√3/2</b> (half the cube’s diagonal), and the sphere touching all edges <b>a√2/2</b> (half a face diagonal).'),
      L('Har qanday tetraedrga ham ichki, ham tashqi sfera chizish mumkin. Muntazam piramidada tashqi sfera markazi balandlikda yotadi va R<sub>sf</sub> = b²/(2h) formula bilan topiladi (b — yon qirra, h — balandlik): bu yon qirra va balandlik orqali o‘tgan kesimdagi uchburchakka tashqi chizilgan aylanadan kelib chiqadi.', 'Около любого тетраэдра можно описать сферу и в любой тетраэдр — вписать. В правильной пирамиде центр описанной сферы лежит на высоте, а радиус R<sub>сф</sub> = b²/(2h) (b — боковое ребро, h — высота): это следует из окружности, описанной около треугольника в сечении через боковое ребро и высоту.', 'Every tetrahedron has both an inscribed and a circumscribed sphere. In a regular pyramid the circumcentre lies on the height and the radius is R<sub>sph</sub> = b²/(2h) (b the lateral edge, h the height): this follows from the circle circumscribed about the triangle in the section through a lateral edge and the height.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Решённые примеры', 'Worked examples'), ex: [
      { q: L('Radiusi 13 bo‘lgan shar markazdan 5 masofadagi tekislik bilan kesildi. Kesim yuzini toping.', 'Шар радиуса 13 пересечён плоскостью на расстоянии 5 от центра. Найдите площадь сечения.', 'A ball of radius 13 is cut by a plane at distance 5 from the centre. Find the area of the section.'),
        s: L('r = √(169 − 25) = √144 = 12. S = πr² = 144π ≈ 452,4.', 'r = √(169 − 25) = √144 = 12. S = πr² = 144π ≈ 452,4.', 'r = √(169 − 25) = √144 = 12. S = πr² = 144π ≈ 452.4.') },
      { q: L('x² + y² + z² − 4x + 6y − 2z − 2 = 0 sferaning markazi va radiusini toping.', 'Найдите центр и радиус сферы x² + y² + z² − 4x + 6y − 2z − 2 = 0.', 'Find the centre and radius of the sphere x² + y² + z² − 4x + 6y − 2z − 2 = 0.'),
        s: L('To‘la kvadratlar: (x − 2)² − 4 + (y + 3)² − 9 + (z − 1)² − 1 − 2 = 0 ⇒ (x − 2)² + (y + 3)² + (z − 1)² = 16. Markaz (2; −3; 1), R = 4.', 'Полные квадраты: (x − 2)² − 4 + (y + 3)² − 9 + (z − 1)² − 1 − 2 = 0 ⇒ (x − 2)² + (y + 3)² + (z − 1)² = 16. Центр (2; −3; 1), R = 4.', 'Completing squares: (x − 2)² − 4 + (y + 3)² − 9 + (z − 1)² − 1 − 2 = 0 ⇒ (x − 2)² + (y + 3)² + (z − 1)² = 16. Centre (2; −3; 1), R = 4.') },
      { q: L('Radiusi 10 bo‘lgan sharda ikkita parallel kesim radiuslari 6 va 8. Kesimlar orasidagi masofani toping.', 'В шаре радиуса 10 проведены два параллельных сечения радиусов 6 и 8. Найдите расстояние между ними.', 'In a ball of radius 10 two parallel sections have radii 6 and 8. Find the distance between them.'),
        s: L('d₁ = √(100 − 36) = 8, d₂ = √(100 − 64) = 6. Kesimlar markazning bir tomonida bo‘lsa: 8 − 6 = 2; turli tomonlarida bo‘lsa: 8 + 6 = 14. Javob: 2 yoki 14.', 'd₁ = √(100 − 36) = 8, d₂ = √(100 − 64) = 6. Если сечения по одну сторону от центра: 8 − 6 = 2; по разные: 8 + 6 = 14. Ответ: 2 или 14.', 'd₁ = √(100 − 36) = 8, d₂ = √(100 − 64) = 6. If the sections are on the same side of the centre: 8 − 6 = 2; on opposite sides: 8 + 6 = 14. Answer: 2 or 14.') },
      { q: L('Yer radiusini 6371 km deb, 60° shimoliy kenglikdagi parallel uzunligini toping.', 'Считая радиус Земли 6371 км, найдите длину параллели на 60° северной широты.', 'Taking the Earth’s radius as 6,371 km, find the length of the parallel at 60° N.'),
        s: L('Parallel — sharning ekvator tekisligiga parallel kesimi; uning radiusi r = R·cos 60° = 3185,5 km (markazdan masofa d = R·sin 60°). Uzunlik 2πr ≈ 2·3,1416·3185,5 ≈ 20 015 km — ekvatorning roppa-rosa yarmi.', 'Параллель — сечение шара плоскостью, параллельной экватору; её радиус r = R·cos 60° = 3185,5 км (расстояние от центра d = R·sin 60°). Длина 2πr ≈ 2·3,1416·3185,5 ≈ 20 015 км — ровно половина экватора.', 'A parallel is a section of the ball by a plane parallel to the equator; its radius is r = R·cos 60° = 3,185.5 km (distance from the centre d = R·sin 60°). Length 2πr ≈ 2·3.1416·3,185.5 ≈ 20,015 km — exactly half the equator.') },
      { q: L('A(2; 2; 1) nuqta x² + y² + z² = 9 sferaga nisbatan qanday joylashgan? B(2; 2; 2) nuqta-chi?', 'Как расположена точка A(2; 2; 1) относительно сферы x² + y² + z² = 9? А точка B(2; 2; 2)?', 'Where is A(2; 2; 1) relative to the sphere x² + y² + z² = 9? And B(2; 2; 2)?'),
        s: L('R = 3. OA² = 4 + 4 + 1 = 9 ⇒ OA = 3 — A sferada yotadi. OB² = 12 ⇒ OB = 2√3 ≈ 3,46 &gt; 3 — B sferadan tashqarida.', 'R = 3. OA² = 4 + 4 + 1 = 9 ⇒ OA = 3 — A лежит на сфере. OB² = 12 ⇒ OB = 2√3 ≈ 3,46 &gt; 3 — B вне сферы.', 'R = 3. OA² = 4 + 4 + 1 = 9 ⇒ OA = 3 — A lies on the sphere. OB² = 12 ⇒ OB = 2√3 ≈ 3.46 &gt; 3 — B is outside.') }
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>Sfera va sharni chalkashtirish.</b> Sfera — sirt, uning yuzi bor; shar — jism, uning hajmi bor.', '<b>Путают сферу и шар.</b> Сфера — поверхность, у неё площадь; шар — тело, у него объём.', '<b>Confusing sphere and ball.</b> A sphere is a surface with an area; a ball is a solid with a volume.'),
      L('<b>r = R − d deb yozish.</b> To‘g‘ri formula Pifagor teoremasidan: r = √(R² − d²). Masalan, R = 5, d = 3 da r = 4, 2 emas.', '<b>Пишут r = R − d.</b> Верная формула — из теоремы Пифагора: r = √(R² − d²). Например, при R = 5, d = 3 r = 4, а не 2.', '<b>Writing r = R − d.</b> The correct formula comes from Pythagoras: r = √(R² − d²). For R = 5, d = 3, r = 4, not 2.'),
      L('<b>Tenglamada belgilarni noto‘g‘ri olish.</b> (x + 3)² bo‘lsa, markaz koordinatasi −3; o‘ng tomondagi son R emas, R².', '<b>Ошибаются в знаках в уравнении.</b> При (x + 3)² координата центра −3; число справа — R², а не R.', '<b>Sign errors in the equation.</b> (x + 3)² means the centre coordinate is −3; the number on the right is R², not R.'),
      L('<b>Ikki kesim masalasida bitta javob bilan cheklanish.</b> Kesimlar markazning bir yoki turli tomonlarida bo‘lishi mumkin.', '<b>Дают один ответ в задаче о двух сечениях.</b> Сечения могут лежать по одну или по разные стороны от центра.', '<b>Giving one answer in two-section problems.</b> The sections can lie on the same or opposite sides of the centre.'),
      L('<b>Har qanday kesimni katta doira deb hisoblash.</b> Katta doira faqat markazdan o‘tuvchi tekislik bilan hosil bo‘ladi.', '<b>Считают любое сечение большим кругом.</b> Большой круг даёт только плоскость через центр.', '<b>Treating every section as a great circle.</b> Only a plane through the centre gives a great circle.')
    ] },
    { kind: 'life', h: L('Hayotda sfera', 'Сфера в жизни', 'Spheres in real life'), p: [
      L('<b>Geografiya va navigatsiya.</b> Yer globusidagi kenglik φ bo‘lgan parallel — radiusi R·cos φ bo‘lgan kichik aylana. Toshkent taxminan 41,3° shimoliy kenglikda joylashgan, shuning uchun Toshkent parallelining radiusi ≈ 6371·cos 41,3° ≈ 4790 km. Samolyotlar ikki shahar orasida katta aylana yoyi bo‘ylab uchadi — bu sferadagi eng qisqa yo‘l; shuning uchun Toshkentdan Nyu-Yorkka reyslar xaritada shimolga egilgan bo‘lib ko‘rinadi.', '<b>География и навигация.</b> Параллель широты φ на глобусе — малая окружность радиуса R·cos φ. Ташкент находится примерно на 41,3° с. ш., поэтому радиус параллели Ташкента ≈ 6371·cos 41,3° ≈ 4790 км. Самолёты летят между городами по дуге большой окружности — кратчайшему пути на сфере; поэтому рейсы из Ташкента в Нью-Йорк на карте кажутся изогнутыми к северу.', '<b>Geography and navigation.</b> The parallel at latitude φ on a globe is a small circle of radius R·cos φ. Tashkent lies at about 41.3° N, so the radius of its parallel is ≈ 6,371·cos 41.3° ≈ 4,790 km. Planes fly between cities along an arc of a great circle — the shortest path on a sphere; that is why flights from Tashkent to New York look bent northwards on a flat map.'),
      L('<b>GPS.</b> Sun’iy yo‘ldoshdan kelgan signal vaqtidan qabul qilgich unga bo‘lgan masofani biladi, ya’ni o‘zi markazi yo‘ldoshda bo‘lgan sferada yotganini aniqlaydi. Ikki sfera aylana bo‘yicha kesishadi, uchinchisi bu aylanani ikki nuqtada kesadi, to‘rtinchi yo‘ldosh esa soat xatosini tuzatadi. Shunday qilib, telefoningiz o‘rnini sferalar kesishmasi orqali topadi. <b>Texnika:</b> sharikli podshipniklar, sferik rezervuarlar (gaz bosimga eng chidamli shakl), linzalar va antennalar sferik sirtlar bilan ishlaydi.', '<b>GPS.</b> По времени прихода сигнала со спутника приёмник знает расстояние до него, то есть что лежит на сфере с центром в спутнике. Две сферы пересекаются по окружности, третья пересекает её в двух точках, а четвёртый спутник поправляет ошибку часов. Так телефон находит своё место через пересечение сфер. <b>Техника:</b> шариковые подшипники, сферические резервуары (форма, лучше всего держащая давление газа), линзы и антенны работают со сферическими поверхностями.', '<b>GPS.</b> From the arrival time of a satellite’s signal a receiver knows its distance from it, i.e. that it lies on a sphere centred at the satellite. Two spheres meet in a circle, a third cuts that circle in two points, and a fourth satellite corrects the clock error. So your phone finds its position as an intersection of spheres. <b>Engineering:</b> ball bearings, spherical tanks (the shape that best withstands gas pressure), lenses and antennas all work with spherical surfaces.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Interesting facts'), list: [
      L('Yer aslida ideal shar emas: qutblarda biroz siqilgan, ekvator radiusi (6378 km) qutb radiusidan (6357 km) taxminan 21 km katta.', 'Земля не идеальный шар: она немного сплюснута у полюсов, экваториальный радиус (6378 км) примерно на 21 км больше полярного (6357 км).', 'The Earth is not a perfect ball: it is slightly flattened at the poles, the equatorial radius (6,378 km) being about 21 km larger than the polar one (6,357 km).'),
      L('Sferadagi uchburchak burchaklari yig‘indisi 180° dan katta: ekvator va ikki meridian 90° oraliqda burchaklari 90°, 90°, 90° bo‘lgan uchburchak hosil qiladi.', 'Сумма углов треугольника на сфере больше 180°: экватор и два меридиана через 90° образуют треугольник с углами 90°, 90°, 90°.', 'The angles of a triangle on a sphere add up to more than 180°: the equator and two meridians 90° apart form a triangle with angles 90°, 90°, 90°.'),
      L('Ulug‘bek rasadxonasida (XV asr) yulduzlar o‘rni osmon sferasidagi koordinatalar bilan katalogga yozilgan — 1018 ta yulduz.', 'В обсерватории Улугбека (XV в.) положения звёзд записаны в каталог координатами на небесной сфере — 1018 звёзд.', 'At Ulugh Beg’s observatory (15th century) star positions were recorded as coordinates on the celestial sphere — 1,018 stars.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Sfera — markazdan R masofadagi nuqtalar; shar — sfera bilan chegaralangan jism.', 'Сфера — точки на расстоянии R от центра; шар — тело, ограниченное сферой.', 'A sphere is the set of points at distance R from the centre; a ball is the solid it bounds.'),
      L('Tenglama: (x − a)² + (y − b)² + (z − c)² = R²; shar — ≤ R².', 'Уравнение: (x − a)² + (y − b)² + (z − c)² = R²; шар — ≤ R².', 'Equation: (x − a)² + (y − b)² + (z − c)² = R²; the ball is ≤ R².'),
      L('Har qanday tekis kesim — doira, r = √(R² − d²); markazdan o‘tgan kesim — katta doira.', 'Любое плоское сечение — круг, r = √(R² − d²); сечение через центр — большой круг.', 'Every plane section is a disc, r = √(R² − d²); the one through the centre is a great circle.'),
      L('d &lt; R — kesadi, d = R — urinadi, d &gt; R — umumiy nuqta yo‘q; urinma tekislik radiusga perpendikulyar.', 'd &lt; R — пересекает, d = R — касается, d &gt; R — общих точек нет; касательная плоскость перпендикулярна радиусу.', 'd &lt; R cuts, d = R touches, d &gt; R misses; a tangent plane is perpendicular to the radius.'),
      L('Kub: ichki sfera a/2, tashqi sfera a√3/2.', 'Куб: вписанная сфера a/2, описанная a√3/2.', 'Cube: inscribed sphere a/2, circumscribed a√3/2.'),
      L('Beruniy urinma va to‘g‘ri burchakli uchburchak yordamida Yer radiusini ≈ 6340 km deb o‘lchagan.', 'Беруни с помощью касательной и прямоугольного треугольника измерил радиус Земли ≈ 6340 км.', 'Al-Biruni used a tangent line and a right triangle to measure the Earth’s radius as ≈ 6,340 km.')
    ] }
  ] });


  // ---------- t12. Shar va uning bo‘laklari hajmi ----------
  T.add(P, 't12', { sections: [
    { kind: 'intro', h: L('Arximedning sevimli teoremasi', 'Любимая теорема Архимеда', 'Archimedes’ favourite theorem'), p: [
      L('Arximed yuzlab kashfiyotlar qilgan: richag qonuni, suzish qonuni, π sonini baholash, qamal mashinalari… Ammo u o‘zining eng go‘zal natijasi deb boshqasini hisoblagan: silindrga ichki chizilgan shar hajmi silindr hajmining roppa-rosa ⅔ qismiga teng. U qabr toshiga silindr ichidagi sharni chizishlarini vasiyat qilgan. Taxminan 140 yildan keyin, mil. av. 75-yilda, Rim notig‘i <b>Sitseron</b> Sirakuzada butalar orasidan aynan shu chizmali qabr toshini topgan va shundan uni Arximed qabri deb tanigan.', 'Архимед сделал сотни открытий: закон рычага, закон плавания, оценку числа π, осадные машины… Но самым красивым своим результатом он считал другое: объём шара, вписанного в цилиндр, равен ровно ⅔ объёма цилиндра. Он завещал изобразить на своей могиле шар в цилиндре. Примерно через 140 лет, в 75 г. до н. э., римский оратор <b>Цицерон</b> нашёл в Сиракузах среди кустов надгробие именно с таким чертежом и по нему узнал могилу Архимеда.', 'Archimedes made hundreds of discoveries: the law of the lever, the law of floating bodies, an estimate of π, siege engines… Yet he considered something else his most beautiful result: the volume of a ball inscribed in a cylinder is exactly ⅔ of the cylinder’s volume. He asked for a ball in a cylinder to be carved on his tomb. About 140 years later, in 75 BC, the Roman orator <b>Cicero</b> found among bushes in Syracuse a tombstone with exactly this drawing and recognised it as Archimedes’ grave.'),
      L('Bu mavzuda shar hajmi formulasi <b>V = ⁴⁄₃πR³</b> ni Kavalyeri prinsipi bilan isbotlaymiz va shar bo‘laklari — segment, qatlam va sektor hajmlarini topamiz. Bu formulalar tarvuz, sayyora yoki sut sisternasining hajmini hisoblashda kerak bo‘ladi.', 'В этой теме мы докажем формулу объёма шара <b>V = ⁴⁄₃πR³</b> с помощью принципа Кавальери и найдём объёмы частей шара — сегмента, слоя и сектора. Эти формулы нужны, чтобы посчитать объём арбуза, планеты или молочной цистерны.', 'In this topic we prove the ball volume formula <b>V = ⁴⁄₃πR³</b> using Cavalieri’s principle and find the volumes of the parts of a ball — the cap, the layer and the sector. These formulas are needed to compute the volume of a watermelon, a planet or a milk tank.')
    ] },
    { kind: 'def', h: L('Shar bo‘laklari', 'Части шара', 'Parts of a ball'), p: [
      L('<b>Shar segmenti</b> — sharning kesuvchi tekislik bilan ajratilgan bo‘lagi. Segment asosi — kesimdagi doira, <b>balandligi</b> h — asos markazidan sfera bilan kesishguncha perpendikulyar kesma. Har bir tekislik sharni ikki segmentga ajratadi, ularning balandliklari yig‘indisi 2R. h = R bo‘lganda segment — <b>yarim shar</b>.', '<b>Шаровой сегмент</b> — часть шара, отсекаемая секущей плоскостью. Основание сегмента — круг сечения, <b>высота</b> h — отрезок перпендикуляра от центра основания до сферы. Каждая плоскость делит шар на два сегмента, сумма их высот 2R. При h = R сегмент — <b>полушар</b>.', 'A <b>spherical cap</b> (segment) is the part of a ball cut off by a plane. Its base is the disc of the section and its <b>height</b> h is the perpendicular segment from the centre of the base to the sphere. Every plane splits a ball into two caps whose heights add up to 2R. When h = R the cap is a <b>hemisphere</b>.'),
      L('<b>Shar qatlami</b> — sharning ikki parallel tekislik orasidagi bo‘lagi; uning ikkita asosi (radiuslari r₁, r₂) va balandligi h bor. <b>Shar sektori</b> — shar segmenti va uchi shar markazida, asosi segment asosi bo‘lgan konusdan tashkil topgan jism (h &lt; R holda). Uni doiraviy sektorni simmetriya o‘qi atrofida aylantirib ham olish mumkin. Asos radiusi va segment balandligi orasida muhim bog‘lanish bor: <b>r² = h(2R − h)</b>.', '<b>Шаровой слой</b> — часть шара между двумя параллельными плоскостями; у него два основания (радиусы r₁, r₂) и высота h. <b>Шаровой сектор</b> — тело, составленное из шарового сегмента и конуса с вершиной в центре шара и основанием сегмента (при h &lt; R). Его можно получить вращением кругового сектора вокруг оси симметрии. Радиус основания и высота сегмента связаны важным соотношением: <b>r² = h(2R − h)</b>.', 'A <b>spherical layer</b> (zone solid) is the part of a ball between two parallel planes; it has two bases (radii r₁, r₂) and height h. A <b>spherical sector</b> is the solid made of a cap and the cone with apex at the centre and the cap’s base as its base (for h &lt; R). It can also be obtained by rotating a circular sector about its axis of symmetry. The base radius and the cap height satisfy the key relation <b>r² = h(2R − h)</b>.')
    ] },
    { kind: 'history', h: L('Arximed, Szu Chunchji va Kavalyeri', 'Архимед, Цзу Чунчжи и Кавальери', 'Archimedes, Zu Chongzhi and Cavalieri'), p: [
      L('Arximed shar hajmini ikki usulda topgan. «Usul» asarida u jismlarni xayoliy tarozida «tortgan»: shar va konusning yupqa qatlamlarini silindr qatlamlari bilan muvozanatlashtirib, javobni oldindan bilib olgan. So‘ng «Sfera va silindr haqida» asarida natijani tugatish usuli bilan qat’iy isbotlagan. «Usul» asari 1906-yilda Konstantinopolda eski ibodat kitobi sahifalari ostidan (palimpsestdan) topilgan.', 'Архимед нашёл объём шара двумя способами. В сочинении «Метод» он «взвешивал» тела на воображаемых весах: уравновешивая тонкие слои шара и конуса слоями цилиндра, он заранее узнавал ответ. Затем в книге «О шаре и цилиндре» строго доказал результат методом исчерпывания. «Метод» был найден в 1906 году в Константинополе под текстом старого молитвенника (палимпсест).', 'Archimedes found the volume of a ball in two ways. In “The Method” he “weighed” solids on an imaginary balance: balancing thin slices of a ball and a cone against slices of a cylinder, he learned the answer in advance. Then in “On the Sphere and Cylinder” he proved the result rigorously by exhaustion. “The Method” was discovered in 1906 in Constantinople beneath the text of an old prayer book (a palimpsest).'),
      L('Xitoyda V–VI asrlarda <b>Szu Chunchji</b> va uning o‘g‘li <b>Szu Gen</b> «agar ikki jismning har bir balandlikdagi kesimlari teng bo‘lsa, hajmlari ham teng» degan prinsipni qo‘llab, shar hajmini mustaqil ravishda topganlar. Yevropada bu prinsipni 1635-yilda italyan matematigi <b>Bonaventura Kavalyeri</b> «bo‘linmaslar geometriyasi» asarida bayon qildi, shuning uchun u Kavalyeri nomi bilan ataladi. Bir asr o‘tmay Nyuton va Leybnits integral hisobni yaratdi — unda bu g‘oyalar umumiy usulga aylandi.', 'В Китае в V–VI веках <b>Цзу Чунчжи</b> и его сын <b>Цзу Гэн</b> независимо нашли объём шара, применив принцип «если сечения двух тел на каждой высоте равны, то равны и объёмы». В Европе этот принцип изложил в 1635 году итальянский математик <b>Бонавентура Кавальери</b> в «Геометрии неделимых», поэтому он носит его имя. Менее чем через век Ньютон и Лейбниц создали интегральное исчисление, в котором эти идеи стали общим методом.', 'In China in the 5th–6th centuries <b>Zu Chongzhi</b> and his son <b>Zu Geng</b> independently found the volume of a ball using the principle “if the sections of two solids at every height are equal, so are their volumes”. In Europe the principle was set out in 1635 by the Italian mathematician <b>Bonaventura Cavalieri</b> in his “Geometry of Indivisibles”, hence its name. Less than a century later Newton and Leibniz created integral calculus, turning these ideas into a general method.')
    ] },
    { kind: 'rule', h: L('Shar hajmi: Kavalyeri isboti', 'Объём шара: доказательство Кавальери', 'Volume of a ball: Cavalieri’s proof'), p: [
      L('<b>Teorema.</b> Radiusi R bo‘lgan shar hajmi <b>V = ⁴⁄₃·π·R³</b>.', '<b>Теорема.</b> Объём шара радиуса R равен <b>V = ⁴⁄₃·π·R³</b>.', '<b>Theorem.</b> The volume of a ball of radius R is <b>V = ⁴⁄₃·π·R³</b>.'),
      L('<b>Isbot.</b> Yarim sharni tekis asosi bilan stolga qo‘yamiz. Uning yonida radiusi R, balandligi R bo‘lgan silindr tursin, silindr ichidan esa uchi pastki asos markazida, asosi silindrning yuqori asosi bo‘lgan konus o‘yib olingan bo‘lsin. Stoldan x balandlikdagi tekislik bilan ikkala jismni kesamiz. Yarim shardagi kesim — radiusi √(R² − x²) bo‘lgan doira, yuzi <b>π(R² − x²)</b>. Ikkinchi jismdagi kesim — halqa: tashqi radiusi R, ichki radiusi x (konus 45° qiyalikda), yuzi πR² − πx² = <b>π(R² − x²)</b>. Kesimlar har bir balandlikda teng!', '<b>Доказательство.</b> Поставим полушар плоским основанием на стол. Рядом поставим цилиндр радиуса R и высоты R, из которого вырезан конус с вершиной в центре нижнего основания и основанием — верхним основанием цилиндра. Рассечём оба тела плоскостью на высоте x. Сечение полушара — круг радиуса √(R² − x²), площадь <b>π(R² − x²)</b>. Сечение второго тела — кольцо с внешним радиусом R и внутренним x (конус под 45°), площадь πR² − πx² = <b>π(R² − x²)</b>. Сечения равны на каждой высоте!', '<b>Proof.</b> Put a hemisphere on a table, flat side down. Next to it stand a cylinder of radius R and height R from which a cone has been removed, with apex at the centre of the bottom base and base equal to the top of the cylinder. Cut both solids by a plane at height x. The hemisphere’s section is a disc of radius √(R² − x²), area <b>π(R² − x²)</b>. The second solid’s section is a ring with outer radius R and inner radius x (the cone is at 45°), area πR² − πx² = <b>π(R² − x²)</b>. The sections are equal at every height!'),
      L('Kavalyeri prinsipiga ko‘ra hajmlar teng: V<sub>yarim shar</sub> = πR²·R − ⅓πR²·R = ⅔πR³. Butun shar ikki marta katta: V = ⁴⁄₃πR³. ∎ Integral bilan: V = π∫<sub>−R</sub><sup>R</sup>(R² − x²)dx = π(2R³ − ⅔R³) = ⁴⁄₃πR³.', 'По принципу Кавальери объёмы равны: V<sub>полушара</sub> = πR²·R − ⅓πR²·R = ⅔πR³. Весь шар вдвое больше: V = ⁴⁄₃πR³. ∎ Через интеграл: V = π∫<sub>−R</sub><sup>R</sup>(R² − x²)dx = π(2R³ − ⅔R³) = ⁴⁄₃πR³.', 'By Cavalieri’s principle the volumes are equal: V<sub>hemisphere</sub> = πR²·R − ⅓πR²·R = ⅔πR³. The whole ball is twice that: V = ⁴⁄₃πR³. ∎ With an integral: V = π∫<sub>−R</sub><sup>R</sup>(R² − x²)dx = π(2R³ − ⅔R³) = ⁴⁄₃πR³.')
    ] },
    { kind: 'rule', h: L('Segment, qatlam va sektor hajmlari', 'Объёмы сегмента, слоя и сектора', 'Volumes of the cap, layer and sector'), p: [
      L('<b>Shar segmenti:</b> <b>V = π·h²·(R − h/3)</b>. Isbot g‘oyasi: segmentni yupqa doiraviy qatlamlarga bo‘lamiz, x balandlikdagi kesim yuzi π(R² − x²); x ning R − h dan R gacha qiymatlari bo‘yicha yig‘sak (integral), π[R²h − (R³ − (R − h)³)/3] = πh²(R − h/3) chiqadi. Tekshiruv: h = R da ⅔πR³ (yarim shar), h = 2R da ⁴⁄₃πR³ (butun shar).', '<b>Шаровой сегмент:</b> <b>V = π·h²·(R − h/3)</b>. Идея доказательства: разобьём сегмент на тонкие круглые слои, площадь сечения на высоте x равна π(R² − x²); суммируя по x от R − h до R (интеграл), получим π[R²h − (R³ − (R − h)³)/3] = πh²(R − h/3). Проверка: при h = R — ⅔πR³ (полушар), при h = 2R — ⁴⁄₃πR³ (весь шар).', '<b>Spherical cap:</b> <b>V = π·h²·(R − h/3)</b>. Proof idea: slice the cap into thin discs; the section at height x has area π(R² − x²); summing over x from R − h to R (an integral) gives π[R²h − (R³ − (R − h)³)/3] = πh²(R − h/3). Check: h = R gives ⅔πR³ (hemisphere), h = 2R gives ⁴⁄₃πR³ (the whole ball).'),
      L('<b>Shar sektori:</b> <b>V = ⅔·π·R²·h</b>, bu yerda h — sektorga kiruvchi segment balandligi. Isbot: sektor = segment + konus. Konus asosi radiusi r² = h(2R − h), balandligi R − h. ⅓πh(2R − h)(R − h) + πRh² − ⅓πh³ ni soddalashtirsak, ⅔πR²h qoladi. <b>Shar qatlami</b> hajmi ikki segment hajmlari ayirmasi sifatida topiladi yoki V = πh³/6 + πh(r₁² + r₂²)/2 formulasi bilan.', '<b>Шаровой сектор:</b> <b>V = ⅔·π·R²·h</b>, где h — высота сегмента, входящего в сектор. Доказательство: сектор = сегмент + конус. Радиус основания конуса r² = h(2R − h), высота R − h. Упростив ⅓πh(2R − h)(R − h) + πRh² − ⅓πh³, получим ⅔πR²h. Объём <b>шарового слоя</b> находят как разность объёмов двух сегментов или по формуле V = πh³/6 + πh(r₁² + r₂²)/2.', '<b>Spherical sector:</b> <b>V = ⅔·π·R²·h</b>, where h is the height of the cap inside the sector. Proof: sector = cap + cone. The cone has base radius r² = h(2R − h) and height R − h. Simplifying ⅓πh(2R − h)(R − h) + πRh² − ⅓πh³ leaves ⅔πR²h. The volume of a <b>spherical layer</b> is the difference of two caps, or V = πh³/6 + πh(r₁² + r₂²)/2.')
    ] },
    { kind: 'table', h: L('Arximed nisbatlari', 'Отношения Архимеда', 'Archimedes’ ratios'), p: [
      L('Radiusi R bo‘lgan shar, unga tashqi chizilgan silindr (r = R, h = 2R) va shu silindrga ichki chizilgan konusni (r = R, h = 2R) taqqoslaymiz.', 'Сравним шар радиуса R, описанный около него цилиндр (r = R, h = 2R) и вписанный в этот цилиндр конус (r = R, h = 2R).', 'Compare a ball of radius R, the cylinder circumscribed about it (r = R, h = 2R) and the cone inscribed in that cylinder (r = R, h = 2R).')
    ], table: {
      head: [L('Jism', 'Тело', 'Solid'), L('Hajm', 'Объём', 'Volume'), L('Nisbat', 'Отношение', 'Ratio')],
      rows: [
        [L('Konus', 'Конус', 'Cone'), L('⅓πR²·2R = ⅔πR³', '⅓πR²·2R = ⅔πR³', '⅓πR²·2R = ⅔πR³'), '1'],
        [L('Shar', 'Шар', 'Ball'), L('⁴⁄₃πR³', '⁴⁄₃πR³', '⁴⁄₃πR³'), '2'],
        [L('Silindr', 'Цилиндр', 'Cylinder'), L('πR²·2R = 2πR³', 'πR²·2R = 2πR³', 'πR²·2R = 2πR³'), '3']
      ] }, after: [
      L('Konus : shar : silindr = 1 : 2 : 3. Demak, konus va shar birgalikda silindrni to‘ldiradi — Kavalyeri isbotining yana bir ko‘rinishi.', 'Конус : шар : цилиндр = 1 : 2 : 3. Значит, конус и шар вместе заполняют цилиндр — ещё одна форма доказательства Кавальери.', 'Cone : ball : cylinder = 1 : 2 : 3. So the cone and the ball together fill the cylinder — another face of Cavalieri’s proof.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Решённые примеры', 'Worked examples'), ex: [
      { q: L('Radiusi 6 sm bo‘lgan shar hajmini toping.', 'Найдите объём шара радиуса 6 см.', 'Find the volume of a ball of radius 6 cm.'),
        s: L('V = ⁴⁄₃·π·216 = 288π ≈ 904,8 sm³.', 'V = ⁴⁄₃·π·216 = 288π ≈ 904,8 см³.', 'V = ⁴⁄₃·π·216 = 288π ≈ 904.8 cm³.') },
      { q: L('Shar hajmi 36π. Uning diametrini toping.', 'Объём шара 36π. Найдите его диаметр.', 'A ball has volume 36π. Find its diameter.'),
        s: L('⁴⁄₃πR³ = 36π ⇒ R³ = 36·3/4 = 27 ⇒ R = 3, diametr 6.', '⁴⁄₃πR³ = 36π ⇒ R³ = 36·3/4 = 27 ⇒ R = 3, диаметр 6.', '⁴⁄₃πR³ = 36π ⇒ R³ = 36·3/4 = 27 ⇒ R = 3, diameter 6.') },
      { q: L('Radiusi 5 bo‘lgan shardan balandligi 2 bo‘lgan segment kesib olindi. Uning hajmi va asos radiusini toping.', 'От шара радиуса 5 отсечён сегмент высоты 2. Найдите его объём и радиус основания.', 'A cap of height 2 is cut from a ball of radius 5. Find its volume and base radius.'),
        s: L('V = π·4·(5 − ⅔) = 4π·13/3 = 52π/3 ≈ 54,5. Asos radiusi: r² = h(2R − h) = 2·8 = 16, r = 4.', 'V = π·4·(5 − ⅔) = 4π·13/3 = 52π/3 ≈ 54,5. Радиус основания: r² = h(2R − h) = 2·8 = 16, r = 4.', 'V = π·4·(5 − ⅔) = 4π·13/3 = 52π/3 ≈ 54.5. Base radius: r² = h(2R − h) = 2·8 = 16, r = 4.') },
      { q: L('Radiusi 6 bo‘lgan sharning segment balandligi 2 bo‘lgan sektori hajmini toping.', 'Найдите объём шарового сектора шара радиуса 6, если высота его сегмента 2.', 'Find the volume of a spherical sector of a ball of radius 6 whose cap has height 2.'),
        s: L('V = ⅔·π·36·2 = 48π ≈ 150,8.', 'V = ⅔·π·36·2 = 48π ≈ 150,8.', 'V = ⅔·π·36·2 = 48π ≈ 150.8.') },
      { q: L('Radiusi 10 sm bo‘lgan yarim shar shaklidagi kosaga 5 sm chuqurlikda suv quyildi. Suv hajmi kosa sig‘imining qancha qismi?', 'В полусферическую чашу радиуса 10 см налита вода глубиной 5 см. Какую часть вместимости чаши составляет вода?', 'A hemispherical bowl of radius 10 cm holds water 5 cm deep. What fraction of the bowl’s capacity is the water?'),
        s: L('Suv — balandligi 5 bo‘lgan segment: V = π·25·(10 − 5/3) = 25π·25/3 = 625π/3 ≈ 654,5 sm³. Kosa: ⅔π·1000 = 2000π/3. Nisbat 625/2000 = 0,3125 — chuqurlik yarmi bo‘lsa ham, suv sig‘imning atigi 31% i.', 'Вода — сегмент высоты 5: V = π·25·(10 − 5/3) = 25π·25/3 = 625π/3 ≈ 654,5 см³. Чаша: ⅔π·1000 = 2000π/3. Отношение 625/2000 = 0,3125 — при глубине в половину вода занимает лишь 31% вместимости.', 'The water is a cap of height 5: V = π·25·(10 − 5/3) = 25π·25/3 = 625π/3 ≈ 654.5 cm³. The bowl: ⅔π·1000 = 2000π/3. Ratio 625/2000 = 0.3125 — at half depth the water fills only 31% of the bowl.') },
      { q: L('Radiusi 1 sm bo‘lgan 27 ta qo‘rg‘oshin sharcha eritilib, bitta shar quyildi. Uning radiusi qancha?', '27 свинцовых шариков радиуса 1 см переплавили в один шар. Каков его радиус?', '27 lead balls of radius 1 cm are melted into one ball. What is its radius?'),
        s: L('Hajm saqlanadi: ⁴⁄₃πR³ = 27·⁴⁄₃π·1³ ⇒ R³ = 27 ⇒ R = 3 sm. Radius bor-yo‘g‘i 3 marta oshdi.', 'Объём сохраняется: ⁴⁄₃πR³ = 27·⁴⁄₃π·1³ ⇒ R³ = 27 ⇒ R = 3 см. Радиус вырос всего в 3 раза.', 'Volume is conserved: ⁴⁄₃πR³ = 27·⁴⁄₃π·1³ ⇒ R³ = 27 ⇒ R = 3 cm. The radius grew only 3 times.') }
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>R² va R³ ni chalkashtirish:</b> hajm — ⁴⁄₃πR³ (kub birlik), sfera yuzi — 4πR² (kvadrat birlik).', '<b>Путают R² и R³:</b> объём — ⁴⁄₃πR³ (кубические единицы), площадь сферы — 4πR² (квадратные).', '<b>Mixing R² and R³:</b> volume is ⁴⁄₃πR³ (cubic units), sphere area is 4πR² (square units).'),
      L('<b>Diametrni formulaga qo‘yish.</b> d = 12 bo‘lsa, R = 6; aks holda javob 8 marta katta chiqadi.', '<b>Подставляют диаметр.</b> Если d = 12, то R = 6; иначе ответ получится в 8 раз больше.', '<b>Plugging in the diameter.</b> If d = 12 then R = 6; otherwise the answer is 8 times too big.'),
      L('<b>Segment balandligini asos radiusi bilan almashtirish.</b> h — tekislikdan sferagacha masofa, r — kesim radiusi; ular r² = h(2R − h) bilan bog‘langan.', '<b>Путают высоту сегмента с радиусом основания.</b> h — расстояние от плоскости до сферы, r — радиус сечения; они связаны r² = h(2R − h).', '<b>Confusing the cap height with the base radius.</b> h is the distance from the plane to the sphere, r is the section radius; they are linked by r² = h(2R − h).'),
      L('<b>Hajm chiziqli o‘zgaradi deb o‘ylash.</b> Radius 2 marta oshsa, hajm 8 marta oshadi; yarim chuqurlikdagi suv yarim hajm emas.', '<b>Думают, что объём меняется линейно.</b> При удвоении радиуса объём растёт в 8 раз; вода на половине глубины — не половина объёма.', '<b>Thinking volume changes linearly.</b> Doubling the radius multiplies the volume by 8; water at half depth is not half the volume.'),
      L('<b>Sektor formulasida h ni sektor radiusi deb olish.</b> ⅔πR²h dagi h — segment balandligi.', '<b>Принимают h в формуле сектора за радиус.</b> В ⅔πR²h h — высота сегмента.', '<b>Taking h in the sector formula as a radius.</b> In ⅔πR²h, h is the cap height.')
    ] },
    { kind: 'life', h: L('Hayotda shar hajmi', 'Объём шара в жизни', 'Ball volume in real life'), p: [
      L('<b>Astronomiya.</b> Yer hajmi ⁴⁄₃π·6371³ ≈ 1,08·10¹² km³. Oy radiusi 1737 km, Yer radiusidan ≈ 3,67 marta kichik, demak hajmi 3,67³ ≈ 49 marta kichik. Quyosh radiusi Yernikidan ≈ 109 marta katta, shuning uchun Quyoshga taxminan 109³ ≈ 1,3 million Yer sig‘adi. Sayyora zichligini topish uchun ham hajm kerak: massa hajmga bo‘linadi.', '<b>Астрономия.</b> Объём Земли ⁴⁄₃π·6371³ ≈ 1,08·10¹² км³. Радиус Луны 1737 км — примерно в 3,67 раза меньше земного, значит объём меньше в 3,67³ ≈ 49 раз. Радиус Солнца примерно в 109 раз больше земного, поэтому в Солнце поместилось бы около 109³ ≈ 1,3 миллиона Земель. Объём нужен и для плотности планеты: масса делится на объём.', '<b>Astronomy.</b> The Earth’s volume is ⁴⁄₃π·6371³ ≈ 1.08·10¹² km³. The Moon’s radius, 1,737 km, is about 3.67 times smaller than the Earth’s, so its volume is 3.67³ ≈ 49 times smaller. The Sun’s radius is about 109 times the Earth’s, so roughly 109³ ≈ 1.3 million Earths would fit inside it. Volume is also needed for a planet’s density: mass divided by volume.'),
      L('<b>Sanoat va turmush.</b> Gaz va suyuqlik saqlanadigan sferik rezervuarlar, sisternalarning yarim shar shaklidagi tublari, podshipnik sharchalari massasini hisoblash, sport to‘plaridagi havo miqdori — hammasi shar yoki segment formulalariga tayanadi. Shifokorlar o‘sma yoki kista hajmini taxminan shar deb, diametrini o‘lchab baholaydi. Oshpazlar uchun ham foydali: diametri 2 marta katta tarvuzda 8 marta ko‘p meva bor, po‘sti esa atigi 4 marta ko‘p.', '<b>Промышленность и быт.</b> Сферические резервуары для газа и жидкостей, полусферические днища цистерн, расчёт массы шариков подшипников, количество воздуха в спортивных мячах — всё опирается на формулы шара и сегмента. Врачи оценивают объём опухоли или кисты, приближая её шаром и измеряя диаметр. Полезно и поварам: в арбузе вдвое большего диаметра мякоти в 8 раз больше, а корки — лишь в 4 раза.', '<b>Industry and everyday life.</b> Spherical tanks for gas and liquids, hemispherical ends of tankers, the mass of bearing balls, the amount of air in sports balls — all rely on ball and cap formulas. Doctors estimate the volume of a tumour or cyst by treating it as a ball and measuring its diameter. Useful for cooks too: a watermelon twice the diameter has 8 times the flesh but only 4 times the rind.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Interesting facts'), list: [
      L('Kubga ichki chizilgan shar kub hajmining π/6 ≈ 52% ini egallaydi.', 'Шар, вписанный в куб, занимает π/6 ≈ 52% объёма куба.', 'A ball inscribed in a cube fills π/6 ≈ 52% of the cube.'),
      L('Bir xil sharlarni eng zich joylashtirish usuli (do‘konlardagi apelsin piramidasi) fazoning ≈ 74% ini to‘ldiradi. Buni Kepler 1611-yilda taxmin qilgan, T. Heyls esa 1998-yilda kompyuter yordamida isbotlagan.', 'Самая плотная упаковка одинаковых шаров (пирамида апельсинов в магазине) заполняет ≈ 74% пространства. Это предположил Кеплер в 1611 году, а Т. Хейлс доказал в 1998 году с помощью компьютера.', 'The densest packing of equal balls (the orange pyramid at a grocer’s) fills ≈ 74% of space. Kepler conjectured this in 1611 and T. Hales proved it in 1998 with computer help.'),
      L('Berilgan sirt yuziga ega jismlar orasida shar eng katta hajmga ega — shuning uchun sovun pufaklari va tomchilar sharsimon.', 'Среди тел с данной площадью поверхности наибольший объём у шара — поэтому мыльные пузыри и капли круглые.', 'Among solids with a given surface area the ball has the largest volume — which is why soap bubbles and drops are round.')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверьте себя', 'Test yourself'), p: [
      L('Masalalarni avval mustaqil yeching, keyin yechim bilan solishtiring.', 'Сначала решите задачи самостоятельно, затем сравните с решением.', 'Solve the problems on your own first, then compare with the solutions.')
    ], ex: [
      { q: L('Yarim shar hajmi 144π. Uning radiusini toping.', 'Объём полушара 144π. Найдите его радиус.', 'A hemisphere has volume 144π. Find its radius.'),
        s: L('⅔πR³ = 144π ⇒ R³ = 216 ⇒ R = 6.', '⅔πR³ = 144π ⇒ R³ = 216 ⇒ R = 6.', '⅔πR³ = 144π ⇒ R³ = 216 ⇒ R = 6.') },
      { q: L('Qirrasi 10 sm bo‘lgan kubga ichki chizilgan shar kub hajmining qancha qismini egallaydi?', 'Какую часть объёма куба с ребром 10 см занимает вписанный шар?', 'What fraction of a cube of edge 10 cm does its inscribed ball fill?'),
        s: L('R = 5, V<sub>shar</sub> = ⁴⁄₃π·125 = 500π/3 ≈ 523,6 sm³; kub 1000 sm³. Nisbat π/6 ≈ 0,52.', 'R = 5, V<sub>шара</sub> = ⁴⁄₃π·125 = 500π/3 ≈ 523,6 см³; куб 1000 см³. Отношение π/6 ≈ 0,52.', 'R = 5, V<sub>ball</sub> = ⁴⁄₃π·125 = 500π/3 ≈ 523.6 cm³; cube 1000 cm³. Ratio π/6 ≈ 0.52.') }
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Shar hajmi V = ⁴⁄₃πR³, yarim shar ⅔πR³.', 'Объём шара V = ⁴⁄₃πR³, полушара ⅔πR³.', 'Ball volume V = ⁴⁄₃πR³, hemisphere ⅔πR³.'),
      L('Isbot: yarim shar va «silindr minus konus» jismining kesimlari teng — Kavalyeri prinsipi.', 'Доказательство: сечения полушара и тела «цилиндр минус конус» равны — принцип Кавальери.', 'Proof: the sections of a hemisphere and the solid “cylinder minus cone” are equal — Cavalieri’s principle.'),
      L('Segment: V = πh²(R − h/3), r² = h(2R − h); sektor: V = ⅔πR²h; qatlam — segmentlar ayirmasi.', 'Сегмент: V = πh²(R − h/3), r² = h(2R − h); сектор: V = ⅔πR²h; слой — разность сегментов.', 'Cap: V = πh²(R − h/3), r² = h(2R − h); sector: V = ⅔πR²h; layer — difference of caps.'),
      L('Konus : shar : silindr = 1 : 2 : 3 — Arximed qabr toshidagi teorema.', 'Конус : шар : цилиндр = 1 : 2 : 3 — теорема с надгробия Архимеда.', 'Cone : ball : cylinder = 1 : 2 : 3 — the theorem on Archimedes’ tomb.'),
      L('Radius k marta oshsa, hajm k³ marta oshadi.', 'При увеличении радиуса в k раз объём растёт в k³ раз.', 'Scaling the radius by k scales the volume by k³.')
    ] }
  ] });


  // ---------- t13. Sfera sirtining yuzi ----------
  T.add(P, 't13', { sections: [
    { kind: 'intro', h: L('Apelsin po‘stini tekislab bo‘ladimi?', 'Можно ли расправить кожуру апельсина?', 'Can you flatten an orange peel?'), p: [
      L('Silindr yon sirtini qirqib, to‘g‘ri to‘rtburchakka, konus yon sirtini esa sektorga yoyish mumkin edi. Endi apelsin po‘stini tekislab ko‘ring: u albatta yirtiladi yoki g‘ijimlanadi. Sferani hech qanday cho‘zishsiz tekislikka yoyib bo‘lmaydi — shuning uchun dunyo xaritalarining hammasi qandaydir buzilishga ega: Grenlandiya ko‘pincha Afrikadek katta ko‘rinadi, aslida esa undan 14 marta kichik.', 'Боковую поверхность цилиндра можно разрезать и развернуть в прямоугольник, конуса — в сектор. А теперь попробуйте расправить кожуру апельсина: она обязательно порвётся или сомнётся. Сферу нельзя развернуть на плоскость без растяжений — поэтому все карты мира чем-то искажены: Гренландия часто выглядит размером с Африку, хотя на самом деле в 14 раз меньше.', 'A cylinder’s lateral surface can be cut and unrolled into a rectangle, a cone’s into a sector. Now try flattening an orange peel: it will tear or crumple. A sphere cannot be laid flat without stretching — which is why every world map is distorted somehow: Greenland often looks as big as Africa, though it is really 14 times smaller.'),
      L('Unda sfera yuzini qanday topamiz? Bu savolga 2200 yil oldin Arximed ajoyib javob bergan: sfera yuzi to‘rtta katta doira yuziga teng, <b>S = 4πR²</b>. Bu mavzuda formulani hajm orqali keltirib chiqaramiz, sferik belbog‘ va segment sirti yuzini o‘rganamiz hamda formulani bo‘yoq hisoblashdan tortib sayyoralargacha qo‘llaymiz.', 'Как же тогда найти площадь сферы? 2200 лет назад Архимед дал замечательный ответ: площадь сферы равна четырём площадям большого круга, <b>S = 4πR²</b>. В этой теме мы выведем формулу через объём, изучим площади сферического пояса и сегмента и применим формулу — от расчёта краски до планет.', 'How, then, do we find the area of a sphere? 2,200 years ago Archimedes gave a wonderful answer: the area of a sphere equals four great-circle areas, <b>S = 4πR²</b>. In this topic we derive the formula from the volume, study the areas of spherical zones and caps and apply the formula — from paint estimates to planets.')
    ] },
    { kind: 'def', h: L('Sfera yuzi qanday ta’riflanadi', 'Как определяется площадь сферы', 'How the area of a sphere is defined'), p: [
      L('Ko‘pyoqlarda sirt yuzi — yoqlar yuzlari yig‘indisi; silindr va konusda yoyilma yuzi. Sferada yoyilma yo‘q, shuning uchun yuzni limit orqali ta’riflaymiz. Shar sirtiga qalinligi Δ bo‘lgan yupqa qatlam — «po‘st» qoplaymiz. Po‘st hajmi taxminan sirt yuzi × qalinlik ga teng: ΔV ≈ S·Δ. Qalinlik qancha kichik bo‘lsa, bu taxmin shuncha aniq. Shuning uchun <b>sfera yuzi</b> deb po‘st hajmining uning qalinligiga nisbati Δ → 0 dagi limitiga aytiladi: S = lim (V(R + Δ) − V(R))/Δ.', 'У многогранников площадь поверхности — сумма площадей граней; у цилиндра и конуса — площадь развёртки. У сферы развёртки нет, поэтому площадь определяют через предел. Покроем шар тонким слоем — «кожурой» толщины Δ. Объём кожуры примерно равен площадь × толщина: ΔV ≈ S·Δ. Чем тоньше слой, тем точнее приближение. Поэтому <b>площадью сферы</b> называют предел отношения объёма кожуры к её толщине при Δ → 0: S = lim (V(R + Δ) − V(R))/Δ.', 'For polyhedra the surface area is the sum of the face areas; for cylinders and cones it is the area of the net. A sphere has no net, so its area is defined through a limit. Cover the ball with a thin “peel” of thickness Δ. The peel’s volume is roughly area × thickness: ΔV ≈ S·Δ. The thinner the layer, the better the approximation. So the <b>area of a sphere</b> is defined as the limit of the peel’s volume divided by its thickness as Δ → 0: S = lim (V(R + Δ) − V(R))/Δ.'),
      L('Boshqacha ta’rif ham bor: sferaga tashqi chizilgan ko‘pyoqlar yuzlarining yoqlar soni cheksiz oshgandagi limiti. Ikkala ta’rif bir xil natija beradi.', 'Есть и другое определение: предел площадей описанных около сферы многогранников при неограниченном увеличении числа граней. Оба определения дают одинаковый результат.', 'There is another definition too: the limit of the areas of polyhedra circumscribed about the sphere as the number of faces grows without bound. Both definitions give the same result.')
    ] },
    { kind: 'history', h: L('Arximed, Beruniy va xaritalar', 'Архимед, Беруни и карты', 'Archimedes, al-Biruni and maps'), p: [
      L('<b>Arximed</b> «Sfera va silindr haqida» asarida isbotladi: sfera yuzi uning katta doirasi yuzidan to‘rt marta katta va tashqi chizilgan silindrning yon sirtiga teng: 2πR·2R = 4πR². Bundan tashqari, silindrning to‘la sirti 6πR² bo‘lgani uchun silindr va sfera yuzlari nisbati ham 3 : 2 — xuddi hajmlar nisbati kabi! Arximed «quti teoremasi» deb ataladigan yana bir natijani ham topgan: sferani ikkita parallel tekislik bilan kesganda ular orasidagi belbog‘ yuzi silindrdagi mos belbog‘ yuziga teng.', '<b>Архимед</b> в книге «О шаре и цилиндре» доказал: площадь сферы в четыре раза больше площади её большого круга и равна боковой поверхности описанного цилиндра: 2πR·2R = 4πR². Кроме того, полная поверхность цилиндра 6πR², так что площади цилиндра и сферы тоже относятся как 3 : 2 — как и объёмы! Архимед нашёл и так называемую «теорему о шляпной коробке»: пояс сферы между двумя параллельными плоскостями имеет ту же площадь, что и соответствующий пояс цилиндра.', '<b>Archimedes</b>, in “On the Sphere and Cylinder”, proved that the area of a sphere is four times that of its great circle and equals the lateral area of the circumscribed cylinder: 2πR·2R = 4πR². Moreover, the cylinder’s total area is 6πR², so the areas of cylinder and sphere are also in the ratio 3 : 2 — just like the volumes! Archimedes also found the so-called “hat-box theorem”: the zone of a sphere between two parallel planes has the same area as the corresponding band of the cylinder.'),
      L('Sferadagi shakllarni tekislikka ko‘chirish muammosi bilan <b>Beruniy</b> ham shug‘ullangan: u «Osmon sferasini tekislikda tasvirlash» haqida maxsus risola yozib, xaritalar uchun bir nechta proyeksiyalarni tavsiflagan. 1569-yilda Merkator dengizchilar uchun burchaklarni saqlaydigan xarita yaratdi, ammo unda maydonlar qutblar tomon kattalashadi. 1827-yilda <b>Gauss</b> «Ajoyib teorema»sida sferani hech qanday buzilishsiz tekislikka tasvirlab bo‘lmasligini qat’iy isbotladi.', 'Задачей переноса фигур со сферы на плоскость занимался и <b>Беруни</b>: он написал особый трактат об изображении небесной сферы на плоскости и описал несколько картографических проекций. В 1569 году Меркатор создал для мореплавателей карту, сохраняющую углы, но площади на ней растут к полюсам. В 1827 году <b>Гаусс</b> в «Замечательной теореме» строго доказал, что сферу невозможно изобразить на плоскости без искажений.', '<b>Al-Biruni</b> also worked on transferring figures from the sphere to the plane: he wrote a special treatise on depicting the celestial sphere on a plane and described several map projections. In 1569 Mercator made an angle-preserving chart for sailors, but on it areas grow towards the poles. In 1827 <b>Gauss</b>, in his “Remarkable Theorem”, proved rigorously that a sphere cannot be mapped onto a plane without distortion.')
    ] },
    { kind: 'rule', h: L('Sfera yuzi formulasi', 'Формула площади сферы', 'The sphere area formula'), p: [
      L('<b>Teorema.</b> Radiusi R bo‘lgan sfera yuzi <b>S = 4πR²</b>.', '<b>Теорема.</b> Площадь сферы радиуса R равна <b>S = 4πR²</b>.', '<b>Theorem.</b> The area of a sphere of radius R is <b>S = 4πR²</b>.'),
      L('<b>Isbot (po‘st orqali).</b> V(R + Δ) − V(R) = ⁴⁄₃π[(R + Δ)³ − R³] = ⁴⁄₃π(3R²Δ + 3RΔ² + Δ³). Δ ga bo‘lamiz: ⁴⁄₃π(3R² + 3RΔ + Δ²). Δ → 0 da bu ifoda ⁴⁄₃π·3R² = 4πR² ga intiladi. ∎ Hosila tilida: S = V′(R) = (⁴⁄₃πR³)′ = 4πR². Xuddi shunday doira yuzi πR² ning hosilasi aylana uzunligi 2πR ni beradi.', '<b>Доказательство (через кожуру).</b> V(R + Δ) − V(R) = ⁴⁄₃π[(R + Δ)³ − R³] = ⁴⁄₃π(3R²Δ + 3RΔ² + Δ³). Делим на Δ: ⁴⁄₃π(3R² + 3RΔ + Δ²). При Δ → 0 это выражение стремится к ⁴⁄₃π·3R² = 4πR². ∎ На языке производной: S = V′(R) = (⁴⁄₃πR³)′ = 4πR². Точно так же производная площади круга πR² даёт длину окружности 2πR.', '<b>Proof (via the peel).</b> V(R + Δ) − V(R) = ⁴⁄₃π[(R + Δ)³ − R³] = ⁴⁄₃π(3R²Δ + 3RΔ² + Δ³). Divide by Δ: ⁴⁄₃π(3R² + 3RΔ + Δ²). As Δ → 0 this tends to ⁴⁄₃π·3R² = 4πR². ∎ In the language of derivatives: S = V′(R) = (⁴⁄₃πR³)′ = 4πR². In the same way the derivative of the disc area πR² gives the circumference 2πR.'),
      L('<b>Teskari yo‘l (piramidalar).</b> Sferani juda ko‘p kichik bo‘laklarga bo‘lib, har birini shar markazi bilan tutashtirsak, shar uchi markazda, balandligi R bo‘lgan ingichka «piramidalar»ga bo‘linadi. Ularning hajmlari yig‘indisi ⅓·(S₁ + S₂ + …)·R = ⅓·S·R. Demak, ⁴⁄₃πR³ = ⅓·S·R, bundan yana S = 4πR². Bu bog‘lanish <b>V = ⅓·S·R</b> sharga tashqi chizilgan ko‘pyoqlar uchun ham foydali.', '<b>Обратный путь (пирамиды).</b> Разобьём сферу на очень много малых кусочков и соединим каждый с центром — шар разобьётся на тонкие «пирамиды» с вершиной в центре и высотой R. Сумма их объёмов ⅓·(S₁ + S₂ + …)·R = ⅓·S·R. Значит, ⁴⁄₃πR³ = ⅓·S·R, откуда снова S = 4πR². Связь <b>V = ⅓·S·R</b> полезна и для многогранников, описанных около шара.', '<b>The reverse route (pyramids).</b> Split the sphere into very many small pieces and join each to the centre: the ball splits into thin “pyramids” with apex at the centre and height R. Their volumes add up to ⅓·(S₁ + S₂ + …)·R = ⅓·S·R. So ⁴⁄₃πR³ = ⅓·S·R, which again gives S = 4πR². The relation <b>V = ⅓·S·R</b> is also useful for polyhedra circumscribed about a ball.')
    ] },
    { kind: 'rule', h: L('Sferik segment va belbog‘ yuzi', 'Площадь сферического сегмента и пояса', 'Area of a spherical cap and zone'), p: [
      L('<b>Teorema (Arximed).</b> Balandligi h bo‘lgan sferik segment sirti (asosisiz) va ikki parallel tekislik orasidagi, balandligi h bo‘lgan sferik belbog‘ yuzi bir xil formula bilan topiladi: <b>S = 2πR·h</b>. Ajablanarli tomoni: yuz faqat qatlam qalinligiga bog‘liq, uning sferada qayerda joylashganiga emas!', '<b>Теорема (Архимед).</b> Площадь поверхности сферического сегмента высоты h (без основания) и сферического пояса высоты h между двумя параллельными плоскостями находят по одной формуле: <b>S = 2πR·h</b>. Удивительно: площадь зависит только от толщины слоя, а не от того, где он расположен на сфере!', '<b>Theorem (Archimedes).</b> The surface area of a spherical cap of height h (without its base) and of a spherical zone of height h between two parallel planes is given by one formula: <b>S = 2πR·h</b>. Amazingly, the area depends only on the thickness of the slab, not on where it sits on the sphere!'),
      L('<b>Tushuntirish.</b> Sferani tashqi chizilgan silindrga gorizontal nurlar bilan proyeksiyalaymiz. Qutb yaqinida belbog‘ qiyshayib, kengroq bo‘ladi, lekin uning aylanasi qisqaroq; ekvator yaqinida esa aksincha. Bu ikki ta’sir aniq bir-birini kompensatsiya qiladi va sferik belbog‘ yuzi silindrdagi balandligi h bo‘lgan belbog‘ yuziga (2πR·h) teng bo‘ladi. Tekshirish: h = 2R da butun sfera 4πR², h = R da yarim sfera 2πR².', '<b>Пояснение.</b> Спроецируем сферу горизонтальными лучами на описанный цилиндр. У полюса пояс наклонён и шире, но его окружность короче; у экватора — наоборот. Эти два эффекта в точности компенсируют друг друга, и площадь сферического пояса равна площади пояса цилиндра той же высоты h (2πR·h). Проверка: при h = 2R — вся сфера 4πR², при h = R — полусфера 2πR².', '<b>Explanation.</b> Project the sphere horizontally onto the circumscribed cylinder. Near a pole the zone is tilted and wider but its circle is shorter; near the equator it is the other way round. The two effects cancel exactly, so the zone has the same area as the cylinder band of the same height h (2πR·h). Check: h = 2R gives the whole sphere 4πR², h = R gives the hemisphere 2πR².'),
      L('Yaxlit yarim shar (tubi bilan) to‘la sirti: 2πR² + πR² = <b>3πR²</b>. Radius k marta oshsa, sfera yuzi k² marta oshadi; sirt yuzining hajmga nisbati S/V = 3/R — shar kattalashgan sari bu nisbat kamayadi.', 'Полная поверхность сплошного полушара (с дном): 2πR² + πR² = <b>3πR²</b>. При увеличении радиуса в k раз площадь сферы растёт в k² раз; отношение площади к объёму S/V = 3/R — с ростом шара оно уменьшается.', 'The total surface of a solid hemisphere (with its base) is 2πR² + πR² = <b>3πR²</b>. Scaling the radius by k scales the area by k²; the area-to-volume ratio S/V = 3/R shrinks as the ball grows.')
    ] },
    { kind: 'steps', h: L('Sferaga oid masalani yechish', 'Решение задачи о сфере', 'Solving a sphere problem'), list: [
      L('Nima berilganini aniqlang: R, diametr, katta doira yuzi, hajm yoki sirt.', 'Определите, что дано: R, диаметр, площадь большого круга, объём или поверхность.', 'Identify what is given: R, the diameter, the great-circle area, the volume or the area.'),
      L('Avval R ni toping: d = 2R, S<sub>k.d.</sub> = πR², V = ⁴⁄₃πR³ ⇒ R = ∛(3V/4π), S = 4πR² ⇒ R = √(S/4π).', 'Сначала найдите R: d = 2R, S<sub>б.к.</sub> = πR², V = ⁴⁄₃πR³ ⇒ R = ∛(3V/4π), S = 4πR² ⇒ R = √(S/4π).', 'First find R: d = 2R, S<sub>g.c.</sub> = πR², V = ⁴⁄₃πR³ ⇒ R = ∛(3V/4π), S = 4πR² ⇒ R = √(S/4π).'),
      L('Butun sfera — 4πR², yarim sfera — 2πR², segment yoki belbog‘ — 2πRh.', 'Вся сфера — 4πR², полусфера — 2πR², сегмент или пояс — 2πRh.', 'Whole sphere 4πR², hemisphere 2πR², cap or zone 2πRh.'),
      L('Yaxlit jism bo‘lsa, tekis asoslar yuzini qo‘shishni unutmang.', 'Если тело сплошное, не забудьте прибавить площади плоских оснований.', 'For a solid body, remember to add the areas of the flat bases.'),
      L('Javobni π orqali va taxminiy son ko‘rinishida yozing, birlik kvadrat ekanini tekshiring.', 'Запишите ответ через π и приближённо, проверьте, что единицы квадратные.', 'Write the answer in terms of π and approximately, and check the units are squared.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Решённые примеры', 'Worked examples'), ex: [
      { q: L('Radiusi 5 bo‘lgan sfera yuzini toping.', 'Найдите площадь сферы радиуса 5.', 'Find the area of a sphere of radius 5.'),
        s: L('S = 4π·25 = 100π ≈ 314,2.', 'S = 4π·25 = 100π ≈ 314,2.', 'S = 4π·25 = 100π ≈ 314.2.') },
      { q: L('Sfera yuzi 64π. Shar hajmini toping.', 'Площадь сферы 64π. Найдите объём шара.', 'A sphere has area 64π. Find the volume of the ball.'),
        s: L('4πR² = 64π ⇒ R² = 16 ⇒ R = 4. V = ⁴⁄₃π·64 = 256π/3 ≈ 268,1.', '4πR² = 64π ⇒ R² = 16 ⇒ R = 4. V = ⁴⁄₃π·64 = 256π/3 ≈ 268,1.', '4πR² = 64π ⇒ R² = 16 ⇒ R = 4. V = ⁴⁄₃π·64 = 256π/3 ≈ 268.1.') },
      { q: L('Radiusi 10 bo‘lgan sferadan balandligi 2 bo‘lgan segment kesildi. Segmentning sferik sirti va asos doirasi yuzlarini taqqoslang.', 'От сферы радиуса 10 отсечён сегмент высоты 2. Сравните площадь его сферической поверхности и площадь круга основания.', 'A cap of height 2 is cut from a sphere of radius 10. Compare the area of its curved surface with the area of its base disc.'),
        s: L('Sferik sirt: 2π·10·2 = 40π. Asos radiusi: r² = h(2R − h) = 2·18 = 36, asos yuzi 36π. Egri sirt tekis asosdan biroz katta — shunday bo‘lishi kerak.', 'Сферическая поверхность: 2π·10·2 = 40π. Радиус основания: r² = h(2R − h) = 2·18 = 36, площадь основания 36π. Кривая поверхность немного больше плоского основания — так и должно быть.', 'Curved surface: 2π·10·2 = 40π. Base radius: r² = h(2R − h) = 2·18 = 36, base area 36π. The curved surface is slightly larger than the flat base — as it should be.') },
      { q: L('Yer sirtining qancha qismi ekvator va 30° shimoliy kenglik orasida joylashgan?', 'Какая часть поверхности Земли лежит между экватором и 30° северной широты?', 'What fraction of the Earth’s surface lies between the equator and 30° N?'),
        s: L('Bu belbog‘ balandligi h = R·sin 30° = R/2. Yuzi 2πR·R/2 = πR², butun sirt 4πR². Javob: ¼ qismi — shimoliy yarim sharning roppa-rosa yarmi!', 'Высота этого пояса h = R·sin 30° = R/2. Площадь 2πR·R/2 = πR², вся поверхность 4πR². Ответ: ¼ — ровно половина северного полушария!', 'This zone has height h = R·sin 30° = R/2. Its area is 2πR·R/2 = πR² out of 4πR². Answer: ¼ — exactly half of the northern hemisphere!') },
      { q: L('Diametri 20 m bo‘lgan yarim sferik gumbazni bo‘yash kerak. 1 m² ga 0,2 kg bo‘yoq ketsa, qancha bo‘yoq kerak?', 'Нужно покрасить полусферический купол диаметром 20 м. Сколько краски нужно при расходе 0,2 кг на 1 м²?', 'A hemispherical dome of diameter 20 m must be painted. How much paint is needed at 0.2 kg per m²?'),
        s: L('R = 10, yuz 2πR² = 200π ≈ 628,3 m². Bo‘yoq: 628,3·0,2 ≈ 125,7 kg (amalda zaxira bilan ≈ 130 kg).', 'R = 10, площадь 2πR² = 200π ≈ 628,3 м². Краска: 628,3·0,2 ≈ 125,7 кг (на практике с запасом ≈ 130 кг).', 'R = 10, area 2πR² = 200π ≈ 628.3 m². Paint: 628.3·0.2 ≈ 125.7 kg (about 130 kg with a margin in practice).') },
      { q: L('Shar radiusi 3 marta oshirildi. Sirt yuzi va hajmi necha marta oshadi?', 'Радиус шара увеличили в 3 раза. Во сколько раз выросли площадь поверхности и объём?', 'A ball’s radius is tripled. By what factors do its surface area and volume grow?'),
        s: L('Yuz R² ga proporsional: 3² = 9 marta. Hajm R³ ga proporsional: 3³ = 27 marta.', 'Площадь пропорциональна R²: в 3² = 9 раз. Объём пропорционален R³: в 3³ = 27 раз.', 'Area is proportional to R²: 3² = 9 times. Volume is proportional to R³: 3³ = 27 times.') }
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>Sfera yuzini πR² deb yozish</b> — bu faqat katta doira yuzi; sfera undan 4 marta katta.', '<b>Пишут площадь сферы как πR²</b> — это лишь площадь большого круга; сфера в 4 раза больше.', '<b>Writing the sphere’s area as πR²</b> — that is only the great circle; the sphere is 4 times bigger.'),
      L('<b>Yaxlit yarim shar sirtida tubini unutish:</b> 2πR² emas, 3πR².', '<b>Забывают дно сплошного полушара:</b> не 2πR², а 3πR².', '<b>Forgetting the base of a solid hemisphere:</b> 3πR², not 2πR².'),
      L('<b>Segment yuzida h o‘rniga asos radiusini qo‘yish.</b> 2πRh dagi h — segment balandligi.', '<b>Подставляют радиус основания вместо h в площадь сегмента.</b> В 2πRh h — высота сегмента.', '<b>Using the base radius instead of h for a cap.</b> In 2πRh, h is the cap’s height.'),
      L('<b>Diametrni radius deb olish</b> — natija 4 marta katta chiqadi.', '<b>Принимают диаметр за радиус</b> — результат в 4 раза больше.', '<b>Taking the diameter for the radius</b> — the result is 4 times too large.'),
      L('<b>Yuz va hajm o‘sishini tenglashtirish.</b> Radius k marta oshsa, yuz k², hajm k³ marta oshadi.', '<b>Приравнивают рост площади и объёма.</b> При увеличении радиуса в k раз площадь растёт в k², объём — в k³ раз.', '<b>Equating growth of area and volume.</b> Scaling the radius by k multiplies area by k² and volume by k³.')
    ] },
    { kind: 'life', h: L('Hayotda sfera yuzi', 'Площадь сферы в жизни', 'Sphere area in real life'), p: [
      L('<b>Yer va sayyoralar.</b> Yer sirti 4π·6371² ≈ 510 mln km²; uning ≈ 71% i (≈ 361 mln km²) okeanlar bilan qoplangan, quruqlik esa ≈ 149 mln km². Iqlimshunoslar Quyoshdan keladigan energiyani hisoblashda shunday mulohaza qiladi: Yer nurni katta doira yuzi πR² bilan «ushlaydi», lekin issiqlikni butun sirti 4πR² bilan chiqaradi — ya’ni o‘rtacha har bir kvadrat metrga Quyosh doimiysining ¼ qismi to‘g‘ri keladi.', '<b>Земля и планеты.</b> Поверхность Земли 4π·6371² ≈ 510 млн км²; около 71% (≈ 361 млн км²) покрыто океанами, суша ≈ 149 млн км². Климатологи, считая солнечную энергию, рассуждают так: Земля «ловит» свет площадью большого круга πR², а излучает тепло всей поверхностью 4πR² — то есть в среднем на каждый квадратный метр приходится ¼ солнечной постоянной.', '<b>Earth and planets.</b> The Earth’s surface is 4π·6371² ≈ 510 million km²; about 71% (≈ 361 million km²) is ocean and ≈ 149 million km² is land. Climate scientists reason about sunlight like this: the Earth “catches” light with its great-circle area πR² but radiates heat from its whole surface 4πR² — so on average each square metre gets ¼ of the solar constant.'),
      L('<b>Biologiya va texnika.</b> Hujayralar juda kichik bo‘lishining sababi — S/V = 3/R: kichik hujayrada hajm birligiga ko‘proq sirt to‘g‘ri keladi va moddalar almashinuvi tez kechadi. Fil va kit katta bo‘lgani uchun issiqlikni sekin yo‘qotadi, sichqon esa tez soviydi va ko‘p ovqatlanishi kerak. Muhandislar sferik gaz rezervuarlari uchun eng kam metall sarflanishini aynan 4πR² bilan hisoblaydi; havo sharlari, futbol to‘pi qoplamasi, gumbazlarni qoplash ham shu formulaga tayanadi. Dorixonalarda kukun dorilar mayda zarralarga maydalanadi — umumiy sirt kattalashib, dori tezroq eriydi.', '<b>Биология и техника.</b> Клетки очень малы из-за S/V = 3/R: у маленькой клетки на единицу объёма приходится больше поверхности, и обмен веществ идёт быстро. Слон и кит из-за размеров теряют тепло медленно, а мышь быстро остывает и должна много есть. Инженеры рассчитывают минимальный расход металла на сферические газгольдеры именно по 4πR²; воздушные шары, покрышки мячей, облицовка куполов тоже опираются на эту формулу. Лекарственные порошки измельчают — суммарная поверхность растёт, и лекарство растворяется быстрее.', '<b>Biology and engineering.</b> Cells are tiny because S/V = 3/R: a small cell has more surface per unit volume, so its metabolism is fast. Elephants and whales lose heat slowly because of their size, while a mouse cools quickly and must eat a lot. Engineers compute the minimum metal for spherical gas tanks with 4πR²; balloons, football covers and dome cladding rely on the same formula. Powdered medicines are ground finely — the total surface grows and the drug dissolves faster.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Interesting facts'), list: [
      L('Kubga ichki chizilgan sfera yuzi kub sirtining π/6 qismiga teng — xuddi hajmlar nisbati kabi (qirra 6: 36π ≈ 113 va 216).', 'Площадь сферы, вписанной в куб, составляет π/6 поверхности куба — как и отношение объёмов (ребро 6: 36π ≈ 113 и 216).', 'The sphere inscribed in a cube has π/6 of the cube’s surface — the same ratio as the volumes (edge 6: 36π ≈ 113 vs 216).'),
      L('Berilgan hajmdagi jismlar orasida eng kichik sirtga shar ega — shuning uchun sovun pufagi va mushuk uxlayotganda «yumaloq» bo‘ladi.', 'Среди тел данного объёма наименьшую поверхность имеет шар — поэтому мыльный пузырь и спящая кошка «круглые».', 'Among solids of a given volume the ball has the smallest surface — which is why soap bubbles and sleeping cats are “round”.'),
      L('Futbol to‘pi 12 ta beshburchak va 20 ta oltiburchakdan tikiladi — kesik ikosaedr sferaga juda yaqin.', 'Футбольный мяч сшит из 12 пятиугольников и 20 шестиугольников — усечённый икосаэдр очень близок к сфере.', 'A football is sewn from 12 pentagons and 20 hexagons — the truncated icosahedron is very close to a sphere.')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверьте себя', 'Test yourself'), p: [
      L('Masalalarni avval mustaqil yeching, keyin yechim bilan solishtiring.', 'Сначала решите задачи самостоятельно, затем сравните с решением.', 'Solve the problems on your own first, then compare with the solutions.')
    ], ex: [
      { q: L('Katta doira yuzi 9π. Sfera yuzini toping.', 'Площадь большого круга 9π. Найдите площадь сферы.', 'A great circle has area 9π. Find the area of the sphere.'),
        s: L('Sfera yuzi to‘rtta katta doiraga teng: 4·9π = 36π (R = 3).', 'Площадь сферы равна четырём большим кругам: 4·9π = 36π (R = 3).', 'The sphere equals four great circles: 4·9π = 36π (R = 3).') },
      { q: L('Radiusi 6 bo‘lgan yaxlit yarim sharning to‘la sirtini toping.', 'Найдите полную поверхность сплошного полушара радиуса 6.', 'Find the total surface of a solid hemisphere of radius 6.'),
        s: L('S = 3πR² = 3π·36 = 108π ≈ 339,3.', 'S = 3πR² = 3π·36 = 108π ≈ 339,3.', 'S = 3πR² = 3π·36 = 108π ≈ 339.3.') }
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Sfera yoyilmaga ega emas; uning yuzi limit orqali ta’riflanadi.', 'Сфера не имеет развёртки; её площадь определяется через предел.', 'A sphere has no net; its area is defined via a limit.'),
      L('S = 4πR² — to‘rtta katta doira yoki tashqi chizilgan silindr yon sirti.', 'S = 4πR² — четыре больших круга или боковая поверхность описанного цилиндра.', 'S = 4πR² — four great circles, or the lateral area of the circumscribed cylinder.'),
      L('S = V′(R) va V = ⅓·S·R — yuz va hajm bir-biridan keltirib chiqariladi.', 'S = V′(R) и V = ⅓·S·R — площадь и объём выводятся друг из друга.', 'S = V′(R) and V = ⅓·S·R — area and volume follow from each other.'),
      L('Segment va belbog‘: S = 2πRh; yarim sfera 2πR², yaxlit yarim shar 3πR².', 'Сегмент и пояс: S = 2πRh; полусфера 2πR², сплошной полушар 3πR².', 'Cap and zone: S = 2πRh; hemisphere 2πR², solid hemisphere 3πR².'),
      L('Silindr va sfera yuzlari ham, hajmlari ham 3 : 2 nisbatda.', 'И площади, и объёмы цилиндра и сферы относятся как 3 : 2.', 'Both the areas and the volumes of cylinder and sphere are in the ratio 3 : 2.'),
      L('Radius k marta oshsa, yuz k² marta oshadi; S/V = 3/R.', 'При увеличении радиуса в k раз площадь растёт в k² раз; S/V = 3/R.', 'Scaling the radius by k scales the area by k²; S/V = 3/R.')
    ] }
  ] });


  // ---------- t14. Takrorlash: stereometriya ----------
  T.add(P, 't14', { sections: [
    { kind: 'intro', h: L('Butun stereometriya bir qarashda', 'Вся стереометрия одним взглядом', 'All of solid geometry at a glance'), p: [
      L('Ikki yil davomida biz fazodagi geometriya bilan shug‘ullandik: aksiomalardan boshlab, parallellik va perpendikulyarlikni, burchak va masofalarni, koordinata va vektorlarni o‘rgandik, so‘ng ko‘pyoqlar va aylanma jismlarga o‘tdik. Endi hammasini bitta tizimga yig‘ish vaqti keldi. Yaxshi xabar: o‘nlab formulalarni alohida-alohida yod olish shart emas — ular bir nechta g‘oyadan kelib chiqadi.', 'Два года мы занимались геометрией пространства: начав с аксиом, изучили параллельность и перпендикулярность, углы и расстояния, координаты и векторы, затем перешли к многогранникам и телам вращения. Теперь пора собрать всё в одну систему. Хорошая новость: десятки формул не нужно заучивать по отдельности — они вытекают из нескольких идей.', 'For two years we have studied the geometry of space: starting from axioms, we learned parallelism and perpendicularity, angles and distances, coordinates and vectors, and then moved to polyhedra and solids of revolution. Now it is time to gather everything into one system. The good news: dozens of formulas need not be memorised separately — they follow from a few ideas.'),
      L('Bu ideyalar: 1) «to‘g‘ri» jismlar va «uchli» jismlar oilalari; 2) Kavalyeri prinsipi; 3) o‘xshashlik qonuni k, k², k³; 4) har qanday fazoviy masalani tekis to‘g‘ri burchakli uchburchakka keltirish. Bu takrorlash mavzusida formulalar jadvalini tuzamiz, jismlar kombinatsiyalarini ko‘rib chiqamiz va imtihonga xos masalalarni yechamiz.', 'Эти идеи: 1) семейства «прямых» и «остроконечных» тел; 2) принцип Кавальери; 3) закон подобия k, k², k³; 4) сведение любой пространственной задачи к плоскому прямоугольному треугольнику. В этой теме повторения составим таблицу формул, рассмотрим комбинации тел и решим типичные экзаменационные задачи.', 'The ideas are: 1) the families of “straight” and “pointed” solids; 2) Cavalieri’s principle; 3) the similarity law k, k², k³; 4) reducing every spatial problem to a flat right triangle. In this review topic we build a table of formulas, look at combinations of solids and solve typical exam problems.')
    ] },
    { kind: 'table', h: L('Asosiy formulalar jadvali', 'Таблица основных формул', 'Table of the main formulas'), table: {
      head: [L('Jism', 'Тело', 'Solid'), L('Sirt', 'Поверхность', 'Surface'), L('Hajm', 'Объём', 'Volume')],
      rows: [
        [L('Prizma', 'Призма', 'Prism'), L('S<sub>yon</sub> = P<sub>perp</sub>·b; to‘g‘ri prizmada P·h', 'S<sub>бок</sub> = P<sub>перп</sub>·b; у прямой P·h', 'S<sub>lat</sub> = P<sub>perp</sub>·b; right prism P·h'), L('S·h', 'S·h', 'S·h')],
        [L('Parallelepiped', 'Параллелепипед', 'Box'), L('2(ab + bc + ca)', '2(ab + bc + ca)', '2(ab + bc + ca)'), L('abc; d² = a² + b² + c²', 'abc; d² = a² + b² + c²', 'abc; d² = a² + b² + c²')],
        [L('Silindr', 'Цилиндр', 'Cylinder'), L('2πrh; to‘la 2πr(r + h)', '2πrh; полная 2πr(r + h)', '2πrh; total 2πr(r + h)'), L('πr²h', 'πr²h', 'πr²h')],
        [L('Piramida', 'Пирамида', 'Pyramid'), L('muntazam: ½·P·l', 'правильная: ½·P·l', 'regular: ½·P·l'), L('⅓·S·h', '⅓·S·h', '⅓·S·h')],
        [L('Konus', 'Конус', 'Cone'), L('πrl; to‘la πr(r + l)', 'πrl; полная πr(r + l)', 'πrl; total πr(r + l)'), L('⅓πr²h', '⅓πr²h', '⅓πr²h')],
        [L('Kesik piramida', 'Усечённая пирамида', 'Frustum'), L('½(P₁ + P₂)·l', '½(P₁ + P₂)·l', '½(P₁ + P₂)·l'), L('⅓h(S₁ + S₂ + √(S₁S₂))', '⅓h(S₁ + S₂ + √(S₁S₂))', '⅓h(S₁ + S₂ + √(S₁S₂))')],
        [L('Kesik konus', 'Усечённый конус', 'Truncated cone'), L('π(r₁ + r₂)l', 'π(r₁ + r₂)l', 'π(r₁ + r₂)l'), L('⅓πh(r₁² + r₁r₂ + r₂²)', '⅓πh(r₁² + r₁r₂ + r₂²)', '⅓πh(r₁² + r₁r₂ + r₂²)')],
        [L('Shar / sfera', 'Шар / сфера', 'Ball / sphere'), L('4πR²; segment 2πRh', '4πR²; сегмент 2πRh', '4πR²; cap 2πRh'), L('⁴⁄₃πR³; segment πh²(R − h/3)', '⁴⁄₃πR³; сегмент πh²(R − h/3)', '⁴⁄₃πR³; cap πh²(R − h/3)')]
      ] }, after: [
      L('Bu yerda P<sub>perp</sub> — perpendikulyar kesim perimetri, b — yon qirra, l — apofema yoki yasovchi.', 'Здесь P<sub>перп</sub> — периметр перпендикулярного сечения, b — боковое ребро, l — апофема или образующая.', 'Here P<sub>perp</sub> is the perimeter of the perpendicular section, b a lateral edge, l the apothem or slant height.')
    ] },
    { kind: 'rule', h: L('Ikki oila va Kavalyeri prinsipi', 'Два семейства и принцип Кавальери', 'Two families and Cavalieri’s principle'), p: [
      L('<b>«To‘g‘ri» jismlar</b> — prizma va silindr: balandlik bo‘ylab har bir kesim asosga teng, shuning uchun <b>V = S·h</b>. <b>«Uchli» jismlar</b> — piramida va konus: uchdan k masofadagi kesim yuzi k²·S, shuning uchun hajm uchdan bir marta kichik: <b>V = ⅓·S·h</b>. Konus aslida «cheksiz ko‘p yoqli piramida», silindr esa «cheksiz ko‘p yoqli prizma».', '<b>«Прямые» тела</b> — призма и цилиндр: каждое сечение по высоте равно основанию, поэтому <b>V = S·h</b>. <b>«Остроконечные» тела</b> — пирамида и конус: сечение на доле k от вершины имеет площадь k²·S, поэтому объём втрое меньше: <b>V = ⅓·S·h</b>. Конус — это «пирамида с бесконечным числом граней», цилиндр — «призма с бесконечным числом граней».', '<b>“Straight” solids</b> — prisms and cylinders: every section along the height equals the base, so <b>V = S·h</b>. <b>“Pointed” solids</b> — pyramids and cones: the section at fraction k from the apex has area k²·S, so the volume is three times smaller: <b>V = ⅓·S·h</b>. A cone is a “pyramid with infinitely many faces”, a cylinder a “prism with infinitely many faces”.'),
      L('<b>Kavalyeri prinsipi</b> bularning hammasini birlashtiradi: kesimlari har bir balandlikda teng bo‘lgan jismlar teng hajmli. Shu tufayli og‘ma prizma hajmi to‘g‘ri prizmanikiga teng (S·h), piramida hajmi asos shakliga emas, faqat asos yuziga bog‘liq, shar hajmi esa «silindr minus konus»ga teng. Shar «uchinchi oila»: unda V = ⅓·S·R, bu yerda S = 4πR² — sharni markazda uchli juda ko‘p ingichka piramidalar deb qarash mumkin.', '<b>Принцип Кавальери</b> объединяет всё это: тела с равными сечениями на каждой высоте равновелики. Благодаря ему объём наклонной призмы равен объёму прямой (S·h), объём пирамиды зависит не от формы основания, а только от его площади, а объём шара равен «цилиндр минус конус». Шар — «третье семейство»: для него V = ⅓·S·R, где S = 4πR², — шар можно считать множеством тонких пирамид с вершиной в центре.', '<b>Cavalieri’s principle</b> ties all this together: solids with equal sections at every height have equal volumes. Thanks to it, an oblique prism has the same volume as a right one (S·h), a pyramid’s volume depends only on the area of its base, not its shape, and a ball equals “cylinder minus cone”. The ball is a “third family”: V = ⅓·S·R with S = 4πR² — it can be viewed as many thin pyramids with apex at the centre.')
    ] },
    { kind: 'rule', h: L('O‘xshashlik qonuni', 'Закон подобия', 'The similarity law'), p: [
      L('Agar ikki jism o‘xshash bo‘lib, o‘xshashlik koeffitsiyenti k bo‘lsa (barcha chiziqli o‘lchamlar k marta farq qilsa), ularning <b>sirt yuzlari k² marta</b>, <b>hajmlari k³ marta</b> farq qiladi. Bu qoida har qanday jism uchun — kub, piramida, shar, hatto odam yoki mashina modeli uchun ham to‘g‘ri.', 'Если два тела подобны с коэффициентом k (все линейные размеры отличаются в k раз), то их <b>площади поверхностей отличаются в k² раз</b>, а <b>объёмы — в k³ раз</b>. Это правило верно для любого тела — куба, пирамиды, шара и даже модели человека или машины.', 'If two solids are similar with ratio k (all lengths differ by a factor k), their <b>surface areas differ by k²</b> and their <b>volumes by k³</b>. This holds for any solid — a cube, a pyramid, a ball, even a model of a person or a car.'),
      L('Piramida yoki konusni asosga parallel kesganda kesib olingan uchli qism berilgan jismga o‘xshash: uchdan balandlikning k qismida kesilsa, kesim yuzi k²·S, kichik jism hajmi k³·V. Masalan, konus shaklidagi stakan balandligining yarmigacha to‘ldirilsa, unda sig‘imning atigi ⅛ qismi suv bo‘ladi; ⅔ balandlikkacha to‘ldirilsa — 8/27 ≈ 30%.', 'При сечении пирамиды или конуса параллельно основанию отсечённая остроконечная часть подобна данному телу: при сечении на доле k высоты от вершины площадь сечения k²·S, объём малого тела k³·V. Например, если конический бокал наполнить до половины высоты, в нём будет лишь ⅛ вместимости; до ⅔ высоты — 8/27 ≈ 30%.', 'When a pyramid or cone is cut parallel to its base, the pointed part cut off is similar to the original: cut at fraction k of the height from the apex, the section has area k²·S and the small solid volume k³·V. For example, a conical glass filled to half its height holds only ⅛ of its capacity; filled to ⅔ of the height, 8/27 ≈ 30%.')
    ] },
    { kind: 'rule', h: L('Jismlar kombinatsiyalari', 'Комбинации тел', 'Combinations of solids'), p: [
      L('<b>Shar va kub</b> (qirra a): ichki shar R = a/2, tashqi shar R = a√3/2. <b>Shar va to‘g‘ri burchakli parallelepiped</b>: tashqi shar radiusi diagonal yarmi, R = ½√(a² + b² + c²). <b>Shar va silindr</b>: tashqi shar R² = r² + (h/2)²; ichki shar faqat h = 2r bo‘lganda mavjud va R = r.', '<b>Шар и куб</b> (ребро a): вписанный шар R = a/2, описанный R = a√3/2. <b>Шар и прямоугольный параллелепипед</b>: радиус описанного шара — половина диагонали, R = ½√(a² + b² + c²). <b>Шар и цилиндр</b>: описанный шар R² = r² + (h/2)²; вписанный существует только при h = 2r, и тогда R = r.', '<b>Ball and cube</b> (edge a): inscribed ball R = a/2, circumscribed R = a√3/2. <b>Ball and rectangular box</b>: the circumscribed ball’s radius is half the diagonal, R = ½√(a² + b² + c²). <b>Ball and cylinder</b>: circumscribed R² = r² + (h/2)²; an inscribed ball exists only when h = 2r, and then R = r.'),
      L('<b>Shar va konus</b>: hamma narsa o‘q kesimga — teng yonli uchburchakka keltiriladi. Ichki shar radiusi — uchburchakka ichki chizilgan aylana radiusi: ρ = S<sub>Δ</sub>/p (p — yarim perimetr). Tashqi shar radiusi — uchburchakka tashqi chizilgan aylana radiusi: R = l²/(2h). <b>Shar va muntazam piramida</b>: tashqi shar R = b²/(2h); ichki shar markazi balandlikda yotadi va asosdagi ikki yoqli burchak bissektrisasi yordamida topiladi: ρ = r·tg(φ/2).', '<b>Шар и конус</b>: всё сводится к осевому сечению — равнобедренному треугольнику. Радиус вписанного шара — радиус вписанной в треугольник окружности: ρ = S<sub>Δ</sub>/p (p — полупериметр). Радиус описанного шара — радиус описанной окружности: R = l²/(2h). <b>Шар и правильная пирамида</b>: описанный шар R = b²/(2h); центр вписанного лежит на высоте и находится с помощью биссектрисы двугранного угла при основании: ρ = r·tg(φ/2).', '<b>Ball and cone</b>: everything reduces to the axial section — an isosceles triangle. The inscribed ball’s radius is the triangle’s inradius: ρ = S<sub>Δ</sub>/p (p the semiperimeter). The circumscribed ball’s radius is its circumradius: R = l²/(2h). <b>Ball and regular pyramid</b>: circumscribed R = b²/(2h); the inscribed ball’s centre lies on the height and is found with the bisector of the dihedral angle at the base: ρ = r·tan(φ/2).')
    ] },
    { kind: 'history', h: L('Stereometriya tarixidan lavhalar', 'Страницы истории стереометрии', 'Pages from the history of solid geometry'), list: [
      L('<b>Mil. av. ~1850-yil</b> — Moskva papirusi: kesik piramida hajmi.', '<b>~1850 г. до н. э.</b> — Московский папирус: объём усечённой пирамиды.', '<b>c. 1850 BC</b> — the Moscow Papyrus: volume of a frustum.'),
      L('<b>Mil. av. V–IV asr</b> — Demokrit piramida va konus hajmini topadi, Evdoks isbotlaydi; Platon besh muntazam ko‘pyoqni olam unsurlari bilan bog‘laydi.', '<b>V–IV вв. до н. э.</b> — Демокрит находит объёмы пирамиды и конуса, Евдокс доказывает; Платон связывает пять правильных многогранников со стихиями.', '<b>5th–4th c. BC</b> — Democritus finds the volumes of the pyramid and cone, Eudoxus proves them; Plato links the five regular polyhedra with the elements.'),
      L('<b>Mil. av. ~300-yil</b> — Yevklid «Negizlar»i: XI–XIII kitoblar stereometriyaga bag‘ishlangan, XIII kitobda faqat beshta muntazam ko‘pyoq borligi isbotlangan.', '<b>~300 г. до н. э.</b> — «Начала» Евклида: книги XI–XIII посвящены стереометрии, в XIII доказано, что правильных многогранников ровно пять.', '<b>c. 300 BC</b> — Euclid’s Elements: Books XI–XIII treat solid geometry; Book XIII proves there are exactly five regular polyhedra.'),
      L('<b>Mil. av. III asr</b> — Arximed: shar hajmi va sfera yuzi, 3 : 2 nisbat.', '<b>III в. до н. э.</b> — Архимед: объём шара и площадь сферы, отношение 3 : 2.', '<b>3rd c. BC</b> — Archimedes: ball volume and sphere area, the 3 : 2 ratio.'),
      L('<b>IX–XI asrlar</b> — al-Xorazmiy jismlar o‘lchashni algebra kitobiga kiritadi; Beruniy Yer radiusini o‘lchaydi va sferani tekislikda tasvirlash usullarini o‘rganadi.', '<b>IX–XI вв.</b> — аль-Хорезми включает измерение тел в книгу по алгебре; Беруни измеряет радиус Земли и изучает способы изображения сферы на плоскости.', '<b>9th–11th c.</b> — al-Khwarizmi includes the measurement of solids in his algebra book; al-Biruni measures the Earth’s radius and studies ways of mapping the sphere onto a plane.'),
      L('<b>1615</b> — Kepler «Vino bochkalari stereometriyasi» asarida bochka hajmini hisoblaydi; <b>1635</b> — Kavalyeri prinsipi; <b>1750-yillar</b> — Eyler ko‘pyoqlar uchun U − Q + Yo = 2 formulasini e’lon qiladi.', '<b>1615</b> — Кеплер в «Стереометрии винных бочек» вычисляет объём бочки; <b>1635</b> — принцип Кавальери; <b>1750-е</b> — Эйлер публикует формулу В − Р + Г = 2 для многогранников.', '<b>1615</b> — Kepler computes barrel volumes in his “Stereometry of Wine Barrels”; <b>1635</b> — Cavalieri’s principle; <b>1750s</b> — Euler publishes V − E + F = 2 for polyhedra.')
    ] },
    { kind: 'steps', h: L('Har qanday stereometrik masala uchun reja', 'План для любой стереометрической задачи', 'A plan for any solid geometry problem'), list: [
      L('Aniq chizma chizing; ko‘rinmas chiziqlarni shtrix bilan belgilang.', 'Сделайте аккуратный чертёж; невидимые линии — штрихами.', 'Draw a neat figure; show hidden lines dashed.'),
      L('Jism turini va kerakli formulani aniqlang (jadvalga qarang).', 'Определите тип тела и нужную формулу (см. таблицу).', 'Identify the solid and the formula needed (see the table).'),
      L('Kerakli kesimni tanlang: o‘q kesim, diagonal kesim yoki balandlik orqali o‘tgan kesim.', 'Выберите удобное сечение: осевое, диагональное или через высоту.', 'Choose a convenient section: axial, diagonal or through the height.'),
      L('Kesimda to‘g‘ri burchakli uchburchakni toping va Pifagor teoremasi yoki trigonometriyani qo‘llang.', 'Найдите в сечении прямоугольный треугольник и примените теорему Пифагора или тригонометрию.', 'Find a right triangle in the section and apply Pythagoras or trigonometry.'),
      L('Noma’lum kattaliklarni topib, formulaga qo‘ying; o‘xshashlik bo‘lsa, k, k², k³ ni ishlating.', 'Найдите неизвестные и подставьте в формулу; при подобии используйте k, k², k³.', 'Find the unknowns and substitute; with similarity use k, k², k³.'),
      L('Javobni tekshiring: birliklar, taxminiy qiymat, chegaraviy hollar (masalan, r₂ = 0).', 'Проверьте ответ: единицы, приближённое значение, предельные случаи (например, r₂ = 0).', 'Check the answer: units, an estimate, limiting cases (e.g. r₂ = 0).')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Решённые примеры', 'Worked examples'), ex: [
      { q: L('Radiusi 3 bo‘lgan shar, unga tashqi chizilgan silindr va shu silindrga ichki chizilgan konus hajmlarini toping.', 'Найдите объёмы шара радиуса 3, описанного около него цилиндра и вписанного в этот цилиндр конуса.', 'Find the volumes of a ball of radius 3, the cylinder circumscribed about it and the cone inscribed in that cylinder.'),
        s: L('Silindr va konus: r = 3, h = 6. Konus ⅓π·9·6 = 18π, shar ⁴⁄₃π·27 = 36π, silindr π·9·6 = 54π. Nisbat 18 : 36 : 54 = 1 : 2 : 3.', 'Цилиндр и конус: r = 3, h = 6. Конус ⅓π·9·6 = 18π, шар ⁴⁄₃π·27 = 36π, цилиндр π·9·6 = 54π. Отношение 18 : 36 : 54 = 1 : 2 : 3.', 'Cylinder and cone: r = 3, h = 6. Cone ⅓π·9·6 = 18π, ball ⁴⁄₃π·27 = 36π, cylinder π·9·6 = 54π. Ratio 18 : 36 : 54 = 1 : 2 : 3.') },
      { q: L('Konusning radiusi 6, balandligi 8. Unga ichki va tashqi chizilgan sharlar radiuslarini toping.', 'Радиус конуса 6, высота 8. Найдите радиусы вписанного и описанного шаров.', 'A cone has radius 6 and height 8. Find the radii of its inscribed and circumscribed balls.'),
        s: L('l = 10. O‘q kesim: tomonlari 10, 10, 12, yuzi ½·12·8 = 48, yarim perimetr 16. Ichki: ρ = 48/16 = 3. Tashqi: R = l²/(2h) = 100/16 = 6,25.', 'l = 10. Осевое сечение: стороны 10, 10, 12, площадь ½·12·8 = 48, полупериметр 16. Вписанный: ρ = 48/16 = 3. Описанный: R = l²/(2h) = 100/16 = 6,25.', 'l = 10. Axial section: sides 10, 10, 12, area ½·12·8 = 48, semiperimeter 16. Inscribed: ρ = 48/16 = 3. Circumscribed: R = l²/(2h) = 100/16 = 6.25.') },
      { q: L('O‘lchamlari 3, 4, 12 bo‘lgan to‘g‘ri burchakli parallelepipedga tashqi chizilgan sfera yuzini toping.', 'Найдите площадь сферы, описанной около прямоугольного параллелепипеда 3 × 4 × 12.', 'Find the area of the sphere circumscribed about a 3 × 4 × 12 box.'),
        s: L('d = √(9 + 16 + 144) = √169 = 13, R = 6,5. S = 4π·42,25 = 169π ≈ 530,9.', 'd = √(9 + 16 + 144) = √169 = 13, R = 6,5. S = 4π·42,25 = 169π ≈ 530,9.', 'd = √(9 + 16 + 144) = √169 = 13, R = 6.5. S = 4π·42.25 = 169π ≈ 530.9.') },
      { q: L('Muntazam to‘rtburchakli piramidaning barcha qirralari 6 ga teng. Hajmi va to‘la sirtini toping.', 'Все рёбра правильной четырёхугольной пирамиды равны 6. Найдите объём и полную поверхность.', 'All edges of a regular square pyramid equal 6. Find its volume and total surface area.'),
        s: L('R = 6√2/2 = 3√2, h = √(36 − 18) = 3√2. V = ⅓·36·3√2 = 36√2 ≈ 50,9. Yon yoqlar teng tomonli: 4·(√3/4)·36 = 36√3. S = 36 + 36√3 ≈ 98,4.', 'R = 6√2/2 = 3√2, h = √(36 − 18) = 3√2. V = ⅓·36·3√2 = 36√2 ≈ 50,9. Боковые грани равносторонние: 4·(√3/4)·36 = 36√3. S = 36 + 36√3 ≈ 98,4.', 'R = 6√2/2 = 3√2, h = √(36 − 18) = 3√2. V = ⅓·36·3√2 = 36√2 ≈ 50.9. The lateral faces are equilateral: 4·(√3/4)·36 = 36√3. S = 36 + 36√3 ≈ 98.4.') },
      { q: L('Ikki o‘xshash shishaning balandliklari 10 sm va 15 sm. Kichigiga 0,4 l sig‘adi. Kattasiga qancha sig‘adi va uning yorlig‘i uchun necha marta ko‘p qog‘oz kerak?', 'Высоты двух подобных бутылок 10 см и 15 см. Меньшая вмещает 0,4 л. Сколько вмещает большая и во сколько раз больше бумаги нужно на её этикетку?', 'Two similar bottles are 10 cm and 15 cm tall. The small one holds 0.4 L. How much does the large one hold, and how many times more paper does its label need?'),
        s: L('k = 15/10 = 1,5. Hajm: 0,4·1,5³ = 0,4·3,375 = 1,35 l. Yorliq yuzi k² = 2,25 marta katta.', 'k = 15/10 = 1,5. Объём: 0,4·1,5³ = 0,4·3,375 = 1,35 л. Площадь этикетки больше в k² = 2,25 раза.', 'k = 15/10 = 1.5. Volume: 0.4·1.5³ = 0.4·3.375 = 1.35 L. The label area is k² = 2.25 times larger.') },
      { q: L('Silindr: r = 2, h = 5. Hajmi, to‘la sirti va tashqi chizilgan shar radiusini toping.', 'Цилиндр: r = 2, h = 5. Найдите объём, полную поверхность и радиус описанного шара.', 'Cylinder: r = 2, h = 5. Find its volume, total surface and the radius of the circumscribed ball.'),
        s: L('V = π·4·5 = 20π. S = 2π·2·5 + 2·4π = 20π + 8π = 28π. R² = 4 + 2,5² = 10,25, R = √10,25 ≈ 3,2.', 'V = π·4·5 = 20π. S = 2π·2·5 + 2·4π = 20π + 8π = 28π. R² = 4 + 2,5² = 10,25, R = √10,25 ≈ 3,2.', 'V = π·4·5 = 20π. S = 2π·2·5 + 2·4π = 20π + 8π = 28π. R² = 4 + 2.5² = 10.25, R = √10.25 ≈ 3.2.') }
    ] },
    { kind: 'mistake', h: L('Eng ko‘p uchraydigan xatolar', 'Самые частые ошибки', 'The most common mistakes'), list: [
      L('<b>Oilalarni aralashtirish:</b> piramida va konusda ⅓ ni unutish yoki prizmaga ⅓ qo‘shib yuborish.', '<b>Путают семейства:</b> забывают ⅓ у пирамиды и конуса или добавляют ⅓ к призме.', '<b>Mixing the families:</b> forgetting ⅓ for pyramids and cones or adding ⅓ to a prism.'),
      L('<b>Balandlik, apofema, yasovchi va yon qirrani chalkashtirish.</b> Hajmga faqat h kiradi, yon sirtga — l.', '<b>Путают высоту, апофему, образующую и боковое ребро.</b> В объём входит только h, в боковую поверхность — l.', '<b>Confusing height, apothem, slant height and lateral edge.</b> Volume uses only h; lateral area uses l.'),
      L('<b>Radius o‘rniga diametr qo‘yish</b> — ayniqsa shar formulalarida (xato 4 yoki 8 marta).', '<b>Подставляют диаметр вместо радиуса</b> — особенно в формулах шара (ошибка в 4 или 8 раз).', '<b>Using the diameter instead of the radius</b> — especially in ball formulas (an error of 4 or 8 times).'),
      L('<b>O‘xshashlikda k, k², k³ ni chalkashtirish.</b>', '<b>Путают k, k², k³ при подобии.</b>', '<b>Mixing up k, k², k³ under similarity.</b>'),
      L('<b>Birliklarni aralashtirish:</b> sm va m bir masalada; 1 m³ = 1000 l, 1 l = 1000 sm³.', '<b>Смешивают единицы:</b> см и м в одной задаче; 1 м³ = 1000 л, 1 л = 1000 см³.', '<b>Mixing units:</b> cm and m in one problem; 1 m³ = 1000 L, 1 L = 1000 cm³.'),
      L('<b>Ikki javobli holatlarni o‘tkazib yuborish</b> (masalan, sharning ikki parallel kesimi markazning ikki tomonida).', '<b>Пропускают случаи с двумя ответами</b> (например, два параллельных сечения шара по разные стороны от центра).', '<b>Missing two-answer cases</b> (e.g. two parallel sections of a ball on opposite sides of the centre).')
    ] },
    { kind: 'life', h: L('Stereometriya kasblarda', 'Стереометрия в профессиях', 'Solid geometry in professions'), p: [
      L('<b>Me’mor va quruvchi</b> beton, g‘isht va tom materiallari hajmi va yuzini hisoblaydi: poydevor — parallelepiped, ustun — silindr, gumbaz — yarim shar, tom — piramida. Samarqanddagi Registon madrasalari va Go‘ri Amir maqbarasining gumbazlarini qoplash uchun koshinlar miqdori sfera sirti formulasi yordamida taxminan baholanadi. <b>Muhandis-texnolog</b> idishlar, sisterna va bunkerlar sig‘imini hisoblaydi: neft rezervuarlari silindrsimon, gaz rezervuarlari sferik.', '<b>Архитектор и строитель</b> считают объёмы и площади бетона, кирпича и кровли: фундамент — параллелепипед, колонна — цилиндр, купол — полушар, крыша — пирамида. Количество изразцов для облицовки куполов медресе Регистана и мавзолея Гур-Эмир в Самарканде приближённо оценивается по формуле площади сферы. <b>Инженер-технолог</b> считает вместимость сосудов, цистерн и бункеров: нефтяные резервуары цилиндрические, газовые — сферические.', '<b>Architects and builders</b> compute volumes and areas of concrete, brick and roofing: a foundation is a box, a column a cylinder, a dome a hemisphere, a roof a pyramid. The number of tiles needed to clad the domes of the Registan madrasas and the Gur-e-Amir mausoleum in Samarkand is estimated approximately with the sphere-area formula. <b>Process engineers</b> compute the capacity of vessels, tankers and hoppers: oil tanks are cylindrical, gas tanks spherical.'),
      L('<b>Dizayner va 3D-modelchi</b> jismlarni ko‘pyoqlar (uchburchakli to‘rlar) bilan yaqinlashtiradi: kompyuter o‘yinlaridagi har bir yumaloq narsa aslida minglab uchburchak yoqli ko‘pyoq. 3D-printerda buyum chop etishdan oldin dastur uning hajmini — demak, plastik sarfi va narxini — hisoblaydi. <b>Logist</b> konteyner va qutilarga yuk joylashtirishda hajmlardan foydalanadi, <b>shifokor</b> esa KT va MRT tasvirlaridan a’zolar hajmini kesimlar yuzlari yig‘indisi bo‘yicha — aynan Kavalyeri g‘oyasi bilan — hisoblaydi.', '<b>Дизайнер и 3D-моделлер</b> приближают тела многогранниками (треугольными сетками): каждый круглый предмет в компьютерной игре — многогранник с тысячами треугольных граней. Перед печатью на 3D-принтере программа считает объём изделия — а значит, расход пластика и цену. <b>Логист</b> пользуется объёмами при загрузке контейнеров и коробок, а <b>врач</b> по снимкам КТ и МРТ вычисляет объём органов как сумму площадей сечений — именно по идее Кавальери.', '<b>Designers and 3D modellers</b> approximate solids by polyhedra (triangle meshes): every round object in a computer game is a polyhedron with thousands of triangular faces. Before 3D printing, the software computes the object’s volume — and hence the plastic used and the price. <b>Logisticians</b> use volumes when loading containers and boxes, and <b>doctors</b> compute organ volumes from CT and MRI scans as sums of section areas — exactly Cavalieri’s idea.')
    ] },
    { kind: 'practice', h: L('Mustaqil ish uchun masalalar', 'Задачи для самостоятельной работы', 'Problems for independent work'), p: [
      L('Avval yechib ko‘ring, so‘ng javoblar bilan solishtiring.', 'Сначала решите сами, затем сверьтесь с ответами.', 'Solve them first, then compare with the answers.')
    ], ex: [
      { q: L('Kub qirrasi 2. Unga tashqi chizilgan shar hajmini toping.', 'Ребро куба 2. Найдите объём описанного шара.', 'A cube has edge 2. Find the volume of its circumscribed ball.'),
        s: L('R = 2√3/2 = √3. V = ⁴⁄₃π·3√3 = 4√3π ≈ 21,8 (kub hajmi 8 dan 2,7 marta katta).', 'R = 2√3/2 = √3. V = ⁴⁄₃π·3√3 = 4√3π ≈ 21,8 (в 2,7 раза больше объёма куба 8).', 'R = 2√3/2 = √3. V = ⁴⁄₃π·3√3 = 4√3π ≈ 21.8 (2.7 times the cube’s volume 8).') },
      { q: L('Konus va silindrning asoslari va balandliklari teng, silindr hajmi 30. Konus hajmi?', 'У конуса и цилиндра равны основания и высоты, объём цилиндра 30. Объём конуса?', 'A cone and a cylinder have equal bases and heights; the cylinder’s volume is 30. The cone’s volume?'),
        s: L('V<sub>konus</sub> = ⅓·30 = 10.', 'V<sub>конуса</sub> = ⅓·30 = 10.', 'V<sub>cone</sub> = ⅓·30 = 10.') },
      { q: L('Ikosaedrda 12 uch va 20 yoq bor. Nechta qirrasi bor?', 'У икосаэдра 12 вершин и 20 граней. Сколько у него рёбер?', 'An icosahedron has 12 vertices and 20 faces. How many edges does it have?'),
        s: L('Eyler formulasi: 12 − Q + 20 = 2 ⇒ Q = 30.', 'Формула Эйлера: 12 − Р + 20 = 2 ⇒ Р = 30.', 'Euler’s formula: 12 − E + 20 = 2 ⇒ E = 30.') }
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('«To‘g‘ri» jismlar (prizma, silindr): V = S·h; «uchli» jismlar (piramida, konus): V = ⅓·S·h; shar: V = ⁴⁄₃πR³ = ⅓·S·R.', '«Прямые» тела (призма, цилиндр): V = S·h; «остроконечные» (пирамида, конус): V = ⅓·S·h; шар: V = ⁴⁄₃πR³ = ⅓·S·R.', '“Straight” solids (prism, cylinder): V = S·h; “pointed” ones (pyramid, cone): V = ⅓·S·h; ball: V = ⁴⁄₃πR³ = ⅓·S·R.'),
      L('Yon sirtlar: ½·P·l, πrl, π(r₁ + r₂)l, 2πrh; sfera 4πR².', 'Боковые поверхности: ½·P·l, πrl, π(r₁ + r₂)l, 2πrh; сфера 4πR².', 'Lateral areas: ½·P·l, πrl, π(r₁ + r₂)l, 2πrh; sphere 4πR².'),
      L('Kavalyeri prinsipi: teng kesimlar — teng hajmlar.', 'Принцип Кавальери: равные сечения — равные объёмы.', 'Cavalieri’s principle: equal sections — equal volumes.'),
      L('O‘xshashlik: uzunlik k, yuz k², hajm k³.', 'Подобие: длина k, площадь k², объём k³.', 'Similarity: length k, area k², volume k³.'),
      L('Konus : shar : silindr = 1 : 2 : 3; kombinatsiyalar o‘q kesimga keltiriladi.', 'Конус : шар : цилиндр = 1 : 2 : 3; комбинации сводятся к осевому сечению.', 'Cone : ball : cylinder = 1 : 2 : 3; combinations reduce to the axial section.'),
      L('Har bir fazoviy masala oxir-oqibat tekis to‘g‘ri burchakli uchburchakka keltiriladi.', 'Каждая пространственная задача в итоге сводится к плоскому прямоугольному треугольнику.', 'Every spatial problem eventually reduces to a flat right triangle.')
    ] }
  ] });

})(this);
